\begin{align}
\label{eq:AnDef}
A(n) =
\sum_{G \in \mathcal G_k^c(n)}
\frac{1}
{|\Aut(G)|}\prod_{v\in V_G} \Lambda_{\deg(v)}\, ,
\end{align}
where $\Aut(G)$ is the group of automorphisms of a labeled graph $\Gamma$ representing $G$ as defined below. 
Throughout, we use the multi-index notation: bold symbols typically denote $c$-tuples, as in $\boldsymbol{w} = (w_1,\dots,w_c)$. The multi-index factorial is $\boldsymbol{w}! = w_1!\cdots w_c!$, while $\boldsymbol{x}^{\boldsymbol{w}}$ is shorthand notation for $x_1^{w_1} \cdots x_c^{w_c}$. Moreover, we use $|\boldsymbol{w}| = w_1+\dots +w_c$. We define a polynomial $g\in \mathbb{R}[x_1,\ldots,x_c]$ storing the parameters $\Lambda_{\bb w}$ by
\begin{equation}\label{eq:poly_g}
g(x_1,\ldots,x_c) = 
-\sum_{i=1}^c \frac{x_i^2}{2} +
\sum_{\bb w\in\mathcal C_k^c
}
\Lambda_{\bb w}
\frac{\bb x^{\bb w}}{\bb w!}\, .
\end{equation}
Let $\crit^*(g)$ be the set of critical points of $g$ lying in the complex cone over the sphere $S^{c-1}$,
\[
\crit^*(g) = \left\{ \boldsymbol{z} \in \mathbb{C}^c \,:\, \frac{\partial g}{\partial x_1}(\boldsymbol{z}) =\ldots = \frac{\partial g}{\partial x_c}(\boldsymbol{z}) = 0 \text{ and } \boldsymbol{z} = \tau \cdot \bb x \text{ for } \tau \in \mathbb{C}\setminus\{0\} \text{ and } \bb x \in S^{c-1} \right\} .
\]
Among these, let 
\[
 \Psi = \argmin_{\bb z= \tau \cdot \bb x \in \crit^*(g)} |\tau|
\] 
be the subset of critical points of minimal distance to the origin.
Moreover, let $\Hess g$ be the Hessian of $g$ which is the symmetric matrix formed by its second partial derivatives.

