 =\frac{22}{256}A_1''-\frac{70}{16}A_1'+11A_1-\frac{54}{16}\al'+108(\al-1)-\frac{10}{3}\sum_{k=1}^\infty \frac{\binom{4k}{k}}{k16^k}.
 \end{align*}
 Applying \eqref{Fj,d}--\eqref{Fj,ddd} with $j=1$ and $x=1/{16}$, we get
 \begin{equation} A_1=\int_{1}^{\alpha}\frac{4(y-\alpha)(1+3y)^2}{y(y+1)(11y^3-11y^2-7y-1)}dy,\label{F1,d}
 \end{equation}
 \begin{equation} A_1'=\int_{1}^{\al}\frac{4(4(3y^3-2y^2-y)-\al')(1+3y)^2}{y(y+1)(11y^3-11y^2-7y-1)}dy,
 \label{F1,dd}
 \end{equation}
 and
 \begin{equation} A_1''=\int_{1}^{\al}\frac{4(16(27y^5-30y^4-16y^3+14y^2+5y)-\al'')(1+3y)^2}{y(y+1)(11y^3-11y^2-7y-1)}dy.\label{F1,ddd}
 \end{equation}
 So we deduce further that
 \begin{equation}\label{sigma1}\sigma_1=\int_{1}^{\alpha}\frac{(27y^2-3y-40)(3y+1)^2}{2y(y+1)}dy
 -\frac{54}{16}\cdot\frac{64\alpha^5}{(3\alpha+1)^2}+108(\alpha-1)-\frac{40}{3}\log\frac{4\alpha}{3\alpha+1}
 \end{equation}
 with the aid of the identity
