 &\ \ \ (27y^2-3y-40)(11y^3-11y^2-7y-1)\\
 &=\frac{11}{16}\l(16(27y^5-30y^4-16y^3+14y^2+5y)-\al''\r)
 \\&\ \ \ -35(4(3y^3-2y^2-y)-\al')+11(y-\al).
 \end{aligned} \label{pqr,1/16}
 \end{equation}
 equivalent to \eqref{relation}.
 For the function
 $$g(y)=\frac{1}{2}(81y^3-54y^2-243y+216)-20\log\frac{2y}{y+1},$$
 it is easy to verify that
 $$g'(y)=\frac{(27y^2-3y-40)(3y+1)^2}{2y(y+1)}.$$
