 \begin{align*}\sigma_1&=g(\al)-g(1)-\frac{216\alpha^5}{(3\alpha+1)^2}+108(\alpha-1)-\frac{40}{3}\log\frac{4\alpha}{3\alpha+1}\\
 &=\frac{27\alpha(\alpha+1)(11\alpha^3-11\alpha^2-7\alpha-1)}{2(3\alpha+1)^2}
 \\&\ \ \ -\frac{20}{3}\log{\l(2+\frac{2(5\alpha^2+2\alpha+1)(11\alpha^3-11\alpha^2-7\alpha-1)}{(\alpha+1)^3(3\alpha+1)^2}\r)} \\
