\begin{theorem}\label[theorem]{thm: Morse functions agree at fixed points} 
 Let $\vec\beta \in (0, \infty)^n$ be generic, let $\alpha_i(R)= \frac{1}{2} - R \beta_i$ for $R>0$, and assume $R_\text{max}$ solves $W_{[n]}(\vec\alpha(R_\text{max}))=(n-2)/2$ as in \Cref{thm: map from hyperpolygon to Higgs}. For $R\in(0,R_\text{max})$, let $M_\text{HP}$ and $M_R=M_{R,\vec\alpha(R)}$ be the Morse-Bott functions on $\mathcal{X}(\beta)$ and $\mathcal{M}_R(\vec \alpha(R))$ described in \eqref{eqn: Morse-Bott functions}.
 For each $\U(1)$-fixed point $(\bx,\by)$ and corresponding $\U(1)$-fixed harmonic bundle $\mathcal T_R(\bx,\by)=(\mathcal E,\varphi,h_R)$, and for all $0<R<R_\text{max}$, we have \begin{equation} M_R(\mathcal E,\varphi,h_R)=2\pi M_\text{HP}(\bx,\by).\end{equation}
\end{theorem}
\begin{proof} \hfill
\begin{itemize}
\item[($\ell=1$)]
 Suppose $(\bx,\by)\in X_\emptyset$, hence $M_\text{HP}(\bx,\by)=0$. Then $\by=0$, so the corresponding Higgs bundle has $\varphi=0$. Therefore, $M_R(\mathcal E,\varphi,h_R)=0$.
\item[($\ell=2$)]
Suppose $(\bx,\by)\in X_I$ for $I \neq \emptyset$. Pick a basis in which $x_i\in\langle e_1\rangle$ for $i\in I$ and $x_i\in\langle e_2\rangle$ for $i\in I^c$. Since $y_i=0$ for $i\in I^c$, the Higgs bundle has the form
 $$\varphi=\begin{pmatrix}0&\varphi_{12}\\0&0\end{pmatrix}.$$
Since $\mathcal{E}= \mathcal{O} \oplus \mathcal{O}$ as holomorphic bundles, then $\mathcal{L}_1 \simeq \mathcal{O}$.
Moreover, the set $I$ appearing in the statement of \Cref{prop:morsehitchin} agrees with the set $I$ appearing in the statement of \Cref{prop: HP Morse function}.
Then 
 \begin{align*}
 M_R(\mathcal E,\varphi,h_R) &= -\pi i R^{-1} \left( \deg \mathcal{L}_1 + \sum_{i \in I} (\frac{1}{2}-\alpha_i(R)) + \sum_{i \in I^c} (\alpha_i(R)- \frac{1}{2}) \right)\\
 &=- \pi i \left(\sum_{i\in I}\beta_i-\sum_{i\in I^c}\beta_i\right)\\\
 &= 2\pi \cdot \frac{1}{2i} W_{I}(\vec \beta)\\
 &=2\pi M(\bx,\by).
 \end{align*}
 \end{itemize}
\end{proof}

\subsection{Proof of Main Theorem}\label{sec:mainthm}
We now prove the main theorem:
\begin{restatable}{theorem}{HKdegeneration}\label[theorem]{thm: HK degeneration}
 Suppose $\vec\beta\in(0,\infty)^n$ is generic and define $\vec\alpha(R)\in(0,\frac12)^n$ by $\alpha_i(R)=\frac12-R\beta_i$. For $R>0$ small enough that $W_{[n]}(\vec\alpha(R))>(n-2)/2$, let $\mathcal T_R\from\mathcal X(\vec\beta)\into\mathcal M_R(\vec\alpha)$ be the family of embeddings described above. Then the family of hyperkähler metrics $\mathcal{T}_R^*(g_R)$ converges pointwise to $2\pi\cdot g_\text{HP}$ as $R \to 0$.
\end{restatable}
\begin{proof} Let $\delta>0$.
 Let $(\bx,\by)$ be a unitary hyperpolygon and $(\dot\bx,\dot\by)$ a unitary deformation of $(\bx,\by)$. The image $(\mathcal E,\varphi)=\mathcal T_R(\bx,\by)$ is a Higgs bundle with holomorphic structure $\delbar_{\mathcal E}=\delbar$ independent of $(\bx, \by)$, while the parabolic flag structure $\mathcal F$ depends on $(\bx, \by)$. 
 It suffices to prove that for every unitary deformations $(\dot \bx, \dot \by) \in T_{(\bx, \by)} \mathcal{X}(\vec \beta)$ and associated harmonic deformation 
 $\mathtt{H}_R \in T_{\mathcal{T}_R(\bx, \by)} \mathcal{M}_R(\vec(\alpha))$,
 \begin{equation}\label{eqn: main goal}
 \lim_{R\to0}\| \mathtt{H}_R\|_{g_R}^2=2\pi\sum_i\left(|\dot x_i|^2+|\dot y_i|^2\right).
 \end{equation}
 Recall that the deformation $(\dot\bx,\dot\by)$ corresponds to the Higgs bundle deformation $(\dot{\eta}, \dot{\mathcal F},\dot\varphi)$. 
 It will be convenient to introduce the notation $\dot{\Phi} = \dot \Psi^{1,0}$, 
 so that 
 the associated deformation in the $h_R$-unitary formulation is $(\dot \nabla_R^{0,1},\dot\Phi_R)=(-\delbar\dot\nu_R,\dot\varphi+[\dot\nu_R,\varphi])$ as discussed in \Cref{sec:hitchinhk}.
Using \eqref{eq:hk expression} and the regularity of $\gamma_R$,
 \begin{align}
 \|(\dot \nabla^{0,1}_R,\dot\Phi_R)\|^2
 &=\sum_{i=1}^n \left( \lim_{\delta'\to0}\oint_{\partial B_{\delta'}(p_i)}R^{-1}\langle\dot\nu_R,\delbar\dot\nu_R\rangle_{h_R}\right) +\int_{\P^1}R\langle\dot\varphi,\dot\Phi_R\rangle_{h_R}
 \notag\\
 &=\sum_{i=1}^n \left( \lim_{\delta'\to0}\oint_{\partial B_{\delta'}(p_i)}R^{-1}\langle\dot\nu_R,\delbar\dot\nu_R\rangle_{h_{\app,R}} \right)+\int_{\P^1}R\langle\dot\varphi,\dot\Phi_{\app,R}\rangle_{h_{\app,R}}+O(R^2)
 \notag\\
 &=\sum_{i=1}^n \left( \lim_{\delta'\to0}\oint_{\partial B_{\delta'}(p_i)}R^{-1}\langle\dot\nu_{\text{app},R},\delbar\dot\nu_{\text{app},R}\rangle_{h_{\text{app},R}} \right)\\
 &\quad+\int_{\P^1}R\langle\dot\varphi,\dot\Phi_{\text{app},R}\rangle_{h_{\text{app},R}}+O(R^2)
 \notag\\
 &\quad+\sum_{i=1}^n \left( \lim_{\delta'\to0}\oint_{\partial B_{\delta'}(p_i)}\underbrace{R^{-1}\langle\rho_R,\delbar\dot\nu_{\text{app},R}\rangle_{h_{\text{app},R}}+R^{-1}\langle\dot\nu_{\text{app},R},\delbar\rho_R\rangle_{h_{\text{app},R}}}_{f_\text{cor}(\bar{z-p_i})^{-1}\de\bar z} \right).
 \end{align}
 The last integrand can be written as $f_\text{cor}(\bar{z-p_i})^{-1}\de\bar z$. Since $\rho_R\in L_{{2-\eps}}^{2,2}(\End(\mathcal E))$, we have $\rho_R\in o(r^{1-\eps})$ and $\delbar\rho_R\in o(r^{-\eps})$. Thus, $|f_\text{cor}|$ has leading order terms of the form $r^{1-\eps-4R\beta_i}$, so for sufficiently small $R$ we can bound it above by $Cr^{1/2}$ for some constant $C$;
 this constant is uniform as $R\to0$ by analyticity of $\rho_R$. Now $Cr^{1/2}(\bar{z-p_i})^{-1}\de\bar z$ vanishes under integration along $\partial B_{\delta'}(p_i)$ in the limit $\delta'\to0$, so the last integral is zero. Finally, the uniform boundedness of $\langle\dot\varphi,\dot\Phi_{\text{app},R}\rangle_{h_R}$ on $[0,R_{\max})\times K_\delta$ and \Cref{prop: local metric pairing} implies \eqref{eqn: main goal}.
\end{proof}

Recall the Morse-Bott functions in \eqref{eqn: Morse-Bott functions} arising as moment maps with respect to the real symplectic form for the $\U(1)$-actions on the hyperk\"ahler spaces $\mathcal X(\vec\beta)=X\fourslash_{(0, \vec \beta)}$ and $\mathcal M_R(\vec\alpha(R))$:
 $$M_\text{HP}(\bx,\by)=\frac i2\sum_i|y_i|^2,
 \quad M_R(\mathcal E,\varphi,h_R)=\frac i2\int_{\C\P^1}R|\varphi|_{h_R}^2$$
 In \Cref{thm: Morse functions agree at fixed points}, we proved that $M_R(\mathcal{T}_R(\bx, \by))=2 \pi M_\text{HP}(\bx, \by)$ at corresponding $U(1)$-fixed points. Now, we prove that the family of Morse functions converges: 
\begin{theorem}
 \label[theorem]{thm: moment maps agree}
 In the setting of \Cref{thm: HK degeneration}, for any unitary hyperpolygon $(\bx,\by)$ and corresponding $(0,R_{\max})$-family of harmonic bundles $\mathcal{T}_R(\bx, \by)$, we have \begin{equation} \lim_{R\to0}M_R(\mathcal{T}_R(\bx,\by))=2\pi M_\text{HP}(\bx,\by).\end{equation}
\end{theorem}
\begin{proof}
 Let $(\bx,\by)$ be a unitary hyperpolygon, and let $\gamma_R$, $R_\text{max}$, and $\eps\in(0,\frac12)$ be as in \Cref{prop: approximate h accuracy}. Our approximation $h_{\text{app},R}$ is uniformly bounded on $K_\delta=\CP^1 \sm \bigcup_{i} B_\delta(p_i)$ as $R\to0$, and therefore, so is $h_R=e^{\gamma_R}\cdot h_{\text{app},R}$ (recall $\lim_{R\to}\gamma_R=0$ and $\gamma_R$ is real analytic in $R$). 
 Thus, $R|\varphi|_{h_R}^2\to0$ on $K_\delta$ as $R\to0$.

