 Many other geometric quantities have natural weighted versions that fit together within a coherent weighted manifold framework (see Table 1 of \cite{BaldaufOzuch22}, for example). This leads to natural definitions of weighted minimal surfaces, weighted outer-minimising surfaces (see Definition \ref{def-weighted-min}), and to conjecture a weighted Riemannian Penrose inequality. However, we show this follows immediately from the conformal transformation discussed above.
 \begin{thm}\label{thm-weightedPenrose-intro}
 Let $(M^n,g,e^{-f}dV_g)$ be a weighted asymptotically flat manifold of dimension $3\le n\le 7$ containing a closed $f$-outer-minimising $f$-minimal hypersurface $\Sigma$. Assume $S_f\ge 0$, then
 \begin{equation}\label{eq-weightedPenrose}
 m_f(g)\;\ge\;\frac12\left(\frac{A_f(\Sigma)}{\omega_{n-1}}\right)^{\!\frac{n-2}{n-1}}.
 \end{equation}
 Furthermore, if we also assume that $M$ is spin\footnote{Recall $n=3$ implies spin automatically.}, then equality holds in \eqref{eq-weightedPenrose} if and only if $(M^n,g,e^{-f}dV_g)$ is an $f$-Schwarzschild manifold.
 \end{thm}

Let $(M^n,g,e^{-f}dV_g)$ be a weighted $n$-dimensional asymptotically flat manifold with decay $\tau>\frac{n-2}{2}$. We define a densitised curvature map
 \[
 \Phi(g,f)= S_f\,e^{-f}dV_g,
 \]
 where
 \begin{equation*}
 S_f=R_f+\frac{1}{n-1}|\nabla f|^2=R+2\Delta(f)- \frac{n-2}{n-1}|\nabla f|^2,
 \end{equation*}
 motivated by Theorem \ref{thm-LLS}. Following Michel's formalism on geometric mass invariants \cite{Michel11}, there is $1$-form valued differential operator $\mathbb U$ defined by
 \begin{equation}\label{eq-Michel-formula1}
 V\,D\Phi_{(\mathring{g},\mathring{f})}(h, \varphi)-\langle(h,\varphi),D\Phi_{(\mathring{g},\mathring{f})}^*(V)\rangle=\div_{\mathring g}\mathbb U(V,h,\varphi)dV_{\mathring g},
 \end{equation}
 where $h=g-\mathring g$, $\varphi=f-\mathring f$, $V$ is a scalar function, and $\langle \cdot,\cdot,\rangle$ is the natural pairing. We note here that instead of using the densitised map $\Phi$, one could instead define the adjoint map with respect to a weighted $L^2$ inner product. Although we include the background weight function $\mathring f$ in the expression above for clarity, we will be taking it to vanish identically in the definition of the weighted mass. Choosing $V$ in the kernel of $D\Phi_{(\mathring{g},\mathring{f}\equiv 0)}^*$ and integrating $\div_{\mathring g}\mathbb U$ over $M$ gives a flux integral at infinity, which corresponds to a geometric invariant \`a la Michel \cite{Michel11}. Although for the mass definition we need only compute the variation around the base point $(\mathring g,0)$, the linearisation and its adjoint at a general point will be useful in what follows. We compute
 \begin{align}\begin{split}
 D\Phi_{(g,f)}(h,\varphi) \,=\,& \Big(
 \big( \nabla^i \nabla^j h_{ij} - \Delta(h^i{}_i) \big) 
 - 2\big( \nabla^j h_{ij} - \frac{1}{2}\nabla_i(h^k{}_k) \big)\nabla^i f \\
 &\quad - h_{ij}\Big( \ric^{ij} + 2\nabla^i \nabla^j f - \frac{n-2}{n-1}\,\nabla^i f \nabla^j f \Big) \\
 &\qquad +\left(2 \Delta \varphi - \frac{2(n-2)}{n-1}\,\nabla^i f \,\nabla_i \varphi\right)\\
 &\qquad+S_f(g)\left( \frac12 \tr_g(h)-\varphi \right)\Big)e^{-f}dV_g,\end{split}
 \end{align}
 with formal adjoint

From this we see that linearising around $(\mathring g, \mathring f\equiv0)$ gives
 \begin{equation}
 D\Phi_{(\mathring g,0)}(h,\varphi)=\left( \onabla^i \onabla^j h_{ij} - \oDelta(\tr_{\mathring g}(h)) +2\oDelta(\varphi)\right)dV_{\mathring g}
 \end{equation}
 and
 \begin{equation}\begin{split}
 D_g\Phi_{(\mathring g,0)}^*(V)^{ij}=\;& \Big(\onabla^i \onabla^j V - (\oDelta V)\, \mathring g^{ij}\Big)dV_{\mathring g},\\
 D_f\Phi_{(\mathring g,0)}^*(V)=\;& 2 \oDelta V dV_{\mathring g}.
 \end{split}\end{equation}
 We see immediately that the kernel of $D\Phi^*_{(\mathring g,0)}$ consists of affine functions. Taking $V\equiv 1$, and using $h=g-\mathring g$ and $\varphi=f$, we have
 \begin{equation*}
 \mathbb U(1,g-\mathring g,f)=\div_{\mathring g}(g)-\onabla\tr_{\mathring g}(g)+2\onabla f.
 \end{equation*}
 We then immediately see that integrating this over large spheres recovers the weighted mass
 \begin{equation}
 \lim_{\rho\to\infty}\int_{S_\rho}\mathbb U_i(1,g-\mathring g,f)dS^i=2(n-1)\omega_{n-1}\m_f(g),
 \end{equation}
 making use of the fact that $e^{-f}=1+O(r^{-\tau})$. That is, the weighted mass is the geometric mass invariant associated with $S_fe^{-f}dV_g$ and we have established Theorem \ref{thm-Michel}. An important aspect of this formalism for mass invariants is that it gives a somewhat universal framework to prove that they are indeed geometric quantities, independent of the choice of coordinates at infinity \cite{Michel11}. However, for the weighted mass this readily follows from the coordinate invariance of the ADM mass \cite{BaldaufOzuch22,LawLopezSantiago24}, so in the interest of brevity we do not explicitly present this here.

\begin{align}\begin{split}
 \mathfrak c^a_f(g)&=\frac{1}{\m_f(g)}\lim_{\rho\to\infty}\int_{S_\rho}\mathbb U_i(x^a,g-\mathring g,f)dS^i\\
 &=\frac{1}{\m_f(g)}\lim_{\rho\to\infty}\int_{S_\rho}x^a\Big(\onabla^{j}g_{ij}-\onabla_i\big(\tr_{\mathring g}g\big)+2\,\onabla_if\Big)
 \\ &\qquad -(g-\mathring g)_{ia}
 +\Big(\tr_{\mathring g}(g-\mathring g)-2f\Big)\delta_i^a\, dS^i,
 \end{split}
 \end{align}
 where $x^a$ is a coordinate function. We next show that this is simply the same as the standard centre of mass for the conformal metric $\widetilde g = e^{-\frac{2}{n-1}f}\,g$.
 \begin{prop}
 Let $(M^n,g,e^{-f}dV_g)$ be a smooth asymptotically flat weighted manifold of order $\tau>\frac{n-2}{2}$, and let $\widetilde g = e^{-\frac{2}{n-1}f}\,g$. Then
 \[
 \mathfrak c^a_f(g)=\mathfrak c^a_{\mathrm{ADM}}(\widetilde g),
 \]
 where $\mathfrak c_{ADM}$ is the usual centre of mass for an asymptotically flat manifold given by 
 \begin{equation}\begin{split}\label{eq-CoM}
 \mathfrak c_{ADM}^a(\widetilde g)&=\lim_{\rho\to\infty}\frac{1}{\m_{ADM}(\widetilde g)}\int_{S_\rho}
 x^a\Big(\mathring\nabla^j(\widetilde g)_{ij}-\mathring\nabla_i\tr_{\mathring g}(\widetilde g)\Big)\\ &\qquad
 -(\widetilde g -\mathring g)_{ia}+\tr_{\mathring g}(\widetilde g-\mathring g)\,\delta_i^{\,a}dS^i,\end{split}
 \end{equation}
 whenever $\mathfrak c_{ADM}(\widetilde g)$ is well-defined.\footnote{ To ensure the centre of mass is well-defined requires an additional parity assumption \cite{ReggeTeitelboim74}.}
 \end{prop}
 \begin{proof}
 The decay conditions allow us to write
 \begin{equation}\label{eq-conf-expansion-com}
 \widetilde g
 = g - \frac{2}{n-1}f\,\mathring g + O_2(r^{-2\tau}).
 \end{equation}
 Inserting this into \eqref{eq-CoM} and recalling $\m_{ADM}(\widetilde g)=\m_f(g)$ one quickly arrives at
 \[
 \mathfrak c^a_f(g)=\mathfrak c^a_{\mathrm{ADM}}(\widetilde g).
 \]
 \end{proof}

\begin{thm}\label{thm-weighted-hawking-bound}
 Let $(M^3,g,e^{-f}dV_g)$ be asymptotically flat and assume
 \[
 S_f \ge\ 0.
 \]
 Let $\Sigma\subset M$ be a connected closed surface that is $f$-outer-minimising in $(M^3,g,e^{-f}dV_g)$.
 Then
 \begin{equation}\label{eq-weighted-hawking-bound}
 \m_f(g)\ \ge\ \m_{H,f}(\Sigma;g).
 \end{equation}
 \end{thm}

post_theorem_intro_text:
The reader is directed to definition \ref{def-AF} for the assumed decay rates for asymptotically flat weighted manifolds.

	Somewhat surprisingly, Law, Lopez, and Santiago \cite{LawLopezSantiago24} showed that after a particular conformal transformation, the weighted positive mass theorem reduces precisely to the usual (unweighted) positive mass theorem, which can then be applied directly. In fact, the result they obtain is actually stronger than the previously established more technical proofs.
	\begin{thm}[Law--Lopez--Santiago \cite{LawLopezSantiago24}]\label{thm-LLS}
		Let $(M^n,g,e^{-f}dV_g)$ be an asymptotically flat weighted manifold with $f=o_2(|x|^{-(n-2)/2})$ and $R_f\in L^1(M)$. Set
		\[
		\widetilde g \;=\; e^{-\frac{2}{n-1}f}\,g.
		\]
		Then the scalar curvature of $\widetilde g$, $\widetilde R$ is given by
		\[
		\widetilde R \;=\; e^{\frac{2}{n-1}f}\Big(R_f + \frac{1}{n-1}\,|\nabla f|^2\Big),
		\]
		and
		\[
		\m_f(g) \;=\; \mathfrak{m}(\widetilde g).
		\]
		In particular, if $R_f\ge -\frac{1}{n-1}|\nabla f|^2$ then $R_{\widetilde g}\ge 0$ and hence $\m_f(g)\ge 0$.
	\end{thm}
	Without this insight, one may be tempted to pursue a proof of a weighted Riemannian Penrose inequality by adapting the proofs of Huisken and Ilmanen \cite{HuiskenIlmanen01} or Bray \cite{Bray01} to the weighted setting\footnote{The present author at least was, prior to learning of the article \cite{LawLopezSantiago24}.}. However, it turns out that the expected weighted Riemannian Penrose inequality follows from the same conformal transformation then applying the standard Riemannian Penrose inequality to the conformal metric. In this note, we show this weighted Riemannian Penrose inequality and some related results on weighted manifolds that follow from this same conformal picture. In order to better understand why this approach works so well, we investigate the quantity $$S_f=R_f+\frac{1}{n-1}|\nabla f|^2.$$ In particular, we study the geometric mass invariant associated with $S_f$ via Michel's mass invariant formalism \cite{Michel11}, and establish that it is precisely the weighted mass. 
	\begin{thm}\label{thm-Michel}
		Let $(M^n,g,e^{-f}dV_g)$ be an asymptotically flat weighted manifold and define the densitised curvature operator $\Phi(g,f)=S_f(g)\,e^{-f}dV_g$. The kernel of $D\Phi^*_{(\mathring g,0)}$ consists of affine functions $V$ defining geometric mass invariants in the sense of Michel \cite{Michel11}
		\begin{equation}
			\mathfrak{m}(g,f,V)=\lim_{\rho\to\infty}\int_{S_\rho}\mathbb U_i(g,f,V)\,\nu^idS,
		\end{equation}
		where $\mathbb U(g,f,V)$ satisfies
		\begin{equation*}
			\div_{\mathring g}\mathbb U(g,f,V)=V\, D\Phi_{(\mathring g,0)}.
		\end{equation*}
		Furthermore, for $V=1$ and assuming $S_f\in L^1$ then we have
		\begin{equation*}
			\mathfrak{m}(g,f,1)=\m_f(g).
		\end{equation*}
	\end{thm}

	With this in mind, it is not surprising that we can establish so many properties of the weighted mass via the conformal metric $\widetilde g$, whose scalar curvature is $S_f$.  This framework also naturally leads to a definition of centre of mass for weighted manifolds, which agrees with the standard (unweighted) centre of mass of $\widetilde g$.

	Examining the linearisation of $S_f$ and its formal adjoint leads to a natural definition of weighted static metrics, which can be understood as candidates for minimisers of the weighted mass. We prove that this definition of weighted staticity also can be understood via the conformal metric $\widetilde g$. From this we prove the following weighted static uniqueness theorem for what we call the $f$-Schwarzschild family of metrics, which differ from regular Schwarzschild metrics by the conformal factor $e^{-\frac{2f}{n-1}}$ (see Definition \ref{def-f-schwarzschild}).
	\begin{thm}\label{thm-fstatic-bh-rigidity-intro}
		Let $(M^n,g,e^{-f}dV_g)$ be an asymptotically flat weighted manifold with compact boundary
		$\Sigma=\partial M$, and assume $f\to 0$ at infinity.
		Assume either $3\le n\le 7$ or $M$ is spin, and for $n>3$ further assume $\Sigma$ is connected.

\noindent 		Suppose there exists an $f$-static potential $V\in C^\infty(M)$ satisfying
		\[
		V>0\ \text{on }M\setminus\Sigma,\qquad V=0\ \text{on }\Sigma,\qquad V\to 1\ \text{at infinity}.
		\]

	\noindent 	Then $(M^n,g,e^{-f}dV_g)$ is $f$-Schwarzschild of mass $m=\m_f(g)$.
	\end{thm}
	\newpage
	Many other geometric quantities have natural weighted versions that fit together within a coherent weighted manifold framework (see Table 1 of \cite{BaldaufOzuch22}, for example). This leads to natural definitions of weighted minimal surfaces, weighted outer-minimising surfaces (see Definition \ref{def-weighted-min}), and to conjecture a weighted Riemannian Penrose inequality. However, we show this follows immediately from the conformal transformation discussed above.
	\begin{thm}\label{thm-weightedPenrose-intro}
		Let $(M^n,g,e^{-f}dV_g)$ be a weighted asymptotically flat manifold of dimension $3\le n\le 7$ containing a closed $f$-outer-minimising $f$-minimal hypersurface $\Sigma$. Assume $S_f\ge 0$, then
		\begin{equation}\label{eq-weightedPenrose}
			m_f(g)\;\ge\;\frac12\left(\frac{A_f(\Sigma)}{\omega_{n-1}}\right)^{\!\frac{n-2}{n-1}}.
		\end{equation}
		Furthermore, if we also assume that $M$ is spin\footnote{Recall $n=3$ implies spin automatically.}, then equality holds in \eqref{eq-weightedPenrose} if and only if $(M^n,g,e^{-f}dV_g)$ is an $f$-Schwarzschild manifold.
	\end{thm}

	We remark that it appears as though much of what one might want to study in connection to this weighted mass ultimately can be reduced to the unweighted situation by means of this straightforward conformal transformation.

