The split simple real Lie group $G=G_{2(2)}$ has a unique (up to conjugation) parabolic subgroup $P$ whose unipotent radical $N$ is a $5$-dimensional Heisenberg group. Let $P=MAN$ be a Langlands decomposition, then $M$ has two connected components and we denote by $\sgn:M\to M/M_0\simeq\{\pm1\}$ the non-trivial character of $M$. The characters $\chi_s$ of $A$ are parameterized by $s\in\CC$, and we form the degenerate principal series representations
$$ \pi_{\varepsilon,s} = \Ind_P^G(\sgn^\varepsilon\otimes\chi_s\otimes1) \qquad (\varepsilon\in\ZZ/2\ZZ=\{0, 1\}, s\in\CC). $$
The parameterization is chosen such that $\pi_{\varepsilon,s}$ is unitary for $s\in\frac{3}{2}+i\RR$ and that $\pi_{0,s}$ contains the trivial representation as a subrepresentation resp. quotient for $s=0$ resp. $s=3$.

By the general theory of Knapp and Stein, there exists a meromorphic family $A(\varepsilon,s)$ of intertwining operators $\pi_{\varepsilon,s}\to\pi_{\varepsilon,3-s}$. Together with the irreducibility of $\pi_{\varepsilon,s}$ for $s\in(1,2)$ this immediately yields the complementary series:

\begin{thmalph}[see Propositions~\ref{prop:ladderker} and \ref{prop:doubleladderker}]\label{thmintroC}
 \begin{itemize}
 \item The ladder representation $\pi_{\mathrm{min}}$ of $G$ is the kernel of the intertwining operator $A(1,s)$ at $s=\frac{2}{3}$.
 \item The double ladder representation $\pi_{\mathrm{small}}$ of $G$ is the kernel of the intertwining operator $A(0,s)$ at $s=\frac{1}{3}$.
 \end{itemize}
\end{thmalph}

\begin{thmalph}[see Theorems~\ref{thm:LDS} and \ref{thm:QDS}]\label{thmintroD}
 \begin{itemize}
 \item The limit of discrete series $\pi_4^{\textup{GW}}$ is isomorphic to the kernel of the intertwining operator $A(\varepsilon,s)$ for $s=2$, $\varepsilon\equiv1\pmod2$.
 \item The quaternionic discrete series representation $\pi^{\textup{GW}}_k$ ($k\geq6$ even) is isomorphic to the subrepresentation of $\pi_{\varepsilon,s}$ for $s=\frac{k}{2}$, $\varepsilon\equiv\frac{k}{2}+1\pmod2$, consisting of those vectors on which the intertwining operator $A(\varepsilon,s')$ vanishes of order two at $s'=s$.
 \end{itemize}
\end{thmalph}

\begin{proposition}
\label{prop:irredtriv}
The representation $\pi_{0,s}$ is reducible if and only if $s$ or $\tilde{s}=3-s$ is contained in $\ZZ_{\geq2}\cup(2+\frac{2}{3}\ZZ_{\geq0})$.
\end{proposition}

Next we show that all other $K$-isotypic components are generated from $(0,0)$. We prove by induction over $n$ that the isotypic component of $\sigma(n,m)$ is contained in the subrepresentation $V$ generated by $\sigma(0,0)$ for all $m\in\ZZ_{\geq0}$. For $n=0$ and $n=2$, the $K$-type $\sigma(n,m)$ has multiplicity one, so by the previous argument it is contained in $V$, and for $n=1$ the $K$-type $\sigma(n,m)$ does not occur in $I(s)$. This shows the claim for $n=0,1,2$, which represents the induction start. For the induction step consider a $K$-type $\sigma(n+3,m+1)$ for $n,m\in\ZZ_{\geq0}$. (Note that $\sigma(n+3,0)$ is a multiplicity-one $K$-type and therefore contained in $V$ by the previous arguments, so we may assume $m\geq0$.) We use Proposition~\ref{prop:v_action} to show that every vector in $(\Gamma_{n+3}\boxtimes\Gamma_{m+1})^L$ can be reached by $R_s(\sigma(n',m'))$ with $0\leq n'<n+3$ and $m'\geq0$. By Lemma~\ref{basemultspace}, when $n+m \equiv 0 \pmod 4$ then $\{v_{n,m}(s,k):k=0,\ldots,[\frac{a(n,m)}{2}]\}$ is a basis for $(\Gamma_n \boxtimes \Gamma_m)^L$, and when $n+m \equiv 2 \pmod 4$, the vectors $\{v_{n,m}'(s,k):k=0,\ldots,[\frac{a(n,m)-1}{2}]\}$ form a basis of $(\Gamma_n \boxtimes \Gamma_m)^L$. We treat the following four cases separately:
\begin{enumerate}[label=(\alph*)]
 \item If $n+m \equiv 0 \pmod 4$ and $a(n,m)$ is even, then $a(n+3,m+1)=a(n,m)+1$ and hence the dimensions of $(\Gamma_n \boxtimes \Gamma_m)^L$ and $(\Gamma_{n+3} \boxtimes \Gamma_{m+1})^L$ agree. By \eqref{prop:v_action1} the space $(\Gamma_{n+3} \boxtimes \Gamma_{m+1})^L$ is reached from $(\Gamma_n\boxtimes\Gamma_m)^L$ if
 $$ (2k + r(n,m) + a(n,m) + s) \neq 0 \qquad \mbox{for all }0 \leq k \leq \left[\frac{a(n,m)}{2}\right], $$
 which is the case since $s \notin \mathbb{Z}$.
 \item If $n+m \equiv 2 \pmod 4$ and $a(n,m)$ is odd, then the same argument as in (a), using \eqref{prop:v_action2} instead of \eqref{prop:v_action1}, shows that $(\Gamma_{n+3} \boxtimes \Gamma_{m+1})^L$ is reached from $(\Gamma_n \boxtimes \Gamma_m)^L$.
 \item If $n+m \equiv 0 \pmod 4$ and $a(n,m)$ is odd, the first $[\frac{a(n,m)}{2}]=\frac{a(n,m)-1}{2}$ vectors in $(\Gamma_{n+3} \boxtimes \Gamma_{m+1})^L$ are reached from $(\Gamma_{n} \boxtimes \Gamma_m)^L$ by the same argument as in (a). We have to show that also the last vector $v_{n+3,m+1}(s,\frac{a(n,m)+1}{2})$ can be reached from lower $K$-types. Assume first that $a(n+3,m+1) = a(n+2,m) + 1 = a(n,m)+1$. Then we also reach the final vector $v_{m+3,n+1}(s,\frac{a(n,m)+1}{2})$ from $(\Gamma_{n+2} \boxtimes \Gamma_m)^L$ using \eqref{prop:v_action4} if
 $$ 0 \neq 3s + r(n+2,m) - a(n+2,m) + m +6\frac{a(n,m)-1}{2} = 3s + \frac{m+n}{2}+m-2. $$
 Since $a(n,m)$ is odd and $n+m\equiv0\pmod2$, a case by case analysis of $n\mod3$ shows that $m$ must be odd, so the above condition is satisfied since $\tilde{s}\not\in2+\frac{2}{3}\ZZ_{\geq0}$, i.e. $s\not\in1+\frac{2}{3}\ZZ_{\leq0}$.
 If not $a(n+3,m+1) = a(n+2,m) + 1$, then we must have $a(n+3,m+1) = a(n,m+2) + 1$, and in this case we can use \eqref{prop:v_action6} to conclude that the last vector $v_{m+3,n+1}(s,\frac{a(n,m)+1}{2})$ is reached from $(\Gamma_{n+2}\boxtimes\Gamma_m)^L$ since $s\not\in\ZZ$.
 \item The case where $n+m\equiv2\pmod4$ and $a(n,m)$ is even is treated similarly as in (c).\qedhere
\end{enumerate}
\end{proof}

\begin{proposition}
\label{prop:sgnirred}
The representation $\pi_{1,s}$ is reducible if and only if $s$ or $\tilde{s}=3-s$ is contained in $\ZZ_{\geq2}\cup(\frac{7}{3}+\frac{2}{3}\ZZ_{\geq0})$.
\end{proposition}

Fix $k\geq6$ and let $s=\frac{k}{2}$, $\varepsilon=\frac{k}{2}+1$. We know that the $K$-types in $I(\varepsilon,s)$ are of the form $(3m,m+2r)$, $(3m+2,m+2r)$, $(3m+4,m+2r)$ and $(3m+2r,m)$ with $r,m\in\ZZ_{\geq0}$.
\begin{enumerate}[label=(\Alph*)]
 \item\label{CaseA} The $K$-types $(3m+j,m+2r)$ ($j=0,2,4$) are generically obtained from the multiplicity-one $K$-types
 $B = \{ (j,a) \}_{2r \leq a \leq 2(r+m), a \ \mathrm{even}, \ \frac{a}{2} \equiv s \mod 2 }$. Note that the multiplicity-one $K$-type $(j,a)$ only appears in $I(\varepsilon,s)$ when $j+a \equiv 2 (s+1) \mod 4$. Here we only need the maps $T_{n',m'}^{n'+3,m'+1}(z)$, and for the last basis vector also $T_{n',m'}^{n'+3,m'-1}(z)$. As in the proof of Theorem~\ref{thm:LDS}, we choose for a $K$-type $(3m+j,m+2r)$ vectors $v_i$ in the multiplicity-one $K$-types in $B$ as well as linear maps $T_i(z)$ which are concatenations of maps of the form $T_{n',m'}^{n'+3,m'+1}(z)$ and $T_{n',m'}^{n'+3,m'+1}(z)$, such that $(T_i(z)v_i)_i$ is a basis of the multiplicity space of $(3m+j,m+2r)$ for generic $z\in\CC$.
 \item\label{CaseB} For the $K$-types $(3m+2r,m)$, we only need the maps $T_{n',m'}^{n'+3,m'+1}(z)$ and $T_{n',m'}^{n'+1,m'+1}$ and the multiplicity-one $K$-types $C = \{ (a,0) \}_{2r \leq a \leq 2(r+m), a \ \mathrm{even}, \ \frac{a}{2} \equiv s \mod 2 }$. In a similar way, we let $(T_i(z)v_i)_i$ be a basis of the multiplicity space of $(3m+2r,m)$ for generic $z$.
\end{enumerate}

post_theorem_intro_text:
By the general theory of Knapp and Stein, there exists a meromorphic family $A(\varepsilon,s)$ of intertwining operators $\pi_{\varepsilon,s}\to\pi_{\varepsilon,3-s}$. Together with the irreducibility of $\pi_{\varepsilon,s}$ for $s\in(1,2)$ this immediately yields the complementary series:

\begin{coralph}[see Corollary~\ref{cor:ComplementarySeries}]\label{corintroB}
    For $\varepsilon\in\mathbb{Z}/2\mathbb{Z}$ and $s\in\mathbb{R}$ the representation $\pi_{\varepsilon,s}$ is irreducible and unitarizable if and only if $s\in(1,2)$.
\end{coralph}

By embedding $\pi_{\varepsilon,s}$ into a principal series representation induced from a minimal parabolic subgroup of $G$, these complementary series representations can be identified with irreducible subrepresentations/quotients of the principal series at the edges of its complementary series as obtained by Vogan~\cite{Vog94}.
See Section
\ref{coml-series-sec} below.

It was observed by Kable~\cite[Theorem 4.8]{Kab12} that the minimal representation of $G$ is a unitarizable subrepresentation of $\pi_{1,s}$ for $s=\frac{2}{3}$, and it is given by the joint kernel of a system of conformally invariant differential operators. This representation is also referred to as \emph{ladder representation} since its $K$-types are contained in a single line. Kable also showed in \cite[Theorem 4.10]{Kab12} that the kernel of another system of conformally invariant differential operators in $\pi_{0,s}$ for $s=\frac{1}{3}$ is a non-unitary subrepresentation $\pi_{\mathrm{small}}$ whose $K$-types are contained in two parallel lines, which is why we call it \emph{double ladder representation}. We show that both subrepresentations are equal to the kernel of the corresponding intertwining operator $A(\varepsilon,s)$, when suitably normalized.

\begin{thmalph}[see Propositions~\ref{prop:ladderker} and \ref{prop:doubleladderker}]\label{thmintroC}
    \begin{itemize}
        \item The ladder representation $\pi_{\mathrm{min}}$ of $G$ is the kernel of the intertwining operator $A(1,s)$ at $s=\frac{2}{3}$.
        \item The double ladder representation $\pi_{\mathrm{small}}$ of $G$ is the kernel of the intertwining operator $A(0,s)$ at $s=\frac{1}{3}$.
    \end{itemize}
\end{thmalph}

Finally, we identify some quaternionic discrete series representations of $G$ as subrepresentations of $\pi_{\varepsilon,s}$. The fact that these are subrepresentations was observed earlier by Yoshinaga~\cite{Yoshi98}. We relate them to the kernel of the intertwining operator $A(\varepsilon,s)$.

Recall from \cite{GW96} a family of irreducible unitary representations $\pi_k^{\textup{GW}}$, $k\geq2$. For $k\geq5$ they belong to the discrete series and for $k=4$ the representation is a limit of discrete series.

\begin{thmalph}[see Theorems~\ref{thm:LDS} and \ref{thm:QDS}]\label{thmintroD}
    \begin{itemize}
        \item The limit of discrete series $\pi_4^{\textup{GW}}$ is isomorphic to the kernel of the intertwining operator $A(\varepsilon,s)$ for $s=2$, $\varepsilon\equiv1\pmod2$.
        \item The quaternionic discrete series representation $\pi^{\textup{GW}}_k$ ($k\geq6$ even) is isomorphic to the subrepresentation of $\pi_{\varepsilon,s}$ for $s=\frac{k}{2}$, $\varepsilon\equiv\frac{k}{2}+1\pmod2$, consisting of those vectors on which the intertwining operator $A(\varepsilon,s')$ vanishes of order two at $s'=s$.
    \end{itemize}
\end{thmalph}

\subsection*{Method of proof}

The restriction of the degenerate principal series representations $\pi_{\varepsilon,s}$ to $K$ is not multiplicity-free. This makes it difficult to study the structure of the underlying $(\mathfrak{g}_\mathbb{C},K)$-module, because the transition between two $K$-types by the Lie algebra action is expressed in terms of a linear map between the multiplicity spaces. Building on the work of Kable~\cite{Kab12}, we determine these maps explicitly (see Proposition~\ref{Mmatrix}) and identify a convenient basis of every multiplicity space that is adapted to the transition between $K$-types by the Lie algebra action (see Section~\ref{sec:MultSpaceBasis}). It turns out that the action of the Knapp--Stein intertwining operators on each $K$-isotypic component is upper triangular with respect to this basis, and we are able to determine the corresponding eigenvalues (see Corollary~\ref{cor:ClosedFormulasIntertwinerMultOneKtypes} and Theorem~\ref{thm:ClosedFormulasIntertwinerEigenvalues}). This allows us to prove Theorem~\ref{thmintroA} and deduce Corollary~\ref{corintroB}. The proof of Theorems~\ref{thmintroC} and \ref{thmintroD} also uses the explicit form of the eigenvalues together with a detailed analysis of the transition between certain $K$-types.
As far as we know
our  method
of constructing
 bases where 
 the Knapp-Stein
 operator acts as upper triangular matrices has
 not appeared before, and it may be useful
 for studying other principal
 series.

\subsection*{Other related works}

This work builds on Kable's paper~\cite{Kab12} where an abstract formula for the Lie algebra action was obtained and where the first vector in our basis of the multiplicity spaces appears. We also view our paper as an attempt to treat the last missing case in the algebraic study of degenerate principal series begun by the last named author~\cite{Zha22,Zha23}. More analytic aspects of the same class of degenerate principal series can be found in \cite{FWZ22}, where the Knapp--Stein operators were studied using the Heisenberg group Fourier transform, and in \cite{Fra22}, where an $L^2$-model for the the minimal representation is constructed also using the Heisenberg group Fourier transform.

