ref_dict.graded-derived-nakayama:
\begin{proposition}\label{graded-derived-nakayama}
In the setting of \Cref{NotationDerivedQuot}, assume that \(M\) is derived gradedwise \(I\)-complete.
Let $f_1,\ldots,f_r$ be homogeneous generators of $I$, and let $m \in \Z$.
\begin{enumerate}
    \item If $\pi_i(M/^L(f_1,\ldots,f_r))=0$ for $i<m$, then $\pi_i(M)=0$ for $i<m$.
    \item If \(\pi_i(M \Lgrotimes_R R/I) = 0\) for \(i < m\), then \(\pi_i(M) = 0\) for \(i < m\).
\end{enumerate}
\end{proposition}

ref_dict.LimitCommutative:
\begin{theorem} \label{LimitCommutative}
    Let $R$ be a $G$-graded ring and let $I$ be a finitely generated homogeneous ideal of \(R\).
    Take a diagram \(\{M_j\}_{j \in J} \colon J \to \mcalD_{\graded{G}}^{\comp{I}}(R)\) indexed by a (not necessarily small) simplicial set \(J\).
    Assume the existence of the limits of the diagrams
    \begin{align*}
        \{\mcalF^I(M_j)\}_{j \in J} = \{\dcomp{I}{M_j}\}_{j \in J} & \colon J \to \mcalD^{\comp{I}}(R); \quad j \mapsto \dcomp{I}{M_j} \quad \text{and} \\
        \{\mcalT^I(\mcalF^I(M_j))\} = \{\dcomp{I}{M_j}\abracket{G}\}_{j \in J} & \colon J \to \mcalD^{\comp{I}}(R); \quad j \mapsto \dcomp{I}{M_j} \abracket{G}.
    \end{align*}
    If the natural morphism
    \begin{equation} \label{AssumptionIsomMorphism}
        (\lim_{J} \dcomp{I}{M_j})\abracket{G} \to \lim_{J}(\dcomp{I}{M_j}\abracket{G})
    \end{equation}
    is an isomorphism in \(\mcalD^{\comp{I}}(R)\), then the limit $\grlim_{J} M_j$ of $\{M_j\}_{j \in J}$ exists in $\mcalD_{\graded{G}}^{\comp{I}}(R)$, and the natural morphism
    \begin{equation*}
        \mcalF^I(\grlim_{J} M_j) = \dcomp{I}{\grlim_{J} M_j} \to \lim_{J} \dcomp{I}{M_j} = \lim_{J} \mcalF^I(M_j)
    \end{equation*}
    is an isomorphism in \(\mcalD^{\comp{I}}(R)\), i.e., the limit is preserved by the functor \(\mcalF^I\).
\end{theorem}

ref_dict.DerivedGradedCatEquiv:
\begin{proposition} \label{DerivedGradedCatEquiv}
    There exists an (essentially unique) \(t\)-exact equivalence of stable \(\infty\)-categories
    \begin{equation*}
        \eta \colon \mcalD(\Mod_{\graded{G}}(R)) \xrightarrow{\simeq} \mcalD_{\graded{G}}(R),
    \end{equation*}
    which makes the following diagram commutative:
    \begin{center}
        \begin{tikzcd}
            \mcalD(\Mod_{\graded{G}}(R)) \arrow[d] \arrow[r, "\eta"] & \mcalD_{\graded{G}}(R) \arrow[d] \\
            \mcalD(\Mod(R)) \arrow[r, "\simeq"]                           & \mcalD(R)                          
        \end{tikzcd}
    \end{center}
    where the vertical functors are forgetful functors and the lower equivalence is given in \cite[Proposition 7.1.1.15 and Remark 7.1.1.16]{lurie2017Higher}.
\end{proposition}

ref_dict.PropertiesDerivedGradedModules:
\begin{proposition} \label{PropertiesDerivedGradedModules}
    On \(\mcalD_{\graded{G}}(R)\), we have the following properties.
    \begin{enumerate}
        \item \label{PresentabilityDgrR} The \(\infty\)-category \(\mcalD_{\graded{G}}(R)\) is presentable and stable.
        \item \label{LimitsColimitsDgrR} The canonical functor \(\mcalD_{\graded{G}}(R) \to \mcalD_{\graded{G}}(\setZ)\) induced from \(\setZ \to R\) is conservative and preserves all limits and colimits. In particular, its left adjoint is given by the base change \(- \Lgrotimes_{\setZ} R \colon \mcalD_{\graded{G}}(\setZ) \to \mcalD_{\graded{G}}(R)\) used by the symmetric monoidal structure on \(\mcalD_{\graded{G}}(\setZ)\).
        \item \label{ClosedMonoidalDgrR} The symmetric monoidal structure on \(\mcalD_{\graded{G}}(\setZ)\) induces a symmetric monoidal structure \(- \Lgrotimes_R -\) on \(\mcalD_{\graded{G}}(R)\) and it is closed, i.e., for any \(M \in \mcalD_{\graded{G}}(R)\), the endofunctor \(- \Lgrotimes_R M\) on \(\mcalD_{\graded{G}}(R)\) admits a right adjoint \(\grmapspt_R(M, -)\).
        \item \label{tStructureDgrR} Using the \(t\)-structure on \(\mcalD_{\graded{G}}(\setZ)\) in \Cref{PropertiesDgrZ}\Cref{tStructureDgrZ}, we can equip \(\mcalD_{\graded{G}}(R)\) with a left and right complete accessible \(t\)-structure such that \(M \in \mcalD_{\graded{G}}(R)\) is connective (resp., coconnective) if and only if \(M_g \in \mcalD(\setZ)\) satisfies \(\pi_i(M_g) = 0\) for any \(i < 0\) (resp., \(i > 0\)) for all \(g \in G\).
        \item \label{ConnectivePartDgrR} The connective part \(\mcalD_{\graded{G}, \geq 0}(R)\) is stable under small colimits and extensions. The heart \(\mcalD_{\graded{G}}^{\heartsuit}(R)\) of this \(t\)-structure is isomorphic to the abelian category \(\Mod_{\graded{G}}(R)\) of (discrete) \(G\)-graded \(R\)-modules.
        \item \label{HomotopyGroupsDgrR} The \(t\)-structure inherits the homotopy groups \(\pi_i(M)\) of \(M \in \mcalD_{\graded{G}}(R)\) whose underlying \(G\)-graded abelian group is \(\bigoplus_{g \in G} \pi_i(M_g)\) by using the homotopy group \(\pi_i(M_g)\) on \(\mcalD(\setZ)\).
        \item \label{ForgetfulFunctorDgrR} The functor \(\mcalD_{\graded{G}}(\setZ) \to \mcalD(\setZ)\) in \Cref{PropertiesDgrZ}\Cref{ForgetfulFunctorDgrZ} induces a forgetful functor
        \begin{equation*}
            \theta = \theta_R \colon \mcalD_{\graded{G}}(R) \to \mcalD(R); \quad M = (M_g)_{g \in G} \mapsto \bigoplus_{g \in G} M_g,
        \end{equation*}
        which is conservative, symmetric monoidal, \(t\)-exact, and preserves all colimits.
    \end{enumerate}
\end{proposition}

ref_dict.ExistenceRetracts:
\begin{theorem} \label{ExistenceRetracts}
    Let \(R\) be a \(G\)-graded ring.
    Write the forgetful functor \(\theta \colon \mcalD_{\graded{G}}(R) \to \mcalD(R)\), which is given in \Cref{PropertiesDerivedGradedModules}\Cref{ForgetfulFunctorDgrR}.
    Then \(\theta\) admits a morphism retraction, i.e., the morphism
    \begin{equation*}
        \theta_{M, N} = \theta_{M, N}^R \colon \Map_{\mcalD_{\graded{G}}(R)}(M, N) \to \Map_{\mcalD(R)}(\theta(M), \theta(N))
    \end{equation*}
    in \(\Ani\) given by \(\theta\) has a retraction
    \begin{equation} \label{RetractionMappingSpaceGraded}
        r = r_{M, N} = r_{M, N}^{R} \colon \Map_{\mcalD(R)}(\theta(M), \theta(N)) \to \Map_{\mcalD_{\graded{G}}(R)}(M, N)
    \end{equation}
    satisfying the commutative diagrams (\ref{DiagramRetractionMappingSpace}), (\ref{DiagramRetractionMappingSpaceConverse}), and (\ref{DiagramRetractionMappingSpaceTensor}).
\end{theorem}

ref_dict.def-coaction:
\begin{definition}\label{def-coaction}
Let $R$ be a ring.
\begin{enumerate}
\item
Let
\[
R[G]\defeq \bigoplus_{g \in G} R \cdot t^g
\]
be the group ring with multiplication given by $t^g \cdot t^h=t^{g+h}$, namely, \(R[G]\) is the group ring of \(G\) over \(R\).
Then we have a natural isomorphism $R[G] \simeq \Z[G] \otimes_{\Z} R$.
Furthermore, $R[G]$ has a structure of a coalgebra over $R$ with
\begin{align*}
\begin{alignedat}{2}
\Delta &\colon R[G] \to R[G] \otimes_R R[G]
&\qquad t^g &\mapsto t^g \otimes t^g, \\
e      &\colon R[G]\to R
&\qquad t^g   &\mapsto 1, \\
\iota  &\colon R[G] \to R[G]
&\qquad t^g &\mapsto t^{-g}.
\end{alignedat}
\end{align*}

\item
Let $R$ be a ring.
A \emph{$\Z[G]$-coaction} on $R$ is a ring homomorphism
\[
\rho \colon R \to R \otimes_{\Z} \Z[G]\simeq R[G]
\]
such that the following diagrams commute:
\begin{center}
\begin{minipage}{0.45\textwidth}
\[
\begin{tikzcd}
    R \arrow[r,"\rho"] \arrow[d,"\rho"'] 
        & R \otimes_{\Z} \Z[G] \arrow[d,"\id \otimes \Delta"] \\
    R \otimes_{\Z} \Z[G] \arrow[r,"\rho \otimes \id"] 
        & R \otimes_{\Z} \Z[G] \otimes_{\Z} \Z[G]
\end{tikzcd}
\]
\end{minipage}
\hspace{0.5cm}
\begin{minipage}{0.35\textwidth}
\[
\begin{tikzcd}
    R \arrow[r,"\rho"] \arrow[d,equal] 
        & R \otimes_{\Z} \Z[G] \arrow[ld,"\id \otimes e"] \\
    R.
\end{tikzcd}
\]
\end{minipage}
\end{center}
By abuse of notation, we denote by $e$ the ring homomorphism
\[
R[G] \simeq R \otimes_{\Z} \Z[G] \xrightarrow{\id \otimes e} R .
\]
\end{enumerate}
\end{definition}

full_context:
Graded modules over a graded ring appear in various mathematical contexts, such as algebraic geometry, commutative algebra, algebraic topology, and representation theory; For instance, one of the most fundamental forms of correspondence is that between graded modules on a graded ring and quasi-coherent sheaves on the projective spectrum of it.

To provide a flexible framework for modern applications, one effective approach is to generalize these notions to an \(\infty\)-categorical setting.
In this direction, previous studies have successfully developed the theory of derived \(\setZ\)-graded modules over rings with trivial grading particularly for the study of filtrations and Rees constructions (see, for example, \cites{lurie2015Rotation,antieau2025Filtrations,moulinos2021Geometry,raksit2026Hochschild}\footnote{More generally, they consider the \(\infty\)-category of \(\setZ\)-graded objects of a given \(\infty\)-category.}).
However, many geometric contexts---such as projective varieties in mixed characteristic---require a theory that accommodates both nontrivial gradings on a base ring and general grading groups including $\setZ^2$ and $\setZ[1/p]$.

For the purpose of this introduction, let \(R\) be a \(G\)-graded ring for a torsion-free abelian group \(G\) and let \(I\) be a finitely generated homogeneous ideal of \(R\).
This paper introduces the $\infty$-category $\mcalD_{\graded{G}}(R)$ of \emph{derived $G$-graded modules} and its full subcategory \(\mcalD_{\graded{G}}^{\comp{I}}(R)\) of \emph{derived gradedwise \(I\)-complete}\footnote{In our previous research \cite{ishizuka2025Graded}, we developed a graded variant of perfectoid rings, \emph{graded perfectoid rings}. Being a \(G\)-graded ring \(R\) graded perfectoid requires \(1/p \in G\) except for trivial cases, so we need to consider general \(G\) rather than just \(\setZ\).
Moreover, to define graded perfectoid rings, we need the notion of gradedwise completeness, which is a counterpart of \(p\)-adic completeness of perfectoid rings.
The content of this paper is a foundational step toward studying ``absolute graded perfectoidization'' in our forthcoming work \cite{ishizuka2026Absolute}.} objects and establish the foundational properties of these categories that are familiar from the non-graded or non-derived case:

\begin{enumerate}
 \item The category \(\mcalD_{\graded{G}}(R)\) is a compactly generated stable closed symmetric monoidal \(\infty\)-category (\Cref{PropertiesDerivedGradedModules}).
 \item It is equivalent to the derived \(\infty\)-category \(\mcalD(\Mod_{\graded{G}}(R))\) of \(G\)-graded \(R\)-modules (\Cref{DerivedGradedCatEquiv}).
 \item The mapping space of \(\mcalD_{\graded{G}}(R)\) can be realized as the fiber product of mapping spaces of \(\mcalD(R)\) and \(\mcalD_{\graded{G}}(\setZ)\) over those of \(\mcalD(\setZ)\) (\Cref{FiberMappingSpaceDgr}).
 \item The morphism of mapping spaces \(\Map_{\mcalD_{\graded{G}}(R)}(M, N) \to \Map_{\mcalD(R)}(M, N)\) admits a retraction satisfying some compatibility with tensor products and compositions (\Cref{ExistenceRetracts}).
 \item The inclusion functor \(\mcalD_{\graded{G}}^{\comp{I}}(R) \hookrightarrow \mcalD_{\graded{G}}(R)\) admits a left adjoint, which is called the derived gradedwise completion functor \(\dgrcomp{I}{-}\) (\Cref{DerivedGradedwiseComp}).
 \item The functor \(\dgrcomp{I}{-}\) can be written as the limit of derived quotients (\Cref{ind-generator}).
 \item A Nakayama-type result holds for derived gradedwise completeness (\Cref{graded-derived-nakayama}).
\end{enumerate}

Our goal is not only to establish these foundations but also to clarify the relationship between derived graded modules and derived comodules.
Classically, a $G$-grading on an abelian group corresponds to a $\setZ[G]$-coaction; for example, $\setZ$-graded abelian groups correspond to abelian groups equipped with a $\setG_m$-action.
We obtain a generalization of this correspondence in our setting:

Our goal is not only to establish these foundations but also to clarify the relationship between derived graded modules and derived comodules.
Classically, a $G$-grading on an abelian group corresponds to a $\setZ[G]$-coaction; for example, $\setZ$-graded abelian groups correspond to abelian groups equipped with a $\setG_m$-action.
We obtain a generalization of this correspondence in our setting:

\noindent
One of the key ingredients in the proof of \Cref{intro} is the verification of a sufficient condition (\Cref{LimitCommutative}) for a diagram whose limit is preserved under the functor\footnote{Note that the functor $\mcalF^I$ does not preserve limits in general (see \Cref{NonIsomGradedLimit}).}
\[
\mcalF^I \colon \mcalD_{\graded{G}}^{\comp{I}}(R) \xrightarrow{\mathrm{forget}} \mcalD(R) \xrightarrow{\dcomp{I}{-}} \mcalD^{\comp{I}}(R).
\]
By combining this criterion with the Barr--Beck--Lurie theorem (\Cref{BarrBeckLurie}), we obtain \Cref{intro}.

\begin{theorem}[{cf. \cite[Proposition 4.7.3.3 and Theorem 4.7.3.5]{lurie2017Higher}\footnote{We will use its comodule version. See, for example, \cite[Proposition 2.2 and Theorem 2.3]{banerjee2017Galois}.}}] \label{BarrBeckLurie}
 Let \(\mcalF \colon \mcalC \to \mcalD\) be a functor of \(\infty\)-categories admitting a right adjoint \(\mcalG \colon \mcalD \to \mcalC\).
 Then the composition \(\mcalT \defeq \mcalF \circ \mcalG\) becomes an (endomorphism) comonad on \(\mcalD\) and the left coaction \(\mcalF \to \mcalT \circ \mcalF\) of \(\mcalT\) on \(\mcalF\) is just the unit \(\id_{\mcalC} \to \mcalG \circ \mcalF\) of the adjunction \((\mcalF, \mcalG)\) composed with \(\mcalF\).
 This gives rise to a comparison functor
 \begin{equation*}
 \mcalF' \colon \mcalC \to \coMod_{\mcalT}(\mcalD)
 \end{equation*}
 of \(\infty\)-categories whose composition with the forgetful functor \(\coMod_{\mcalT}(\mcalD) \to \mcalD\) is equivalent to \(\mcalF\), where \(\coMod_{\mcalT}(\mcalD)\) is the \(\infty\)-category of comodules over \(\mcalT\) in \(\mcalD\).
 If \(\mcalF'\) is an equivalence of \(\infty\)-categories, then we say that the functor \(\mcalF\) is \emph{comonadic}.

\begin{definition} \label{DefMG}
 Let \(R\) be a \(G\)-graded ring.
 Let \(R[G]\) be the coalgebra over \(R\) with the \(\setZ[G]\)-coaction \(\rho_R \colon R \to R[G]\) defined in \Cref{def-coaction}.
 We define a functor \(M \to M[G]\) by the composition
 \begin{equation} \label{DefMGEquation}
 \mcalD(R) \xrightarrow{- \otimes^L_R R[G]} \mcalD(R[G]) \xrightarrow{\rho_{R, *}} \mcalD(R); \quad M \mapsto M \otimes^L_R R[G] \mapsto \rho_{R, *}(M \otimes^L_R R[G]) \eqdef M[G],
 \end{equation}
 where the \(- \otimes^L_R R[G]\) is the derived base change along the canonical morphism \(R \to R[G]\) sending \(r \mapsto r t^0\) (not \(\rho_R\)) and \(\rho_{R, *}\) is the restriction of scalars along \(\rho_R\).

Using the dual of \Cref{DefModuleOverMonad}, we have a right adjoint \((\mcalG^I)''\) of the forgetful functor \((\mcalF^I)'' \colon \coMod_G^{\comp{I}}(R) \to \mcalD^{\comp{I}}(R)\) and the underlying functor of the comonad \(\mcalT^I\) is equivalent to the composition \((\mcalF^I)'' \circ (\mcalG^I)''\).
 By \Cref{MorphismsAdjoint}, any object \(\widetilde{M}\) of \(\coMod_G^{\comp{I}}(R)\) admits an underlying object \(M \defeq (\mcalF^I)''(\widetilde{M})\) of \(\mcalD^{\comp{I}}(R)\) and a morphism
 \begin{equation*}
 \rho_M \colon M \to (\mcalF^I)''((\mcalG^I)''(\widetilde{M})) \xrightarrow{\simeq} \mcalT^I(M) \overset{\eqref{ComonadRepresentation}}{=} M\abracket{G}
 \end{equation*}
 in \(\mcalD^{\comp{I}}(R)\) and a commutative diagram representing the coaction axioms of \(R[G]\)-comodules (with infinitely many higher homotopies).
 For example, \eqref{DiagramMonadAssociativeUnital} and \eqref{DiagramMonadUnit} tell us that commutative diagrams
 \begin{equation} \label{DefComoduleGradedModulesDiagram}
 \begin{tikzcd}
 M \arrow[r, "\rho_M"] \arrow[d, "\rho_M"'] & \mcalT^I(M) \arrow[d, "\mcalT^I(\rho_M)"] & & M \arrow[r, "\rho_M"] \arrow[rd, "\id_M"'] & \mcalT^I(M) \arrow[d, "e_M \defeq e(M)"] \\
 \mcalT^I(M) \arrow[r, "\Delta(M)"] & \mcalT^I \circ \mcalT^I(M) & & & M 
 \end{tikzcd}
 \end{equation}
 in \(\mcalD^{\comp{I}}(R)\) are given as datum, which represent the coassociativity and counit axioms, respectively.
 For simplicity, we will write such object \(\widetilde{M}\) as \((M, \rho_M)\) and \(\rho_M\) is called an \emph{\(I\)-formal coaction} of \(M\).
\end{definition}

\begin{remark} \label{RemarkComoduleNotation}
 The notation \(\coMod_G^{\comp{I}}(R)\) does \emph{NOT} mean the \(\infty\)-category of comodules over the derived \(I\)-complete coalgebra \(R\abracket{G}\) in \(\mcalD^{\comp{I}}(R)\).
 Actually, the defining comonad \(\mcalT^I\) is just
 \begin{equation*}
 M \mapsto \dcomp{I}(\rho_{R, *}(M \otimes^L_R R\abracket{G}))
 \end{equation*}
 and not \(M \to M \widehat{\otimes}^L_R R\abracket{G}\).

\begin{theorem} \label{Pullback_lemma}
 Let \(R\) be a \(G\)-graded ring and let \(I\) be a finitely generated homogeneous ideal of \(R\).
 Take an object \((M, \rho)\) of \(\coMod_G^{\comp{I}}(R)\).
 For each $g \in G$, we define $M_g \in \mcalD(\Z)$ by the pullback diagram \eqref{Pullback_g} in \Cref{GradedPartComodule}.
 Then, there exists a morphism \(\rho_{\graded} \colon M_{\graded} \to M[G]\) in \(\mcalD_{\graded{G}}^{\comp{I}}(R)\) and a pullback diagram
 \begin{equation} \label{Pullback_sum}
 \begin{tikzcd}
 M_{\gr} \arrow[r,"\rho_{\gr}"] \arrow[d,"\alpha"] & M[G] \arrow[d,"\beta"] \\
 M \arrow[r,"\rho"] & M\abracket{G}
 \end{tikzcd}
 \end{equation}
 in \(\mcalD(R)\) such that \(\rho_{\graded}\) splits in \(\mcalD_{\graded{G}}(\setZ)\) and the underlying pullback diagram in \(\mcalD(\setZ)\) is
 \begin{equation} \label{Pullback_sum_Z}
 \begin{tikzcd}
 \bigoplus_{g \in G} M_g \arrow[rr, "\bigoplus_{g \in G} \rho_g"] \arrow[d, "\alpha'"] & & \bigoplus_{g \in G} M \cdot t^g \arrow[d, "\beta'"] \\
 M \arrow[rr, "\rho"] & & {M\abracket{G},} 
 \end{tikzcd}
 \end{equation}
 where \(\alpha'\) and \(\beta'\) are morphisms induced from \(\{\alpha_g\}_{g \in G}\) and \(\{\beta_g\}_{g \in G}\), respectively.
 In particular, \(\alpha\) induces an isomorphism
 \begin{equation*}
 \dcomp{I}{M_{\graded}} \xrightarrow{\cong} M
 \end{equation*}
 in \(\mcalD^{\comp{I}}(R)\).
\end{theorem}

expanded_sketch:
One of the key ingredients in the proof of the main theorem is the verification of a sufficient condition ensuring that a diagram whose limit is preserved under the functor
\[
\mcalF^I \colon \mcalD_{\graded{G}}^{\comp{I}}(R) \xrightarrow{\mathrm{forget}} \mcalD(R) \xrightarrow{\dcomp{I}{-}} \mcalD^{\comp{I}}(R).
\]
We first prove the following theorem.
\begin{theorem} \label{LimitCommutative}
    Let $R$ be a $G$-graded ring and let $I$ be a finitely generated homogeneous ideal of \(R\).
    Take a diagram \(\{M_j\}_{j \in J} \colon J \to \mcalD_{\graded{G}}^{\comp{I}}(R)\) indexed by a (not necessarily small) simplicial set \(J\).
    Assume the existence of the limits of the diagrams
    \begin{align*}
        \{\mcalF^I(M_j)\}_{j \in J} = \{\dcomp{I}{M_j}\}_{j \in J} & \colon J \to \mcalD^{\comp{I}}(R); \quad j \mapsto \dcomp{I}{M_j} \quad \text{and} \\
        \{\mcalT^I(\mcalF^I(M_j))\} = \{\dcomp{I}{M_j}\abracket{G}\}_{j \in J} & \colon J \to \mcalD^{\comp{I}}(R); \quad j \mapsto \dcomp{I}{M_j} \abracket{G}.
    \end{align*}
    If the natural morphism
    \begin{equation} \label{AssumptionIsomMorphism}
        (\lim_{J} \dcomp{I}{M_j})\abracket{G} \to \lim_{J}(\dcomp{I}{M_j}\abracket{G})
    \end{equation}
    is an isomorphism in \(\mcalD^{\comp{I}}(R)\), then the limit $\grlim_{J} M_j$ of $\{M_j\}_{j \in J}$ exists in $\mcalD_{\graded{G}}^{\comp{I}}(R)$, and the natural morphism
    \begin{equation*}
        \mcalF^I(\grlim_{J} M_j) = \dcomp{I}{\grlim_{J} M_j} \to \lim_{J} \dcomp{I}{M_j} = \lim_{J} \mcalF^I(M_j)
    \end{equation*}
    is an isomorphism in \(\mcalD^{\comp{I}}(R)\), i.e., the limit is preserved by the functor \(\mcalF^I\).
\end{theorem}
By combining this criterion with the Barr--Beck--Lurie theorem,
\begin{theorem}[{cf. \cite[Proposition 4.7.3.3 and Theorem 4.7.3.5]{lurie2017Higher}\footnote{We will use its comodule version. See, for example, \cite[Proposition 2.2 and Theorem 2.3]{banerjee2017Galois}.}}] \label{BarrBeckLurie}
    Let \(\mcalF \colon \mcalC \to \mcalD\) be a functor of \(\infty\)-categories admitting a right adjoint \(\mcalG \colon \mcalD \to \mcalC\).
    Then the composition \(\mcalT \defeq \mcalF \circ \mcalG\) becomes an (endomorphism) comonad on \(\mcalD\) and the left coaction \(\mcalF \to \mcalT \circ \mcalF\) of \(\mcalT\) on \(\mcalF\) is just the unit \(\id_{\mcalC} \to \mcalG \circ \mcalF\) of the adjunction \((\mcalF, \mcalG)\) composed with \(\mcalF\).
    This gives rise to a comparison functor
    \begin{equation*}
        \mcalF' \colon \mcalC \to \coMod_{\mcalT}(\mcalD)
    \end{equation*}
    of \(\infty\)-categories whose composition with the forgetful functor \(\coMod_{\mcalT}(\mcalD) \to \mcalD\) is equivalent to \(\mcalF\), where \(\coMod_{\mcalT}(\mcalD)\) is the \(\infty\)-category of comodules over \(\mcalT\) in \(\mcalD\).
    If \(\mcalF'\) is an equivalence of \(\infty\)-categories, then we say that the functor \(\mcalF\) is \emph{comonadic}.

    On the comonadicity, Barr--Beck--Lurie theorem states that the following two conditions are equivalent:
    \begin{enumerate}
        \item The functor \(\mcalF\) is comonadic.
        \item The functor \(\mcalF\) is conservative and for any \(\mcalF\)-split\footnote{Here, an \(\mcalF\)-split cosimplicial object is a cosimplicial object \(X^{\bullet}\) on \(\mcalC\) such that whose composition \(\mcalF(X^{\bullet}) \colon \Delta \xrightarrow{X^{\bullet}} \mcalC \xrightarrow{\mcalF} \mcalD\) is a split cosimplicial object in \(\mcalD\).} cosimplicial object \(X^{\bullet} \colon \Delta \to \mcalC\), the limit \(\lim_{\Delta} X^{\bullet}\) exists in \(\mcalC\) and is preserved by \(\mcalF\).
    \end{enumerate}
\end{theorem}
we obtain the main theorem.

