\begin{conv}\label{conv of Determinantal rings 2}
Here, the notation follows Convention \ref{conv of Determinantal rings}(3).
For each integer $1\le h\le \l-\l'$, we set 
\begin{itemize}
\item $\mathfrak{S}_h=\{i \mid \l-\l_i\ge h\}$ and $\mathfrak{T}_h=\{i \mid \l-\l_i< h\}$;
\item $\mathfrak{U}_h^{+}=\{i \mid i \in \mathfrak{S}_h, i-1\in \mathfrak{T}_h\},\ \mathfrak{U}_h^{-}=\{i \mid i \in \mathfrak{T}_h, i-1\in \mathfrak{S}_h\}$, and $\mathfrak{U}_h=\mathfrak{U}_h^{+}\cup \mathfrak{U}_h^{-}$;
\item $\mathfrak{U}=\bigcup_{h=1}^{\l-\l'} \mathfrak{U}_h$.
\end{itemize}
\end{conv}

ref_dict.general case of cano trace:
\begin{prop}\label{general case of cano trace}
Under Conventions \ref{conv of Schubert cycle} and \ref{conv of Schubert cycle2}, we assume that $B$ is a Gorenstein normal domain.
Then the canonical trace of $G_B(X; \g)$ is 
$$\prod_{h=1}^{\k-\k'}\Bigl( \bigcap_{i\in\U_h} J_B(x;\sigma_i) \Bigr).$$
In particular, the minimal elements of the Gorenstein locus $G_B(X; \g)$ are exactly $J_B(x;\sigma_i)$ with $i\in\U$.
\end{prop}

ref_dict.conv of Schubert cycle2:
\begin{conv}\label{conv of Schubert cycle2}
Here, the notation follows Convention \ref{conv of Schubert cycle}(2).
For each integer $1\le h\le \k-\k'$, we set 
\begin{itemize}
\item $\S_h=\{i \mid \k-\k_i\ge h\}$ and $\T_h=\{i \mid \k-\k_i< h\}$;
\item $\U_h^{+}=\{i \mid i \in \S_h, i-1\in \T_h\},\ \U_h^{-}=\{i \mid i \in \T_h, i-1\in \S_h\}$, and $\U_h=\U_h^{+}\cup \U_h^{-}$;
\item $\U=\bigcup_{h=1}^{\k-\k'} \U_h$.
\end{itemize}
For any $1\le h\le \k-\k'$, $\S_h$ and $\T_h$ are disjoint subsets of $\{0, 1,\ldots, t\}$, and their union equals $\{0, 1,\ldots, t\}$.
Also, $\U_h$ is a non-empty subset of $\{1,\ldots, t\}$ for every $1\le h\le \k-\k'$.
\end{conv}

