		\node[xshift=-3cm, yshift=-0.8cm, align=center] at (B) {nonlocal $H$-convergence \cite{Wau25}\\ (Thm.~\ref{thm:NonlocalTopologieFracGradPlusOrtho})};

		\coordinate (C) at ([shift={(0.5cm, 0.5cm)}]A);
		\coordinate (D) at ([shift={(-0.5cm, -1.5cm)}]B);
		\coordinate (E) at ([shift={(0.5cm, 0.5cm)}]C);
		\coordinate (F) at ([shift={(-0.5cm, -3cm)}]D);

