\label{intro-der-equiv}
Let $R$ be a commutative noetherian ring. Let $\CA \subseteq \modr$ be a resolving subcategory. Then there is an equivalence of categories $ D^b(\xbar{\CA} \cap \L) \rightsquigarrow {D^b_{\tiny \L}}(\CA)$ in the following cases :
    \begin{enumerate}
        \item $R$ is a regular ring.
        \item $\L$ satisfies condition $(*)$.
        \item $\L = \L_{V(I)}$ where $I \subseteq R$ is an ideal which has a filtration $\{ I_n \}$ which is equivalent to the $I$-adic filtration and $\textrm{dim}_{\tiny \CA}(R/I_n) < \infty$.
    \end{enumerate}

ref_dict.efpd-subsection:
\begin{cor}\label{intersection cor}
    Let $R$ be a noetherian local ring. Then there exists a non-zero finitely generated $R$-module of finite length and finite projective dimension if and only if $R$ is Cohen-Macaulay. 
\end{cor}

\subsection*{Filtrations of ideals and asymptotic behaviour of projective dimension}\label{efpd-subsection}
\begin{defn}
    A filtration $\{J_n\}$ of $I$, i.e., $I  \supseteq J_1 \supseteq \cdots  \supseteq J_{n-1} \supseteq J_n \supseteq \cdots$ where each $J_n$ is an ideal in $R$, is said to be equivalent to the $I$-adic filtration $\{I^k\}$ if for all $k \in \BN$, there exists $n$ such that $J_n \subseteq I^k$ and for all $n \in \BN$, there exists $k$ such that $I^k \subseteq J_n$.
\end{defn}
Equivalently, the filtration $\{J_n\}$ induces the $I$-adic topology.
\begin{eg}\label{equivalent filtration eg}
    \begin{enumerate}[(i)]
        \item For an ideal $I$ in $R$ with a generating set $\tildes$, we define $I^{[r]}_{\tildes} := (\tildes^r)$. Clearly $I^{[r]}_{\tildes} \subseteq I^r$ and $I^{rd} \subseteq I^{[r]}_{\tildes}$ where $d$ denotes the number of elements in the sequence $\tildes$. Hence, the square power filtration $\{ I^{[n]}_{\tildes} \}$ is equivalent to the power filtration $\{I^k\}$.
        \item For a regular ring $R$ and an ideal $I \subseteq R$, the symbolic power filtration $\{I^{(n)}\}$ of $I$ is known to be equivalent to $\{I^k\}$ (\cite[Theorem 3.5]{JKV}). In fact, the hypothesis on $R$ can be further weakened (\cite[Proposition 4.7]{JKV}).
    \end{enumerate}
\end{eg}
\begin{rmk}
    Let $I$ be an ideal of $R$ and $\tildes$ a generating set of $I$. If $\ch(R) = p > 0$ is prime, then 
    $I^{[p^n]}_{\tildes}$ is the $n$-th Frobenius power of $I$ and hence is independent of the generating set $\tildes$. We denote it by $I^{[p^n]}$.
\end{rmk}

The next lemma follows directly from \cite[Theorem 1.7]{Peskine_Szpiro_thesis}.
\begin{lemma} \label{char p proj dim}
    Let $I\subseteq R$ be an ideal and $\ch(R) = p >0$, where $p$ is a prime. If $\pd(R/I) < \infty$ then $\pd(R/I) = \pd(R/I^{[p^n]})$ for every $n \in \BN$.
\end{lemma}

\begin{defn} \label{def-efpd}
Let $I \subseteq R$ be an ideal.
    The ideal $I$ is said to have eventually finite projective dimension (efpd) if there is a filtration $\{J_n\}$ of $I$ equivalent to $\{I^k\}$ such that $\pd(R/J_n) < \infty$ for all $n \in \BN$. 
\end{defn}

\begin{rmk}\label{propertiesefpd}
    If $I, J \subseteq R$ are ideals such that $\sqrt{I} = \sqrt{J}$, then $I$ has efpd if and only if $J$ has efpd. 
\end{rmk}

We discuss a few classes of ideals which have eventually finite projective dimension.
\begin{eg}\label{efpd example}
    \begin{enumerate}
        \item When $R$ is a regular ring, every ideal has finite projective dimension and hence every ideal has efpd. 
        \item Let $\ch(R) = p >0$, where $p$ is a prime and $\pd(R/I)< \infty$. Then by Lemma \ref{char p proj dim}, $\pd(R/I) = \pd(R/I^{[p^n]})$ for all $n \in \BN$. Hence, it follows from Example \ref{equivalent filtration eg}(ii) that $I$ has efpd.
        \item \label{CI eg} Let $I$ be a set-theoretic complete intersection ideal, i.e., there exists a regular sequence $a_1,\dots,a_n$ such that $\sqrt{(a_1,\dots,a_n)} = \sqrt{I}$. Since $a_1^k,\dots,a_n^k$ is also a regular sequence for each $k \in \BN$, the Koszul complex $K(a_1^k,\dots,a_n^k)$ is a free resolution of $R/(a_1^k,\dots,a_n^k)$. Thus $\pd(R/(a_1^k,\dots,a_n^k)) < \infty$ for all $k \in \BN$. Hence every set-theoretic complete intersection ideal has efpd.
        \item As a special case of (\ref{CI eg}), the maximal ideal in a Cohen-Macaulay local ring has efpd. 
        \item Every nilpotent ideal has efpd, since the filtration $\{I^n\}$ eventually becomes zero.
        \item Let $R$ be an artinian ring with $Maxspec(R) =  \{\m_1,\dots,\m_t\}$ for some $t \geq 1$. Then there exists $n \in \BN$ such that $R \cong R/\m_{1}^{n} \times \cdots \times R/\m_{t}^{n}$ and  $(\m_{1} \cdots \m_{t})^{n} = 0$. We claim that every ideal $I \subseteq R$ has efpd. Without loss of generality, we may assume $I$ is a radical ideal. Hence $I = \prod_{i \in \Lambda} \m_{i}$ for some subset $\Lambda \subseteq [t]$. If $R$ is a local ring, then $I$ is the maximal ideal which is nilpotent. Hence $I$ has efpd. Suppose there are more than one maximal ideal in $R$. Then we may assume $\Lambda \subset [t]$ to be any non-empty proper subset. Then for all $k \geq n$, $$I^k = \prod_{i \in \Lambda} \m_{i}^{k} \cong \prod_{j \in [t]\backslash \Lambda} R/\m_{j}^{k} \cong \prod_{j \in [t]\backslash \Lambda} R/\m_{j}^{n}$$ is a projective $R$-module. Hence $I$ has efpd. 
        \item Let $f: R \to S$ be a flat ring homomorphism and $I \subseteq R$ has efpd. Then there exists a filtration $\{J_n\}$ of $I$ such that $\pd_R(R/J_n) < \infty$ and $\{J_n\}$ is equivalent to $\{I^k\}$. Hence $\pd_S(S/(J_nS ))<\infty$ and $\{J_nS\}$ is equivalent to $\{{(IS)}^k\}$. Thus $IS \subseteq S$ has efpd. 
        \item \label{efpd localizes} If $I \subseteq R$ has efpd, then $I_{\cp} \subseteq R_{\cp}$ has efpd for all $\cp \in Spec(R)$, since localisation is flat.
        \item\label{Dutta Hochster Mclaughlin eg} 
        Let $R = k[x_1,x_2,x_3,x_4]_{\tiny \m}/(x_1x_4 - x_2x_3 )$ where $k = \BZ/p\BZ$ and $\m = (x_1,x_2,x_3,x_4)$. The construction of Dutta-Hochster-McLaughlin\cite{Dutta_Hochster_Mclaughlin} shows the existence of an $R$-module $M$ of finite length and finite projective dimension such that the intersection multiplicity $\chi_R(M,N) < 0$ for some module $N$. The existence of a flat local ring homomorphism from a regular local ring to $R$ would imply that $\chi_R(M,N) \geq 0$. Therefore there is no flat local ring homomorphism from any regular local ring to $R$. Since $R$ has a module of finite length and finite projective dimension, Corollary \ref{intersection cor} implies that $R$ is a Cohen-Macaulay local ring. Thus $\m R \subseteq R$ has efpd. Thus we have an example of an ideal having efpd, which is not extended from a regular local ring under a flat map.
        \end{enumerate}
\end{eg}
\indent Later in Section 4, we show that a maximal ideal in a noetherian local ring has efpd if and only if the ring is Cohen-Macaulay. We also give a necessary condition for arbitrary ideals to have eventually finite projective dimension. 
\begin{eg}\label{efpd non-example}
    Let $R = k[X,Y]/(XY)$. The ideal $(X)$ in $R$ does not have efpd.
\end{eg}

\subsection*{Subcategories of mod(R)}
We denote by $\modr$ the category of finitely generated $R$-modules.

\begin{defn}\label{serresub defn}
\begin{enumerate}
    \item A Serre subcategory of $\modr$, denoted by $\L$, is a full subcategory of $\modr$ such that for any short exact sequence $0 \to M' \to M \to M'' \to 0$  in $\modr$, $M \in \L$ if and only if $M', M'' \in \L$.
    \item A set $V \subseteq \text{Spec}(R)$ is called a specialization closed set if it is a union of closed sets.
    \item Given a specialization closed set $V$, there is a corresponding Serre subcategory defined as $$\L_V = \{ M \in \modr \mid \\Supp(M) \subseteq V \}.$$
    \item \label{VL defn} Given a Serre subcategory $\L$, there is a corresponding specialization closed set defined as
    $$V_{\tiny \L} = \bigcup_{M \in {\tiny \L}} \Supp(M).$$
\end{enumerate}

\end{defn}
\begin{rmk}\label{serresub}\cite{Gabriel}
Clearly, $\L \subseteq \L_{V_{\tiny \L}}$. Suppose $M \in \L_{V_{\tiny \L}}$. Then, by definition, $$\Ass(M) \subseteq \Supp(M) \subseteq V_{\tiny \L} = \bigcup_{M' \in {\tiny \L}} \Supp(M').$$ Thus, for each $\cp \in \Ass(M)$, there exists a module $M' \in \L$ such that $\cp \in \Supp(M')$. Since $\L$ is a Serre subcategory, it follows that $R/{\cp} \in \L$, since it is a quotient of some associated prime of $M'$, which is in $\L$ since it is a submodule of $M'$. Using the existence of a finite filtration for $M$ whose quotients are $R/{\cp}$ where $\cp \in \Ass(M)$, we obtain that $M \in \L$ and hence that $\L = \L_{V_{\tiny \L}} $.
\end{rmk}

\begin{defn}
    A full subcategory $\CA \subseteq \modr$ is said to be resolving if 
    \begin{enumerate}
        \item $R$ is in $\CA$.
        \item $M \oplus N \in \CA$ if and only if $M$ and $N$ are in $\CA$. 
        \item If $0 \to M' \to M \to M''\to 0$ is an exact sequence and $M'' \in \CA$, then $M \in \CA$ if and only if $M' \in \CA$.
    \end{enumerate}
\end{defn}
As a consequence, the category of finitely generated projective $R$-modules $\CP$ is contained in any resolving subcategory. Some examples of resolving subcategories are $\CP, \modr$, the category of Gorenstein dimension zero modules (also called totally reflexive modules) and the category of maximal Cohen-Macaulay (MCM) modules in a Cohen-Macaulay local ring. Basic properties and statements about resolving subcategories may be found in \cite{Dao-Takahashi} and \cite{Sanders}. The collection of resolving subcategories of $\modr$ is classified in these articles, and in particular, it shows that $\modr$ has many resolving subcategories.

\begin{defn}
    A full subcategory $\T \subseteq \modr$ is a thick subcategory of $\modr$ if it is resolving and for any exact sequence in $\modr$, $$0 \to M' \to M \to M'' \to 0,$$  $M,M' \in \T$ implies $M'' \in \T$.
\end{defn}

\begin{rmk}
    Let $\Omega^i M$ denote the $i^{th}$ syzygy of $M$.
    For a resolving subcategory $\CA$, define the closure $\overline{\CA} = \{ M \in \modr \mid \Omega^{\gg 0} M \in \CA \}$.
    Then $\overline{\CA}$ is a thick subcategory of $\modr$.
\end{rmk}

\begin{eg} Here are some examples of thick subcategories of $\modr$ which arise as a closure of a resolving subcategory. 
    \begin{enumerate}
        \item $\xbar{\CP}$ is the category of finitely generated modules having finite projective dimension.
        \item The closure of Gorenstein dimension zero modules is the full subcategory of $\modr$ having finite Gorenstein dimension.
        \item When $R$ is a Cohen-Macaulay local ring, $\overline{MCM(R)} = \modr$.
    \end{enumerate}
\end{eg}

We fix the following notations:
    For $X_\bullet \in Ch^b(\modr)$,
    \begin{enumerate}
        \item $\min_{c}(X_{\bullet}) = \sup\{ n \mid P_{\bullet} = 0 \text{ for all } i <n  \}$
        \item $\min(X_\bullet) = \sup\{ n \mid H_i(X_{\bullet}) = 0 \text{ for all } i <n  \}$ 
        \item $\supph(X_{\bullet}) = \{ n \mid H_n(X_{\bullet}) \neq 0 \}$
        \item $\wid(X_\bullet) = \begin{cases}
            \sup\{ i-j \mid H_i(X_\bullet), H_j(X_\bullet) \neq 0 \} & \text{if\ } X_\bullet \text{\ is not acyclic} \\ 
            -\infty & \text{if\ } X_\bullet \text{\ is acyclic} 
        \end{cases} $
        \item $\width(X_\bullet) = \begin{cases}
            0 & \text{if\ } \wid(X_\bullet) = -\infty \\
            \wid(X_\bullet) & \text{otherwise}
        \end{cases}$
        \item $\Sigma X_\bullet$ denotes the shift of the complex $X_\bullet$, that is, $(\Sigma X_\bullet)_k = (X_\bullet)_{k+1}$     \end{enumerate}

\subsection*{Preliminaries on \texorpdfstring{$K_0$}{K0} of certain categories}

In \cite{ChandaSane}, the stable range $\alpha(\L)$ of $K_0$ relative to a Serre subcategory $\L$ of $\modr$ and a computable invariant $\beta(\L) \geq \alpha(\L)$ were introduced and studied. 
We recall below the definitions and results about $\beta(\L)$ which are relevant to this article. Later in Section 3, we give bounds on $\beta(\L)$ in certain cases.
\begin{defn}
\begin{enumerate}
    \item Let $k \geq 1$ and $P_\bullet \in Ch^{[0,k]}_{\tiny \L}(\CP)$. A pair $(Q_\bullet,u)$ is said to be a reducer of $P_\bullet$ if $Q_\bullet \in Ch^{[0,k-1]}_{\tiny \L}(\CP)$ and $u: Q_\bullet \to P_\bullet$ is a chain complex map such that $u_0: Q_0 \to P_0$ is surjective.
    \item $\beta(\L) = \inf\{ m \in \BN \mid \text{every}\ P_\bullet \in Ch^{[0,k]}_{\tiny \L}(\CP) \ \text{has a reducer, for all}\ k>m \}$.
\end{enumerate}
\end{defn}
Recall the notation that $\tildes = s_1,\dots,s_d$. A careful observation and reformulation in terms of the dual of the chain complex of \cite[Proposition 23]{Foxby-Halvorsen} yields the next lemma.
\begin{lemma}\label{Foxby-Halvorsen}
    Let $I = (\tildes)$ be an ideal and $\L = \L_{V(I)}$. For $P_\bullet \in Ch^{-}_{\tiny \L}(\CP)$, there exists $r \in \BN$ and a chain complex map $\Psi : K(\tildes^r ; P_0) \to P_\bullet$ such that $\Psi_0$ is an isomorphism.
\end{lemma}
Lemma \ref{Foxby-Halvorsen} is crucially used in this form in \cite{SandersSane} and later in \cite{ChandaSane} to obtain the first example of a reducer and which also yields statement (2) of the next lemma.
\begin{lemma}\label{beta properties} \cite{ChandaSane}
Let $I = (\tildes)$ be an ideal and $\L = \L_{V(I)}$. 
    \begin{enumerate}
        \item When $\L \neq 0$, $\grade(I) \leq \beta(\L)$.
        \item $\beta(\L) \leq d$.
    \end{enumerate}
\end{lemma}
A direct consequence of \cite[Theorem 6.3]{ChandaSane} is stated below.
\begin{lemma}\label{grade-beta equality}
    If $\grade(I) = \beta(\L)$ then $K_0(\xbar \CP \cap \L) \cong K_0(\DbLP)$.
\end{lemma}

\begin{rmk}
We recall that $\beta(\L_{V(I)})$ is bounded above by $\limsup \left\{ \pd(R/I^{[r]}_{\tildes}) \mid n \in \BN \right\}$ as proved in \cite[Theorem 5.1]{ChandaSane}. We note that the same proof shows that the bound can be obtained with any filtration $\{J_n\}$ equivalent to  $\{I^k\}$, i.e.,
    $$\beta(\L_{V(I)}) \leq \limsup \left\{ \pd(R/J_n) \mid n \in \BN \right\} .$$
    Note that the RHS of the above inequality is also an upper bound for the non-vanishing of the local cohomology $H^i_I(M)$ for an $R$-module $M$, since it is the direct limit of $\Ext^i_R(R/J_n,M)$.
\end{rmk}

\subsection*{Notations for further use}
\label{notations}
We collect below some notations that will be used in the rest of the article.
\begin{itemize}
    \item $\tildei = \{ i_1,\dots,i_m \} \in \P$ with $i_j < i_{j+1}$. \\
    \item $\ei$ := $e_{i_1} \wedge  \dots \wedge e_{i_m}$. \\
    \item $P_{\tildei}$ : the $R$-linear map $\bigoplus_{\tildei \in \tiny \P} M\ei \to M$ where $\sum_{\tildei \in \tiny{\P}} c_{\tildei} \ei$ maps to $c_{\tildei}$.\\
    \item $\tildei \sqcup k$ : the $(m+1)$-ordered subset containing $\tildei$ and $k$ where $k \notin \tildei$. \\
    \item $\kappa^{n,k}$ : the chain complex map from $K(\tildes^{n};M)$ to $K(\tildes^k;M)$ where $\kappa^{n,k}_m$ maps $\ei$ to $(s_{i_1}\cdots s_{i_m})^{n-k} \ei$ for all $\tildei \in \P$ and $m \in [d]$ where $n \geq k >0$.\\
    \item $l$ : the common stabilization point for the chain of the submodules $(0:_M s_i^t)$ (defined in notations~\ref{notations1}).
\end{itemize}
Note that for $n \geq t \geq k$, $\kappa^{n,k} = \kappa^{t,k} \circ \kappa^{n,t}$. When $M=R$, $\kappa^{n,k}$ is a map of dg algebras.

\section{Factoring $\kappa$ through the Tate resolution}\label{section main thm}
In this section, we define the Tate resolution and prove the main theorem about the existence of a map from a suitable Tate resolution to the Koszul complex as mentioned in the introduction. We begin with a lemma about the vanishing of maps on Koszul homologies.
\begin{lemma}\label{homology map is zero}
    There exists $h \in \BN$ such that for all $r \geq 1$, the map  $$H_i(\kappa^{h+rd,r}) : H_i(K(\tildes^{h+rd};M)) \longrightarrow H_i(K(\tildes^r;M))$$ is zero for all $i \geq 1$. For $i=0$, the map is the natural surjection $\displaystyle{M/({\tildes}^{h+rd})M \to M/({\tildes^r})M}$.
\end{lemma}
\begin{proof}
    Let $S = R[X_1,\dots, X_d]$ be the polynomial ring and $f: S \to R$ the ring map mapping $X_i$ to $s_i$. We denote the $S$-module structure on $M$ through $f$ by $\prescript{}{S}{M}$.   Then for all $h \geq 0$, we have the following commutative diagram :     $$\xymatrix{  \Tor_i^S(S/(X_1^{h+rd},\dots,X_d^{h+rd}),\prescript{}{S}{M}) \ar[r]^{\cong} \ar[d]^{} & H_i(K(X_1^{h+rd},\dots,X_d^{h+rd};\prescript{}{S}{M})) \ar[r]^-{\cong} \ar[d]^{}  & H_i(K(\tildes^{h+rd};M)) \ar[d]^{} \\  \Tor_i^S(S/(X_1^r,\dots,X_d^r),\prescript{}{S}{M}) \ar[r]^{\cong} & H_i(K(X_1^r,\dots,X_d^r;\prescript{}{S}{M})) \ar[r]^-\cong  & H_i(K(\tildes^r;M))   }$$
    Since the Koszul complex is concentrated in degrees zero to $d$, it is sufficient to prove that for all $1 \leq i \leq d$, there exists $h \geq 0$ such that
    \begin{equation}\label{tor-map}
    \Tor_i^S(S/(X_1^{h+rd},\dots,X_d^{h+rd}),\prescript{}{S}{M}) \to \Tor_i^S(S/(X_1^r,\dots,X_d^r),\prescript{}{S}{M})
    \end{equation}
     is the zero map. Since the natural surjection $S/(X_1^{h+rd},\dots,X_d^{h+rd}) \twoheadrightarrow S/(X_1^r,\dots,X_d^r)$ factors through $S/(X_1,\dots,X_d)^{h+rd} \twoheadrightarrow S/(X_1,\dots,X_d)^{rd}$, the map in \eqref{tor-map} is zero if the natural map $\Tor_i^S(S/(X_1,\dots,X_d)^{h+rd},\prescript{}{S}{M}) \to \Tor_i^S(S/(X_1,\dots,X_d)^{rd},\prescript{}{S}{M})$ is zero. Using Proposition \ref{andre-homology} with the exponent $rd$, there exists $h(i) \in \BN$, for each $1 \leq i \leq d$, such that for all $r \geq 1$, the map 
\begin{equation*}
    \Tor_i^S(S/(X_1,\dots,X_d)^{h(i)+rd},\prescript{}{S}{M}) \to \Tor_i^S(S/(X_1,\dots,X_d)^{rd},\prescript{}{S}{M})
\end{equation*}
 is zero. Choosing $h = \max\{h(i) \mid 1 \leq i \leq d \}$, we get that
 \begin{equation*}
    \Tor_i^S(S/(X_1,\dots,X_d)^{h+rd},\prescript{}{S}{M}) \to \Tor_i^S(S/(X_1,\dots,X_d)^{rd},\prescript{}{S}{M})
\end{equation*}
 is the zero map for all $1 \leq i \leq d$. 
\end{proof}
We fix the integer $h$ (which depends on $M$ and $\tildes$) obtained above for the rest of this section, i.e., for all $r \geq 1$,
    \begin{equation*}
    H_i(\kappa^{h+rd,r}): H_i(K(\tildes^{h+rd};M)) \longrightarrow H_i(K(\tildes^r;M))
\end{equation*}
 is the zero map for all $1 \leq i \leq d$. The following technical lemma about the divisibility of elements is used for our induction statement in Theorem \ref{chainmapexists}. 
\begin{lemma}\label{T2}
 Given $n \geq 1$, $r \geq 1$, there exists $v := q(n,r) = h+(n+r)d$ such that for all  $m \geq 1$ and $x \in \ker\left(\partial_m^{K({\tildes}^v ; M)}\right)$, there exists $y \in K_{m+1}(\tildes^r ; M)$ such that :
 \begin{enumerate}[(a)]
     \item $\partial_{m+1}^{K(\tildes^r;M)}(y) = \kappa^{v,r}_m(x)$.
     \item $P_{\tildej}(y)$ is divisible by $\prod_{j \in \tildej} s_j^{n}$ for all $\tildej \in \Pmm$.
 \end{enumerate} 
\end{lemma}   
\begin{proof}
From Lemma \ref{homology map is zero}, the natural map $H_m(\kappa^{v,n+r}) : H_m(K(\tildes^v ; M)) \rightarrow H_m(K(\tildes^{n+r} ; M))$ is zero for all $m \geq 1$. Therefore for all $x \in \ker\left(\partial_m^{K({\tildes}^v ; M)}\right)$, we get $\kappa^{v,n+r}_m(x) \in B_m(K(\tildes^{n+r} ; M))$, where $B_m(K(\tildes^{n+r} ; M))$ denotes $\im(\partial_{m+1}^{K({\tildes^{n+r} ; M)}})$. Hence the commutative diagram below shows that $\kappa^{v,r}_m(x) \in B_m(K(\tildes^r ; M))$.
  $$ \begin{tikzcd}[sep=large]  
 & K_{m+1}(\tildes^{n+r};M) \arrow[twoheadrightarrow]{d}{\partial_{m+1}^{K(\tildes^{n+r};M)}} \arrow{r}{\kappa^{n+r,r}_{m+1}} & K_{m+1}(\tildes^{r};M) \arrow[twoheadrightarrow]{d}{\partial_{m+1}^{K(\tildes^r;M)}} \arrow{r}{P_{\tildei}} & \left( \prod_{i \in \tildei} s_i^{n-1} \right) M  \\
 \ker\left( \partial_m^{K(\tildes^v;M)} \right) \arrow[r,"\kappa^{v,n+r}_m","(Lemma\ \ref{homology map is zero})"']  &  B_m(K(\tildes^{n+r};M))  \arrow{r}{\kappa^{n+r,r}_m} &  B_m(K(\tildes^r;M)) &
\end{tikzcd}$$ 
Since $\kappa^{v,n+r}_m(x) \in B_m(K(\tildes^{n+r};M))$, there exists $z = \sum_{\tildej \in \tiny{\Pmm}} c_{\tildej} \ej \in K_{m+1}(\tildes^{n+r};M)$ such that $\partial_{m+1}^{K(\tildes^{n+r};M)}(z) = \kappa^{v,n+r}_m(x)$. Let $y: = \kappa^{n+r,r}_{m+1}(z)$. Then $\partial_{m+1}^{K(\tildes^r;M)}(y) = \kappa^{v,r}_m(x)$. Also, 
$$ y = \sum_{\tildej \in \tiny{\Pmm}} \left( \prod_{j \in \tildej} s_j^{n} \right) c_{\tildej} \ej \quad \textrm{and hence} \quad 
P_{\tildej}(y) = \left( \prod_{j \in \tildej} s_j^{n} \right)  c_{\tildej} \quad \textrm{ for all } \tildej \in \Pmm.$$
\end{proof}

\begin{thm}\label{T1}
  Let $r \geq 1$, $m \geq 1$ and $x = \sum_{\tildei \in \tiny{\P}} x_{\tildei} \ei \in \ker\left( \partial_{m}^{K(\tildes^r;M)} \right)$. Suppose $x_{\tildei}$ is divisible by $\prod_{i \in \tildei}s_i^{l+n}$  for each $\tildei \in \P$. Then there exists $y\in \ker\left( \partial_m^{K(\tildes^{n+r};M)} \right) $ such that $x = \kappa^{n+r,r}_m(y)$.
\end{thm}
\begin{proof}
We first consider the case $m = 1$. Then $x =\sum_{i =1}^{d}x_i e_i$ and $\partial_1^{K(\tildes^r;M)}(x) = \sum_{i =1}^{d} s_i^r x_i  = 0$. Since $s_i^{l+n}$ divides $x_i$, there exists $c_i \in M$ such that $x_i = s_i^{l+n} c_i$ for all $i \in [d]$. Define $y =\sum_{i =1}^{d}s_i^{l} c_i  e_i \in K_1(\tildes^{n+r};M)$. Then $\partial_1^{K(\tildes^{n+r};M)}(y) = \sum_{i =1}^{d} s_i^{l+n+r} c_i = \sum_{i =1}^{d} s_i^r x_i = 0$. Further, 
$\kappa^{n+r,r}_1(y) =\sum_{i =1}^{d} s_i^{l+n} c_i  e_i= x$, thus proving the statement in this case.\par Consider the case $m \geq 2$. Since $x = \sum_{\tildei \in \tiny \P} x_{\tildei} \ei  \in \ker\left(\partial_{m}^{K(\tildes^r;M)}\right)$, we have
\begin{equation}
    \sum_{\tildej \in \tiny \Pm} \left( \sum_{k \in [d]\backslash \tildej} (-1)^{\tau(k,\tildej)+1} s_k^r x_{(\tildej \sqcup k)} \right) \ej = 0
\end{equation}
where $\tau(k,\tildej)$ denotes the position of $k$ in the ordered set $\tildej \sqcup k$. Hence for each $\tildej \in \Pm$, 
\begin{equation}\label{K1}
    \sum_{k \in [d]\backslash \tildej} (-1)^{\tau(k,\tildej)+1} s_k^r x_{(\tildej \sqcup k)} = 0.
\end{equation}
Since $\prod_{t \in \tildei}s_t^{l+n}$ divides $x_{\tildei}$, we get $x_{\tildei}= \left( \prod_{t \in \tildei}s_t^{l+n} \right) x'_{\tildei}$ for some $x'_{\tildei} \in M$. Thus for each $\tildej \in \Pm$ and $k \in [d] \setminus \tildej$, we obtain
\begin{align*}
    0 = \sum_{k \in [d]\backslash \tildej} (-1)^{\tau(k,\tildej)+1} s_k^r x_{(\tildej \sqcup k)} & = \sum_{k \in [d]\backslash \tildej} (-1)^{\tau(k,\tildej)+1} s_k^r \left( \prod_{t \in (\tildej \sqcup k)}s_t^{l+n}\right) x'_{(\tildej \sqcup k)} \\
    & = \left(\prod_{t \in \tildej}s_t^{l}\right)\left(\prod_{t \in \tildej}s_t^{n} \right)  \sum_{k \in [d]\backslash \tildej} (-1)^{\tau(k,\tildej)+1} s_k^{n+r} (s_k^{l}  x'_{(\tildej \sqcup k)}) .\\
\end{align*}
By Lemma \ref{annihilatorlemma}, for all $n \geq 1$, $\left(0:_M \left( \prod_{t \in \tildej}s_t^{n+l}\right) \right) = \left( 0:_M\left(\prod_{t \in \tildej}s_t^{l}\right)\right)$. Thus,
$$\left( \prod_{t \in \tildej}s_t^{l} \right) \sum_{k \in [d]\backslash \tildej} (-1)^{\tau(k,\tildej)+1} s_k^{n+r} (s_k^{l}  x'_{(\tildej \sqcup k)}) = 0.$$ 
 Take $y_{\tildei} = \left( \prod_{t \in \tildei}s_t^{l} \right) x'_{\tildei} $. Observe that $x_{\tildei} = \left( \prod_{t \in \tildei}s_t^n \right)y_{\tildei}$. Define $y := \sum_{\tildei \in \tiny{\P}} y_{\tildei} \ei \in K_m{(\tildes^{n+r};M)}$. Then, for all $\tildej \in \Pm$, the above equation yields
$$ \sum_{k \in [d]\backslash \tildej} (-1)^{\tau(k,\tildej)+1} s_k^{n+r}   y_{(\tildej \sqcup k) } = 0 .$$ 
Therefore $y \in \ker\left( \partial_m^{K(\tildes^{n+r};M)}\right)$. Clearly $\kappa^{n+r,r}_m(y) = x$. 
\end{proof} 

\begin{defn}\label{defn-rmk}
Let $\tildef = f_1 \ldots , f_n \in R$. Taking intuition from the construction of the Tate resolution (refer for example \cite{Avramov}), we now construct a chain complex $T'(\tildef;M)$. Define
\[
T'_i(\tildef;M) = \begin{cases}
            0 & \textrm{ if }~  i < 0 \\
            K_i(\tildef;M) & \textrm{ if }~ i = 0, 1 \\
            K_i(\tildef;M) \oplus R^{t_i} & \textrm{ if }~  i \geq 2
        \end{cases}
\]
where the differentials and $t_i$ are inductively defined as follows : \\$\partial_1^{T'(\tildef;M)} := \partial_1^{K(\tildef;M)}$. Choose a generating set $S_1$ of $Z_1(T'(\tildef;M))$ and define $t_2 = \lvert S_1 \rvert$. Suppose for all $j \leq r-1$, the differentials $\partial_j^{T'(\tildef;M)}$ have been defined , generating sets $S_j$ of $Z_j(T'(\tildef;M))$ have been chosen and $t_{j+1} = \lvert S_j \rvert$. Define $\partial_r^{T'(\tildef;M)}$ by
$\partial_r^{T'(\tildef;M)}|_{K_r(\tildef;M)} = \partial_r^{K(\tildef;M)}$ and $\partial_r^{T'(\tildef;M)}$ maps a basis of $R^{t_r}$ to the set $S_{r-1} $ of $Z_{r-1}(T'(\tildef;M))$. Choose a generating set $S_r$ of $Z_r(T'(\tildef;M))$ and define $t_{r+1}=\lvert S_r \rvert$.
\end{defn}

Note that $T'(\tildef;M)$ satisfies the following properties : 
 \begin{enumerate}
        \item $K(\tildef;M)$ is a subcomplex of $T'(\tildef;M)$.
        \item $H_i(T'(\tildef;M)) = 0$ for all $i \geq 1$ and $H_0(T'(\tildef;M)) = M/(\tildef)M$.
    \end{enumerate}
 A slightly enhanced version of the above construction when $M = R$ in order to obtain a dg $R$-algebra structure is precisely the Tate resolution on $R/(\tildef)$ as defined in \cite{Avramov}, which we denote by $T (\tildef)$. We are now set up to state and prove the main theorem.

\begin{thm}\label{chainmapexists}
 Given $r \geq 1$, there exists  a chain complex map $\phi: T'(\tildes^{u(r)};M) \to K(\tildes^r;M)$ with $\phi|_{K(\tildes^{u(r)};M)} = \kappa^{u(r),r}$ for $u(r) = (h+l)\left(\sum_{j = 0}^{d-1}d^j\right) + rd^{d}$. In particular, there exists a chain complex map $\phi: T (\tildes^{u(r)}) \to K(\tildes^r)$ such that $\phi_0 = \kappa^{u(r),r}_0 = id_R$.
 \end{thm}
\begin{proof}
 Recall the notation $q(n,r) = h+(n+r)d$ from Lemma \ref{T2}. Define
 $$
 q^{(i)} = 
 \begin{cases}
     q(0,r)-r = h + rd -r & \quad \textrm{ if }~ i = 0 \\
     q(q^{(i-1)}+ l,r)-r & \quad \textrm{ if }~ i \geq 1 \\
 \end{cases} \qquad \qquad . $$
Claim : For $i\geq 0$, $q^{(i)} = h\left(\sum_{j = 0}^{i}d^j\right) + rd^{i+1} + l \left(\sum_{j = 0}^{i-1}d^j\right) d -r$. \\
 The claim is clearly true for the base case $i=0$ and follows by induction as shown by the calculation below : 
 \begin{align*}
     q^{(i+1)} = q(q^{(i)}+l,r)-r  & = h + \left(h\left(\sum_{j = 0}^{i}d^j\right) + rd^{i+1} + l \left(\sum_{j = 0}^{i-1}d^j\right) d -r+ l + r \right) d -r \\
     & = h\left(\sum_{j = 0}^{i+1}d^j\right) + rd^{i+2} + l \left(\sum_{j = 0}^{i}d^j\right) d -r.
 \end{align*}
  Therefore $q^{(d-1)}+l+r = h\left(\sum_{j = 0}^{d-1}d^j\right) + rd^d + l \left(\sum_{j = 0}^{d-2}d^j\right) d + l = (h+l)\left(\sum_{j = 0}^{d-1}d^j\right) + rd^{d} = u(r)$. For the rest of this proof, we abbreviate $u(r)$ by $u$. We now proceed to construct $\phi$. For $m = 0$, define $\phi_0$ to be the identity map. For $m > d$, the zero map is the only possible map.
  For $1 \leq m \leq d$, we will inductively define $\phi_m$ such that\begin{enumerate}[(a)]
      \item $\phi_{m-1} \partial_m^{ T'(\tildes^{u};M)} = \partial_m^{K(\tildes^r;M)} \phi_m$
      \item $\phi_m|_{K_m(\tildes^u;M)} = \kappa^{u,r}_m$
      \item $P_{\tildei} \phi_m$ is divisible by $\prod_{i \in \tildei} s_i^{q^{(d-m)}+l}$ for all $\tildei \in \P$.
  \end{enumerate} 
   Then, we will show that the constructed map $P_{\tildei}\phi_d$ being divisible by $\prod_{i \in \tildei} s_i^{q^{(0)}+l}$ will imply that $\phi_{d} \partial_{d+1}^{\tiny T'(\tildes^{u};M)} = 0 = \partial_{d+1}^{K(\tildes^r;M)} \phi_{d+1}$, which will complete the proof. \\
  \indent In the base case $m=1$, note that $T'_1(\tildes^{u};M) = M^d \cong \bigoplus_{i = 1}^{d} Me_i$ and so we can define $\phi_1$ by extending $\phi_1(e_i) = s_i^{u-r} e_i $. Then $\phi_{0} \partial_1^{ T'(\tildes^{u};M)} = \partial_1^{K(\tildes^r;M)} \phi_1$, $\phi_1|_{K_1(\tildes^u;M)} = \kappa^{u,r}_1$ and $P_i \phi_1$ is divisible by $ s_i^{q^{(d-1)}+l}$, i.e., conditions (a), (b) and (c) hold.
  \par Suppose $\phi_{t}$ exists for $1 \leq t<m \leq d$ such that the conditions (a), (b) and (c) hold. Recall that $T'_m(\tildes^u;M) = K_m(\tildes^u;M) \oplus R^{t_m}$. We will define $\phi_m$ on each of the summands separately and check that (a), (b) and (c) above are satisfied on the summands. Define $\phi_m|_{K_m(\tildes^u;M)} := \kappa^{u,r}_m$. Since $\partial_m^{ T'(\tildes^{u};M)}|_{K_m(\tildes^u;M)} = \partial_m^{ K(\tildes^{u};M)}$ by definition and $\kappa^{u,r}$ is a chain complex map, $\phi_{m-1} \partial_m^{ T'(\tildes^{u};M)}|_{K_m(\tildes^u;M)} = \partial_m^{K(\tildes^r;M)} \phi_m|_{K_m(\tildes^u;M)}$. Since $P_{\tildei}\kappa^{u,r}_m$ is divisible by $\prod_{i \in \tildei} s_i^{u-r}$ for all $\tildei \in \P$ and $u-r \geq q^{(d-m)}+l$, the condition (c) follows for the summand $K_m(\tildes^u;M)$. Let $x$ be a basis element in the free $R$-module $R^{t_m} \subseteq T'_m(\tildes^{u};M)$. By induction, $\phi_{m-1} \partial_m^{ T'(\tildes^{u};M)}(x) \in \ker\left(\partial_{m-1}^{K(\tildes^r;M)}\right)$ and $P_{\tildei}\phi_{m-1} \partial_m^{\tiny T'(\tildes^{u};M)}(x)$ is divisible by $\prod_{i \in \tildei} s_i^{q^{(d-m+1)}+l}$. From Theorem \ref{T1}, there exists $z \in \ker\left( \partial_{m-1}^{K(\tildes^{q^{(d-m+1)}+r};M)}\right)$ such that $\kappa^{q^{(d-m+1)}+r,r}_{m-1}(z) = \phi_{m-1} \partial_m^{ T'(\tildes^{u};M)}(x)$. Since $q^{(d-m+1)}+r = q(q^{(d-m)}+ l,r)$ and $z \in \ker\left( \partial_{m-1}^{K(\tildes^{q^{(d-m+1)}+r};M)}\right)$, Lemma \ref{T2} implies that there exists $y \in K_{m}(\tildes^r;M)$ such that $\partial_{m}^{K(\tildes^r;M)}(y) = \kappa^{q^{(d-m+1)}+r,r}_{m-1}(z)$ and $P_{\tildei} (y)$ is divisible by $\prod_{i \in \tildei} s_i^{q^{(d-m)}+l}$. Define $\phi_m(x) := y$. Then, $$\phi_{m-1} \partial_m^{ T'(\tildes^{u};M)}(x) = \kappa^{q^{(d-m+1)}+r,r}_{m-1}(z) = \partial_{m}^{K(\tildes^r;M)}(y)=   \partial_m^{K(\tildes^r;M)} \phi_m(x).$$ 
  Extend this to a map $\phi_m$ on 
  $R^{t_m}$ by linearity. 
  Since for every basis element of $R^{t_m}$, the properties (a) and (c) are satisfied, both of these hold for every element in $R^{t_m}$. Thus $\phi_m$ has been constructed inductively for $1 \leq m \leq d$. \\
  \indent It remains to check that $\phi_{d} \partial_{d+1}^{\tiny T'(\tildes^{u};M)} = 0$. Let $x \in T'_{d+1}(\tildes^{u};M)$. Since $P_{\tildei}\phi_{d} \partial_{d+1}^{\tiny T'(\tildes^{u};M)}(x)$ is divisible by $\prod_{i \in \tildei} s_i^{q^{(0)}+l}$, by Theorem \ref{T1}, there exists $z \in \ker\left(\partial_d^{K(\tildes^{q^{(0)}+r};M)}\right)$ such that $\kappa^{q^{(0)}+r,r}_{d}(z) = \phi_{d} \partial_{d+1}^{\tiny T'(\tildes^{u};M)}(x)$. Since $q^{(0)}+r = q(0,r)$ and $z \in \ker\left(\partial_d^{K(\tildes^{q^{(0)}+r};M)}\right)$, Lemma \ref{T2}(a) implies that $\kappa^{q^{(0)}+r,r}_{d}(z) \in \im\left(\partial_{d+1}^{K(\tildes^r;M)}\right) = 0$.  This completes the proof. 
  \end{proof}
  \begin{rmk}
      Note that in the previous Theorem~\ref{chainmapexists}, the obtained $\phi$ need not be unique since at each degree, there could be several choices of lifts. Since both the Tate resolution $T (\tildes^{u(r)})$ and the Koszul complex $K(\tildes^r)$ are dg $R$-algebras, one may ask if we could construct the above map such that it is a dg $R$-algebra map. Begin with any map $\phi: T (\tildes^{u(r)}) \to K(\tildes^r)$ obtained from Theorem~\ref{chainmapexists}.
      Since the dg $R$-algebra $T (\tildes^{u(r)})$ is a polynomial algebra of the form $R[\{X_{ij} \mid i >0, j \in \Lambda_i \}]$ where $X_{ij}$ are variables of degree $i$, we can define a dg $R$-algebra map $\gamma: T (\tildes^{u(r)}) \to K(\tildes^r)$ by mapping $\gamma(X_{ij}) = \phi(X_{ij})$ and then extend it to all of $T (\tildes^{u(r)})$ using the dg-structure. Hence there exists a map of dg $R$-algebras from $T (\tildes^{u(r)})$ to $K(\tildes^r)$ which extends $\kappa^{u(r),r}$.
  \end{rmk}
  \begin{cor}\label{chain map for modules}
      Let $r \geq 1$ and $u(r)$ denote the integer as in Theorem \ref{chainmapexists}. Let $P_\bullet(M/(\tildes^{u(r)})M)$ be a projective resolution of $M/(\tildes^{u(r)})M$. Then there exists a chain complex map $$\xi: P_\bullet(M/(\tildes^{u(r)})M) \to K(\tildes^r;M)$$ such that $H_0(\xi)$ is the natural surjection $M/(\tildes^{u(r)})M \twoheadrightarrow M/(\tildes^r)M$.
  \end{cor}

ref_dict.def-efpd:
\begin{defn} \label{def-efpd}
Let $I \subseteq R$ be an ideal.
    The ideal $I$ is said to have eventually finite projective dimension (efpd) if there is a filtration $\{J_n\}$ of $I$ equivalent to $\{I^k\}$ such that $\pd(R/J_n) < \infty$ for all $n \in \BN$. 
\end{defn}

ref_dict.uniform artin rees:
\begin{thm}\label{uniform artin rees}
    Let $R$ be a noetherian ring, $I = (\tildes)$ an ideal and $M$ a finitely generated $R$-module. Given $r \geq 1$, there exists $w(r):=u(h+rd)$ such that  the map $$\Tor_i^R(R/I^{w(r)},M) \to \Tor_i^R(R/I^r,M)$$ is zero for all $i \geq 1$.
\end{thm}

ref_dict.SAR defn:
\begin{defn} \cite{Aberbach} \label{SAR defn}
    Let $R$ be a commutative noetherian ring and $M$ a finitely generated $R$-module. Then $M$ is said to be syzygetically Artin-Rees with respect to an ideal $I$ if there exists a free resolution $P_\bullet$ and a uniform integer $h$  such that for all $r \geq 0$ and for $i \geq 0$,
    \begin{equation}\label{SAR}
    I^{r+h} P_i \cap B_i \subseteq I^{r} B_i.
\end{equation} 
\end{defn}

