\section{Remarks on ideals of eventually finite projective dimension}\label{last section}
\subsection*{Some consequences of the derived equivalence} 
 We now study when an ideal $I$ in a noetherian ring has efpd. The next lemma exhibits a sequence of implications that give necessary conditions for an ideal to have eventually finite projective dimension.
\begin{lemma}\label{4 statements}
Let $R$ be a noetherian ring, $I \neq R$  an ideal in it and $\L =  \L_{V(I)}$. Consider the following statements.
\begin{enumerate}[(i)]
    \item $I$ is an ideal of eventually finite projective dimension.
    \item There is a derived equivalence $ D^b( \xbar{\CP} \cap \L )  \simeq \DbLP$.
    \item There exists a non-zero finitely generated module $M$ with finite projective dimension and $\Supp(M) = V(I)$.
    \item For every minimal prime $\cp$ of $I$, $R_{\cp}$ is Cohen-Macaulay. 
\end{enumerate}

ref_dict.SR prop:
\begin{defn}\label{SR prop}
    Let $\CA \subseteq \modr$ be a resolving subcategory, $\L$ a Serre subcategory of $\modr$, $X_\bullet \in Ch^b_{\tiny \L} (\modr)$ and $J \subseteq R$ such that $X_\bullet$ is not exact and $R/J \in \L$. We say that $(T_\bullet,\alpha,I)$  is a strong reducer of $(X_\bullet, J)$ with respect to $\CA$
    if the following conditions are satisfied : 
    \begin{enumerate}
        \item $T_{\bullet} \in Ch^b_{\tiny \L}(\CA)$.
        \item $\min_c(T_{\bullet}) = m$ where $m = \min(X_\bullet)$.
        \item $\alpha: T_{\bullet} \to X_{\bullet}$ is a chain complex map.
        \item $\supph(T_{\bullet}) = \{ m \}$ and $H_m(T_\bullet) = T_m/IT_m$.
        \item $H_m(\alpha): H_m(T_{\bullet}) \to H_m(X_{\bullet})$ is surjective.
        \item $I \subseteq J$ .
    \end{enumerate}
    \indent A Serre subcategory $\L$ of $\modr$ is defined to have the strong reducer (SR) property with respect to $\CA$, if for every $X_\bullet \in Ch^b_{\tiny \L} (\modr)$ and $J \subseteq R$ such that $X_\bullet$ is not an exact complex and $R/J \in \L$, $(X_\bullet, J)$ has a strong reducer with respect to $\CA$.
\end{defn}

