A \emph{spherical variety} is a normal irreducible variety \(X\) admitting the algebraic action of a connected reductive group \(G\), such that a Borel subgroup \(B\subseteq G\) has an open orbit in \(X\). Spherical varieties naturally extend the well-known classes of toric, and generalised flag varieties, which are combinatorially characterised up to equivariant isomorphism by lattice fans, and marked Dynkin diagrams, respectively. The full class of spherical varieties exhibit rich geometrical properties, and admit a hybrid description consisting of both fans and representation theoretical combinatorics.

\begin{enumerate}
 \item a complete spherical variety to admit a toric structure (\Cref{main thm}),\label{one}
 \item a spherical variety to be smooth along any given \(G\)-orbit (\Cref{smoothness theorem}).\label{two}
\end{enumerate}

\begin{defin}[{\cite[Definition~5.1]{GH15}}]\label{def:spherical skeleton}
 The \emph{spherical skeleton} \(\mathscr{R}_X\) of a spherical variety \(X\) is a quadruple, equipped with two maps
 \[
 \mathscr{R}_X\coloneq(\Sigma,S^p,\mathcal{D}^a,\Gamma), \quad \varsigma \colon \mathcal{D}^a \to \mathcal{P}(S), \quad \rho' \colon \mathcal{D}^a \cup \Gamma \to \Lambda^*\coloneqq\operatorname{Hom}(\Lambda,\mathbb{Z}).
 \]
 Here, \(\Lambda\) is the sublattice of \(\mathcal{M}\) spanned by the spherical roots \(\Sigma\) of \(X\); \(S^p\) is the subset of simple roots whose minimal parabolic subgroups stabilise every color of \(X\); \(\mathcal{D}^a\) is the set of type \(a\) colors of \(X\); and \(\Gamma\) is the set of \(G\)-invariant prime divisors of \(X\).
 For each color \(D\in\mathcal{D}\) (of any type) of \(X\), \(\varsigma(D)\) is the set of simple roots whose associated minimal parabolic subgroup do not fix \(D\). To each \(B\)-invariant divisor \(D\in\mathcal{D}\cup\Gamma\), \(\rho'\) associates the dual vector \(\rho'(D)\coloneqq\rho(D)|_{\Lambda^*}\).
\end{defin}

The anticanonical class of a spherical variety \(X\) has a distinguished representative, namely
\[
 -K_X=\sum_{D\in\Delta}m_D D,
\]
where the coefficients \(m_D\) can be obtained from the spherical skeleton (see \Cref{rem:coeffs-anticanonical}) and \(\Delta \coloneq \mathcal{D} \cup \Gamma\) denotes the set of \(B\)-invariant prime divisors of \(X\) (which can be extracted from the spherical skeleton \(\mathscr{R}_X\)).

Furthermore, the spherical skeleton comes with the following combinatorial function
\[
 \widetilde{\wp}(\mathscr{R}_X) \coloneqq |R^+| - |R_{S^p}^+| -\sup\left\{\sum_{D\in\Delta}m_D-1+\langle\rho'(D), \vartheta\rangle \, \mid \, \vartheta \in \mathcal{Q}^*_{\mathscr{R}_X}\cap\mathrm{cone}(\Sigma)\right\},
\]
where \(R_{S^p}\) is the sub-root system generated by \(S^p\), and \(R^+\) (resp.~\(R_{S^p}^+\)) is the set of positive roots of \(R\) (resp.~\(R_{S^p}\)).
\begin{rem}
 This definition is different to the definition of \(\wp(\mathscr{R}_X)\) in~\cite{GH15}, and they are related in the following way: \(\widetilde{\wp}(\mathscr{R}_X)=|R^+|-|R_{S^p}^+|-\wp(\mathscr{R}_X)\). Moreover either \(\widetilde{\wp}(\mathscr{R}_X)\le|R^+|-|R_{S^p}^+|\) is a rational number, or it is negative infinity, by \cite[Proposition~5.6]{GH15}.
\end{rem}

We now state our main theorem, which proves \cite[Conjecture~1.4]{GH15}, and answers \eqref{one}.

\begin{thm}\label{main thm} Let \(X\) be a complete spherical variety, then
\[
\widetilde{\wp}(\mathscr{R}_X)\ge0,
\]
with equality if and only if \(X\) is isomorphic to a toric variety.
\end{thm}

\begin{enumerate}
    \item a complete spherical variety to admit a toric structure (\Cref{main thm}),\label{one}
    \item a spherical variety to be smooth along any given \(G\)-orbit (\Cref{smoothness theorem}).\label{two}
\end{enumerate}

\begin{rem}\noindent\phantomsection\label{rem:coeffs-anticanonical}
	We list some properties of the coefficients \(m_D\) in the standard spherical anticanonical divisor of a spherical variety \(X\hookleftarrow G/H\).
	By~\cite[Theorem~4.2]{BrionAnticanonical} (see also~\cite[\S3.6]{LunaAnticanonical} or~\cite[Theorem~1.5]{GorensteinFano}), the anticanonical sheaf of \(G/H\) is associated to the \(B\)-weight \(\kappa=2(\rho_S-\rho_{S^p})\), where for \(I \subseteq S\) we denote by \(\rho_I\) the half sum of positive roots in the root system generated by \(I\). 
    For each color \(D \in \D\) which is moved by a simple root \(\alpha \in S\), the coefficients \(m_D\) are:
	\begin{align*}
		m_D &= \frac12 \langle \alpha^\vee, \kappa\rangle = 1 && \text{for \(D\) of type \(a\) or \(2a\)},\\
		m_D &= \langle \alpha^\vee, \kappa \rangle \ge 2 && \text{for \(D\) of type \(b\)}.
	\end{align*}
\end{rem}

\begin{thm}\noindent\phantomsection\label{smoothness theorem}
	Let \(X\) be a spherical variety, and \(Y\subseteq X\) a \(G\)-orbit.
	Let \(I\subseteq\Delta\) be the set of \(B\)-invariant divisors \(D\) with \(Y\subseteq\overline{D}\).
	Then \(X\) is smooth along \(Y\) if and only if \(\widetilde{\wp}(\mathscr{R}_I)<1\).
\end{thm}

We now state our main theorem, which proves \cite[Conjecture~1.4]{GH15}, and answers \eqref{one}.

We now introduce the smoothness criterion which answers \eqref{two}. It utilises the following operation on spherical skeletons.

\begin{thm}\noindent\phantomsection\label{smoothness theorem}
 Let \(X\) be a spherical variety, and \(Y\subseteq X\) a \(G\)-orbit.
 Let \(I\subseteq\Delta\) be the set of \(B\)-invariant divisors \(D\) with \(Y\subseteq\overline{D}\).
 Then \(X\) is smooth along \(Y\) if and only if \(\widetilde{\wp}(\mathscr{R}_I)<1\).
\end{thm}

\begin{thm}[{\cite[Corollary of Theorem~1.6]{GHPsphericalMukai}}]
 \noindent\phantomsection\label{Spherical Mukai} Let \(X\) be a complete \(\QQ\)-Gorenstein spherical variety, then
 \[
 \widetilde{\wp}(X)\ge0,
 \]
 with \(\widetilde{\wp}(X)<1\) only if \(X\) is isomorphic to a toric variety.
\end{thm}

Let us now give an overview of the structure of the paper.
Firstly, in \Cref{sec:complete case proof} we introduce an algorithm which replaces a complete spherical variety \(X\) with a complete \(\QQ\)-Gorenstein spherical variety \(X'\) such that \(\widetilde{\wp}(X)=\widetilde{\wp}(X')\). In \Cref{sec:proof-of-gorenstein-algorithm} we prove the correctness of this algorithm. Next, in \Cref{sec:multiplicity free} we show the statement: ``\(\widetilde{\wp}(X)=0\) if \(X\) is isomorphic to a toric variety'', is equivalent to \(\widetilde{\wp}(V)=0\) where \(V\) is a member of one of \(42\) families of multiplicity free spaces. Finally, in \Cref{Table} we explicitly verify this equality for each of these \(42\) families, completing the proof of \Cref{main thm}.

\section{\texorpdfstring{Toric varieties and \(\widetilde{\wp}\)}{Toric varieties and P}}\noindent\phantomsection\label{sec:multiplicity free}
Let us continue to use the notation and assumptions from above.
In particular, \(X\) denotes a complete \(G\)-spherical variety.
In this section we prove that \(\widetilde{\wp}(X)<1\) if and only if \(X\) is isomorphic to a toric variety, if and only if \(\widetilde{\wp}(X)=0\), which completes the proof of \Cref{main thm}.
Indeed, we show
\[
 \widetilde{\wp}(X) <1 \Rightarrow X\text{ isomorphic to a toric variety} \Rightarrow \widetilde{\wp}(X)=0 \Rightarrow \widetilde{\wp}(X)<1.
\]

\begin{rem}\noindent\phantomsection\label{toric skeleton}
 There is a natural notion of isomorphism of spherical skeletons (see~\cite[Section~5]{GH15}), and by design \(\widetilde{\wp}(X)=\widetilde{\wp}(\mathscr{R}_X)\) only depends on \(\mathscr{R}_X\) up to isomorphism.
 For completeness and to ensure that this work is self-contained, we briefly recall when two spherical skeletons \(\mathscr{R}_1 = (\Sigma_1, S_1^p, \D_1^a, \Gamma_1, \varsigma_1, \rho'_1)\) and \(\mathscr{R}_2 = (\Sigma_2, S_2^p, \D_2^a, \Gamma_2, \varsigma_2, \rho'_2)\) are considered to be \emph{isomorphic}, written \(\mathscr{R}_1 \cong \mathscr{R}_2\).
 Suppose the underlying root system of \(\mathscr{R}_1\) (resp.~\(\mathscr{R}_2\)) is \(R_1\) (resp.~\(R_2\)).
 We say \(\mathscr{R}_1\) and \(\mathscr{R}_2\) are isomorphic if there exists an isomorphism of root systems \(\varphi_R \colon R_1 \to R_2\) and two bijections \(\varphi_\D \colon \D_1^a \to \D_2^a\) and \(\varphi_\Gamma\colon \Gamma_1 \to \Gamma_2\) such that \(\varphi_R(\Sigma_1) = \Sigma_2\), \(\varphi_R(S_1^p) = S_2^p\), and \(\rho'_1(D) = \rho'_2(\varphi_\D(D))\circ\varphi_R\) on \(\Sigma_1\) for every \(D \in \D_1^a\) as well as \(\rho'_1(D) = \rho'_2(\varphi_\Gamma(D))\circ \varphi_R\) on \(\Sigma_1\) for every \(D \in \Gamma_1\). 
\end{rem}

The following theorem is a key result that is required in the proof of \Cref{main thm}.
\begin{thm}[{\cite[Theorem~6.7]{GH15}}]\noindent\phantomsection\label{thm:toric-is-mult-free-space}
 A complete \(G\)-spherical variety \(X\) is isomorphic to a toric variety if and only if \(\mathscr{R}_X \cong \mathscr{R}_V\) for \(V\) a \emph{\(G\)-multiplicity free space}; i.e.~a rational \(G\)-representation with the structure of a \(G\)-spherical variety (see also \Cref{def:mult-free-space}).
\end{thm}

