ref_dict.prop:ladderker:
\begin{proposition}
\label{prop:ladderker}
The kernel of the intertwining operator $(s-\frac{2}{3})A(1,s):I(1,s)\to I(1,\tilde{s})$ at $s = \frac{2}{3}$ is the ladder representation of $G$. It is also the image of the intertwiner $A(1,\tilde{s}):I(1,\tilde{s})\to I(1,s)$. Moreover, this subrepresentation has $K$-types $\sigma(3m+2,m)$ ($m\in\ZZ_{\geq0}$) with corresponding embedding vectors $v_{3m+2,m}(s,0)$.
\end{proposition}

ref_dict.prop:sgnirred:
\begin{proposition}
\label{prop:sgnirred}
The representation $\pi_{1,s}$ is reducible if and only if $s$ or $\tilde{s}=3-s$ is contained in $\ZZ_{\geq2}\cup(\frac{7}{3}+\frac{2}{3}\ZZ_{\geq0})$.
\end{proposition}

ref_dict.prop:irredtriv:
\begin{proposition}
\label{prop:irredtriv}
The representation $\pi_{0,s}$ is reducible if and only if $s$ or $\tilde{s}=3-s$ is contained in $\ZZ_{\geq2}\cup(2+\frac{2}{3}\ZZ_{\geq0})$.
\end{proposition}

ref_dict.thmintroC:
\begin{thmalph}[see Propositions~\ref{prop:ladderker} and \ref{prop:doubleladderker}]\label{thmintroC}
    \begin{itemize}
        \item The ladder representation $\pi_{\mathrm{min}}$ of $G$ is the kernel of the intertwining operator $A(1,s)$ at $s=\frac{2}{3}$.
        \item The double ladder representation $\pi_{\mathrm{small}}$ of $G$ is the kernel of the intertwining operator $A(0,s)$ at $s=\frac{1}{3}$.
    \end{itemize}
\end{thmalph}

ref_dict.cor:ComplementarySeries:
\begin{corollary}\label{cor:ComplementarySeries}
    For both choices of $\varepsilon\in\ZZ/2\ZZ$, the representations $\pi_{\varepsilon,s}$ belong to the complementary series for $s\in(1,2)$, i.e. $\pi_{\varepsilon,s}$ is irreducible and unitarizable for $s\in(1,2)$.
\end{corollary}

