\label{thm:main}
	Let $ F$ be a finite extension of $\QQ_p$, let $\chi\in\Irr(\mathcal G)$, and let $\eta\mid\res^\G_H\chi$ be an irreducible constituent. Then for the $\chi$-component in the Wedderburn decomposition
\begin{equation} \label{eq:QFG-Wedderburn}
    \Q^ F(\G) \simeq \bigoplus_{\chi\in \Irr(\G)/\sim_ F} M_{\nFchi}(\DFchi)  .
\end{equation}
	\begin{theoremlist}
		\item the size of the matrix ring is $n_{F,\chi} = n_\eta v_{F,\chi}$, \label{item:main-n}
		\item the Schur index of $D_{F,\chi}$ is $s_{F,\chi} = s_\eta (F(\eta):F_\chi)$, \label{item:main-s}
		\item the skew field is isomorphic to the total ring of quotients of a skew power series ring: $D_{F,\chi} \simeq \Quot\left(\OO_{D_\eta}[[X; \tau_F, \tau_F-\id]]\right)$. \label{item:main-D}
	\end{theoremlist}

ref_dict.def : CQ1 exact chain complexes:
\begin{deftn} \label{def : CQ1 exact chain complexes}
  Let $C_{\bullet}$ be a chain complex in $\KQ^{(1)}$. We say that $C_{\bullet}$ is $\HQ^{(1)}$-exact if the following properties hold:
   \begin{itemize}
       \item We have that $C_n = 0$ for all $n<0$ and $C_0$ is indecomposable dominant. 
       \item For every $n>0$ and every finite set $Z \subset \ZQz$, we have that 
       $$ Z \cap \mathrm{Supp}(C_0) \neq \emptyset \quad \Rightarrow \quad \forall f : C_n \rightarrow \mu_Z(C_0), f \circ d_{n-1}^{C_{\bullet}} = 0 \Rightarrow \text{$f$ factors through $d_n^{C_{\bullet}}$.} $$
   \end{itemize}
   \end{deftn}

ref_dict.thm : existence of morphisms eta:
\begin{thm} \label{thm : existence of morphisms eta}
    There exists a family of irreducible morphisms 
    $$\{\eta_i^{(X,h)}   \in \mathrm{Hom}_{\HQ^{(1)}} \left( (X,h) , \mu_i (X,h) \right) , \enspace \text{$(X,h)$ indecomposable in $\HQ^{(1)}$}, i \in \Sigma(X,h) \}$$ 
    satisfying the following properties:
     \begin{enumerate}
         \item For every $i \in \Sigma(X,h)$ and every $j \in I$ such that  $j \rightsquigarrow i$ in $Q$, we have that  
         $$j \in \Sigma( \mu_i(X,h)) \qquad \text{and} \qquad  \eta_j^{\mu_i(X,h)} \circ \eta_i^{(X,h)} = 0 . $$ 
         \item For any object $T$ in $\HQ^{(1)}$, and any morphism $f \in \mathrm{Hom}_{\HQ^{(1)}}(\mu_i(X,h), T)$, we have that 
         $$ f \circ \eta_i^{(X,h)} = 0 \quad \Rightarrow \quad \text{$f$ factors through $\bigoplus_{ \substack{j \rightsquigarrow i \\ j \in \Sigma(\mu_i(X,h))}} \eta_j^{\mu_i(X,h)}$.} $$
     \end{enumerate}
  \end{thm}

ref_dict.thm : thm1 intro:
\begin{thm} \label{thm : thm1 intro}
      For each positive (or negative simple) root $\beta$, there exists a unique (up to isomorphism) strongly $\HQ^{(1)}$-exact complex $C_{\bullet}[\beta]$ in $\KQ^{(1)}$ such that $C_n[\beta]=0$ if $n<0$ and $C_0[\beta]$ is indecomposable and isomorphic to $Y[\beta]$. 
  \end{thm}

ref_dict.def : Serre tiltings:
\begin{deftn} \label{def : Serre tiltings}
 Given any indecomposable object $(X,h)$ in $\tMQ$ and any \textit{finite} subset $Y = \{ y_1 , \ldots  , y_r\} \subseteq X$, we define the \textbf{Serre tilting} of $(X,h)$ at $Y$ as the object of $\tMQ$ given by  
 $$ \mu_Y(X,h) := \left(  (X \setminus Y) \sqcup SY \enspace , \enspace  h - \sum_{y \in Y} \delta_y \right) $$
 where $SY$ stands for $SY := \{S y_1, \ldots , S y_r\}$.  For simplicity we will write $\mu_y(X)$ for $\mu_{\{y \}}(X)$.
   \end{deftn}

ref_dict.def : quasi-additive functions:
\begin{deftn} \label{def : quasi-additive functions}
     A function $f : \ZQz \longrightarrow \mathbb{Z}$ will be called quasi-additive if $\widetilde{f}$ has finite support, i.e. $\widetilde{f}(x)=0$ on all but finitely many vertices of $\ZQ$.
   \end{deftn}

ref_dict.def : strong exactness:
\begin{deftn} \label{def : strong exactness}
     Let $C_{\bullet}$ be a chain complex in $\KQ^{(1)}$.  We say that $C_{\bullet}$ is strongly $\HQ^{(1)}$-exact if $C_{\bullet}$ is $\HQ^{(1)}$-exact and moreover all the non-trivial components of each differential of $C_{\bullet}$ are of the form $\eta_i \otimes \mathrm{id}$ for some $i \in \mathrm{Supp}(C_0)$. 

   \end{deftn}

