The following lemma is similar to \cite[Theorem 3.3 and Lemma 3.4]{SandersSane}. The proof is really a check that the proofs of those results work, with the strong reducer replacing the 
choices of ideals and Koszul resolution. That being the case, we only give a sketch of the proof.
\begin{lemma}\label{morphisms in derived category} 
 Suppose $\L$ has the SR property with respect to $\CA$. Let $X_\bullet \xrightarrow{f} Y_\bullet$ be a morphism in $\DbLT$ such that $X_\bullet$ and $Y_\bullet$ are chain complexes in $Ch^b(\T \cap \L), \min(X_\bullet \oplus Y_\bullet) =m$ and $\min_c(X_\bullet), \min_c(Y_\bullet) \geq m$. Then there exists chain complexes $M_\bullet^X$ and $M_\bullet^Y$ in $Ch^b(\T \cap \L)$ and maps of chain complexes $M_\bullet^X \xrightarrow{\beta^X} X_\bullet$, $M_\bullet^Y \xrightarrow{\beta^Y} Y_\bullet$ and $M_\bullet^X \xrightarrow{\rho} M_\bullet^Y$, such that 
 \begin{itemize}
 \item $M_\bullet^X, M_\bullet^Y \in Ch^b(\T \cap \L)$ with $M_i^X = M_i^Y = 0$ for all $i \neq m$.
 \item there is a commutative square in $\DbLT$: 
 $$\xymatrix{ M_\bullet^X \ar[r]^{\beta^X} \ar[d]^{\rho} & X_\bullet \ar[d]^{f\qquad .}\\ M_\bullet^Y \ar[r]^{\beta^Y} & Y_\bullet }$$
 \item $H_m(\beta^X)$ and $H_m(\beta^Y)$ are surjective. 
 \end{itemize}
 Let $C_\bullet^X$ and $C_\bullet^Y$ be the cones of $\beta^X$ and $\beta^Y$ respectively. If $\width(X_\bullet \oplus Y_\bullet) = k >0$, then
 \begin{enumerate}
 \item $\width(C_\bullet^X \oplus C_\bullet^Y)< k$.
 \item $\width(C_\bullet^X \oplus Y_\bullet)\leq k$.
 \item If $\min(X_\bullet) < \min(Y_\bullet)$, then $\min(C_\bullet^X \oplus Y_\bullet)\leq k-1$.
 \end{enumerate}
\end{lemma}
\begin{proof}
Define the complex $M_\bullet^Y$ to be $\Sigma^m Y_m$ and $\beta^Y: M_\bullet^Y \to Y_\bullet$ the inclusion map. Then $M_\bullet^Y \in Ch^b(\T \cap \L)$ and $\beta^Y$ is a chain complex map such that $H_m(\beta^Y)$ is surjective. \\
Let $f$ be given by a roof diagram $X_\bullet \xleftarrow{q} Q_\bullet \xrightarrow{g} Y_\bullet$ where $q$ is a quasi-isomorphism. We may assume $\min_c(Q_\bullet) = m$. Let $Q_\bullet'$ be the pullback of $\beta^Y$ and $g$ in $Ch^b(\modr)$: 
$$\xymatrix{ Q_\bullet' \ar@{..>}[r]^{\nu} \ar@{..>}[d]^{\mu} & Q_\bullet\ar[d]^{g \qquad .} \\ M_\bullet^Y \ar[r]^{\beta^Y} & Y_\bullet }$$
Thus we get an exact sequence $0 \to Q_\bullet' \to Q_\bullet \oplus M_\bullet^Y \to B_\bullet \to 0$ where $B_\bullet$ is the image of the map $Q_\bullet \oplus M_\bullet^Y \xrightarrow{(g, -\beta^Y)} Y_\bullet$. We observe $B_\bullet \in Ch^b(\L)$ and hence $B_\bullet \in Ch^{b}_{\tiny \L}(\modr)$. Since $M_\bullet^Y$ and $Q_\bullet$ also lie in $Ch^{b}_{\tiny \L}(\modr)$, we get $Q_\bullet' \in Ch^{b}_{\tiny \L}(\modr)$. Set $\lambda = q \circ \nu$ and $J = \Ann(X_m)$. Then $R/J \in \L$. Since $\L$ has the SR property with respect to $\CA$, $(Q_\bullet',J)$ has a strong reducer $(T_\bullet,\alpha,I)$ with respect to $\CA$. Therefore, we have the following commutative diagram in $D^{b}_{\tiny \L}(\modr)$: 
$$\xymatrix{ T_\bullet \ar[r]^{\alpha} & Q_\bullet' \ar[r]^{\lambda} \ar[d]^{\mu} & X_\bullet\ar[d]^{f \qquad .} \\ & M_\bullet^Y \ar[r]^{\beta^Y} & Y_\bullet }$$
Define $M_\bullet^X$ to be the chain complex $\Sigma^m H_m(T_\bullet) \in Ch^b(\xbar \CA \cap \L) \subseteq Ch^b(\T \cap \L)$. Since $I \subseteq J = \Ann(X_m)$ and $H_m(T_\bullet) \cong T_m/IT_m$, the map $\lambda_m \circ \alpha_m : T_m \to X_m$ factors through $T_m/IT_m$. Therefore, we get a chain complex map $\beta^X : M_\bullet^X \to X_\bullet$. Also $\mu \circ \alpha$ factors through $M_\bullet^X$ giving a chain complex map $\rho: M_\bullet^X \to M_\bullet^Y$ such that the following diagram commutes in $\DbLT$:
 $$\xymatrix{ M_\bullet^X \ar[r]^{\beta^X} \ar[d]^{\rho} & X_\bullet \ar[d]^{f \qquad .} \\ M_\bullet^Y \ar[r]^{\beta^Y} & Y_\bullet. }$$To show that $H_m(\beta^X)$ is surjective, it is enough to show that $H_m(\nu)$ is surjective, which follows because $Q'_{\bullet}$ is just the degree-wise pullback. The statements $(1), (2)$ and $(3)$ can be derived from the long exact sequence of homologies arising from the mapping cone, similar to the proof of the previous lemma.
\end{proof}

\section{Remarks on ideals of eventually finite projective dimension}\label{last section}
\subsection*{Some consequences of the derived equivalence} 
 We now study when an ideal $I$ in a noetherian ring has efpd. The next lemma exhibits a sequence of implications that give necessary conditions for an ideal to have eventually finite projective dimension.
\begin{lemma}\label{4 statements}
Let $R$ be a noetherian ring, $I \neq R$ an ideal in it and $\L = \L_{V(I)}$. Consider the following statements.
\begin{enumerate}[(i)]
 \item $I$ is an ideal of eventually finite projective dimension.
 \item There is a derived equivalence $ D^b( \xbar{\CP} \cap \L ) \simeq \DbLP$.
 \item There exists a non-zero finitely generated module $M$ with finite projective dimension and $\Supp(M) = V(I)$.
 \item For every minimal prime $\cp$ of $I$, $R_{\cp}$ is Cohen-Macaulay. 
\end{enumerate}
Then $(i) \Rightarrow (ii) \Rightarrow (iii) \Rightarrow (iv)$.
\end{lemma}
\begin{proof}
 $(i) \Rightarrow (ii)$ : This is Corollary \ref{derived equivalence for efpd}(c). \\
 $(ii) \implies (iii)$ : By the Hopkins-Neeman theorem, $$V(I) = \bigcup_{\tiny{X \in \DbLP}} \Supp(X) = \bigcup_{\tiny{X \in D^b( \xbar{\CP} \cap \L )}} \Supp(X) = \bigcup_{\tiny{M \in \xbar{\CP} \cap \L}} \Supp(M).$$
Hence, for each $\cp_i \in Min(I)$, there exists $M_i \in \xbar{\CP} \cap \L$ such that ${(M_i)}_{\cp_{i}} \neq 0$ . Thus $M = \oplus M_i$ is finitely generated, has finite projective dimension and $\Supp(M) = V(I)$. \\
$(iii) \implies (iv):$ For any minimal prime $\cp$ of $I$, the $R_{\cp}$-module $M_{\cp}$ has finite projective dimension and $\Supp(M_{\cp}) = \{ \cp R_{\cp} \}$. Hence by Corollary \ref{intersection cor}, $R_{\cp}$ is Cohen-Macaulay. 
\end{proof}
Note that the implication $(i) \implies (iii)$ follows directly from the definition (for example, by choosing $M = R/I_n$).
\begin{eg}
 Example \ref{efpd non-example} in which $R=k[X,Y]/(XY)$ for a field $k$ and $I = (X)$ also shows that $(iv) \not\Rightarrow (iii)$.
\end{eg}
\begin{question}
 Are any of the other reverse implications true?
\end{question}
 We highlight below the special case where $(R,\m)$ is a local ring and $I$ is an $\m$-primary ideal wherein the statements above are equivalent.
This is a direct extension of \cite[Theorem 1.1]{SandersSane}, which was the inspiration for the previous lemma, and adds to the characterization of Cohen-Macaulay local rings in terms of the efpd property.
\begin{cor}\label{CM characterization}
 Let $(R,\m)$ be a noetherian local ring. Then the following are equivalent :
 \begin{enumerate}[(i)]
 \item $\m$ has efpd.
 \item $ D^b( \xbar{\CP} \cap \L ) \simeq \DbLP$ where $\L = \L_{V(\m)}$.
 \item There exists a non-zero finitely generated module $M$ with finite length finite projective dimension.
 \item $(R,\m)$ is Cohen-Macaulay.
 \end{enumerate}
\end{cor}
\begin{proof} By the previous lemma, we only need to prove $(iv) \Rightarrow (i)$ which follows by observing that when $R$ is Cohen-Macaulay, then $\m$ is a set-theoretic complete intersection ideal. \\
\end{proof}
Note that some of these implications can be directly proved to be equivalent.

