and let $k$ be such that $$n_k<n\leq n_{k+1}.$$
Define $$n_B:=\max\{n,n_{k}^{(d)}+1\}$$
By \eqref{eq:muB}, we have
$$\mu(B)\leq \frac{\#\{E\in \mathcal{E}_{n_B}: E\cap B\neq \emptyset\}}{\# \mathcal{E}_{n_B}}$$
Hence
\begin{align}
 \log_{\ell}\mu(B)&\geq \log_{\ell}\left(\#\{E\in\mc E_{n_B}:E\cap B\neq \emptyset\}\right)+\log_{\ell}\left(\frac{1}{\#\mc E_{n_B}}\right) \notag\\
&=\frac{\log(\#\mc E_{n_B})}{|\log\ell|}-\frac{\log\left(\#\{E\in\mc E_{n_B}:E\cap B\neq \emptyset\}\right)}{|\log\ell|} \notag\\
&\overset{\eqref{eq:l}}{\geq} \frac{\log(\#\mc E_{n_B})}{(n+1)\log\rho_1}-\frac{\log\left(\#\{E\in\mc E_{n_B}:E\cap B\neq \emptyset\}\right)}{n\log\rho_1}. \label{eq:logmuB}
\end{align}
We will treat these two terms separately, using Propositions \ref{prop:count} and \ref{prop:intersection}. Let us start from the first one.
Since $n_B\geq n_k^{(d)}+1$, by Proposition \ref{prop:count}, we have that
$$\# \mc E_{n_B}\geq \dfrac{1}{2}\left(\rho(1-\rho^{-\eta})\right)^{n_k(1-\gamma)+n_B-(n_k^{(d)}+1)}\prod_{i=1}^{d} \floor*{\rho_i^{(n_k^{(d)}+1-n_k^{(i)})}} $$
Therefore,
\begin{multline}\label{eq:ing1}
 \frac{\log(\#\mc E_{n_B})}{(n+1)\log \rho_1}
\geq \sum_{i=1}^d \frac{n_k+n_B-n_k^{(i)}}{n}\frac{\log \rho_i}{\log \rho_1} \\
+O_d\left(\frac{1+|\log(1-\rho^{-\eta})|(n_k+n_B-(n_k^{(d)}+1))}{n\log \rho_1}+\frac{(\gamma\log \rho) n_k}{n\log \rho_1}+\frac{\log(\#\mc E_{n_B})}{n^2\log \rho_1}\right).
\end{multline}
Let us now move on to the second term in \eqref{eq:logmuB}. By Proposition \ref{prop:intersection} and the fact that $n_B\geq n_{k}^{(d)}+1$, we have that
\begin{multline*}
 \#\{E\in\mc E_{n_B}:E\cap B\neq \emptyset\}\leq \\
 \prod_{i=1}^d \left(2\max\left\{\frac{\ell}{\rho_0^{(i)}\rho_i^{-n_k}},1\right\}\cdot \min \left\{\dfrac{l}{\rho_0^{(i)}\rho_i^{-n_k^{(i)}}},1\right\} \cdot \max\left\{\dfrac{\rho_i^{-n_k^{(i)}}}{\rho_i^{-n_B}},\dfrac{\rho_0^{(i)}\rho_i^{-n_k^{(i)}}}{l}\right\}\right)\\
 \leq \prod_{i=1}^d \left(2\max\left\{\frac{\rho_1^{-n}}{\rho_0^{(i)}\rho_i^{-n_k}},1\right\}\cdot \min \left\{\dfrac{\rho_1^{-n}}{\rho_0^{(i)}\rho_i^{-n_k^{(i)}}},1\right\} \cdot \rho_i^{n_B-n_k^{(i)}}\right),
\end{multline*}
where the last inequality follows from the fact that $\rho_1^{-(n+1)}\leq l<\rho_1^{-n}$, $n_B\geq n$, and $\rho_0^{(i)}\cdot \rho_1\leq 1$.
Hence
\begin{multline}
\label{eq:ing2}
\frac{\log(\#\{E\in\mc E_{n_B}:E\cap B\neq \emptyset\})}{n\log\rho_1}\leq \sum_{i=1}^d\max\left\{\frac{n_k}{n}\frac{\log(\rho_i)}{\log(\rho_1)}-1,0\right\}\\
+\min\left\{\frac{n_k^{(i)}}{n}\frac{\log(\rho_i)}{\log(\rho_1)}-1,0\right\}+\frac{n_B-n_k^{(i)}}{n}\frac{\log \rho_i}{\log \rho_1}+O_{d}\left(\sum_{i=1}^d\frac{1+|\log \rho_0^{(i)}|}{n\log \rho_1 }\right). 
\end{multline}
Combining \eqref{eq:ing1} and \eqref{eq:ing2} we deduce that
\begin{multline*}
\log_{\ell}\mu(B)\geq \sum_{i=1}^d \left(\frac{n_k}{n}\frac{\log \rho_i}{\log \rho_1}-\max\left\{\frac{n_k}{n}\frac{\log(\rho_i)}{\log(\rho_1)}-1,0\right\}
-\min\left\{\frac{n_k^{(i)}}{n}\frac{\log(\rho_i)}{\log(\rho_1)}-1,0\right\}\right) \\
+O_{d,\tau,\bs w,\delta}\left(\frac{1}{\log R}+\gamma+\frac{1}{n}\right),
\end{multline*}
which can be re-written as
\begin{multline}
\label{eq:mu}
\log_{\ell}\mu(B)\geq\sum_{i=1}^d\min\left\{\frac{\log(\rho_i)}{\log(\rho_1)}\frac{n_k}{n},1\right\}+ \max\left\{1-\frac{\zeta_i\cdot \log(\rho_i)}{\log(\rho_1)}\frac{n_k}{n},0\right\} \\
+O_{d,\tau,\bs w,\delta}\left(\frac{1}{\log R}+\gamma+\frac{1}{n}\right).
\end{multline}
where $\zeta_i:=(1+\tau w_i)/(1+\tilde{w}_i)$.

\subsection{Finding the Minimum}
We will now study the function
$$f(x):=\sum_{i=1}^d\min\left\{\frac{\log(\rho_i)}{\log(\rho_1)}x,1\right\}+\max\left\{1-\frac{\zeta_i\cdot \log(\rho_i)}{\log(\rho_1)}x,0\right\}$$
for $x\in[0,1]$. For $h=1,\dotsc,d$ and $k=0,\dotsc,d$ we define
$$f_{h,k}(x):=k+d-h+\left(\log(\rho_1\dotsm\rho_h)-\sum_{i=1}^k\zeta_i\cdot\log(\rho_i)\right)\frac{x}{\log(\rho_1)},$$
where the sum over $i$ is null if $k=0$. Our goal will be to prove the following.
\begin{proposition}
\label{prop:min}
It holds that
\begin{equation*}
\min_{x\in[0,1]}f(x)=\min_{1\leq k\leq d}\min_{1\leq h\leq d}f_{h,k}\left(\frac{\log(\rho_1)}{\zeta_{k}\cdot\log(\rho_k)}\right).
\end{equation*} 
\end{proposition}

Now, there are two cases: either the minimum is realized for $k\leq K$ or for $k>K$, where $K$ is defined in Lemma \ref{lem:Rynne}. Let us assume first that the minimum is realized for $k\leq K$. Then, since $\tilde w_i\leq \tau w_{i}$ it must be $h\geq k$ and we have that
\begin{multline*}
\sum_{i=1}^h\frac{1+\tilde{w}_i}{1+\tau w_k}+d-h=\sum_{i=1}^k\frac{1+\tilde{w}_i}{1+\tau w_k}+\sum_{i=k+1}^h\frac{1+\tilde{w}_i}{1+\tau w_k}+d-h \\
\geq \sum_{i=1}^k\frac{1+\tau w_i-\delta(1+\tau w_i)}{1+\tau w_k}+\sum_{i=k+1}^h\frac{1+\tau w_{k}-\delta(1+\tau w_k)}{1+\tau w_k}+d-h \\
\geq \sum_{i=1}^k\frac{1+\tau w_i}{1+\tau w_k}+d-k-\delta(d+\tau).
\end{multline*}
Hence, the dimension is at least $d-\delta(d+\tau)$. If we assume that
$$\delta(\tau +d)<d-\dimH W_{\bs w}(\tau),$$
we find a contradiction. Hence, the minimum must be realized for $k>K$. Since $1+\tilde w_k\leq 1+\tau w_k$ and $\tilde w_i=\tilde w_j$ for any $i,j>K$, it must be $h=d$. The expression above is therefore equal to
$$\min_k\frac{d+1-\sum_{i=1}^k\tau w_k-\tau w_i}{1+\tau w_k},$$
which, by Theorem \ref{thm:Rynne}, yields Theorem \ref{thm:mainthm}.
