We now turn to our main result on geometric distance-regular graphs.

Koolen and Bang~\cite{KB2010} proposed the following two conjectures concerning geometric distance-regular graphs.

\begin{lemma}[cf.~{\cite[Theorem~4.4.3]{bcn89}}]\label{localgraph}
Let $\Gamma$ be a distance-regular graph with valency $k$, diameter $D \geq 3$, and distinct eigenvalues $k = \theta_0 > \theta_1 > \cdots > \theta_D$.
Let $b = \frac{b_1}{\theta_1 + 1}$.
Then, for a vertex $x$ of $\Gamma$, the smallest eigenvalue of the local graph $\Delta_x$ satisfies
\[
\theta_{\min}(\Delta_x) \geq -b - 1.
\]
\end{lemma}

\begin{lemma}[cf.~{\cite[Lemma 5.2]{BHK2007}}]\label{2phi1}
Let $\Gamma$ be a distance-regular graph with valency $k$ and diameter $D \geq 2$, containing a Delsarte clique $C$ of order $s + 1$. Then the following hold:
\begin{enumerate}
 \item Let $i$ and $j$ be positive integers such that $i + j \leq D - 1$. Then $\phi_i + \phi_j \leq s + 1$.
 \item If $\phi_1 > \frac{s + 1}{2}$, then $D = 2$.
 \item Suppose $\phi_1 \geq 2$. Then for all $x \in C$, the local graph $\Delta_x$ is connected, and its second largest eigenvalue equals $s - \phi_1$. Moreover, if $D = 2$, then $\Gamma$ has eigenvalues $k, s - \phi_1, -\frac{k}{s}$.
\end{enumerate}
\end{lemma}

\begin{corollary}\label{psibound-CP}
Let $\Gamma$ be a geometric distance-regular graph with classical parameters $(D, b, \alpha, \beta)$, valency $k$, and diameter $D \geq 3$, and let the distinct eigenvalues of $\Gamma$ be $k = \theta_0 > \theta_1 > \cdots > \theta_D$. Let $(u_i)_i$ denote the standard sequence corresponding to $\theta_1$. Then the following inequalities hold:
\begin{enumerate}
\item $\left( \phi_1 - \frac{b u_2}{u_1} \right)^2 \geq \left( \beta + \frac{1}{u_1} \right) \left( \phi_1 - b^2 - 2b - 1 + \frac{1}{u_1} \right).$

\begin{theorem}[{\cite[Theorem 26]{LK2024+}}]\label{srsg}
Let $\Gamma$ be a geometric distance-regular graph with respect to $\mathcal C$, having valency $k$, smallest eigenvalue $\theta_{\min}$, diameter $D \geq 3$, and $\phi_1 \geq 2$. Let $r = -\theta_{\min}$ and $\beta = \frac{k}{-\theta_{\min}}$. 
Assume that $\Gamma$ satisfies the ELS property. Then the following hold:
Let $x, y$ be a pair of vertices at distance 2 in $\Gamma$. Assume that $[x, y] = \{\ell_1, \ell_2, \ldots, \ell_{\tau_2}\}$. Let $\Sigma= \Sigma(x,y)$ be the subgraph induced on 
$\{x\} \cup \ell_1 \cup \ell_2 \cup \cdots \cup \ell_{\tau_2} \cup \{ z \in \Gamma_2 (x) \mid [x, y]= [x, z]\}$.
Then the graph $\Sigma$ has the following properties:
\begin{enumerate}
\item $\Sigma$ has diameter 2.
\item $\Sigma$ is geodetically closed.
\item If $\Sigma$ contains two vertices of a Delsarte clique $C \in {\mathcal C}$, then $\Sigma$ contains all the vertices of $C$.
\item $\Sigma$ is a geometric strongly regular graph with parameters 
\[
\left( \frac{\beta(\beta - \phi_1 + 1)(\tau_2 - 1)}{\phi_1} + \beta \tau_2 + 1, \ \beta \tau_2, \ \beta - 1 + (\phi_1 - 1)(\tau_2 - 1), \ \phi_1 \tau_2 \right).
\]
\item For every pair of vertices at distance 2, there exists a unique induced subgraph $\Delta$ of $\Gamma$ containing them such that $\Delta$ has diameter 2, is geodetically closed, and has the property that whenever $\Delta$ contains two vertices of a Delsarte clique in $\mathcal{C}$, it contains the entire Delsarte clique.
\end{enumerate}
\end{theorem}

\begin{theorem}\label{JG}
Let $\Gamma$ be a geometric distance-regular graph with diameter $D \geq 3$ and parameters satisfying $\phi_1 = \tau_2 \geq 2$. Then one of the following holds:
\begin{enumerate}
\item $\phi_1=\tau_2=2$ and $\Gamma$ is a Johnson graph. 
\item $\phi_1=\tau_2\geq3$ and $\Gamma$ is a Grassmann graph defined over the field $\mathbb{F}_{\tau_2-1}$.
\end{enumerate}
\end{theorem}
{\bf Proof.}
Let $\alpha = \phi_1 = \tau_2\geq 2$, and $\mathcal{C}$ be a set of Delsarte cliques of $\Gamma$ such that $\Gamma$ is the point graph of the partial linear space $(V(\Gamma), \mathcal{C}, \in)$. Since $D \geq 3$, there exists a pair of noncollinear vertices, so $(V(\Gamma), \mathcal{C}, \in)$ is not a linear space. 
We will further show that all conditions of Theorem~\ref{cuyprs-pls} are satisfied for $(V(\Gamma), \mathcal{C}, \in)$.

\begin{theorem}\label{assemthm}
Let $\Gamma$ be a geometric distance-regular graph with respect to $\mathcal C$, having valency $k$, smallest eigenvalue $\theta_{\min}$, diameter $D \geq 3$, and $\phi_1 \geq 2$. Let $r = -\theta_{\min}$ and $\beta = \frac{k}{-\theta_{\min}}$.
For a vertex $x$, let $\Delta_x$ be the local graph at vertex $x$. 
Assume that $\Gamma$ satisfies the dual Pasch axiom.
Let $\ell$ be a line, $M$ an assembly and $u$ be a vertex of $\Gamma$ not in $M$. 
Then the following hold:
\begin{enumerate}
\item If $\ell$ intersects with $M$, then they intersect in exactly $\phi_1$ vertices;
\item If $u$ has a neighbour in $M$, then $u$ has exactly $\phi_1$ neighbours in $M$ and there is exactly one line through $u$ that intersects $M$. 
\end{enumerate}
As a consequence we have that for each vertex $x$ of $\Gamma$, the local graph $\Delta_x$ at vertex $x$ is the $(\phi_1-1)$-clique extension of a $\frac{\beta}{\phi_1-1} \times r$-grid.
\end{theorem}
{\bf Proof.}
Let $M$ be an assembly and $\ell$ be a line in $\mathcal C$ and assume that $M$ and $\ell$ intersect in a vertex $w$. Let $\ell_1:=\ell , \ell_2, \ldots, \ell_r$ be the lines through $w$. 
As $M \setminus \ell_i \neq \emptyset$ for $i=1,2,\ldots, r$ and each vertex outside $\ell_i$ has at most $\phi_1$ neighbours in $\ell_i$, we have $|M \cap \ell_i|\leq \phi_1$ for 
$i=1,2,\ldots,r$. Note that $M \setminus \{w\}= \bigcup\limits_{i=1}^{r}(M \cap \ell_i \setminus \{w\})$. Therefore 
$(\phi_1-1) r=|M \setminus \{w\}|\leq \sum\limits_{i=1}^{r} (|M\cap \ell_i|-1) \leq \sum\limits_{i=1}^{r} (\phi_1-1)= (\phi_1-1) r$, and hence $|M \cap \ell_i| = \phi_1$ for $1\leq i \leq r$. 
In particular, $|M\cap \ell|= \phi_1$. 
This shows Item~(1) of the theorem.

