  \node (e) at (0,0) {$(1,1)$};
  \node (f) at (2,0) {$(2,0)$};
  \node (g) at (-1,-2) {$(0,1)$};
  \node (h) at (1,-2) {$(1,0)$};
  \node (min) at (0,-4) {$(0,0)$};
  \draw (min) -- (g) -- (d) -- (a) -- (max);
  \draw (min) -- (h) -- (f) -- (c) -- (max);
  \draw (g) -- (e) -- (b) -- (max);
  \draw (h) -- (e) -- (c);
  \draw (d) -- (b);
