\columnbreak 
\begin{align*} 
    \mu_\sP\big((0,3)\big) &= 1\\
    \mu_\sP\big((1,2)\big) &= 1\\
    \mu_\sP\big((2,1)\big) &= 1\\
    \mu_\sP\big((0,2)\big) &= -1\\
    \mu_\sP\big((1,1)\big) &= -1\\
