\begin{prop}\label{W80result}{\upshape{(Weissler~\cite{W80})}}
  Let $N\ge1$ and $f(u)=|u|^{p-1}u$ $(p>1)$. 
  \begin{itemize}
    \item[$\mathrm{(i)}$] $(\text{Existence})$ There exists $T>0$ such that $\eqref{nosing}$ admits a local-in-time solution $u\in C([0,T),L^r(\RN))$ if one of the following holds{\rm :}
    \begin{itemize}
      \item[$(a)$] $r>N(p-1)/2$, $r\ge1$ and $u_0\in L^r(\RN)$. 
      \item[$(b)$] $r=N(p-1)/2$, $r>1$ and $u_0\in L^r(\RN)$. 
    \end{itemize} 
    \item[$\mathrm{(ii)}$] $(\text{Nonexistence})$ For any $0<r<N(p-1)/2$, there exists $u_0\in L^r(\RN)$ such that $\eqref{nosing}$ admits no local-in-time solution. 
  \end{itemize}
\end{prop}

ref_dict.equisuper:
\begin{prop}\label{equisuper}
  Let $0<T\le\infty$ and $f$ be a continuous and nondecreasing function such that $f(0) \ge 0$. Then, $\eqref{1.1}$ has a local-in-time nonnegative solution in $\RN\times(0, T)$ if and only if $\eqref{1.1}$ has a nonnegative supersolution $\overline{u} \in L^{\infty}((0, T), L^{1}_{\rm ul}(\RN)) \cap L^{\infty}_{\rm loc}((0, T), L^{\infty}(\RN))$. Moreover, if a nonnegative supersolution $\overline{u}$ exists, then the solution $u$ satisfies $0\le u(t) \le \overline{u}(t)$ for $0<t<T$. 
\end{prop}

