\end{equation*}
where $G(x, t) = (4\pi t)^{-N/2} \exp{(-|x|^{2} / 4t)}$. We define a solution to $\eqref{1.1}$. 

\begin{defi}\label{Defsol}
  We say that a nonnegative measurable function $u$ is a local-in-time solution to \eqref{1.1} in $\RN\times (0, T)$ if there exists $T>0$ such that $u \in L^{\infty}((0, T), L^{1}_{\rm ul}(\RN)) \cap L^{\infty}_{\rm loc}((0, T), L^{\infty}(\RN))$ and $u$ satisfies 
  \begin{equation*}
      u(x, t) = [e^{t\Delta} u_0](x) + \int_{0}^{t} [e^{(t-s)\Delta} |\cdot|^{-\gamma} f(u(\cdot, s))](x) \,ds
    \end{equation*}
    for a.a. $x\in \RN$, $0<t<T$. 
    We say that a nonnegative measurable function $\overline{u}$ is a supersolution of $\eqref{1.1}$ if there exists $T>0$ such that 
    \begin{equation*}
      \overline{u}(x, t) \ge [e^{t\Delta} u_0](x) + \int_{0}^{t} [e^{(t-s)\Delta} |\cdot|^{-\gamma} f(\overline{u}(\cdot, s))](x) \,ds
    \end{equation*}
    for a.a. $x \in \RN$, $0 < t < T$. 
\end{defi}

We are ready to state the main theorem on the local existence of $\eqref{1.1}$.

