\begin{thm}\label{Nonexist-thm}
 Suppose that $f \in C^{2}([0, \infty)) \cap S_{q}$ with $q \in [1, \infty)$ and 
 \begin{equation}\label{Nonexist-assum}
 \frac{f(\xi) f''(\xi)}{(f'(\xi))^{2}}\ge\delta \quad \text{for}~~\xi\ge 0
 \end{equation}
 for sufficiently small $\delta>0$. Let $0<r<N/(2-\gamma)$ and $q \le 1+r$. Then, there exists a nonnegative initial function $u_0 \in L^{1}_{\rm ul}(\RN)$ such that $F(u_0)^{-r} \in L^{1}_{\rm ul}(\RN)$ and $\eqref{1.1}$ does not have nonnegative local-in-time solutions. 
\end{thm}

\begin{prop}\label{LpLqul}
 \begin{itemize}
 \item[$\mathrm{(i)}$] Let $N\ge 1$ and $1\le p \le q \le \infty$. Then, there exists a constant $C>0$ such that, for $\phi \in L^{p}_{\rm ul}(\RN)$, 
 \begin{equation*}
 \|e^{t\Delta} \phi\|_{L^{q}_{\rm ul}(\RN)} \le C \left(1+t^{-\frac{N}{2} \left(\frac{1}{p} - \frac{1}{q} \right)} \right) \|\phi\|_{L^{p}_{\rm ul}(\RN)} \quad \text{for all }~t>0. 
 \end{equation*}
 In particular, 
 \begin{equation*}
 \|e^{t\Delta} \phi\|_{L^{q}_{\rm ul}(\RN)} \le C t^{-\frac{N}{2} \left(\frac{1}{p} - \frac{1}{q} \right)} \|\phi\|_{L^{p}_{\rm ul}(\RN)} \quad \text{for }~0<t\le 1. 
 \end{equation*}
 \item[$\mathrm{(ii)}$] Let $N\ge 1$ and $1\le p < q \le \infty$. Then, for any $\phi \in \cL^{p}_{\rm ul}(\RN)$ and $\varepsilon > 0$, there exists $t_{\varepsilon}>0$ such that 
 \begin{equation*}
 \|e^{t\Delta} \phi\|_{L^{q}_{\rm ul}(\RN)} \le \varepsilon t^{-\frac{N}{2} \left(\frac{1}{p} - \frac{1}{q} \right)} \quad \text{for}~~0<t<t_{\varepsilon}. 
 \end{equation*}
 \end{itemize}
\end{prop}

\begin{prop}\label{Jensen}
 Let $\zeta\ge 0$ be a constant. 
 \begin{itemize}
 \item[$\mathrm{(i)}$] Suppose that $H:[\zeta, \infty) \to [0, \infty)$ is a convex function. If $\phi \in L^{1}_{\rm ul}(\RN)$, $H(\phi) \in L^{1}_{\rm ul}(\RN)$ and $\phi \ge \zeta$ in $\RN$, then
 \begin{equation*}
 H(e^{t\Delta} \phi) \le e^{t\Delta} H(\phi) \quad \text{in}~~\RN \times (0, \infty). 
 \end{equation*}
 \item[$\mathrm{(ii)}$] Suppose that $K:[\zeta, \infty) \to [0, \infty)$ is a concave function. If $\phi \in L^{1}_{\rm ul}(\RN)$ and $\phi \ge \zeta$ in $\RN$, then
 \begin{equation*}
 K(e^{t\Delta} \phi) \ge e^{t\Delta} K(\phi) \quad \text{in}~~\RN \times (0, \infty). 
 \end{equation*}
 \end{itemize}
\end{prop}

\item[$\mathrm{(ii)}$] $H(u_0) \in \mathcal{L}^{1}_{\mathrm{ul}}(\mathbb{R}^N)$ and 
 \begin{equation}\label{3.2}
