\begin{equation}\label{eq:FPSL lin}
		\left\{\begin{aligned}
			& \frac{\partial u}{\partial t}(t,x) +\frac{\partial}{\partial x}\big((h(x)u(t,x)\big) - \frac{\partial ^2u}{\partial x^2}(t,x) = \delta_{0}(x)N(t), \quad x\in \mathbb{R}, t\geq 0,
			\\
			& N(t) = \lim_{x\rightarrow \infty}h(x)u(t,x),
			\\
