 &\text{ and } \langle x,V_\pm\ran_{{}_M}= \mp x_0+  \langle x',\theta\rangle= \mp x_0+ \sum_{j=1}^n x_j \theta_j,
 \end{split}
 \end{equation}
$ \langle x,V_\pm\ran_{{}_M}$ is the Minkowski scalar product.

  If $\varphi\in C^\infty({\mathbb R})$ and $\theta\in {\mathbb S}^{n-1},$ we denote
  \begin{equation}\label{defphi}
  \vphi_{{}_V}(x):= \varphi(\langle x,V\ran_{{}_M}), \;\  \varphi^\prime_{{}_V}(x):= \varphi^\prime(\langle x,V\ran_{{}_M}) \text{ and }  \varphi^{\prime\prime}_{{}_V}(x):= \varphi^{\prime\prime}(\langle x,V\ran_{{}_M}),
  \end{equation}
   and notice that
  \[
  \begin{split}
   &  \nabla \vphi_{{}_V}(x)  = \vphi_{{}_V}^{\prime}(x) \widetilde V, \;\  
   \p_{x_0}^2 \vphi_{{}_V}(x) = \vphi_{{}_V}^{\prime\prime}(x)
\text{ and }   \p_{x_j}^2 \vphi_{{}_V}(x)= \vphi_{{}_V}^{\prime\prime}(x) \theta_j^2, \;\ j=1, \ldots, n, 
  \end{split}
  \]
  and therefore
  \[
  \square \vphi_{{}_V}=(\p_{x_0}\vphi_{{}_V})^2-|\nabla_{x'} \vphi_{{}_V}|^2=0.
  \]
 We conclude that for $Q(x,u,\nabla u)$ as in \eqref{NLWE},
 \begin{equation}\label{equ0}
 \square \vphi_V(x)= Q\bigl(x,\vphi_V(x),\nabla \vphi_V(x)\bigr) = 0.
  \end{equation}

 We will think of $\vphi_V(x)$ as background solutions of \eqref{NLWE} and will construct solutions of \eqref{NLWE} which are oscillatory perturbations of $\vphi_V(x)$.  This is the main result of the paper:

context:
We construct highly oscillatory solutions of scalar semilinear wave equations \eqref{NLWE} below, for $x_0\in [-T,T]$, with $T$ arbitrary. These are known as nonlinear geometric optics solutions. We show that the coefficient of amplitude $h$ of the oscillatory part of the nonlinear geometric optics expansion of the solution restricted to $x_0=T'<T$ determines the light-ray transform of a vector field associated with $q(x,u)$, which determines $q(x,u)$ uniquely in the maximal region determined by the data. The construction also works for systems such as the ones studied in \cite{Sog}, but these will be treated elsewhere. Our focus is to present the methods in the scalar case. The existence and structure of oscillatory solutions of equations satisfying null conditions have been studied by several people, for example \cite{Cho,Cho1,HunLuk,Tou}, but as far as we know, the inverse problem for \eqref{NLWE} has not been treated.

We consider fully semilinear wave equations of the form
\begin{equation}\label{NLWE}
\begin{aligned}
& \square u:= \, \bigl( -\p_{x_0}^2 +\sum_{j=1}^n \p_{x_j}^2\bigr)u = Q(x,u,\nabla u)=q(x,u)((\p_{x_0}u)^2-|\nabla_{x'} u|^2).
 \end{aligned}
\end{equation}
 Such nonlinear potentials $Q(x,u,\nabla u)$ are called null forms after \cite{Chr,Kla,KlaMac,Sog}. In fact we can show that one can recover $f(x) q(x,u)$ for any $f\in C_0^\infty({\mathbb R}^{n+1})$ and hence may assume that $q(x,u)$ is compactly supported in the variable $x$.

We will construct suitable oscillatory solutions $u$ of \eqref{NLWE}, and we show that the restriction of $u$ to $\{x_0=T\}$, for $T$ large enough, determines $q(x,u)$ provided it is compactly supported in $x$. In general, the existence and uniqueness of solutions of semilinear equations of the form \eqref{NLWE} is only guaranteed for initial data with small energy \cite{Chr,Kla,KlaMac,Sog}, which is not sufficient to study the inverse problem; we need to construct bounded oscillatory solutions whose initial data does not have small energy. The key point of the proof is to construct a one-parameter family of approximate oscillatory solutions of \eqref{NLWE} in the sense of \eqref{defuh} below, valid on arbitrary finite interval $[T_0,T]_{x_0}\times \mrn_{x^{\prime}}$. We then use a result of Gu\`es \cite{Gue} to show that there exists a unique one-parameter family of solutions of \eqref{NLWE} with the same initial data, valid in the same region $[T_0,T]_{x_0}\times \mrn_{x^{\prime}}$, which differs from the approximate solution by a large enough power of the wave length $h$, see Theorem \ref{approx} below. For the convenience of the reader, in Section \ref{PRGU}, we give a proof of Gu\`es' result for this particular case. We emphasize that the results of \cite{Gue} are more general and hold for quasilinear systems. It is also important to emphasize that for any finite time interval there is an oscillatory solution, but the estimates depend on the size of the interval, so these solutions are not global.

We will adopt the following notation:
 \begin{equation}\label{notation}
 \begin{split}
 & \text{ if } V_\pm=(\pm 1,\theta), \;\ \theta\in {\mathbb S}^{n-1}, \text{ we denote } \widetilde V_\pm =(\mp 1,\theta), \\
 &\text{ and } \langle x,V_\pm\ran_{{}_M}= \mp x_0+ \langle x',\theta\rangle= \mp x_0+ \sum_{j=1}^n x_j \theta_j,
 \end{split}
 \end{equation}
$ \langle x,V_\pm\ran_{{}_M}$ is the Minkowski scalar product.

If $\varphi\in C^\infty({\mathbb R})$ and $\theta\in {\mathbb S}^{n-1},$ we denote
 \begin{equation}\label{defphi}
 \vphi_{{}_V}(x):= \varphi(\langle x,V\ran_{{}_M}), \;\ \varphi^\prime_{{}_V}(x):= \varphi^\prime(\langle x,V\ran_{{}_M}) \text{ and } \varphi^{\prime\prime}_{{}_V}(x):= \varphi^{\prime\prime}(\langle x,V\ran_{{}_M}),
 \end{equation}
 and notice that
 \[
 \begin{split}
 & \nabla \vphi_{{}_V}(x) = \vphi_{{}_V}^{\prime}(x) \widetilde V, \;\ 
 \p_{x_0}^2 \vphi_{{}_V}(x) = \vphi_{{}_V}^{\prime\prime}(x)
\text{ and } \p_{x_j}^2 \vphi_{{}_V}(x)= \vphi_{{}_V}^{\prime\prime}(x) \theta_j^2, \;\ j=1, \ldots, n, 
 \end{split}
 \]
 and therefore
 \[
 \square \vphi_{{}_V}=(\p_{x_0}\vphi_{{}_V})^2-|\nabla_{x'} \vphi_{{}_V}|^2=0.
 \]
 We conclude that for $Q(x,u,\nabla u)$ as in \eqref{NLWE},
 \begin{equation}\label{equ0}
 \square \vphi_V(x)= Q\bigl(x,\vphi_V(x),\nabla \vphi_V(x)\bigr) = 0.
 \end{equation}

We will think of $\vphi_V(x)$ as background solutions of \eqref{NLWE} and will construct solutions of \eqref{NLWE} which are oscillatory perturbations of $\vphi_V(x)$. This is the main result of the paper:

expanded_theorem:
\label{main}  Let $q(x,u)$ be supported on $\{|x|\leq R\} \times {\mathbb R}$. 
 Let  $\varphi , \chi\in C_0^\infty({\mathbb R})$  be real valued, let $\omega, \theta\in {\mathbb S}^{n-1}$,  $V=(\pm 1,\theta)$ and  $W=( -1,\omega)$. Let $\vphi_{{}_V}(x)$ and $\chi_{{}_W}(x)$  be defined by

\begin{split}
   &  \text{ if } V_\pm=(\pm 1,\theta), \;\ \theta\in \ms^{n-1},  \text{ we denote } \wt V_\pm =(\mp 1,\theta), \\
 &\text{ and } \lan x,V_\pm\ran_{{}_M}= \mp x_0+  \lan x',\theta\ran= \mp x_0+ \sum_{j=1}^n x_j \theta_j,
 \end{split}
 \eeq
$ \lan x,V_\pm\ran_{{}_M}$ is the Minkowski scalar product.

  If $\vphi\in C^\infty(\mr)$ and $\theta\in \ms^{n-1},$ we denote
  \beq\label{defphi}
  \vphi_{{}_V}(x)\defn \vphi(\lan x,V\ran_{{}_M}), \;\  \vphi^\prime_{{}_V}(x)\defn \vphi^\prime(\lan x,V\ran_{{}_M}) \text{ and }  \vphi^{\prime\prime}_{{}_V}(x)\defn \vphi^{\prime\prime}(\lan x,V\ran_{{}_M}),
  \eeq
   and notice that
  \[
  \begin{split}
   &  \nabla \vphi_{{}_V}(x)  = \vphi_{{}_V}^{\prime}(x) \wt V, \;\  
   \p_{x_0}^2 \vphi_{{}_V}(x) = \vphi_{{}_V}^{\prime\prime}(x)
\text{ and }   \p_{x_j}^2 \vphi_{{}_V}(x)= \vphi_{{}_V}^{\prime\prime}(x) \theta_j^2, \;\ j=1, \ldots, n, 
  \end{split}

For $A,B\in {\mathbb R}$,
 \[
\begin{split}
 u_{inc}(h,V,W,x)= \vphi_{{}_V}(x) +  h \chi_{{}_W}(x) \biggl( A \cos\biggl(\frac{i}{h} \bigl( \langle x,W\ran_{{}_M}\bigr)\biggr)+ B \sin\biggl(\frac{i}{h} \bigl( \langle x,W\ran_{{}_M}\bigr)\biggr)\biggr),
\end{split}
 \]
which satisfies

\begin{split}
 &  x=(x_0,x^{\prime}), \;\ x^{\prime}=(x_1, x_2,\ldots, x_n),   \\
 & \nabla u=(\p_{x_0}u, \p_{x_1}u, \ldots, \p_{x_n}u) \text{ and } \nabla_{x^{\prime}}u=(\p_{x_1}u, \ldots, \p_{x_n}u),
 \end{split}
\]

  We consider  fully semilinear wave equations of the form
\beq\label{NLWE}
\begin{aligned}
&  \square u\defn  \, \bigl( -\p_{x_0}^2 +\sum_{j=1}^n \p_{x_j}^2\bigr)u = Q(x,u,\nabla u)=q(x,u)((\p_{x_0}u)^2-|\nabla_{x'} u|^2).
 \end{aligned}
\eeq
 Such nonlinear potentials $Q(x,u,\nabla u)$ are called null forms after \cite{Chr,Kla,KlaMac,Sog}.  In fact we can show that one can recover $f(x) q(x,u)$ for any $f\in C_0^\infty(\mr^{n+1})$ and hence may assume that $q(x,u)$  is compactly supported in the variable $x$.

 We will construct suitable oscillatory solutions $u$ of \eqref{NLWE}, and we show that the restriction of $u$ to $\{x_0=T\}$, for $T$ large enough, determines $q(x,u)$  provided it is compactly supported in $x$.  In general, the existence and uniqueness of solutions of semilinear equations of the form \eqref{NLWE} is only guaranteed for initial data with small energy \cite{Chr,Kla,KlaMac,Sog}, which is not sufficient to study the inverse problem; we need to construct bounded oscillatory solutions whose initial data does not have small energy.  The key point of the proof is to  construct a one-parameter family of approximate oscillatory solutions of \eqref{NLWE} in the sense of  \eqref{defuh} below, valid on arbitrary finite interval $[T_0,T]_{x_0}\times \mrn_{x^{\prime}}$.    We then use a result  of Gu\`es \cite{Gue} to show that there exists a unique one-parameter family of solutions of \eqref{NLWE} with the same initial data, valid in the same region $[T_0,T]_{x_0}\times \mrn_{x^{\prime}}$, which differs from the approximate solution by a large enough power of the wave length $h$, see Theorem  \ref{approx} below.  For the convenience of the reader, in Section \ref{PRGU},  we give a proof of Gu\`es' result  for this particular case.  We emphasize that the results of \cite{Gue} are more general and hold for quasilinear systems. It is also important to emphasize that for any  finite time interval there is an oscillatory solution, but the estimates depend on the size of the interval, so these solutions are not global.

The oscillatory solutions we construct are  such that the phases are still given by the linear eikonal equation for the wave operator, and the coefficients are determined by transport equations which involve the nonlinearity. This has been called the weakly nonlinear optics regime, see for example \cite{Met1,Rau}.   

   We will adopt the following notation:
   \beq\label{notation}
   \begin{split}
   &  \text{ if } V_\pm=(\pm 1,\theta), \;\ \theta\in \ms^{n-1},  \text{ we denote } \wt V_\pm =(\mp 1,\theta), \\
 &\text{ and } \lan x,V_\pm\ran_{{}_M}= \mp x_0+  \lan x',\theta\ran= \mp x_0+ \sum_{j=1}^n x_j \theta_j,
 \end{split}

if $x$ is not on the support of $\chi_{{}_W}$.  For any $N\in {\mathbb N}$ and any interval $[T_0,T]_{x_0}$,  there exists a unique solution $u(h,V,W,x)$ of \eqref{NLWE}  such that 
\[
u(h,V,W,x)= u_{inc}(h,V,W,x) \text{ for } x_0\ll 0 \text{ outside the support of } q(x,u),
\]
which has an expansion of the form
\begin{equation}\label{defuh}
\begin{split}
& u_{N}(h,V,W,x)=  \vphi_{{}_V}(x) +  h \sum_{p=0}^N h^p \sum_{\pm m=0}^N  e^{\frac{im}{h} \langle x,W\ran_{{}_M}}  A_{m,p}(V,W,x)+ h^{N+1} \mce_N(h,V,W,x),\\
& \text{ where } A_{m,p} \in C^\infty, \;\ \overline{A_{m,p}}= A_{-m,p},  \text{ so  the expansion is real valued,} 
\end{split}
\end{equation}
and satisfy the following initial conditions when $x_0\ll 0$:
\begin{equation}\label{defcoeff}
\begin{split}
& A_{0,p}(V,W,x)=0, \\
&  A_{1,0}(V,W,x)= \frac{1}{2} \chi_{{}_W}(x)(A-i B), \;\    A_{m,0}(V,W,x)=0, \;\ \text{ if } m \ge 2,\\
 & A_{m,p}(V,W,x)=0, \text{ if } p\ge1.
\end{split}
 \end{equation}
The coefficient $A_{1,0}$ satisfies the transport equation
\begin{equation}\label{eqa1p0}
\begin{split}
& \bigl( \p_{x_0}- \omega\cdot \nabla_{x^{\prime}} \bigr) A_{1,0}= F(V,W,x) A_{1,0}, \text{ where } \\
& F(V,W,x)=\langle  q\bigl(x, \vphi_{{}_V}(x)\bigr)  \vphi_{{}_V}^\prime(x)   \widetilde V,\widetilde W \ran_M, \;\ \widetilde W=(1,\omega).
\end{split}
\end{equation}
Moreover, for any $\tau>0$, the error term satisfies
\[
\begin{split}
& \sup_{x_0\in [-\tau,\tau]}\| \mce_N\|_{{}_{L^2({\mathbb R}^n)}}\leq C(N,\tau), \;\  
\sup_{x_0\in [-\tau,\tau]}\| \mce_N\|_{{}_{L^\infty ({\mathbb R}^n)}}\leq C(N,\tau), \\
& \sup_{x_0\in [-\tau,\tau]}\| D_x^\alpha \mce_N\|_{{}_{L^2({\mathbb R}^n)}}\leq C_\alpha(N,\tau) h^{1-|\alpha|}, \;\
\sup_{x_0\in [-\tau,\tau]}\| D_x^\alpha \mce_N\|_{{}_{L^2({\mathbb R}^n)}}\leq C_\alpha(N,\tau) h^{1-|\alpha|}, \;\ |\alpha|\geq 1.
\end{split}
