    \item[(2)] $p\in (\frac{2(N+1)}{N-1},2^{**})$, where
\begin{equation*}
	2^{**} := \frac{2N}{(N-4)_+} :=
	\begin{cases}
		+\infty, & N \le 4,\\[2pt]
		\dfrac{2N}{N-4}, & N \ge 5.
	\end{cases}
\end{equation*}
  \end{itemize}   
\end{itemize}

