Let us now shift our attention to a variation of the system~\eqref{KS}, given by
\begin{equation} \label{KS'}
 \begin{cases}
 n_t = \Delta n - \nabla \cdot \bigl(n(1+n)^{-\alpha} \nabla c\bigr), \\
 \gamma c_t = \Delta c - c + n,
 \end{cases}
\end{equation}
where $\alpha \in \mathbb{R}$. This model also exhibits a criticality phenomenon; however, in contrast to \eqref{KS}, the critical parameter is not the total mass but the exponent $\alpha$. 
More precisely, it has been shown that the value
\[
\alpha^* = 1 - \frac{2}{N}
\]
is critical in the following sense: if $\alpha > \alpha^*$, then solutions to system~\eqref{KS'} are global and bounded \cite{Winkler-Horstmann, Winkler-2011}, whereas if $\alpha < \alpha^*$, there exist solutions that become unbounded when $\Omega$ is a ball in $\mathbb{R}^N$ with $N \geq 2$ \cite{CieslakStinner2015, Winkler2010VolumeFilling}.

\begin{equation} \label{1} 
 \begin{cases}
 n_t + u \cdot \nabla n = \Delta n - \nabla \cdot \left( n S(n)\nabla c \right), \qquad &x\in \Omega, t>0,\\
 u\cdot \nabla c = \Delta c - c + n, \qquad &x\in \Omega, t>0,\\
 u_t + \kappa ( u \cdot \nabla ) u +\nabla P = \Delta u + n \nabla \phi ,\quad \nabla \cdot u =0,\qquad &x\in \Omega, t>0,
 \end{cases}
\end{equation}
 In this system, $n=n(x,t)$, $c=c(x,t)$, $u = u(x,t)$ and $P = P(x,t)$ denote the cell density. chemical concentration, the fluid velocity and pressure, respectively.
Here $S\in C^2 \left [0, \infty \right )$ such that 
\begin{equation}\label{S}
 \begin{cases}
 \lim_{\xi \to \infty}S(\xi) =0 , &\text{ if }N=2,\\
 |S(\xi)| \leq K_S (\xi+1)^{-\alpha} \qquad \text{for all }\xi \geq 0, &\text{ if }N=3,
 \end{cases}
\end{equation}
for some $K_S>0$ and $\alpha>0$, and the given gravitational potential function $\phi$ fulfills 
\begin{align} \label{phi}
 \phi \in W^{2, \infty}(\Omega).
\end{align}
 The system \eqref{1} satisfies the Neumann-Neumann-Dirichlet boundary conditions
\begin{equation} \label{bdry}
 \frac{\partial n}{\partial \nu} =0, \quad \frac{\partial c}{\partial \nu} =0, \quad \text{and } u=0 ,\qquad x \in \partial \Omega, t>0,
\end{equation}
and initial conditions 
\begin{align*}
 n(x,0) =n_0(x), \qquad u(x,0) =u_0(x) \qquad \text{for all } x \in \Omega,
\end{align*}
with 
\begin{equation} \label{initial}
 \begin{cases}
 n_0 \in C^{0} (\bar{\Omega}) &\text{ with } n_0\geq 0 \\
 u_0 \in D(A^\beta) &\text{with } \beta \in \left ( \frac{3}{4}, 1\right ) \text{when }n=3 \quad \text{and } \beta \in \left ( \frac{1}{2}, 1\right ) \text{when }n=2,
 \end{cases}
\end{equation}
where $A := -\mathcal{P}\Delta$ denotes the Stokes operator on 
\[
L^2_\sigma(\Omega) := \left\{ \phi \in L^2(\Omega; \mathbb{R}^N) \,\middle|\, \nabla \cdot \phi = 0 \right\},
\]
with $\mathcal{P}$ representing the Helmholtz projection from $L^2(\Omega;\mathbb{R}^N)$ into $L^2_\sigma(\Omega)$.

Assuming that
\[
|S(\xi)| \le C(\xi+1)^{-\alpha} \quad \text{for all } \xi \ge 0,
\]
with some constants $C>0$ and $\alpha>0$, the existence of globally bounded
solutions to the simplified fully parabolic Keller--Segel--Stokes system (with
$\kappa = 0$) was established in \cite{WangXiang2015}. Closely related results on
global existence and boundedness for the fully parabolic
Keller--Segel--Navier--Stokes system~\eqref{1} were later obtained in
\cite{WangWinklerXiang2018} and \cite{LiZheng2022}. In the particular case $S \equiv 1$, it was shown in \cite{Winkler_SIAM} that if
\(
\int_\Omega n_0 < 2\pi,
\)
then system~\eqref{1} admits a global generalized solution which eventually
becomes smooth and converges to a constant steady state. By contrast, if
\(
\int_\Omega n_0 \in (4\pi, \infty)\setminus \{4k\pi \mid k \in \mathbb{N}\},
\)
unbounded solutions were shown to exist for $u_0 \equiv 0$ and
$\nabla \phi \equiv 0$; see \cite{HorstmannWang2001_blowup}. In order to circumvent
this critical-mass phenomenon, the authors in \cite{WT2023} proved that, under
the optimal condition
\[
\lim_{\xi \to \infty} S(\xi) = 0,
\]
the fully parabolic chemotaxis--Navier--Stokes system admits globally bounded
solutions.

In contrast, research on the parabolic--elliptic case remains relatively scarce. For instance, it was shown in \cite{Winkler+2020} that system~\eqref{1}
possesses global bounded solutions when the chemotactic sensitivity is repulsive
($S \equiv -1$). Furthermore, \cite{Zheng2021} established the existence of
global classical bounded solutions for the simplified Keller--Segel--Stokes
system under the condition
\[
|S(\xi)| \le C(\xi+1)^{-\alpha} \quad \text{for all } \xi \ge 0,
\]
with some $C>0$ and $\alpha>0$. In the special case where $S \equiv 1$,
$\phi = c$, and $\Omega = \mathbb{R}^2$, it was demonstrated in \cite{GongHe2021}
that solutions to the parabolic--elliptic system exist globally in time provided
that \(
\int_\Omega n_0 < 8\pi.
\)
For additional results on global solvability in a wide range of variants of
system~\eqref{1}, we refer the interested reader to
\cite{Cao_2016, Kozono_2016, Duan_2010, Wang2023, DaiLiu}.
These aforementioned findings naturally motivate the investigation of sharp conditions on the
sensitivity function $S$ that guarantee global existence and boundedness of
solutions to the parabolic--elliptic system~\eqref{1}.

Accordingly, the first main objective of the present work is to establish global
solvability and boundedness for system~\eqref{1}, in close analogy with the fully
parabolic framework studied in \cite{WT2023}. More precisely, we formulate the
following theorem.

\begin{remark}
 Theorem \ref{thm1} extends and strengthens the results obtained in
\cite{Zheng2021}, where comparable boundedness results were established only for the
two-dimensional Keller--Segel--Stokes system. 
\end{remark}

\begin{lemma} \label{Moser-Trudinger2}
 Let $\Omega \subset \mathbb{R}^2$ be a bounded domain with smooth boundary. Then for any $\epsilon>0$ there exists $\Gamma=\Gamma(\epsilon,\Omega)>0$ such that then for all $a>0$ and $M\geq 1$ and for each $0 \not\equiv \phi \in C^0(\bar{\Omega}) $ is nonnegative and $\psi \in W^{1,2}(\Omega)$,
 \begin{align}\label{Moser-Trudinger2-1}
 \int_\Omega \phi |\psi| &\leq \frac{1+\epsilon}{2\pi a} \cdot \left \{ \int_\Omega \phi \right \}\cdot \left \{ \int_\Omega \frac{|\nabla \phi|^2}{(\phi+M)^2} \right \} + \frac{(1+\epsilon)a}{8 \pi} \cdot \left \{ \int_\Omega \phi \right \}\cdot \left \{ \int_\Omega |\nabla \psi|^2 \right \} \notag \\
 &\quad+\Gamma a\cdot \left \{ \int_\Omega \phi \right \}\cdot \left \{ \int_\Omega |\psi| \right \}^2 +\frac{8\Gamma}{a} \cdot \left \{ \int_\Omega \phi \right \}^3+\frac{\Gamma(8|\Omega|^2M^2+2)}{a} \cdot \left \{ \int_\Omega \phi \right \}+\frac{2|\Omega|}{ea},
 \end{align}
 and
 \begin{align}\label{Moser-Trudinger2-2}
 \int_\Omega \phi \log( \phi+M) &\leq \frac{1+\epsilon}{2\pi}\cdot \left \{ \int_\Omega \phi \right \}\cdot \left \{ \int_\Omega \frac{|\nabla \phi|^2}{(\phi+M)^2} \right \} \notag \\
 &\quad+8 \Gamma\cdot \left \{ \int_\Omega \phi \right \}^3 +\Gamma (8M^2|\Omega|^2+1)\int_\Omega \phi + \frac{|\Omega |}{e} . 
 \end{align}
\end{lemma}

\begin{proof}
 Thanks to Poincaré inequality, there exists $c_1>0$ such that 
 \begin{align} \label{L2u.1}
 \int_\Omega |\nabla u|^2 \geq c_1 \int_\Omega |u|^2 \qquad \text{for all }t\in (0,T_{\rm max}).
 \end{align}
 Abbreviating $c_2= \left \| \nabla \phi \right \|_{L^\infty(\Omega)} $, testing the third equation of \eqref{1} against $u=(u_1,u_2)$ and invoking Young's inequality, we obtain that 
 \begin{align}\label{L2u.2}
 \frac{d}{dt}\int_\Omega |u|^2 + \int_\Omega |\nabla u|^2 &= \int_\Omega n \nabla \phi \cdot u \notag \\
 &\leq c_2 \int_\Omega n |u| \notag \\
 &\leq c_2 \int_\Omega n |u_1| + c_2 \int_\Omega n |u_2|.
 \end{align}
 By Hölder's inequality and \eqref{L2u.1}, it follows that 
 \begin{align*}
 \left \{ \int_\Omega |u| \right \}^2 \leq |\Omega| \int_\Omega |u|^2 \leq c_1|\Omega| \int_\Omega |\nabla u|^2.
 \end{align*}
 Using this and Lemma \ref{Moser-Trudinger2-1} with $\epsilon=1$ and $a>0$ yields that 
 \begin{align}\label{L2u.3}
 c_2 \int_\Omega n |u_1| + c_2 \int_\Omega n |u_2| &\leq \frac{2c_2}{a}\int_\Omega n \ln \frac{n}{\bar{n}}+ \frac{c_2a}{2 \pi} \cdot \left \{ \int_\Omega n \right \} \cdot \int_\Omega |\nabla u|^2 \notag \\
