 \frac{d}{dt}\int_\Omega |u|^2+\frac{c_1}{4}\int_\Omega |u|^2+\frac{1}{4}\int_\Omega |\nabla u|^2 \leq \frac{2c_2}{a}\int_\Omega n \ln (n+1) +c_3 \qquad \text{for all }t\in (0,T_{\rm max}).
 \end{align}
 This, together with Lemma \ref{L1}[\eqref{L1-1}] and Lemma \ref{ODI} implies that \eqref{L2u-1}. Integrating \eqref{L2u.5} over $(t,t+\tau )$ and employing \eqref{L2u-1} and Lemma \ref{L1}[\eqref{L1-1}], there exists $c_4>0$ such that
 \begin{align*}
 \frac{1}{4}\int_t^{t+\tau }\int_\Omega |\nabla u|^2 \leq \frac{2c_2}{a} \int_t^{t+\tau }\int_\Omega n \log (n+1) +c_3 \tau +\int_\Omega |u(\cdot,t)|^2 \leq c_4\quad\text{for all }t\in (0,T_{\rm max}-\tau),
 \end{align*}
 which entails \eqref{L2u-2}. By invoking Gagliardo–Nirenberg interpolation inequality and using \eqref{L2u-1} and \eqref{L2u-2}, one can find $c_5$ and $c_6$ 
 \begin{align*}
 \int_t^{t+\tau }\int_\Omega | u|^4 &\leq c_5 \int_t^{t+\tau } \left (\int_\Omega |u|^2 \right ) \cdot \int_\Omega |\nabla u|^2 +c_5 \int_t ^{t+\tau} \left ( \int_\Omega |u|^2 \right )^2 \notag \\
 &\leq c_6 \qquad \text{for all }t\in (0,T_{\rm max}-\tau).
 \end{align*}
 This proves \eqref{L2u-3} and thereby completes the proof.
\end{proof}

\begin{lemma}\label{uLinf}
 For any $\beta \in \left ( \frac{1}{2}, 1 \right )$, there exists $C>0$ such that 
 \begin{align}\label{uLinf-1}
 \left \| A^\beta u (\cdot,t) \right \|_{L^2(\Omega)} \leq C \quad \text{for all }t \in (0,T_{\rm max})
 \end{align}
 and 
 \begin{align}\label{uLinf-2}
 \left \|u (\cdot,t) \right \|_{L^\infty(\Omega)} \leq C \quad \text{for all }t \in (0,T_{\rm max}).
 \end{align}
\end{lemma} 
\begin{proof}
 Noting that $\beta <1$, we can choose $r\in (1,2)$ such that $\frac{1}{r}< \frac{3}{2}-\beta$, and apply known smoothing properties of Stokes semigroup $(e^{-tA})_{t\geq 0}$ (see \cite{Giga1986}[p.201] and \cite{Winkler+2015}[Lemma 3.1] ) and continuity features of $\mathcal{P}$ to find $c_1>0$ and $\lambda>0$ such that 
 \begin{align} \label{uLinf.1}
\left\| A^\beta u(\cdot,t) \right\|_{L^2(\Omega)}
&= \left\| A^\beta e^{-tA}u_0
+ \int_0^t A^\beta e^{-(t-s)A} \mathcal{P}\big[n(\cdot,s)\nabla \phi\big] \, ds \right. \notag \\
&\qquad\left.
- \int_0^t A^\beta e^{-(t-s)A} \mathcal{P}\big[(u(\cdot,s)\cdot\nabla)u(\cdot,s)\big] \, ds
\right\|_{L^2(\Omega)} \notag \\
&\leq \left \| A^\beta u_0 \right \|_{L^2(\Omega)} +c_1\int_0^t (t-s)^{-\beta } e^{-\lambda(t-s)}\left \| n(\cdot,s) \right \|_{L^2(\Omega)} \notag \\
&\quad+c_1\int_0^t (t-s)^{-\beta - \frac{1}{r}+\frac{1}{2}} e^{-\lambda(t-s)} \left \| (u(\cdot,s)\cdot\nabla)u(\cdot,s) \right \|_{L^r(\Omega)} \qquad \text{for all }t\in (0,T_{\rm max}).
\end{align}
Applying Lemma \ref{Gradu} and Hölder's inequality, there exists $c_2>0$ such that
\begin{align} \label{uLinf.2}
 \left \| (u\cdot\nabla)u \right \|_{L^r(\Omega)} \leq \left \| u \right \|_{L^{\frac{2r }{2-r}}(\Omega)} \left \| \nabla u \right \|_{L^2(\Omega)} \leq c_2 \qquad \text{for all }t\in (0,T_{\rm max}).
\end{align}
Combining \eqref{uLinf.1} and \eqref{uLinf.2}, and apply Lemma \ref{Lpn}, there exists $c_3>0$ such that
\begin{align}\label{uLinf.3}
 \left\| A^\beta u(\cdot,t) \right\|_{L^2(\Omega)} &\leq \left \| A^\beta u_0 \right \|_{L^2(\Omega)} +c_1 \sup_{t\in (0,T_{\rm max})} \left \| n(\cdot,t) \right \|_{L^2(\Omega )} \int_0^\infty z^{-\beta}e^{-\lambda z}\, dz \notag \\
 &\quad+c_1c_2 \int_0 ^\infty z^{-\beta -\frac{1}{r}+\frac{1}{2}}e^{-\lambda z}\, dz \notag \\
 &\leq c_3 \qquad \text{for all }t\in (0,T_{\rm max}). 
\end{align}
As a consequence of the continuity embedding $D(A^\beta) \to L^\infty (\Omega; \mathbb{R}^2)$ and \eqref{uLinf.3}, there exists $c_4>0$ satisfying 
\begin{align*}
 \left\| u(\cdot,t) \right\|_{L^\infty(\Omega)} \leq c_4 \left\| A^\beta u(\cdot,t) \right\|_{L^2(\Omega)}\leq c_4c_3\qquad \text{for all }t\in (0,T_{\rm max}). 
\end{align*}
The proof is now complete.

