In the Steklov case, the generic behavior of Steklov eigenvalues under boundary perturbations remains unexplored. The purpose of this paper is to establish the generic simplicity of Steklov eigenvalues. We prove that non-zero Steklov eigenvalues are simple for almost all bounded domains with smooth boundary. Precisely, our main theorem is stated as following:

\begin{remark}This theorem also holds for compact manifolds with boundary that admit an embedding into $\R^n$. For a compact Riemannian manifold, such an embedding is guaranteed by the Nash embedding theorem.
\end{remark}

Let $\n$ denote the unit outward normal along $\PO$. According to Corollary 1.6 in \cite{H05}, when $m\geq 2$, there exists a function $\phi\in C^m(\R^n, R)$ such that $\O=\{x| \phi(x)>0\}$ and $|\nabla \phi(x)|=1$ in a neighborhood of $\PO$. Moreover, such $\phi$ is unique on a neighborhood of $\PO$. In this case we can extend $\n= \nabla \phi$ on a neighborhood of $\PO$ and straightforward calculation yields the following properties. \begin{prop}\label{NP}
For a domain $\O \in \R^n$ with $C^m$ boundary $\PO$ and $m\geq 2$, its unit outward normal $\n$ satisfies:
\begin{enumerate}
\item the matrix $\left[\frac{\partial n_i}{\partial x_j}\right]_{i, j=1}^n$ is symmetric on $\PO$;
\item $\frac{\partial \n}{\partial \n}=0$ on $\PO$.
\end{enumerate}
\end{prop}

Let $\Delta, \Delta_{\PO}$ denote the Laplacian on $\O$ and $\PO$ respectively. The second property in Proposition \ref{NP} implies the following relationship between them.
\begin{prop}\label{deco}
Let $\O$ be a bounded domain in $\R^n$ with $C^m$ boundary $\PO$ and $m\geq 2$. Then on $\PO$, there is
\begin{align*}
\Delta u
&=\Delta_{\PO} u+H u_n+u_{nn}.
\end{align*} Here $H=\nabla \cdot \n$ is the mean curvature of the boundary and $u_n= \nabla_{\n} u$. \end{prop} This proposition is a corollary of Theorem 1.13 in \cite{H05} or argument in Chapter 4 in \cite{Li12}.

Finally, we introduce the weak unique–continuation principle for Steklov eigenfunctions, which is an essential tool in the proof of the main theorem. The following theorem is a consequence of the general version on Riemannian manifolds established in \cite{W22}, but it holds under weaker regularity assumptions. For completeness, we include a short proof.
\begin{thm}[Weak unique continuation principle]\label{wucp}
Let $\O$ be a bounded region in $\R^n$ with $C^m$ boundary for $m\geq 2$. Consider a non-constant function $f \in \HM$ with $m-1\geq k\geq 1$ and $p\geq 2$. Assume that $\Lambda f=\lambda f$. If $f=0$ on an open set of $\PO$, then $f$ vanish on $\PO$.
\end{thm}
\begin{proof}
Let $u$ be the harmonic extension of $f$. Then 
\begin{align*}\left\{ 
\begin{aligned}
\Delta u&=0,\, && \O\\ 
u&=f,\, && \PO\\
u_n&=\lambda f,\, && \PO.
\end{aligned}\right.
\end{align*} 
Let $\Gamma$ be an open subset of $\PO$ where $f=0$. Fix an arbitrary point $x\in \Gamma$. Choose a small ball $B(x,r)$ such that $B(x,r)\cap \PO\subset \Gamma$. 
We can extend $u$ to $B(x,r)$ as
\begin{align*}
\left\{ 
\begin{aligned}
\tilde{u}&=u,\, && B(x,r)\cap \O\ \\
\tilde{u}&=0,\, &&B(x,r) \setminus \O
\end{aligned}
\right.
\end{align*} such that $\tilde{u} \in W^{2,p}(B)$. Then we have
\begin{align*}
\Delta \tilde{u}&=0, \, 
\end{align*} on $B(x,r)$ and $\tilde{u}=0$ on the open set $B(x,r)\setminus \bar{\O}$. By the weak unique continuation principle of second order elliptic operators, $\tilde{u}$ must vanish in $B(x,r)$. As a harmonic function on $\O$, $u$ vanishing in the open set $B(x,r)\cap \Omega $ implies that $u$ vanishes everywhere in $\O$.\\
\end{proof}
\begin{remark}
See Theorem 1.1 in \cite{GL} for the weak unique continuation principle of second order elliptic operators. 
\end{remark}

We apply Theorem \ref{T1} to $\Phi$ to prove the following theorem.
\begin{thm}\label{MT3}
Let $\O\in \R^n$ be a bounded domain with $C^m$ boundary and $m\geq 2$. Then there exist an open and dense set $E_1\subset \E(\O)$ such that
\begin{align}\label{ev3}
\begin{aligned}
\phi:&S^k_p(\PO)\times \R\times E_1\rightarrow \ho\\
&(f, \lambda, h)\rightarrow h^{\ast}(\Lambda-\lambda) (h^{-1})^{\ast} f
\end{aligned}
\end{align} has zero as a regular value.
\end{thm}
\begin{proof}
To apply Theorem \ref{T1} to $\Phi$, let $X=S^p_k(\PO)\times S^p_k(\PO)\times \R, Y=C^m(\O, \R^n)$, both of which are separable, and $A= S^p_k(\PO)\times S^p_k(\PO)\times \R\times\E(\O)$. Let $D_1$ denote the differential in the direction of $S^p_k(\partial\Omega)\times S^p_k(\partial\Omega)\times\mathbb{R}$. 
We also use $D_1$ for the differential of $\phi$ in the direction of $S^p_k(\partial\Omega)\times\mathbb{R}$; the meaning will be clear from context.

\subsection{Proof of Main theorem}
\begin{proof}
By Theorem \ref{MT3}, there exist an open and dense set $E_1\subset \E(\O)$ such that
\begin{align*}
\begin{aligned}
\phi:&S^k_p(\PO)\times \R\times E_1\rightarrow \ho\\
&(f, \lambda, h)\rightarrow h^{\ast}(\Lambda-\lambda) (h^{-1})^{\ast} f
\end{aligned}
\end{align*} has $0$ as a regular value.
Let $X=S^k_p(\PO)\times \R, Y=C^m(\O, \R^n),A=S^k_p\times \R\times E_1$ and $\zeta=0$. At any $(f, \lambda, h)\in \phi^{-1}(0)$ with $h\in E_1$, $D_1\phi$ is Fredholm with index $0$ by Lemma \ref{Fred} and $D\phi$ is surjective. Applying Theorem \ref{T1} to this $\phi$ yields that
\[\dot{Y}_{crit}=\{h \in E_1\,| \,\text{0 is a critical value of $\phi(,h)$}\}\] is meager. Then its complement \[E_2=\{h\in E_1\, |\, \text{0 is a regular value of $\phi(,h)$}\}\] is residual. By Lemma \ref{eva2}, this implies that all non-zero Steklov eigenvalues of $\O_h$ are simple for $h\in E_2$.

