		For $r$ small enough, we have $V \subset \Phi_\ell (U_\ell)$ and $\Phi_\ell : \Phi_\ell^{-1} (V) \to V$ is a biholomorphism.
	\end{lem}

ref_dict.prop:Main:
\begin{prop}\label{prop:Main}
		There exist an open set $W \in \CC^n$ and a biholomorphism $\B : V \to W$ such that $\B$ conjugates holomorphically the map $\tilde{F}$ (see equation \eqref{eq:TildeF}) to $(z, \w) \mapsto (z+1, \w)$ and
		$$
		\bigcup_{j \in \NN} T_j (W) = \CC \times (\CC^*)^{n-\bar{m}-1} \times \CC^{\bar{m}}.
		$$
	\end{prop}

