\renewcommand*{\ref{#1}$^\prime$}{\Alph{theorem}}

The class of inverse eigenvalue problems is among the most studied in matrix theory and applied analysis, with contributions from nearly every field of mathematics; for a nice survey, see \cite{MoodySurvey}. Let $A$ be a fixed $n \times n$ matrix over an algebraically closed field~$K$. One of the most famous among them is the \textit{additive inverse eigenvalue problem (AIEP)}:
 \begin{equation}\tag{$*$}\label{prob:additive inverse eigenvalue}
 \parbox{\dimexpr\linewidth-4em}{ Given a multiset $\{\lambda_1,\dots,\lambda_n\} \subset K$, find a diagonal matrix $D$ such that the spectrum of $A+D$ is $\{\lambda_1,\dots,\lambda_n\}$.
 }
 \end{equation}
 Over $\mathbb{C}$, Friedland showed that problem \eqref{prob:additive inverse eigenvalue} is always solvable and, for a generic choice of target spectrum, there are exactly $n!$ different solutions \cite{friedland1972matrices}. Other proofs of \eqref{prob:additive inverse eigenvalue} appear in \cites{FRIEDLAND197715, alexander1978additive}, and other variations of the same problem are investigated in \cites{kapi, VPapan}.

Friedland's result can be rephrased to say that every fiber of the morphism
 \begin{equation*}
 F_A: \operatorname{Diag}_n(\mathbb{C}) \to \mathbb{C}^n/\Sigma_n, \hspace{0.3in} D \mapsto \sigma(A+D),
 \end{equation*}
 sending a diagonal matrix $D$ to the spectrum of $A+D$, has $n!$ points when counted with multiplicities. Here, $\Sigma_n$ is the symmetric group on $n$ elements. In algebro-geometric terms, $F_A$ is finite and flat of degree $n!$, and in particular surjective.

In this paper, we study the fibers of $F_A$, especially the fiber over the spectrum of $A$ itself, consisting of the diagonal matrices $D$ such that $A$ and $A+D$ are isospectral. The other fibers are obtained from this one upon replacing $A$ by a diagonal shift. Our main theorem gives an intrinsic characterization of the ``spectrally rigid'' matrices $A$ for which the central fiber is a \emph{singleton}, that is, when there are no diagonal shifts $D \neq 0 $ preserving the spectrum of $A$.

\begin{equation}\tag{$*$}\label{prob:additive inverse eigenvalue}
        \parbox{\dimexpr\linewidth-4em}{        Given a multiset $\{\lambda_1,\dots,\lambda_n\} \subset K$, find a diagonal matrix $D$ such that the spectrum of $A+D$ is $\{\lambda_1,\dots,\lambda_n\}$.
      }
    \end{equation}

\begin{abstract}
 When can one change the diagonal of a matrix without changing its spectrum? We completely answer this question over an algebraically closed field of characteristic zero or larger than the size of the matrix: An $n \times n$ matrix $A$ admits a nonzero diagonal matrix $D$ such that $A$ and $A+D$ have the same spectrum if and only if, for some size $k$, the $k \times k$ principal minors of $A$ are not all equal. This relates to the classical additive inverse eigenvalue problem in numerical analysis and has implications for existence and rigidity results in the theory of Floquet isospectrality of discrete periodic operators in solid state physics. The proof employs new techniques involving Hilbert schemes of points and the infinitesimal structure of the Hilbert--Chow morphism.
 \end{abstract}

The class of inverse eigenvalue problems is among the most studied in matrix theory and applied analysis, with contributions from nearly every field of mathematics; for a nice survey, see \cite{MoodySurvey}. Let $A$ be a fixed $n \times n$ matrix over an algebraically closed field~$K$. One of the most famous among them is the \textit{additive inverse eigenvalue problem (AIEP)}:
 \begin{equation}\tag{$*$}\label{prob:additive inverse eigenvalue}
 \parbox{\dimexpr\linewidth-4em}{ Given a multiset $\{\lambda_1,\dots,\lambda_n\} \subset K$, find a diagonal matrix $D$ such that the spectrum of $A+D$ is $\{\lambda_1,\dots,\lambda_n\}$.
 }
 \end{equation}
 Over $\CC$, Friedland showed that problem \eqref{prob:additive inverse eigenvalue} is always solvable and, for a generic choice of target spectrum, there are exactly $n!$ different solutions \cite{friedland1972matrices}. Other proofs of \eqref{prob:additive inverse eigenvalue} appear in \cites{FRIEDLAND197715, alexander1978additive}, and other variations of the same problem are investigated in \cites{kapi, VPapan}.

In this paper, we study the fibers of $F_A$, especially the fiber over the spectrum of $A$ itself, consisting of the diagonal matrices $D$ such that $A$ and $A+D$ are isospectral. The other fibers are obtained from this one upon replacing $A$ by a diagonal shift. Our main theorem gives an intrinsic characterization of the ``spectrally rigid'' matrices $A$ for which the central fiber is a \emph{singleton}, that is, when there are no diagonal shifts $D \neq 0 $ preserving the spectrum of $A$.

\noindent Theorem \ref{thm:IntroMain} identifies the set of spectrally rigid matrices with the so-called \textit{variety of symmetrized principal minors} consisting of $n\times n$ matrices whose principal minors of equal size have the same value. This variety has been studied and described by Huang--Oeding \cite{huang2017symmetrization} in connection to the famous principal minor assignment problem \cites{al2024characterizing, holtz2007hyperdeterminantal,grinshpan2013norm}. For instance, a triangular matrix has symmetrized principal minors if and only if all of its diagonal entries are equal. In this case, Theorem \ref{thm:IntroMain} can be verified by direct computation.

\begin{corollary}\label{cor: adjacency matrix}
 Suppose that $A$ is the adjacency matrix of a weighted simple graph $G$. There exists a nonzero diagonal matrix $D$ such that $A$ and $A+D$ have the same spectrum if $G$ is neither edgeless nor complete with all edge weights equal up to sign. 
\end{corollary}
 \noindent One motivation for Corollary \ref{cor: adjacency matrix} comes from the spectral theory of discrete periodic Schr\"{o}dinger operators. Let $\Delta$ denote the discrete Laplacian on $\ZZ^d$ and let $V: \ZZ^d \to \CC$ be a $\Lambda$-periodic potential, where 
 \begin{equation*}
 \Lambda = q_1\ZZ \oplus \cdots \oplus q_d \ZZ, \qquad q_j \in \ZZ_{>0}.
 \end{equation*}

We now briefly outline the proof of Theorem \ref{thm:IntroMain}. For $A$ and $A+D$ to be isospectral, they must have the same characteristic polynomial. Equivalently, all the coefficients $S_1,\dots, S_n$ of the polynomial $\det(A-\lambda I) - \det(A+D-\lambda I)$, which we call the \textit{spectral invariants} of $A$, must vanish. The common zero locus of the ideal
\[
 E_A \coloneqq (S_1,\dots,S_n)\subset k[v_1,\dots,v_n],
\]
known as the \emph{ideal of spectral invariants}, is precisely the set of diagonal matrices $D$ such that $A+D$ is isospectral to $A$. After expanding out $S_i$ in terms of principal minors, one direction of Theorem~\ref{thm:IntroMain} is relatively direct: if all $k \times k$ principal minors of $A$ agree for every $k$, then we show that $E_A = (e_1,\dots,e_n)$, where $e_i$ denotes the $i$-th elementary symmetric polynomial in the $v_j$. In particular, its vanishing set is $\mathcal{V}(E_A)=\{0\}$.

\subsection{\emph{Proof of Theorem~\ref{thm:IntroMain}}} 
One direction is straightforward. If, for each $1\le k \le n$, all principal $k \times k$ minors of $A$ are equal, then by Lemma~\ref{lem:SpectralInvariants} each spectral invariant $S_i$ is a linear combination of elementary symmetric polynomials of degrees $\le i$ with top-degree part equal to $e_i$ and without constant terms. In particular,
 \[
 (S_1,\dots,S_n) = (e_1,\dots,e_n),
 \]
 so the only common zero is the origin. Thus there is no nonzero diagonal matrix $D$ with $A+D$ isospectral to $A$.

Set $m\coloneqq d+1$. Using Proposition~\ref{prop:relations} and Remark~\ref{rmk:single_perturbation}, we can write
 \[
 R^{v_1\cdots v_m}_{\mathrm{top}} = \sum_{k=0}^{n-m} R^{v_1\cdots v_m}_{\mathrm{top},k}.
 \]
 Evaluating at $E$ and using Lemma~\ref{lem:SpectralInvariants} to substitute
 \[
 a_J^{(m+k)} = \sum_{\substack{N\subseteq [n]\setminus J\\ |N|=m}} \det(A_N),
 \]
 we get
 \begin{align*}
 R^{v_1\cdots v_m}_{\mathrm{top}}(E)
 &= \sum_{k=1}^{n-m} \sum_{j=0}^{\min(k,m)} \lambda_{k,j}
 \sum_{\substack{J\subseteq [n]\\ |J|=k\\ |J\cap [m]|=j}}
 \sum_{\substack{N\subseteq [n]\setminus J\\ |N|=m}} \det(A_N) \\
 &= \sum_{\substack{N\subseteq [n]\\ |N|=m}} \det(A_N)
 \sum_{\emptyset\neq J\subseteq [n]\setminus N} \lambda_{|J|,|J\cap [m]|},
 \end{align*}
 with $\lambda_{k,j}$ as in the proof of Proposition~\ref{prop:relations}. (The $k=0$ term vanishes because the $S_i$ have no constant terms.) We can rewrite
 \[
 \sum_{\emptyset\neq J\subseteq [n]\setminus N} \lambda_{|J|,|J\cap [m]|}
 = m!\,(n-m)! + \sum_{J\subseteq [n]\setminus N} \lambda_{|J|,|J\cap [m]|}.
 \]
 We set $r \coloneqq |[m] \setminus N|$ and decompose $J$ as $J = J_1 \sqcup J_2$ such that $J_1 \subseteq [m] \setminus N$ and $J_2 \subseteq [n] \setminus ([m] \cup N)$ with $|J_1| = j$ and $|J_2| = j'$. This yields
 \begin{equation*}
 \sum_{J \subseteq [n] \setminus N} \lambda_{|J|,|J \cap [m]|} = - m \sum_{j = 0}^r (-1)^j \binom{r}{j} \sum_{j' = 0}^{n-m-r} \binom{n-m-r}{j'} (m-1+j')! (n-m-j')!.
 \end{equation*}
 The sums over $j$ and $j'$ are independent, and $\sum_{j = 0}^r (-1)^j \binom{r}{j} = 0$ if $r \geq 1$, so we are left only with the term for $r = 0$, i.e., $N = [m]$. In this case, we get
 \begin{align*}
 \sum_{J \subseteq [n] \setminus [m]} \lambda_{|J|,|J \cap [m]|} &= -m \sum_{j' = 0}^{n-m} \binom{n-m}{j'} (m-1+j')! (n-m-j')! \\
 &= -m \sum_{j' = 0}^{n-m} \binom{m-1+j'}{m-1} (m-1)! (n-m)! \\
 &= - m! (n-m)! \sum_{j' = 0}^{n-m} \binom{m-1+j'}{m-1} \\
 &= - m! (n-m)! \binom{n}{m} = - n!.
 \end{align*}
 Putting everything together, we obtain
 \[
 R^{v_1\cdots v_m}_{\mathrm{top}}(E)
 = m!(n-m)! \sum_{\substack{N\subseteq [n]\\ |N|=m}} \det(A_N)
 \;-\; n!\,\det(A_{[m]}).
 \]
 Since $\operatorname{char}K=0$ or $>n$, the integer $n!$ is invertible in $K$, so this expression vanishes if and only if
 \begin{equation}\label{eq:principalMinors}
 \det(A_{[m]})
 = \binom{n}{m}^{-1}\sum_{\substack{N\subseteq [n]\\ |N|=m}} \det(A_N),
 \end{equation}
 i.e., the principal $m \times m$ minor on indices $[m]$ equals the average of all principal $m \times m$ minors.

