\begin{lem}\label{lem3.4}
Let $\Omega=B_R(0) \subset \mathbb{R}^n$ with $n \geq 3$, and let $\alpha$, $\beta$, $\delta $ be as in Lemma~\ref{alphabeta-lem}. Assume that \eqref{f} and \eqref{g} hold with $p,q <1$ satisfying $(\ref{pq})$. For fixed $y_{\star}$ taken from Lemma~\ref{lem3.3}, there exists a sufficiently small constant $s_{\star}=s_{\star}(\alpha,\beta,\mu^{\star},l,\delta) \in (0,R^n)$ such that if $T>0$ and a nondecreasing function $y(t) \in C^1([0, T))$ satisfies 
\begin{align}\label{y1-3}
\left\{\begin{array}{l}
y^{\prime}(t)\leq 
y^{1+\delta}(t), \ t\in (0,T), \\
y(0) > \max\{\frac{1}{s_{\star}},(1+\frac{\beta}{n-1-n\beta})\frac{1}{R^n}, y_{\star}\},
\end{array}\right.
\end{align}
then, for arbitrary $\theta>0$, the functions $\underline{U}$ and $\underline{W}$ from $(\ref{eq3_7})$ satisfy
\begin{align}\label{mid}
\mathcal{P}[\underline{U}, \underline{W}](s, t) \leq 0, \quad \mathcal{Q}[\underline{U}, \underline{W}](s, t) \leq 0,
\end{align}
for all $t \in (0,T) \cap \left(0, \frac{1}{\theta}\right)$ and $s \in \big(\frac{1}{y(t)},s_{\star}\big]$.
\end{lem}
\begin{proof}
The interval $ (\frac{1}{y(t)},s_{\star}]$ is non-empty, owing to the fact that $y(t) \geq y(0) > \frac{1}{s_{\star}} $. Given the choices of $\alpha$, $\beta$ and $\delta$ in Lemma~\ref{alphabeta-lem}, 
we can choose $s_{\star} \in (0,R^n)$ to be sufficiently small so that 
\begin{align}\label{sstar}
s_{\star}^{1-\beta} < \frac{ln\beta^{1-\beta}}{2\mathrm{e}\mu^{\star}},\quad
s_{\star}^{1-\beta-\frac{1}{n}} < \frac{l}{2\mathrm{e}}
\end{align}
and
\begin{align}\label{sstar-1}
\frac{2\alpha^{\delta-\alpha} l}{c_1}<s_{\star}^{-\big((\frac{1}{n}+\beta-1)p+1-\beta-\delta\big)},\quad
\frac{2n^2\alpha^{\frac{2}{n}-\alpha-1}l}{c_1}<s_{\star}^{-\big((\frac{1}{n}+\beta-1)p+1-\beta-\frac{2}{n}\big)} ,
\end{align}
\begin{align}\label{sstar-2}
s_{\star}^{1-\alpha} < \frac{ln\alpha^{1-\alpha}}{2\mathrm{e}\mu^{\star}},\quad
s_{\star}^{1-\alpha-\frac{1}{n}} < \frac{l}{2\mathrm{e}},
\end{align}
as well as
\begin{align}\label{sstar-3}
\frac{2\beta^{\delta-\beta} l}{c_2}<s_{\star}^{-\big((\frac{1}{n}+\alpha-1)q+1-\alpha-\delta\big)},\quad
\frac{2n^2\beta^{\frac{2}{n}-\beta-1}l}{c_2}<s_{\star}^{-\big((\frac{1}{n}+\alpha-1)q+1-\alpha-\frac{2}{n}\big)},
\end{align}
where 
\begin{align}\label{c2}
c_1=\min\{2^{p-1}\alpha^{-(1-\frac{1}{n})p},2^{\frac{p}{2}-1}\}c_{\star}^{\beta(1-p)}n \mathrm{e}^{p-2} \alpha^{1-\alpha}l^{2-p}\beta^{-\beta(1-p)} 
\end{align}
and $$c_2=\min\{2^{q-1}\beta^{-(1-\frac{1}{n})q},2^{\frac{q}{2}-1}\}{c_{\star \star}}^{\alpha(1-q)}n \mathrm{e}^{q-2} \beta^{1-\beta}l^{2-q}\alpha^{-\alpha(1-q)} $$ 
with $c_{\star}=\min\{\frac{\beta}{\alpha},1\}$ and $c_{\star \star}=\min\{\frac{\alpha}{\beta},1\}$. According to the definitions of $\underline{U}$, $\underline{W}$, $\mathcal{P}$ and $h$ defined in (\ref{h}), along with $\theta t<1$ by (\ref{thetat}), we have
\begin{align}\label{p-1} 
\mathcal{P}[\underline{U}, \underline{W}](s, t)
=& \underline{U}_t - n^2 s^{2 - \frac{2}{n}} \underline{U}_{ss} - n \underline{U}_s \cdot \Big(\underline{W} - \frac{\mu^{\star} s}{n}\Big) f\left(s^{\frac{2}{n}-2}\Big(\underline{W}-\frac{\mu^{\star} s}{n}\Big)^2\right)
\nonumber \\
=&-\theta \mathrm{e}^{-\theta t}\alpha^{-\alpha}l\Big(s-\frac{1-\alpha}{y(t)}\Big)^\alpha
+\mathrm{e}^{-\theta t}\alpha^{1-\alpha} l(1-\alpha)\Big(s-\frac{1-\alpha}{y(t)}\Big)^{\alpha-1}\frac{y^{\prime}(t)}{y^{2}(t)} \nonumber \\
&+\mathrm{e}^{-\theta t}n^2s^{2-\frac{2}{n}}\alpha^{1-\alpha} l (1-\alpha)\Big(s-\frac{1-\alpha}{y(t)}\Big)^{\alpha-2}\nonumber \\
& -n\mathrm{e}^{-\theta t}\alpha^{1-\alpha}l\Big(s-\frac{1-\alpha}{y(t)}\Big)^{\alpha-1} s^{1-\frac{1}{n}}
h\left(s^{\frac{1}{n}-1}\Big(\underline{W}-\frac{\mu^{\star} s}{n}\Big)\right)\nonumber \\
\leq& \alpha^{1-\alpha} l\Big(s-\frac{1-\alpha}{y(t)}\Big)^{\alpha-1}\cdot y^{\delta-1}(t)
+n^2s^{2-\frac{2}{n}}\alpha^{1-\alpha}l \Big(s-\frac{1-\alpha}{y(t)}\Big)^{\alpha-2} \nonumber \\
& -n\mathrm{e}^{-\theta t}\alpha^{1-\alpha}l\Big(s-\frac{1-\alpha}{y(t)}\Big)^{\alpha-1}
 s^{1-\frac{1}{n}}
h\left(s^{\frac{1}{n}-1}\Big(\underline{W}-\frac{\mu^{\star} s}{n}\Big)\right),
\end{align}
for all $t \in (0,T) \cap \big(0, \frac{1}{\theta}\big)$ and $s \in \big(\frac{1}{y(t)},s_{\star}\big]$. 
Due to $\delta \in (0,\frac{1}{n})$, for all $s>\frac{1}{y(t)}$, we obtain
\begin{align}\label{s1y}
y^{\delta-1}(t)<{\alpha}^{\delta-1}\Big(s-\frac{1-\alpha}{y(t)}\Big)^{1-\delta},\
\alpha s<s-\frac{1-\alpha}{y(t)}, \
\beta s<s-\frac{1-\beta}{y(t)}.
\end{align}
Employing the first two inequalities in (\ref{s1y}), we estimate the first two terms on the right-hand side of (\ref{p-1}), and thus derive that
\begin{align}\label{p-2}
 \mathcal{P}[\underline{U}, \underline{W}](s, t) 
\leq & \alpha^{\delta-\alpha} l\Big(s-\frac{1-\alpha}{y(t)}\Big)^{\alpha-\delta}
+n^2\alpha^{\frac{2}{n}-\alpha-1}l \Big(s-\frac{1-\alpha}{y(t)}\Big)^{\alpha-\frac{2}{n}}\nonumber\\
& -n\mathrm{e}^{-\theta t}\alpha^{1-\alpha}l\Big(s-\frac{1-\alpha}{y(t)}\Big)^{\alpha-1}
 s^{1-\frac{1}{n}}
h\left(s^{\frac{1}{n}-1}\Big(\underline{W}-\frac{\mu^{\star} s}{n}\Big)\right).
