In the following, we show that problem $\eqref{1.1}$ admits no local-in-time solution with $u_0$ defined as $\eqref{Nonexist-u_0def}$. Assume by contradiction that, problem $\eqref{1.1}$ admits a solution in $\RN\times(0,T)$ for some $T>0$. 
 Then, by Lemma \ref{Nonexist-lem}, we have 
 \begin{equation}\label{Non1}
 [e^{t\Delta} u_0](0) \le F^{-1}\left(\frac{1}{C} t^{1-\frac{\gamma}{2}}\right) \quad \text{for}~~t \in (0, T). 
 \end{equation}
 On the other hand, since
 \begin{equation*}
 \frac{d^{2}}{d\xi^{2}} \left[F^{-1}(\xi) \right] = f\left(F^{-1}(\xi) \right) f'\left(F^{-1}(\xi) \right)\ge0 \quad \text{for}~~\xi>0, 
 \end{equation*}
 $F^{-1}$ is convex on $(0, \infty)$. Thus, it follows from Proposition~\ref{Jensen} that
 \begin{equation}\label{Non2}
 \begin{split}
 [e^{t\Delta} u_0](0) &= \int_{\RN} G(y, t) F^{-1}(|y|^{A}) \,dy \\
 &\ge F^{-1}\left(\int_{\RN} G(y, t) |y|^{A} \,dy \right) \\
 &= F^{-1}\left((4\pi t)^{-\frac{N}{2}} \int_{\RN} e^{-\frac{|y|^{2}}{4t}} |y|^{A} \,dy \right) \\
 &=F^{-1}(C t^{\frac{A}{2}}) 
 \end{split}
 \end{equation}
 for $t\in(0,T)$. Thus, by $\eqref{Non1}$ and $\eqref{Non2}$, we have
 \begin{equation*}
 F^{-1}\left(C t^{\frac{A}{2}}\right) \le F^{-1}\left(\frac{1}{C} t^{1-\frac{\gamma}{2}} \right) 
 \end{equation*}
 for $t\in(0,T)$. Since $F^{-1}$ is decreasing, we have
 \begin{equation*}
 t^{\frac{A}{2}} \ge C t^{1-\frac{\gamma}{2}}, \quad \text{that is,} \quad t^{\frac{A}{2} - \left(1-\frac{\gamma}{2} \right)} \ge C 
 \end{equation*}
 for $t \in (0, T)$. Therefore, this is contradiction for small $t>0$, since $A/2 - (1-\gamma/2)>0$. This completes the proof of Theorem~\ref{Nonexist-thm}. 
\end{proof}

