\label{Exist-thm}
  Let $N\ge1$, $0<\gamma <\min\{2, N\}$, $u_0\ge 0$ and $f \in S_{q}$ with $q \in [1, \infty)$. Then, there exists $T>0$ such that
\begin{equation} 
  \label{1.1} 
  \left\{ 
  \begin{array}{ll} 
  \partial_t u - \Delta u = |x|^{-\gamma} f(u), &x \in \RN, ~ t\in (0, T), \vspace{3pt} \\ 
  u(x,0)=u_0(x) \ge 0, &x \in \RN, 
  \end{array} 
  \right. 
\end{equation}
  has a local-in-time nonnegative solution $u$ in $\RN \times(0,T)$, if one of the following holds{\rm :} 
  \begin{itemize}
    \item[$\mathrm{(i)}$] $r>N/(2-\gamma)$, $q<1+r$ and $F(u_0)^{-r} \in L^{1}_{\rm ul}(\RN)$. 
    \item[$\mathrm{(ii)}$]  $r>N/(2-\gamma)$, $q=1+r$, $F(u_0)^{-r} \in L^{1}_{\rm ul}(\RN)$ and
      \begin{equation}\label{sub-assum}
        f'(\xi) F(\xi) \le q \quad \text{for large} ~~ \xi>0. 
      \end{equation}
      holds.   
    \item[$\mathrm{(iii)}$] $r=N/(2-\gamma)$, $q<1+r$ and $F(u_0)^{-r} \in \mathcal{L}^{1}_{\rm ul}(\RN)$. 
  \end{itemize}
  Moreover, in all cases, there exists a constant $C>0$ depending on $N$ and $u_0$ such that
  \begin{equation}\label{Exist-thm-est}
    \|F(u(t))^{-r}\|_{L^{1}_{\rm ul}(\RN)} \le C \quad \text{for}~~0<t<T. 
  \end{equation}

