\noindent\textit{Step 5: Putting it together.}
Finally, applying \Cref{thm:mixed-tail}, for any fixed $W_0\in \cW$, we have
\begin{equation*} \begin{aligned}
 \bE \left[\sup_{W\in\cW} X_W\right]
 &=\bE \left[\sup_{W\in\cW} X_W-X_{W_0}\right]\\
 &\leq \bE \left[\sup_{W\in\cW} \left|X_W-X_{W_0}\right|\right]\\
 &\le C\bigl(\sqrt{p}\gamma_2(\cW,d_2)+\gamma_1(\cW,d_{1})\bigr)+2 \sup_{W \in \cW} \bE \left[|X_W - X_{W_0}|\right]\\
 &\leq C\left(\sqrt{p\log(mn)}+\mu r^2\left(\frac{1}{m}+\frac{1}{n}\right)\log^2(mn)\right),
 \end{aligned}
\end{equation*}
for an absolute constant $C>0$. Here, in the last inequality, we use the following estimation 
\begin{equation*}
 \bE \left[|X_W - X_{W_0}|\right]\leq 2\bE \left[|X_W|\right]\leq 2\left(\Var(X_W)\right)^{1/2}\leq 2\sqrt{p}\norm{W}_2\leq 2\sqrt{p}.
\end{equation*}
On the other hand, note that $\Delta_2(\cW) \le 2 \sqrt{\mu r \left( \frac{1}{m} + \frac{1}{n} \right)}$ and $\Delta_\infty(\cW) \le 2 \mu r \left( \frac{1}{m} + \frac{1}{n} \right)$. Hence, applying \Cref{thm:mixed-tail} yields that 
\begin{equation*}
 \begin{aligned}
 \bP\bigg(\sup_{W\in\cW} X_W &\geq C\left(\sqrt{p\log(mn)}+\log^2(mn)\mu r^2\frac{1}{\min\{m, n\}}\right)\\
 &\qquad+c\left(\sqrt{ \frac{\mu ru}{\min\{m,n\}} } +\frac{\mu ru}{\min\{m,n\}}\right)\!\bigg) \leq e^{-u}.
 \end{aligned}
\end{equation*}
Upon setting $u=Cr\log^2(mn)$, with probability at least $1-\exp\{-Cr\log^2(mn)\}$, we have
 \begin{equation*}
 \sup_{W\in\cW} X_W\leq C\left(\sqrt{p\log(mn)}+\frac{\log^2(mn)\mu r^2}{\min\{m, n\}}+\log(mn)r\sqrt{\frac{\mu}{\min\{m, n\}}}\right).
 \end{equation*}
This completes the proof.
\subsection{Determination of second-order optimality}\label{sec:second_order}
In this section, we investigate second-order optimality of solutions in $\mathcal L$. When the rank of the underlying low-rank component $L$ equals the factorization rank $k$, any $(X^{\star},Y^{\star})\in \mathcal L$ is in fact a sharp local minimum: the objective value grows at least linearly with the distance to $\mathcal L$. This is the object of Theorem \ref{thm:localmin}, which leverages the restricted $\ell_1$ operator-norm estimate for $\mathcal P_{\Omega}$ established in \Cref{thm::first-order-optimality}. Given $A\in \mathbb R^{m\times n}$ and $r\le \rank(A)$, we denote by $\sigma_r(A)$ the $r$-th largest singular value of $A$.
\begin{theorem}\label{thm:localmin}
 Assume $k = r$ and that there exists $\epsilon>0$ such that 
 \begin{equation}\label{eq:restricted_bound_sharp}
 \|\mathcal{P}_\Omega(W)\|_1 \leq \frac{1-\epsilon}{2} \|W\|_1,\quad\forall W\in T. 
 \end{equation}
 Then for any $(X^{\star},Y^{\star})\in \mathcal L$, there exists $\rho > 0$ such that
 \begin{align*}
 f(X,Y) - f(X^{\star},Y^{\star}) \ge \frac{\epsilon}{8}\min\{\sigma_{r}(X^{\star}),\sigma_{r}(Y^{\star})\}\, d((X,Y),\mathcal L)
 \end{align*}
 for all $(X,Y)\in B((X^{\star},Y^{\star}),\rho)$.
\end{theorem}

\begin{remark}[Implied linear convergence of the subgradient method]
As the objective (\Eqref{eq:obj}) is weakly convex \cite{vial1983strong}, the sharp growth of $f$ guaranteed by Theorem \ref{thm:localmin} implies that the subgradient method with geometrically decaying step sizes converges linearly when initialized near the solution set $\mathcal L$; see, for example, \cite{burke1993weak,davis2018subgradient,li2020nonconvex}. This corroborates our numerical experiments reported in Figure \ref{fig:error-exact}.
\end{remark}
\begin{proof}
 Fix $(X^{\star},Y^{\star})\in \mathcal L$. As $k = r$, $\mathcal L$ is a smooth embedded manifold. By the tubular neighborhood theorem \cite{lee2003smooth}, there is a neighborhood $\mathcal{N}$ of $(X^{\star},Y^{\star})$ so that the projection
$\mathcal P_{\mathcal L}$ onto $\mathcal L$ is single-valued and continuous on
$\mathcal{N}$. Fix $(X,Y)\in \mathcal N$ and set
\[
(X^\sharp,Y^\sharp):=\mathcal P_{\mathcal L}(X,Y),\qquad H:=X-X^\sharp,\quad K:=Y-Y^\sharp.
\]
Let $G_\sharp:=\{(X^\sharp A, -Y^\sharp A^\top): A\in\mathbb R^{r\times r}\}$ be the tangent 
space to $\mathcal L$ at $(X^\sharp,Y^\sharp)$. Since $(X^\sharp,Y^\sharp)$ minimizes
$\frac12\|(X',Y')-(X,Y)\|_2^2$ over $(X',Y')\in\mathcal L$, first-order optimality yields $(H,K)\in G_\sharp^\perp$. Also,
\begin{equation*}d:= d\big((X,Y),\mathcal L\big) = \|(H,K)\|_2.
\end{equation*}
Expand
\[
\Delta:= XY^\top - X^{\star}Y^{\star\top}
= \underbrace{X^\sharp K^\top + H(Y^\sharp)^\top}_{\Delta_1} + \underbrace{HK^\top}_{\Delta_2}.
\]
Note that $\Delta_1\in T$ and $\Delta_2$ is quadratic in $(H,K)$. We have
\begin{align*}
 f(X,Y) - f(X^{\star},Y^{\star}) &= \|XY^{\top} - M\|_1 - \|X^{\star}(Y^{\star})^{\top} - M\|_1\\
 &= \|\Delta - S\|_1 - \|S\|_1\\
 &= \|\mathcal{P}_{\Omega^c}(\Delta)\|_1 + \|\mathcal{P}_{\Omega}(\Delta) - S\|_1 - \|S\|_1\\
 &= \|\mathcal{P}_{\Omega^c}(\Delta)\|_1 + \langle -\sign(S),\mathcal{P}_\Omega(\Delta)\rangle\\
 &\ge \epsilon \|\mathcal{P}_{\Omega^c}(\Delta)\|_1+ \langle \Lambda,\mathcal{P}_{\Omega^c}(\Delta)\rangle + \langle -\sign(S),\mathcal{P}_\Omega(\Delta)\rangle\\
 &=\epsilon \|\mathcal{P}_{\Omega^c}(\Delta)\|_1+ \langle \Lambda,\Delta\rangle,
\end{align*}
where $\Lambda\in -\sign(S)$ satisfies $\|\mathcal{P}_{\Omega^c}(\Lambda)\|_\infty \leq 1- \epsilon$. By \Cref{lemma:interior}, we may assume additionally that $\Lambda Y^\sharp =\Lambda V = 0$ and $\Lambda^{\top} X^\sharp = \Lambda^{\top} U= 0$. Thus,
\begin{align*}
 \langle \Lambda,\Delta\rangle = \langle \Lambda,\Delta_1 + \Delta_2\rangle = \langle \Lambda,\Delta_2\rangle.
\end{align*}
Also,
\begin{align*}
 \|\mathcal{P}_{\Omega^c}(\Delta)\|_1 \geq \|\mathcal{P}_{\Omega^c}(\Delta_1)\|_1 - \|\mathcal{P}_{\Omega^c}(\Delta_2)\|_1,
\end{align*}
where
\begin{align*}
 \|\mathcal{P}_{\Omega^c}(\Delta_1)\|_1 &= \|\Delta_1\|_1 - \|\mathcal{P}_{\Omega}(\Delta_1)\|_1\\
 &\ge \Bigl(1-\frac{1-\epsilon}{2}\Bigr)\|\Delta_1\|_1\\
 &= \frac{1+\epsilon}{2}\|\Delta_1\|_1
\end{align*}
by \Eqref{eq:restricted_bound_sharp}. Combining the above inequalities, we have
\begin{equation}\label{eq:overall}
 \begin{aligned}
f(X,Y)-f(X^\ast,Y^\ast)
&\ge \epsilon \|\mathcal P_{\Omega^c}(\Delta)\|_1 + \langle \Lambda,\Delta\rangle \\
&\ge \frac{\epsilon}{2}\|\Delta_1\|_1 - \epsilon\|\mathcal P_{\Omega^c}(\Delta_2)\|_1
 + \langle \Lambda,\Delta_2\rangle\\
 &\ge \frac{\epsilon}{2}\|\Delta_1\|_1 - \epsilon\|\mathcal P_{\Omega^c}(\Delta_2)\|_1
 -(1-\epsilon)\|\Delta_2\|_1\\
 &\ge \frac{\epsilon}{2}\|\Delta_1\|_1 - \|\Delta_2\|_1. 
 \end{aligned}
\end{equation}

\begin{theorem}\label{thm:over}
Let $k>r\ge 1$, $(X^{\star},Y^{\star})\in \mathcal L$, and assume $S\neq 0$. Then there exist $(H,K)\in\mathbb{R}^{m\times k}\times \mathbb{R}^{n\times k}$ with
\(
\|H\|_2^2+\|K\|_2^2=1
\)
and $t_0>0$ such that
\[
f(X^{\star}+tH,Y^{\star}+tK)=f(X^{\star},Y^{\star})-\gamma\,t^2
\quad\forall t\in [0,t_0],
\]
where
\[
\gamma:=\frac12\|P_XP_Y\|_{\mathrm{op}}\;>0
\]
and $P_X,P_Y\in \mathbb R^{k\times k}$ are orthogonal projectors onto $\ker(X^{\star})$ and $\ker(Y^{\star})$, respectively.
\end{theorem}
When \( k > 2r \), we always have \( \norm{P_X P_Y}_{\mathrm{op}} = 1 \), which implies that \( \gamma = \frac{1}{2} \). Moreover, unlike the case for smooth functions, the subgradient method can still converge to a saddle point of nonsmooth objectives such as \Eqref{eq:obj}. In our experiments, the subgradient method converges to a true solution even when \( k > r \), as shown in Figure \ref{fig:error-over}. However, the achieved accuracy is not as good as in the case \( k = r \) (see Figure \ref{fig:error-exact}), which aligns with the lack of sharpness suggested by Theorem \ref{thm:over}.

