v_+ > v_-.
\end{equation}
The existence and uniqueness of the small-amplitude 2-shock profile have been treated in \cite{DLZ}:

\begin{lemma}[\cite{DLZ}, Proposition~1.9] \label{SP}
For given $(v_-,u_-)$ with $v_->0$, there exists a positive constant $\delta_0>0$ such that for any $(v_+,u_+,s)$ satisfying \eqref{RH}, \eqref{Lax}, and
\begin{equation*}
|v_+-v_-| =: \delta_S < \delta_0,
\end{equation*}
the ODE system \eqref{waveeq} admits a unique (up to a shift) shock profile $(\bar{v},\bar{u},\bar{\phi})(x)$ satisfying \eqref{ffcond} and
\begin{equation} \label{sprel}
s\bar{v}_x = -\bar{u}_x >0, \quad \underline{C} \bar{u}_x \leq \bar{\phi}_x \leq \overline{C} \bar{u}_x
\end{equation}
for some positive constants $\underline{C}$, $\overline{C}$. Moreover, the unique solution satisfying $\textstyle \bar{v}(0)=\frac{v_-+v_+}{2}$ verifies the derivative bounds
\begin{equation} \label{spbound}
\begin{cases}
\left| \frac{d^k}{dx^k} (\bar{v}-v_+, \bar{u}-u_+,\bar{\phi}-\phi_+) \right| \leq C_k \delta_S^{k+1} e^{-\theta \delta_S |x|}, & x>0 \\
\left| \frac{d^k}{dx^k} (\bar{v}-v_-, \bar{u}-u_-,\bar{\phi}-\phi_-) \right| \leq C_k \delta_S^{k+1} e^{-\theta \delta_S |x|}, & x<0
\end{cases}
\end{equation}
for $k \in \mathbb{N} \cup \{0 \}$, where $C_k>0$ and $\theta>0$ are generic constants.
\end{lemma}

\subsection{Main result}
To state our result, we define the linearized operator $L$ about the profile $(\bar{v},\bar{u},\bar{\phi})$ on $L^2(\mathbb{R})\times L^2(\mathbb{R})$:
\begin{equation} \label{Ldef}
LU := \left(A U \right)_x + \left( B U_x \right)_x + \left(D ( \mathcal{A}^{-1}\mathcal{B} U )_x \right)_x + \left(E ( \mathcal{A}^{-1}\mathcal{B} U )_{xx} \right)_x,
\end{equation}
where
\begin{equation} \label{ABDE}
\begin{split}
A(x) &= \begin{pmatrix}
s & 1 \\
\frac{T+1}{\bar{v}^2} - \frac{\nu\bar{u}_x}{\bar{v}^2} - \frac{\varepsilon^2 \bar{\phi}_x^2}{\bar{v}^3} + \frac{\varepsilon^2}{\bar{v}} \left( \frac{\bar{\phi}_x}{\bar{v}^2} \right)_x + \frac{\varepsilon^2}{\bar{v}^2} \left( \frac{\bar{\phi}_x}{\bar{v}} \right)_x & s
\end{pmatrix} \\
B(x) &= \begin{pmatrix}
0 & 0 \\
\frac{\varepsilon^2 \bar{\phi}_x}{\bar{v}^3} & \frac{\nu}{\bar{v}}
\end{pmatrix}, \quad D(x) = \begin{pmatrix}
0 & 0 \\
\frac{\varepsilon^2 \bar{\phi}_x}{\bar{v}^2} + \frac{\varepsilon^2\bar{v}_x}{\bar{v}^3} & 0
\end{pmatrix}, \quad E(x) = \begin{pmatrix}
0 & 0 \\
-\frac{\varepsilon^2}{\bar{v}^2} & 0
\end{pmatrix}.
\end{split}
\end{equation}
The nonlocal operator $\mathcal{A}^{-1}\mathcal{B}$ denotes the solution operator of the linearized Poisson equation (cf. Appendix~\ref{App_B}), where
\begin{equation} \label{calAB}
\begin{split}
\mathcal{A} & =\bar{v} e^{\bar{\phi}}+ \frac{\varepsilon^2 \bar{v}_x}{\bar{v}^2} \partial_x-\frac{\varepsilon^2}{\bar{v}} \partial_{xx}, \quad \mathcal{B} = -e^{\bar{\phi}} -\frac{\varepsilon^2 \bar{\phi}_{xx}}{\bar{v}^2} + \frac{2\varepsilon^2 \bar{v}_x \bar{\phi}_x}{\bar{v}^3}-\frac{\varepsilon^2 \bar{\phi}_x}{\bar{v}^2} \partial_x.
\end{split}
\end{equation}
For $U=(v,u)^{\mathrm{tr}}$ we use the notational extension $\mathcal{A}^{-1}\mathcal{B}U := (\mathcal{A}^{-1}\mathcal{B}v,0)^{\mathrm{tr}}$, since $D$ and $E$ in \eqref{ABDE} have vanishing second column, and hence only the first component is used in \eqref{Ldef}. We note that, as shown in Appendix~\ref{App_closed}, the operator $L$ is closed and densely defined on $L^2(\mathbb{R})\times L^2(\mathbb{R})$.

