\label{thm1.1}
	Assume $(A_1)$ or $(A_2)$, and $W(x)$ satisfies $(W_1)$ and $(W_2)$. Then
	\begin{itemize}
		\item[(i)] there exists $k_0>0$ such that, for all $k>k_0$, \eqref{1.1} admits a dual ground state solution;
		\item[(ii)] let $k_n\to \infty$ with $k_n>k_0$ for all $n$, and for each $n$ let $u_n$ be a dual ground state solution of
		\begin{equation*}
			\Delta^2 u_n - \beta k_n^2\, \Delta u_n + \alpha k_n^4\, u_n
			= W(x)\, |u_n|^{p-2}u_n
			~\text{in}~\mathbb{R}^N.
		\end{equation*}
		Then there exists a point $x_0\in\mathbb{R}^N$ such that $W(x_0)=W_0$, a ground state solution $u_0$ of the limit problem
		\begin{equation*}
			\Delta^2 u - \beta\, \Delta u + \alpha\, u
			= W_0\, |u|^{p-2}u
			\quad \text{in } \mathbb{R}^N,
		\end{equation*}
		and a sequence $(x_n)$ with $x_n\to x_0$ such that, after translation and rescaling,
		\begin{equation*}
			u_n\!\left(\tfrac{\cdot}{k_n}+x_n\right) \to u_0
			\quad \text{in } L^p(\mathbb{R}^N)\ \text{as } n\to\infty.
		\end{equation*}
	\end{itemize}

ref_dict.lem:profile:
\begin{Lem}\label{lem:profile}
	Assume that $W\equiv W(0)>0$ on $\mathbb{R}^N$.
	Let $(v_n)_n\subset L^{p^\prime}(\mathbb{R}^N)$ be a \((PS)_d\)-sequence for $J$ at level $d>0$.
	Then there exist an integer $m\ge1$, nontrivial critical points $w^{(1)},\dots,w^{(m)}$ of $J$,
	and sequences $(x_n^{(1)}),\dots,(x_n^{(m)})\subset\mathbb{R}^N$ such that ,  for a subsequence , as $n\to\infty$, we have
	\begin{equation}\label{eq:profile}
		\begin{cases}
			\ \ \ \|\,v_n - \sum_{j=1}^m w^{(j)}(\cdot - x_n^{(j)})\,\|_{L^{p^\prime}(\mathbb{R}^N)} \to 0, \\[2pt]
			\ |x_n^{(i)} - x_n^{(j)}| \to \infty \quad (i\neq j),\\[2pt]
			\ \ \ \sum_{j=1}^m J\!\big(w^{(j)}\big) = d.
		\end{cases}
	\end{equation}
\end{Lem}

