\section{Global Boundedness. Proof of Theorem \ref{thm1_2}}\label{bounded}
In this section, we prove Theorem~\ref{thm1_2}. Inspired by \cite{2021-JMAA-Zhong}, we construct a Lyapunov functional of the form 
\begin{align}\label{f-def}
\mathcal{F}(t):=\mathcal{F}(u, v, w, z)=\int_{\Omega} {G}(u) d x+\int_{\Omega} w\mathrm{ln}w d x-\int_{\Omega} \nabla v \cdot \nabla z d x,
\end{align}
where ${G}$ is given by 
\begin{align}\label{G-1}
{G}(s):=\int_{s_1}^s \int_{s_1}^\sigma \frac{{D}(\tau)}{S(\tau)} d \tau d \sigma
\end{align}
with some $s>s_1>0$. The Lyapunov functional $\mathcal{F}(t)$ is nonincreasing along trajectories and plays a crucial role in demonstrating the boundedness of solutions.
\begin{lem}\label{lemma-f}
Suppose that $\left(u, v, w, z\right)$ is a classical solution of $(\ref{eq1.1.0})$, as given in Proposition~\ref{local}. Assume that the functions $D(s)$ and $S(s)$ fulfill $(\ref{eq1.2})$. Then
\begin{align}\label{f}
\frac{d}{d t} \mathcal{F}(t)
=-\int_{\Omega} S(u)\left|\frac{\mathcal{D}(u)}{S(u)} \nabla u-\nabla v\right|^2 d x-\int_{\Omega} w\left|\frac{\nabla w}{w} -\nabla z\right|^2 d x
=-\mathcal{D}(t), \quad t>0 .
\end{align}
Moreover, let $u_0, w_0$ satisfy $(\ref{eq1.1})$, and let $v_0, z_0 \in C^2(\bar{\Omega})$ be the corresponding solutions of
\begin{align}\label{v0}
0=\Delta v_0 -\mu_w +w_0, \quad \left.\partial_\nu v_0\right|_{\partial \Omega}=0, \quad \int_{\Omega} v_0 dx=0
\end{align} 
and 
\begin{align}\label{z0}
0=\Delta z_0 -\mu_u +u_0, \quad \left.\partial_\nu z_0\right|_{\partial \Omega}=0, 
\quad \int_{\Omega} z_0 dx=0,
\end{align}
then
\begin{align}\label{f-inter}
\mathcal{F}(t)-\mathcal{F}(0)=-\int_0^t \mathcal{D}(\zeta) d \zeta, \quad t \in\left(0, T_{\max }\right).
\end{align}
\end{lem}
\begin{proof}
Multiplying the first equation in (\ref{eq1.1.0}) by $G^{\prime}(u)$, we deduce that
\begin{align*}
&\frac{d}{d t} \int_{\Omega} {G}(u) dx \nonumber \\
=& \int_{\Omega}G^{\prime}(u) \nabla \cdot(D(u) \nabla u-S(u) \nabla v) dx \nonumber \\ 
=&-\int_{\Omega} \frac{D^2(u)}{S(u)}|\nabla u|^2 dx
+ \int_{\Omega}D(u) \nabla u \cdot \nabla v dx \nonumber \\
=&- \int_{\Omega} S(u) \left|\frac{D(u)}{S(u)}\nabla u -\nabla v\right|^2 d x
+ \int_{\Omega} S(u) |\nabla v|^2 dx
- \int_{\Omega} D(u)\nabla u \cdot \nabla v dx .
\end{align*}
Using the first and fourth equations in (\ref{eq1.1.0}) and integrating by parts, we have
\begin{align*}
- \int_{\Omega} D(u)\nabla u \cdot \nabla v dx
=& \int_{\Omega} \Big(u_t+\nabla \cdot \big(S(u) \nabla v\big)\Big) v dx \nonumber \\ 
=& \int_{\Omega} u_t v dx
- \int_{\Omega} S(u) |\nabla v|^2 dx \nonumber \\ 
=& \int_{\Omega} (\mu_u-\Delta z)_t v dx
- \int_{\Omega} S(u) |\nabla v|^2 dx \nonumber \\ 
=& \int_{\Omega} (\nabla z)_t \nabla v dx
- \int_{\Omega} S(u) |\nabla v|^2 dx .
\end{align*}
Thus, we deduce that
\begin{align}\label{u-f}
\frac{d}{d t} \int_{\Omega} {G}(u) dx
=- \int_{\Omega} S(u) \left|\frac{D(u)}{S(u)}\nabla u -\nabla v\right|^2 d x
+\int_{\Omega} (\nabla z)_t \cdot \nabla v dx.
\end{align}
By the same way, we know that
\begin{align}\label{w-f}
\frac{d}{d t} \int_{\Omega}w \mathrm{ln}w dx
=- \int_{\Omega} w \left|\frac{\nabla w}{w} -\nabla z\right|^2 d x
+\int_{\Omega} \nabla z \cdot (\nabla v)_t dx.
\end{align}
Consequently, by adding (\ref{u-f}) and (\ref{w-f}), we obtain (\ref{f}). For any $\epsilon>0$, we integrate (\ref{f}) over $(\epsilon,t)$. Thanks to Proposition~\ref{local}, we are able to take $\epsilon \rightarrow 0$ and deduce (\ref{f-inter}). 
\end{proof}
By employing the fact that the Lyapunov functional is nonincreasing along trajectories, we first obtain the boundedness of $\|u\|_{L^{p-q+2}(\Omega)}$ when $q-p<2-\frac{n}{2}$.
\begin{lem}
Let $n \geq 3$. Assume that $D(s)$ and $S(s)$ satisfy $(\ref{eq1.2})$ as well as $(\ref{D-g})$ and $(\ref{S-g})$ with some $K_D, K_S>0$ and $p,q\in \mathbb{R}$ fulfilling 
\begin{align*}
q-p<2-\frac{n}{2}.
\end{align*}
Then, for any $(u_0,v_0,w_0,z_0)$ satisfying $(\ref{eq1.1})$, $(\ref{v0})$ and $(\ref{z0})$, there exists a positive constant $C$, independent of $t$, such that
\begin{align}\label{up-q+2}
 \int_{\Omega} (1+u)^{p-q+2} d x \leq C ,
 \quad t\in (0,T_{\max}).
\end{align}
\end{lem}
\begin{proof}
According to (\ref{f-inter}) and $\int_{\Omega} z(\cdot,t) dx=0$, we deduce that
\begin{align}\label{f-in}
\int_{\Omega}{G}(u) d x+\int_{\Omega} w\mathrm{ln}w d x 
& \leq \int_{\Omega} \nabla v \cdot \nabla z dx+\mathcal{F}(0) \nonumber \\ 
& =-\int_{\Omega}(\Delta v) z d x+\mathcal{F}(0) \nonumber \\ 
& =\int_{\Omega} w z d x+\mathcal{F}(0).
\end{align}
It follows from (\ref{D-g}) and (\ref{S-g}) that 
\begin{align*}
{G}(s):=&\int_{s_0}^s \int_{s_0}^\sigma \frac{{D}(\tau)}{S(\tau)} d \tau d \sigma
\geq \frac{K_D}{K_S}\int_{s_0}^s \int_{s_0}^\sigma (1+\tau)^{p-q} d \tau d \sigma \nonumber \\
=&\frac{K_D}{K_S}\Big(\frac{(1+s)^{p-q+2}}{(p-q+1)(p-q+2)}-\frac{(1+s_0)^{p-q+2}}{(p-q+1)(p-q+2)}-\frac{(1+s_0)^{p-q+1}(s-s_0)}{p-q+1}\Big).
\end{align*}
Integrating with respect to $x$ and using $\int_{\Omega}u(\cdot,t) d x=\int_{\Omega}u_0 d x$, along with $q-p<2-\frac{n}{2}<1$ by $n \geq 3$, one can find a positive constant $c_1$ such that
\begin{align*}
\int_{\Omega} (1+u)^{p-q+2} dx
\leq c_1\int_{\Omega}G(u) dx +c_1.
\end{align*}
Substituting this into (\ref{f-in}), there exists a positive constant $c_2$ such that
\begin{align}\label{f-all}
\int_{\Omega} (1+u)^{p-q+2} dx
+c_1 \int_{\Omega} w\mathrm{ln}w d x 
\leq &c_1\int_{\Omega} w z d x+c_2 \nonumber \\
\leq &c_1\| w_0\|_{L^1(\Omega)}\|z\|_{L^{\infty}(\Omega)}+c_2.
\end{align}
For a fixed $b$ satisfying $p-q+2>b>\frac{n}{2}>1$, one can apply standard elliptic regularity theory, Sobolev imbedding theorems and Young's inequality to obtain positive constants $c_3, c_4, c_5>0$ such that
\begin{align}\label{zLinfty}
\|z\|_{L^{\infty}(\Omega)}
\leq c_3\|z\|_{W^{2,b}(\Omega)}
 \leq c_4 \|u\|_{L^{b}(\Omega)} 
\leq \frac{1}{2c_1\| w_0\|_{L^1(\Omega)}}\int_{\Omega} (1+u)^{p-q+2} dx +c_5.
\end{align}
Inserting (\ref{zLinfty}) into (\ref{f-all}), along with $x\mathrm{ln}x \geq -\frac{1}{e} $ for all $x>0$, we complete our proof.
\end{proof}
\begin{lem}
Let $n \geq 3$. Assume that $D(s)$ and $S(s)$ satisfy $(\ref{eq1.2})$ as well as $(\ref{D-g})$ and $(\ref{S-g})$ with some $K_D, K_S>0$ and $p,q\in \mathbb{R}$ fulfilling 
\begin{align}\label{pq-all-1}
q-p<2-\frac{n}{2}.
\end{align}
Then for all $k_1, k_2 \in(1,\infty)$, there exists a positive constant $C(k_1,k_2)$, independent of $t$, such that
\begin{align}\label{uw-bounded}
 \|u(\cdot, t)\|_{L^{k_1}\left(\Omega \right)}+\ \|w(\cdot, t)\|_{L^{k_2}\left(\Omega \right)} \leq C(k_1,k_2), 
 \quad t\in (0,T_{\max}).
\end{align}
\end{lem}
\begin{proof}
We first claim that, for any
\begin{align*}
k_1>\max\Big\{1,\frac{(1+\frac{2}{n})(p-q+2)+p}{\frac{2}{n}(p-q+2)+p-q+1}-\frac{2}{n}\Big\},
\end{align*}
we can choose 
\begin{align}\label{k2}
k_2 \in \Big(&\max\big\{p-q+2,\frac{n}{2}\big(k_1+\frac{2}{n}\big)-\frac{2}{n}(p-q+2)-p\big\}, \\ \notag
&\big(\frac{2}{n}(p-q+2)+p-q+1\big)\big(k_1+\frac{2}{n}\big)-\frac{2}{n}(p-q+2)-p\Big).
\end{align}
Owing to (\ref{pq-all-1}), we infer that 
\begin{align*}
\frac{2}{n}(p-q+2)+p-q+1>\frac{2}{n}\cdot \frac{n}{2}+\frac{n}{2}-1=\frac{n}{2}.
\end{align*}
Then, for any $k_1>1$, we have
\begin{align}\label{k2-1}
&\frac{n}{2}\big(k_1+\frac{2}{n}\big)-\frac{2}{n}(p-q+2)-p \notag\\ 
<&\Big(\frac{2}{n}(p-q+2)+p-q+1\Big)\big(k_1+\frac{2}{n}\big)-\frac{2}{n}(p-q+2)-p.
\end{align}
Thanks to $k_1>\frac{(1+\frac{2}{n})(p-q+2)+p}{\frac{2}{n}(p-q+2)+p-q+1}-\frac{2}{n}$, we know that
\begin{align*}
p-q+2<\Big(\frac{2}{n}(p-q+2)+p-q+1\Big)\big(k_1+\frac{2}{n}\big)-\frac{2}{n}(p-q+2)-p.
\end{align*}
Combining this with (\ref{k2-1}) guarantees the existence of $k_2$.

