Notice that in the previous result we dropped out any stability assumption on $\Lambda$. In particular, Theorem \ref{mainA} is a direct improvement of \cite[Corollary E]{PYY}. Also, an implicit fact behind the statement of Theorem \ref{mainA} is that any non-trivial sectional-hyperbolic chain-recurrent set within \(\mathcal{R}\) must contain periodic orbits; in other words, sectional-hyperbolicity is enough to rule out the existence of aperiodic classes.

\begin{mainthm}\label{conj1.2}
 Let $M$ be an $n$-dimensional manifold with $n\geq 4$. There exists a 
 $C^1$-generic set $\mathcal{R}\subset \mathcal{X}_*^1(M)$ such that for every 
 $X\in \mathcal{R}$ and every non-trivial chain-recurrent class $\Lambda$ of $X$, 
 the set $\Lambda$ has positive topological entropy, contains a periodic orbit, 
 and is isolated. Consequently, $C^1$-generic singular star flows have only finitely 
 many chain-recurrent classes, all of which are either trivial or homoclinic classes of hyperbolic periodic orbits. 
\end{mainthm}

\begin{theorem}\label{Teohtop}
There exists a $C^1$-generic set $\mathcal{R}\subset \mathcal{X}^1(M)$ such that if $\Lambda$ is a non-trivial sectional-hyperbolic chain-recurrent class then it is robustly periodic, that is, there is an open neighborhood $\mathcal{U}$ of $X$ such that for every $Y\in \mathcal{U}$, one has $Per(Y|_{\Lambda_Y})\neq\emptyset$, where $\Lambda_Y$ denotes the continuation of the chain recurrent class $\Lambda$ for $X$. 
\end{theorem}

We now present the following lemma, which will be used to prove Theorem \ref{Teohtop}.
\begin{lemma}\label{prop2.4CY}
Let $\mathcal{R}$ be the residual set of Lemma \ref{lemm: genericsets}. Let $X\in \mathcal{R}$, $\sigma_X\in Sing(X)$ and $C(\sigma)$ be a non-trivial sectional-hyperbolic chain-recurrent class. There is a neighborhood $\mathcal{U}_0\subset\mathcal{U}_X$ of $X$ such that for every $Y\in \mathcal{U}_0$, the continuation $C(\sigma_Y)$ is sectional-hyperbolic. 
\end{lemma}
\begin{proof}
 Let $X\in \mathcal{R}$ and $\Lambda$ a non-trivial sectional-hyperbolic class of $X$. Recall that sectional-hyperbolicity is a robust property, i.e., there are neighborhoods $U$ of $\Lambda$ and $\mathcal{U}'_X$ of $X$ such that for every $Y\in \mathcal{U}'_X$ the set $\cap_{t\in\R}Y_t(U)$ is sectional-hyperbolic. Let $\mathcal{U}_X$ be given by item 3 of Lemma \ref{lemm: genericsets}. Denote $\mathcal{U}_0=\mathcal{U}_X\cap\mathcal{U}'_X$. Since the map $Y\in \mathcal{U}_X\to C(\sigma)$ is continuous, after possibly shrinking $\mathcal{U}_X$, we can assume $C(\sigma_Y)\subset U$. Therefore, $C(\sigma_Y)$ is contained in the maximal invariant set of $U$ under $Y$. In particular, $C(\sigma_Y)$ is sectional-hyperbolic. 
\end{proof}

\begin{lemma}\label{thm: homoclinicclass}
 If $X\in \mathcal{R}$ and $\Lambda\subset M$ is a non-trivial sectional-hyperbolic chain-recurrent class, then it is a homoclinic class.
\end{lemma}

On the other hand, by \cite[Theorem A]{PYY2}, there is a residual subset $\mathcal{S}'\subset\mathcal{X}^1_*(M)$ such that for any $Y\in \mathcal{S}'$ and $\Lambda$ is a non-trivial chain-recurrent class, one of the following holds:
\begin{enumerate}
 \item $h_{top}(X|_{\Lambda})>0$, $\Lambda$ contains a periodic orbit and is isolated; or 
 \item $h_{top}(\Lambda)=0$ and $\Lambda$ is sectional-hyperbolic aperiodic class.
\end{enumerate}
 By setting $\mathcal{S}=\mathcal{R}'\cap\mathcal{S}'$, any non-trivial sectional-hyperbolic chain-recurrent class for $Y\in \mathcal{S}$ contains a periodic orbit by Theorem \ref{mainA}. Hence, option 2 cannot occur, and the proof is complete.
\end{proof}

\begin{lemma}[Hyperbolic Lemma]\label{hyplemma}
Every compact invariant set without singularities contained in a sectional-hyperbolic set is hyperbolic of saddle type. 
\end{lemma}

\begin{mainthm}\label{mainA}
There exists a $C^1$-generic set $\mathcal{R}\subset \mathcal{X}^1(M)$ such that if $\Lambda$ is a non-trivial sectional-hyperbolic chain-recurrent class, then it is robustly a homoclinic class. 
\end{mainthm}

