    \item $Z_i$ is not measurably isomorphic to $X_i$ for all $j+1 \leq i \leq k$
    \item $X_i$ is topologically isomorphic to $X_{i+1}$ for all $i \geq \ell$.

\end{enumerate}
Furthermore, for every minimal, ergodic, and non-weak mixing $(X,\mu,T)$ there exist $j,\ell$, and $k$, such that $X$ satisfies properties (1)-(4).,

ref_dict.remark12:
\begin{remark}\label{remark12}
Although the growth rate of $\int_0^x |V(t)|dt$ may seem like a power law condition on $V$, we note that it is controlled by $L^p$ and amalgamated $L^p$ conditions and their weak counterparts. For any $p \in (1,\infty)$:
\begin{enumerate}
\item[(a)] If $V \in L^p((0,\infty))$ or $V \in \ell^p(L^1)$, then
\begin{equation}\label{eqnConditionp}
\int_0^x \lvert V(t) \rvert\,dt = o(x^{1-1/p}), \quad x\to\infty.
\end{equation}
\item[(b)] If $V \in L^p_w((0,\infty))$ or $V \in \ell^p_w(L^1)$, then
\begin{equation}\label{eqnWeakCondition}
\int_0^x \lvert V(t) \rvert dt = O(x^{1-1/p}), \quad x \to \infty.
\end{equation}
\end{enumerate}
\end{remark}

