  \end{thm}

ref_dict.def : Serre tiltings:
\begin{deftn} \label{def : Serre tiltings}
 Given any indecomposable object $(X,h)$ in $\tMQ$ and any \textit{finite} subset $Y = \{ y_1 , \ldots  , y_r\} \subseteq X$, we define the \textbf{Serre tilting} of $(X,h)$ at $Y$ as the object of $\tMQ$ given by  
 $$ \mu_Y(X,h) := \left(  (X \setminus Y) \sqcup SY \enspace , \enspace  h - \sum_{y \in Y} \delta_y \right) $$
 where $SY$ stands for $SY := \{S y_1, \ldots , S y_r\}$.  For simplicity we will write $\mu_y(X)$ for $\mu_{\{y \}}(X)$.
   \end{deftn}

ref_dict.def : quasi-additive functions:
\begin{deftn} \label{def : quasi-additive functions}
     A function $f : \ZQz \longrightarrow \mathbb{Z}$ will be called quasi-additive if $\widetilde{f}$ has finite support, i.e. $\widetilde{f}(x)=0$ on all but finitely many vertices of $\ZQ$.
   \end{deftn}

ref_dict.def : strong exactness:
\begin{deftn} \label{def : strong exactness}
     Let $C_{\bullet}$ be a chain complex in $\KQ^{(1)}$.  We say that $C_{\bullet}$ is strongly $\HQ^{(1)}$-exact if $C_{\bullet}$ is $\HQ^{(1)}$-exact and moreover all the non-trivial components of each differential of $C_{\bullet}$ are of the form $\eta_i \otimes \mathrm{id}$ for some $i \in \mathrm{Supp}(C_0)$. 

   \end{deftn}

