 v_{t} - u_x=0, \\
 u_{t} + p_x=0, \\ 
 (C_v\theta+\frac{1}{2} u^2 )_{t} + (pu)_x=0,
 \end{cases}
 \end{equation}
 with initial data
 \begin{align}\label{1.6}
 (u,v,\theta)(0,x) = (u_{0}^{r}, v_{0}^{r}, \theta_{0}^{r})(x) = \begin{cases} 
 (u_{-},v_{-},\theta_{-}), & x<0, \\ 
 (u_{+},v_{+},\theta_{+}), & x > 0. \\ 
 \end{cases}
 \end{align}

We note that substantial evidence indicates that the long-time behavior of the Cauchy problem for the classical compressible Navier-Stokes-Fourier system \eqref{1.1}-\eqref{Newton} is governed by the solution to the Riemann problem \eqref{1.5}-\eqref{1.6}; see, for example, \cite{KVW25}. In particular, Matsumura and Nishihara \cite{MN86,MN92} were the first to establish the asymptotic stability of rarefaction waves for the isentropic Navier-Stokes system, while the full system was later treated in \cite{KMN, LX88, NYZ04}, where analogous results were obtained. The half-space problem was investigated by Kawashima and Zhu in \cite{KZ09}. Moreover, the asymptotic stability of composite waves-combining rarefaction waves, traveling waves, and viscous contact waves-has also been extensively investigated in \cite{Goodman86,HH12,HLM10,Kanel68,Liu86,SX93}.

For reader's convenience, we first recall the rarefaction wave solution to the Riemann problem \eqref{1.5}-\eqref{1.6}. For any $(v_{+}, u_{+}, \theta_{+}) \in \mathbb{R}_{+} \times \mathbb{R}\times\mathbb{R}_{+}$, the 1-rarefaction curve $R_{1}(u_{+},v_{+},\theta_{+})$ is defined as:
 \[
 R_1(v_+, u_+, \theta_+) := \left\{(v, u, \theta) \ \middle| \ 
 \begin{aligned}
 v < v_{+}, 
 s(v, \theta) = s(v_{+}, \theta_{+}) =:s_{+}, 
 u = u_{+} - \int_{v_{+}}^{v} \lambda_{1}(s_{+},v') dv'
 \end{aligned}
 \right\}
 \]
 where the entropy function 
 \[
 s(v, \theta) = \dfrac{R}{\gamma-1} \ln\left(\dfrac{R}{A} \theta v^{\gamma-1}\right)
 \] and $\lambda_{1}(s,v)=-\sqrt{\frac{\gamma p(v,s)}{v}}$ is the first eigenvalue of the matrix
 \[
 A(U) = \begin{pmatrix}
 0 & -1 & 0 \\
 -\dfrac{p}{v} & -\dfrac{(\gamma-1)u}{v} & \dfrac{\gamma-1}{v} \\
 -\dfrac{pu}{v} & p - \dfrac{(\gamma-1)u^2}{v} & \dfrac{(\gamma-1)u}{v}
 \end{pmatrix}.
 \]
 If $(v_-, u_-, \theta_-)\in R_1(v_+, u_+, \theta_+)$, then Riemann problem \eqref{1.5}-\eqref{1.6} admits a continuous weak solution of the form $(v^r, u^r, \theta^r)(x/t)$ which is called centered rarefaction wave defined as
 \begin{equation}\label{1.7}
 \lambda_1(v^r(t,x), \theta^r(t,x)) = 
 \begin{cases} 
 \lambda_1(v_-, \theta_-), & x < \lambda_1(v_-, \theta_-)t, \\ 
 \dfrac{x}{t}, & \lambda_1(v_-, \theta_-)t \leq x \leq \lambda_1(v_+, \theta_+)t, \\ 
 \lambda_1(v_+, \theta_+), & x > \lambda_1(v_+, \theta_+)t, 
 \end{cases} 
 \end{equation}
 and
 \begin{equation}\label{1.8}
 \begin{aligned}
 z_{1}(u^{r}(t,x),v^{r}(t,x)) &= z_{1}(u_{-}, v_{-}) = z_{1}(u_{+}, v_{+}),\\
 s(v^{r}(t,x),\theta^{r}(t,x)) &= s(v_{-},\theta_{-}) = s(v_{+},\theta_{+}),
 \end{aligned}
 \end{equation}
 where $z_{1}(u,v)=u+\int_{v_{+}}^{v}\lambda_{1}(s, v^{\prime})dv^{\prime}$. 3-rarefaction curve $R_{3}$ can be defined via the characteristic speed $\lambda_{3}:=-\lambda_1$ in a similar way.

Before we state the main theorem, we introduce the following noations. Let $L^p(\mathbb{R})$ and $W^{s,p}(\mathbb{R})$ (for $1 \le p \le \infty$) denote the usual Lebesgue and Sobolev spaces on $\mathbb{R}$, equipped with the norms $\|\cdot\|_{L^p}$ and $\|\cdot\|_{W^{s,p}}$, respectively. Note that $W^{0,p}(\mathbb{R}) = L^p(\mathbb{R})$. As usual, we write $H^s(\mathbb{R})$ for $W^{s,2}(\mathbb{R})$. Let $T > 0$ be a constant and $B$ be a Banach space. We denote by $C^k(0, T; B)$ ($k \ge 0$) the space of $B$-valued, $k$-times continuously differentiable functions on $[0, T]$, and by $L^p(0, T; B)$ the space of $B$-valued $L^p$-functions on $[0, T]$. The corresponding spaces of $B$-valued functions on $[0, \infty)$ are defined similarly.

Now, Let 
 \[
 I_0:= \|(v_0- v_0^r, u_0-u_0^r, \theta_0-\theta_0^r)\|_{L^2}+\|((v_0)_x, (u_0)_x, (\theta_0)_x)\|_{H^1}+\|(q_0, S_0)\|_{H^2}.
 \]
 Our main result is stated as follows.

Before we state the main theorem, we introduce the following noations. Let $L^p(\mathbb{R})$ and $W^{s,p}(\mathbb{R})$ (for $1 \le p \le \infty$) denote the usual Lebesgue and Sobolev spaces on $\mathbb{R}$, equipped with the norms $\|\cdot\|_{L^p}$ and $\|\cdot\|_{W^{s,p}}$, respectively. Note that $W^{0,p}(\mathbb{R}) = L^p(\mathbb{R})$. As usual, we write $H^s(\mathbb{R})$ for $W^{s,2}(\mathbb{R})$. Let $T > 0$ be a constant and $B$ be a Banach space. We denote by $C^k(0, T; B)$ ($k \ge 0$) the space of $B$-valued, $k$-times continuously differentiable functions on $[0, T]$, and by $L^p(0, T; B)$ the space of $B$-valued $L^p$-functions on $[0, T]$. The corresponding spaces of $B$-valued functions on $[0, \infty)$ are defined similarly.

Now, we outline the proof strategy for the main theorem. First, within a relative entropy framework centered around a smooth approximate rarefaction wave, we establish the key $L^2$ estimates by leveraging the inherent thermodynamic structure of the system. In addition to the standard $L^2$ estimates, we obtain an extra weighted dissipation term arising from the gradient of the rarefaction wave. This term plays a decisive role in closing the a priori estimates and in establishing the global stability of the rarefaction wave. Next, we derive $H^2$ estimates and dissipation estimates via the conventional energy method. Finally, combining these a priori estimates with the local existence theorem yields the desired result.

The corresponding Euler system associated with the smooth rarefaction wave solution reads as follows
 \begin{equation}\label{3.9}
 \begin{cases}
 v^{R}_{t}-u^{R}_{x}=0,\\
 u^{R}_{t}+p(v^{R},\theta^{R})_{x}=0,\\
 \frac{R}{\gamma-1}\theta^{R}_{t}+p(v^{R},\theta^{R})u^{R}_{x}+q_{x}^{R}=0,\\
 v^Rq^R+\kappa\theta^R_{x}=0,\\
 v^RS^R=\mu u^R_{x}.
 \end{cases}
 \end{equation}
 Subtracting equation \eqref{3.9} from equation \eqref{1.3}, and introducing the following perturbation variables
 \begin{align*}
 \varphi=v-v^R,\quad\psi=u-u^R,\quad\tilde{\theta}=\theta-\theta^R,\quad\tilde{q}=q-q^R,\quad\tilde{S}=S-S^R,
 \end{align*} we obtain
 \begin{equation}\label{3.10}
 \begin{cases}
 \varphi_t - \psi_x = 0, \\
 \psi_t + (p-p^{R})_x = \tilde{S}_x-Q_{1}^{R},\\
 \frac{R}{\gamma-1}\tilde{\theta}_{t}+a^{\prime}(\theta)
 q^{2}\theta_{t} -\frac{2a(\theta)\kappa}{\tau_{1}}\theta_{x}q+
 pu_x-p^{R}u_x^{R}+\tilde{q}_x=\frac{2a(\theta)v}{\tau_{1}}q^2+\frac{v}{\mu} S^2-Q_{2}^{R},\\
 \tau_1\tilde{q}_t + vq-v^{R}q^{R} + \kappa\tilde{\theta}_x = - \tau_1q^R_t, \\
 \tau_2 \tilde{S}_t + vS-v^{R}S^{R} = \mu \psi_x-\tau_2 S^R_t,
 \end{cases}
 \end{equation}
 where $Q_{1}^{R}=-\mu(\frac{u_{x}^{R}}{v^{R}})_{x}$, $Q_{2}^{R}=-\kappa(\frac{\theta_{x}^{R}}{v^{R}})_{x}$. Initial condition
 \begin{align}\label{y3.11}
 (\varphi,\psi,\tilde{\theta},\tilde{q},\tilde{S})(x,0)=(\varphi_{0},\psi_{0},\tilde{\theta}_{0},\tilde{q}_{0},\tilde{S}_{0})(x),\quad x\in\mathbb{R},
 \end{align}
 where
 \begin{align*}
 \varphi_{0}=v_{0}-v^R_{0},\quad\psi_{0}=u_{0}-u^R_{0},\quad\tilde{\theta}_{0}=\theta_{0}-\theta^R_{0},\quad\tilde{q}_{0}=q_{0}-q^R_{0},\quad\tilde{S}_{0}=S_{0}-S^R_{0}.
 \end{align*}
 For the reformulated system \eqref{3.10}-\eqref{y3.11}, we establish the following results on global existence and asymptotic stability.
 \begin{theorem}\label{thm3.1}
 Let $(v_-,u_-,\theta_-)\in R_1(v_+,u_+,\theta_+)$ and $\delta=|v_+-v_-|+|u_+-u_-|+|\theta_+-\theta_-|$. Assume the initial data $(\varphi_0,\psi_0,\tilde{\theta}_0,\tilde{q}_0,\tilde{S}_0)\in H^2$ and let $E_0:=\|(\varphi_0,\psi_0,\tilde{\theta}_0,\tilde{q}_0,\tilde{S}_0)\|_{H^2}^2$. Then, there exists a positive constant $\delta_1$ such that if $E_0+\delta<\delta_1$, the initial value problem \eqref{3.10}-\eqref{y3.11} has a unique global solution in time satisfying
 \begin{align}\label{3-4}
 &(\varphi,\psi,\tilde{\theta},\tilde{q},\tilde{S})(t,x)\in C^0(0,+\infty,H^2),\\
 \label{3-5}&(\varphi_x,\psi_x)(t,x)\in L^2(0,+\infty,H^1),\quad(\tilde{\theta}_x,\tilde{q}_x,\tilde{S}_x)\in L^2(0,+\infty,H^2).
 \end{align}
 Moreover, this solution decay to $(0,0,0)$ uniformly in $x$ as $t\rightarrow \infty$:
 \begin{align*}
 \|(\varphi,\psi,\tilde{\theta},\tilde{q},\tilde{S})\|_{W^{1,\infty}}\rightarrow 0,\quad as \quad t\rightarrow \infty.
 \end{align*}
 \end{theorem}

Since $\mathcal{D}(t)$ is integrable in time, we have
 $(\phi_x,\psi_x,\tilde\theta_x)\in L^2(0,\infty;H^1)$
 and $(\tilde q,\tilde S)\in L^2(0,\infty;H^2)$.
 Together with the uniform bound $E(t)\le C$ and the Sobolev interpolation inequality, we have
 \[
 \|(\phi,\psi,\tilde\theta,\tilde q,\tilde S)(t)\|_{L^\infty}
 \le C\|(\phi,\psi,\tilde\theta,\tilde q,\tilde S)(t)\|_{L^2}^{1/2}\|(\phi_x,\psi_x,\tilde\theta_x,\tilde q_x, \tilde S_x)(t)\|_{L^2}^{1/2},
 \]
 \[
 \|(\phi_x,\psi_x,\tilde\theta_x,\tilde q_x, \tilde S_x)(t)\|_{L^\infty}
 \le C\|(\phi_x,\psi_x,\tilde\theta_x,\tilde q_x, \tilde S_x)(t)\|_{L^2}^{1/2}\|(\phi_{xx},\psi_{xx},\tilde\theta_{xx},\tilde q_{xx}, \tilde S_{xx})(t)\|_{L^2}^{1/2},
 \]
 this yields
 \begin{align}\label{y3.6}
 \|(\phi,\psi,\tilde\theta,\tilde q,\tilde S)(t)\|_{W^{1,\infty}}\to0
 \quad\text{as }t\to\infty.
 \end{align}
 Thus, the proof of the global existence and asymptotic stability is completed.
 \end{proof}
 Finally, applying Theorem \ref{thm3.1}, we conclude the proof of Theorem \ref{th1.1}.
 \begin{proof}[Proof of Theorem \ref{th1.1}] 
 Let $I_0+\delta$ is suitable small where
 \begin{align*}
 I_0 = \| (v_0 - v_0^r, u_0 - u_0^r) \|_{L^2} + \| ((v_0)_x, (u_0)_x) \|_{H^1} + \|(\tilde\theta_0,\tilde q_0,\tilde{S}_0)\|_{H^2}.
 \end{align*}
 Then, we have
 \[
 \|(\varphi_0, \psi_0)\|_{L^2} \le \|(v_0 - v_0^r, u_0 - u_0^r)\|_{L^2} + \|(v_0^r - v^R_0, u_0^r - u^R_0)\|_{L^2} \le I_0 + C\delta,
 \]
 and
 \begin{align*}
 &\|\partial_x(\varphi_0, \psi_0)\|_{H^1} + \|(\tilde\theta_0,\tilde q_0,\tilde S_0)\|_{H^2} \\
 \le& \|\partial_x(v_0, u_0)\|_{H^1} + \|(\theta_{0}, q_0, {S}_0)\|_{H^2} + \|\partial_x(v^R_0, u^R_0)\|_{H^1} 
 + \|(\theta^{R}_0, q^R_0, S^R_0)\|_{H^2} 
 \le I_0 + C\delta.
 \end{align*}
 Hence, $E_0 + \delta \le I_0 + C\delta$, which can be made sufficiently small. 
 Applying Theorem \ref{thm3.1}, we obtain a unique global solution $(\varphi, \psi, \tilde\theta, \tilde{q}, \tilde S)$ to problem \eqref{3.10}-\eqref{y3.11}. 
 Define 
 \[
 (v,u,\theta, q, S) = (\varphi + v^R, \psi + u^R, \tilde\theta+\theta_{R}, \tilde q+q^R, \tilde S + S^R)
 \]
 which solves the original system \eqref{1.3}-\eqref{1.4}. 
 To verify the convergence in (\ref{2.2}), observe that
 \[
 \|(v - v^r, u - u^r, \theta, q, S)\|_{L^\infty} 
 \le \|(\varphi, \psi, \tilde{\theta}, \tilde{q}, \tilde{S})\|_{L^\infty} + \|(v^R - v^r, u^R - u^r, \theta^{R}, q^R, S^R)\|_{L^\infty} \to 0 
 \]
 as $t \to +\infty$, where we have used the convergence result (\ref{y3.6}) and Lemma \ref{lem2.1}. 
 This completes the proof of Theorem \ref{th1.1}.
 \end{proof}

