A proof sketch to establish the main theorem is outlined under \textbf{Main ideas}:

- \emph{Strategy: bootstrap regularity.} The approach is to "improve the regularity of
\begin{equation}\label{1.4}
\left\{
\begin{aligned}
&u_{t}=\nabla \cdot (uv\nabla u)-\chi \nabla \cdot (u^{\alpha}v\nabla v)+\ell uv,&x\in \Omega,\, t>0,\\
& v_{t}=\Delta v-uv,&x\in \Omega,\, t>0,\\
&(uv\nabla u-\chi u^{\alpha}v\nabla v)\cdot \nu=\nabla v\cdot \nu=0,&x\in \partial\Omega,\, t>0,\\
&u(x,0)=u_0(x), v(x,0)=v_0(x), &x\in \Omega,
\end{aligned}
\right.
\end{equation}
 via the bootstrap argument", with the "most crucial step" being to obtain "global boundedness of $\|u(\cdot,t)\|_{L^{p_0}(\Omega)}$ for some $p_0>\frac{3}{2}$."

- \emph{Exploit diffusion-induced dissipation to control bad terms.} One "appropriately utilize[s] the diffusion-induced contributions of the form $\int_{\Omega}u^{k}v|\nabla u|^2$ (for suitable $k$) to counteract" "unfavorable terms" like $\int_{\Omega}u^{\beta}v$.

- \emph{Initial dissipated quantities from time-evolution identities.} As a starting point, they show that
  \(\int_{\Omega}u^{1-\alpha}v|\nabla u|^2\) and \(\int_{\Omega}u\frac{|\nabla v|^{2}}{v}\) are dissipated "by tracking the time evolution of $\int_{\Omega}u^{2-\alpha}$ and ${F}(t):=a\int_{\Omega} \frac{|\nabla v(\cdot,t)|^2}{v(\cdot,t)}-\int_{\Omega}\ln{u(\cdot,t)}$".

- \emph{Interpolation plus dissipation gives key spacetime control.} Bounds for quantities such as
  \begin{align}\label{1.14}
        \int_0^{T}\int_\Omega u^{\frac{5}{3}}v
        \end{align}
  are derived "to make use of the aforementioned dissipation terms and an interpolation inequality".

- \emph{Energy functional $\mathcal G$ yields further dissipation.} Using the preceding spacetime bound, they control terms arising from the evolution of
  \(\mathcal{ G}(t):=\int_{\Omega}u\ln{u}+b\int_{\Omega}\frac{|\nabla v|^4}{v^3}\), deriving dissipation of
  \begin{align}\label{1.15}
            \int_{\Omega}u^{p_*}v|\nabla u|^2  \quad \text{and}\quad  \int_{\Omega}u\frac{|\nabla v|^4}{v^3}
        \end{align}
  for all $p_*\in[1-\alpha,0]$.

- \emph{A key inequality controls $\int \varphi^{\beta}\psi$ by dissipations.} A "novel observation" is the inequality
  \begin{align}\label{1.16}
             \int_{\Omega}\varphi^{\beta}\psi\leq  \int_{\Omega}\varphi^{k}\psi|\nabla \varphi|^2+\int_{\Omega}\varphi\frac{|\nabla \psi|^4}{\psi^3}+C(L,k, \beta)\int_{\Omega}\varphi \psi
         \end{align}
  which, "thanks to the estimates in the lemma above", is used to get the desired $L^{p_0}$ bounds for $u$.

- \emph{From improved integrability to uniform $L^p$ bounds.} The $L^{p_0}$ control allows a "refined version of the key inequality above" and an energy-like property for
  \(\mathcal H(t):=\int_{\Omega}\frac{|\nabla v|^q}{v^{q-1}}+\int_{\Omega}u^{p}\), for any fixed $p>1$, which "yields the bounds for $\|u(\cdot,t)\|_{L^{p}(\Omega)}$" (leading to estimates like \eqref{1.9}).

- \emph{Conclusion via compactness from regularized problems.} Finally, "building upon these estimates and further higher regularity properties of the regularized systems", they "prove the main theorem via compactness arguments", producing a global weak solution with the asserted bounds.

expanded_theorem:
\label{Th1.1}
Let $\Omega \subset \mathbb R^3$ be a bounded domain with smooth boundary, and suppose that $\alpha \in \left( \frac{3}{2}, \frac{19}{12} \right)$ as well as
$\chi >0$ and $\ell>0$. Then for all $p>1$, one can find $C=C(p,K)>0$ with the property that whenever $u_0$ and $v_0$ fulfill
\begin{equation}\label{1.5}
\left\{
\begin{aligned}
&u_0\in W^{1,\infty}(\Omega)\; \hbox{is  such  that}\; u_0\geq 0\; \hbox{and}\; u_0\not\equiv0, \quad \text{and} \\
&v_0\in W^{1,\infty}(\Omega)\; \hbox{is  such  that}\; v_0>0\,\, \text{in} \,\,\Omega\\
\end{aligned}
\right.
\end{equation}
and
\begin{align}\label{1.6}
    \|u_0\|_{L^{\infty}(\Omega)}+\|v_0\|_{L^{\infty}(\Omega)}+\|\nabla \ln v_0\|_{L^{\infty}(\Omega)}\leq K\quad \text{and}\quad \int_{\Omega}\ln{u_0}\geq -K
\end{align}
there exist
\begin{equation}\label{1.8}
\left\{
\begin{aligned}
&u\in C^{0}_{loc}(\overline{\Omega}\times [0,\infty))\cap L^{\infty}_{loc}(\overline{\Omega}\times [0,\infty)) \quad \text{and} \\
&v\in C^{0}_{loc}(\overline{\Omega}\times [0,\infty))\cap C^{2,1}_{loc}(\overline{\Omega}\times (0,\infty))\cap L^{\infty}_{loc}([0,\infty);W^{1,\infty}(\Omega))\\
\end{aligned}
\right.
\end{equation}
such that  $u\geq 0$ and $v>0$ a.e. in $\Omega\times(0,\infty)$, and that
$(u,v)$ forms a continuous global weak solution of
\begin{equation}\label{1.4}
\left\{
\begin{aligned}
&u_{t}=\nabla \cdot (uv\nabla u)-\chi \nabla \cdot (u^{\alpha}v\nabla v)+\ell uv,&x\in \Omega,\, t>0,\\
& v_{t}=\Delta v-uv,&x\in \Omega,\, t>0,\\
&(uv\nabla u-\chi u^{\alpha}v\nabla v)\cdot \nu=\nabla v\cdot \nu=0,&x\in \partial\Omega,\, t>0,\\
&u(x,0)=u_0(x), v(x,0)=v_0(x), &x\in \Omega,
\end{aligned}
\right.
\end{equation}
in the following sense. We recall the definition of continuous weak solution:

\begin{definition}\label{Definition 2.1} Assume  that \eqref{1.5} and \eqref{1.6} hold, suppose that $\chi >0$ and $\ell> 0$, and  that $\alpha\geq 1$. Then a pair of nonnegative functions
\begin{equation}\label{2.1}
\left\{
\begin{aligned}
&u\in C^{0}(\overline{\Omega}\times [0,\infty))\quad and \\
&v\in C^{0}(\overline{\Omega}\times [0,\infty))\cap C^{2,1}(\overline{\Omega}\times(0,\infty))\\
\end{aligned}
\right.
\end{equation}
such that
\begin{align}\label{2.2}
  u^2 \in L^{1}_{loc}([0,\infty); W^{1,1}(\Omega))\quad \hbox{and}\quad u^\alpha\nabla v \in L^{1}_{loc}(\overline{\Omega}\times
  [0,\infty);\mathbb{R}^3)
\end{align}
 will be called a continuous weak solution of \eqref{1.4} if
\begin{align}\label{2.3}
    -\int_{0}^{\infty}\!\int_{\Omega}u\varphi_t-\int_{\Omega}u_0\varphi(\cdot,0)=
    &-\frac{1}{2}\int_{0}^{\infty} \!\int_{\Omega}
     v \nabla u^2 \cdot\nabla\varphi      +\chi\int_{0}^{\infty}\!\int_{\Omega}u^{\alpha}v\nabla v\cdot \nabla \varphi
     +\ell\int_{0}^{\infty}\!\int_{\Omega}uv\varphi
\end{align}
for all
 $\varphi \in C_0^{\infty}(\overline{\Omega}\times [0,\infty))$
 fulfilling $\frac{\partial \varphi}{\partial \nu}=0$ on $\partial\Omega\times(0,\infty)$, and if
\begin{align}\label{2.4}
\int_{0}^{\infty}\int_{\Omega}v\varphi_t+\int_{\Omega}v_0\varphi(\cdot,0)=\int_{0}^{\infty}\int_{\Omega}\nabla
v\cdot\nabla\varphi+\int_{0}^{\infty}\int_{\Omega}uv\varphi.
\end{align}
for any $\varphi \in C_0^{\infty}(\overline{\Omega}\times [0,\infty))$.
\end{definition}
Moreover, we have
\begin{align}\label{1.9}
    \|u(\cdot,t)\|_{L^{p}(\Omega)}+\|v(\cdot,t)\|_{W^{1,\infty}(\Omega)}\leq C(p,K)\qquad for \;a.e.\; t>0.
\end{align}

