Suppose that $X=\ell_2(\mathbb{N})$ with orthonormal basis $(e_n)_{n\in\mathbb{N}}$. Suppose that $(\theta_n)_{n\in\mathbb{N}}$ is a decreasing sequence of angles in $]0,\pi/2[$ with $\theta_n\to0$. Consider the collection $\mathcal{L} = \{L_1,L_2\}$ 
of two closed linear subspaces where $L_1:=\cspan\{\cos(\theta_k)e_{2k-1}+\sin(\theta_k)e_{2k}\mid k\in\mathbb{N}\smallsetminus\{0\}\}$ and $L_2:=\cspan\{e_{2k+1}\mid k\in\mathbb{N}\}$. We have
\begin{enumerate}[ref=\currentenv~\theexample(\roman*)]
    \item\label{ex:counterexi} $P_{L_1}x=\sum_{k\in\mathbb{N}\smallsetminus\{0\}}\left(x_{2k-1}\cos(\theta_k)+x_{2k}\sin(\theta_k)\right)\left(e_{2k-1}\cos(\theta_k)+e_{2k}\sin(\theta_k)\right)$.
    \item\label{ex:counterexii} $P_{L_2}x=(0,x_1,0,x_3,0,x_5,\dots)$.
    \item\label{ex:counterexiii} $\mathcal{L}$ is not innately regular.
\end{enumerate}
Set  $x^{(0)}:=\left(0,x_1,0,x_3,0,x_5,\dots\right)\in\ell_2(\mathbb{N})$ and generate the sequence of alternating projections via
\begin{equation}
    x^{(2n+1)} := P_{L_1}x^{(2n)}\text{ and }x^{(2n+2)} := P_{L_2}x^{(2n+1)}.\label{20252610a}
\end{equation}
Then:
\begin{enumerate}[ref=\currentenv~\theexample(\roman*)]
    \setcounter{enumi}{3}
    \item\label{ex:counterexiv} For all $n\in\mathbb{N}\smallsetminus\{0\}$, the iterates have the following form
    \begin{equation}
        \left(\forall k\in\mathbb{N}\smallsetminus\{0\}\right)\quad\begin{cases}
            x^{(2n-1)}_0=0,\\
            x^{(2n-1)}_{2k-1}=x_{2k-1}\cos^{2n}(\theta_{k}),\\
            x^{(2n-1)}_{2k}=x_{2k-1}\cos^{2n-1}(\theta_{k})\sin(\theta_{k}),\label{20252610b}
        \end{cases}
    \end{equation}
    and
    \begin{equation}
        \left(\forall k\in\mathbb{N}\smallsetminus\{0\}\right)\quad\begin{cases}
            x^{(2n)}_{2k-2}=0,\\
            x^{(2n)}_{2k-1}=x_{2k-1}\cos^{2n}(\theta_{k}).\label{20252610c}
        \end{cases}
    \end{equation}
    \item\label{ex:counterexv} For all $n\in\mathbb{N}\smallsetminus\{0\}$: $\norm{x^{(2n)}-x^{(2n-1)}}^2=\sum_{k=1}^\infty x^2_{2k-1}\cos^{4n}(\theta_{k})\left(\cos^{-2}(\theta_{k})-1\right)$.
\end{enumerate}

Let $\theta_0\in\left]0,\pi/2\right[$, $\theta_k:=\arccos\Big(\big(\frac{k}{k+1}\big)^{\frac{1}{4e^k}}\Big)$, and $x_{2k-1}:=\frac{1}{k^2}$ for all $k\in\mathbb{N}\smallsetminus\{0\}$. Then:
\begin{enumerate}[ref=\currentenv~\theexample(\roman*)]
    \setcounter{enumi}{5}
    \item\label{ex:counterexvi} For all $\gamma\in\left]0,2\right[$: $\displaystyle \sum_{n=0}^\infty\norm{x^{(n+1)}-x^{(n)}}^\gamma=+\infty$.
\end{enumerate}
\end{example}

