\begin{theorem}[main result]
\label{t:GTpolyconeinfi} 
Let $\mathcal{C}$ be a nonempty finite collection of 
nonempty polyhedral cones in $X$. 
Let $\lambda\in]0,1]$ and $x^{(0)}\in X$.
Generate a sequence $(x^{(n)})_{\nnn}$ in $X$ as follows:
Given a current term $x^{(n)}$, pick $R_n \in \mathcal{R}_{\mathcal{C},[\lambda,2-\lambda]}$, and update via
\begin{equation}
 x^{(n+1)} := R_n x^{(n)}.
\end{equation}
Then 
\begin{equation}
\sum_{n=0}^\infty \norm{x^{(n+1)}-x^{(n)}}^\gamma <+\infty\quad \text{for all $\gamma>0$.}
\end{equation}
\end{theorem}
\begin{proof}
For each $C\in\mathcal{C}$, we pick
a finite-codimensional closed 
linear subspace $K_C$ of $X$ as in 
\cref{f:thesis}. 
Next, we set $K := \bigcap_{C\in\mathcal{C}} K_C$.
Then $K$ is a closed linear subspace of $X$, still 
finite-codimensional. 
By \cref{f:thesis} again, we have 
\begin{equation}
\label{e:boom}
(\forall C\in\mathcal{C})\quad
P_C = P_K + P_{D_C}P_{K^\perp},
\end{equation}
where $D_C = C \cap K^\perp$ is a nonempty polyhedral subset of 
the finite-dimensional space $K^\perp$. Note that $D_C$ is also a polyhedral cone because the intersection of a polyhedral cone and a finite-codimensional linear subspace is still polyhedral.

{\it(vi)}: From the choice of $x^{(0)}$, $(\theta_k)_{k\in\mathbb{N}}$, and \cref{ex:counterexv}, we obtain
 \begin{equation}
 (\forall n\in\mathbb{N}\smallsetminus\{0\})\quad\norm{x^{(2n)}-x^{(2n-1)}}^2=\sum_{k=1}^\infty\frac{1}{k^4}\Big(\frac{k}{k+1}\Big)^{\frac{n}{e^k}}\bigg(\Big(1+\frac{1}{k}\Big)^{\frac{1}{2e^k}}-1\bigg).\label{20252610d}
 \end{equation}
 Define $\delta_n:=\ln(n)-\lf\ln(n)\rf$ for all $n\geq3$. Observe that the sequence $(\delta_n)_{n\geq3}$ lies in $[0,1[$. Since in \eqref{20252610d} all components of the infinite series are positive, for all \(n \geq3\) we obtain
 \begin{subequations}
 \begin{align}
 \norm{x^{(2n)}-x^{(2n-1)}}^2&\geq\frac{1}{(\ln(n)-\delta_n)^4}\left(\frac{\ln(n)-\delta_n}{\ln(n)-\delta_n+1}\right)^{e^{\delta_n}}\bigg(
 \Big(1+\frac{1}{\ln(n)-\delta_n}\Big)^{\frac{e^{\delta_n}}{2n}}-1\bigg)\\
 &=\frac{1}{(\ln(n)-\delta_n)^4}\left(\frac{\ln(n)-\delta_n}{\ln(n)-\delta_n+1}\right)^{e^{\delta_n}}\left(e^{\frac{e^{\delta_n}}{2n}\ln\left(1+\frac{1}{\ln(n)-\delta_n}\right)}-1\right).
 \end{align}
 \end{subequations}
 Using the inequalities
 \begin{equation}
 (\forall x>0)\quad e^x-1\geq x\quad\text{and}\quad\ln\Big(1+\frac{1}{x}\Big)\geq\frac{1}{x+1},
 \end{equation}
 we get that
 \begin{subequations}
 \begin{align}
 (\forall n\geq 3)\quad
 &\norm{x^{(2n)}-x^{(2n-1)}}^2\\ &\geq\frac{1}{(\ln(n)-\delta_n)^4}\left(\frac{\ln(n)-\delta_n}{\ln(n)-\delta_n+1}\right)^{e^{\delta_n}}\frac{e^{\delta_n}}{2n}\frac{1}{\ln(n)-\delta_n+1}\\
 &=\frac{e^{\delta_n}}{2n(\ln(n)-\delta_n)^{4-e^{\delta_n}}(\ln(n)-\delta_n+1)^{1+e^{\delta_n}}}\\
 \ &\geq\frac{1}{2n\left(\ln(n)+1\right)^5}, 
 \end{align}
 \end{subequations}
 where the last inequality follows from 
 $0<\ln(n)-\delta_n<\ln(n)+1$. 
 This implies
 \begin{equation}
 \sum_{n=0}^\infty\norm{x^{(n+1)}-x^{(n)}}^\gamma\geq\sum_{n=3}^\infty\norm{x^{(2n)}-x^{(2n-1)}}^\gamma\geq\sum_{n=3}^\infty\frac{1}{(2n)^{\frac{\gamma}{2}}(\ln(n)+1)^{\frac{5\gamma}{2}}}.
 \end{equation}
 Since $\tfrac{(2n)^{\gamma/2}(\ln(n)+1)^{5\gamma/2}}{n^{\gamma/2}\ln^{5\gamma/2}(n)}\to2^{\gamma/2}$, $\gamma\in]0,2[$, and $\sum_{n\geq3}\tfrac{1}{n^p\ln^q(n)}=+\infty$ for all $p\in\left]0,1\right[$ and $q>0$ (see \cite[80--Theorem, Page~124]{Konrad}), we are done.
\end{proof}

We are now ready to announce our counterexample:
\begin{example}[G\"unt\"urk-Thao fails for a line and a
convex set in $\RR^2$]
\label{e:notcone}
 Let $\beta\in \mathbb{R}_{++}$ and 
 $r\in \{2,4,6,8,\ldots\}$. 
 Consider the function $f(x)=\exp(-\beta x^{-r})$ with domain $\bigl[-\left(\beta r/(r+1)\right)^{1/r},\left(\beta r/(r+1)\right)^{1/r}\bigr]$. 
 The derivative of $f$ is 
 \begin{equation}
 f'(x)=\beta rx^{-r-1}\exp(-\beta x^{-r}).
 \end{equation}
 Observe that the assumption of \cref{p:R2sequence2} is satisfied with $q=-r-1$, $\alpha=2\beta$, $p=r$, and $c_{q,\alpha,p}=r\beta$. Hence, we obtain
 \begin{equation}
 1=\lim_{n\to\infty}\frac{u_n}{\left(\frac{\alpha}{\ln(n)}\right)^{1/p}}=\lim_{n\to\infty}\frac{u_n}{\left(\frac{2\beta}{\ln(n)}\right)^{1/r}},
 \end{equation}
 which implies
 \begin{equation}
 (\forall\varepsilon>0)(\exists m_\varepsilon\in\mathbb{N})(\forall n\geq m_\varepsilon)\quad u_n\geq\left(\left(1-\frac{\varepsilon}{2}\right)\left(\frac{2\beta}{\ln(n)}\right)\right)^{1/r}.\label{260106a}
 \end{equation}
 This combined with \cref{p:R2sequence1} yields $(\forall\varepsilon>0)(\exists m_\varepsilon\in\mathbb{N})(\forall\gamma\in\left]0,2-\varepsilon\right])$
 \begin{subequations}
 \begin{align}
 \sum_{n=0}^{\infty}\norm{x^{(n+1)}-x^{(n)}}^\gamma&\geq\sum_{n=m_\varepsilon}^{\infty}\norm{x^{(2n)}-x^{(2n-1)}}^\gamma\notag\\
 &=\sum_{n=m_\varepsilon}^{\infty}\exp\left(-\gamma\beta u_n^{-r}\right)\tag{by \cref{p:R2sequence1} }\\
 &\geq\sum_{n=m_\varepsilon}^{\infty}\exp\left(-\gamma\frac{\ln(n)}{2-\varepsilon}\right)\tag{by \cref{260106a} }\\
 &=\sum_{n=m_\varepsilon}^{\infty}n^{-\frac{\gamma}{2-\varepsilon}}=+\infty;\notag
 \end{align}
 \end{subequations}
 consequently, 
 \begin{equation}
 \sum_{n=0}^{\infty}\norm{x^{(n+1)}-x^{(n)}}^\gamma=+\infty \quad 
 \text{for all $\gamma\in\left]0,2\right[$.}
 \end{equation}
\end{example}

\begin{example}[G\"unt\"urk-Thao fails for a plane 
and a non-polyhedral cone in $\RR^3$]
\label{e:cone}
 Let $\beta\in \mathbb{R}_{++}$ and $r\in\{2,4,6,\ldots\}$. 
 Consider the function $f(x)=\exp(-\beta x^{-r})$ with domain $\bigl[-\left(\beta r/(r+1)\right)^{1/r},\left(\beta r/(r+1)\right)^{1/r}\bigr]$. Note that $f$ is supercoercive and hence, the assumption of \cref{p:R3sequence2} is satisfied with $q=-r-1$, $\alpha=2\beta$, $p=r$, and $c_{q,\alpha,p}=r\beta$. Hence, we obtain
 \begin{equation}
 1=\lim_{n\to\infty}\frac{b_n}{\left(\frac{\alpha}{\ln(n)}\right)^{1/p}}=\lim_{n\to\infty}\frac{b_n}{\left(\frac{2\beta}{\ln(n)}\right)^{1/r}},
 \end{equation}
 which implies
 \begin{equation}
 (\forall\varepsilon>0)(\exists m_\varepsilon\in\mathbb{N})(\forall n\geq m_\varepsilon)\quad b_n\geq\left(\left(1-\frac{\varepsilon}{2}\right)\left(\frac{2\beta}{\ln(n)}\right)\right)^{1/r}.\label{260106}
 \end{equation}
 This combined with \cref{p:R3sequence1} yields
 $ (\forall\varepsilon>0)(\exists m_\varepsilon\in\mathbb{N})(\forall\gamma\in\left]0,2-\varepsilon\right])$
 \begin{subequations}
 \begin{align}
 \quad\sum_{n=0}^{\infty}\norm{x^{(n+1)}-x^{(n)}}^\gamma&\geq\sum_{n=m_\varepsilon}^{\infty}\norm{x^{(2n)}-x^{(2n-1)}}^\gamma
 \notag\\
 &=\sum_{n=m_\varepsilon}^{\infty}
 a_n^\gamma\exp\left(-\gamma\beta b_n^{-r}\right)
 \tag{by \cref{p:R3sequence1iii} }\\
 &\geq\sum_{n=m_\varepsilon}^{\infty}
 a_0^\gamma\exp\left(-\gamma\frac{\ln(n)}{2-\varepsilon}\right)
 \tag{by \cref{p:R3sequence1iv} and \cref{260106} }\\
 &=a_0^\gamma\sum_{n=m_\varepsilon}^{\infty}n^{-\frac{\gamma}{2-\varepsilon}}=+\infty;\notag
 \end{align}
 \end{subequations}
consequently, 
 \begin{equation}\sum_{n=0}^{\infty}\norm{x^{(n+1)}-x^{(n)}}^\gamma=+\infty \quad\text{for all $\gamma\in\left]0,2\right[$.}
 \end{equation}
\end{example}

