The main theorem of \cite{BHS} is as follows:

The main theorem of \cite{BHS} is as follows:

We will follow the notation used in \cite{Morel-Voevodsky}, \cite{Morel-book} and \cite{BHS}. The letter $k$ will always denote a perfect field. Let $\@H_s(k)$ and $\@H(k)$ denote the pointed unstable simplicial and $\#A^1$-homotopy categories introduced by Morel and Voevodsky in \cite{Morel-Voevodsky}. These are obtained as homotopy categories associated with the locally injective model structrure on the category $\Delta^{op}Shv(Sm/k)_{\rm Nis}$ of simplicial Nisnevich sheaves of sets on the category $Sm/k$ of essentially smooth, separated schemes on $k$ and its Bousfield localization at the class of projection maps $\@X \times \#A^1 \to \@X$, respectively. For each $n \in \#N$ and every pointed object $\@X \in \Delta^{op}Shv(Sm/k)_{\rm Nis}$, the simplicial homotopy sheaf $\pi_n(\@X)$ is defined to be the Nisnevich sheafification of the presheaf on $Sm/k$
\[
U \mapsto \Hom_{\@H_s(k)}(\Sigma^nU_+, \@X)
\]
and the $\A^1$-homotopy sheaf $\pi_n^{\#A^1}(\@X)$ is defined to be the Nisnevich sheafification of the presheaf on $Sm/k$
\[
U \mapsto \Hom_{\@H(k)}(\Sigma^nU_+, \@X),
\]
where we suppress the basepoint whenever it is clear from the context.

\begin{corollary}
\label{cor key LES}
Let the notation be as above. If $\pi_0^{\A^1}(\~G)$ is strongly $\#A^1$-invariant, then we have a long exact sequence
\[
\cdots \to \pi_1^{\A^1}(B_{\text{\'et}} \mu)\to \pi_0^{\A^1}(\~G) \to \pi_0^{\A^1}(G) \to \pi_0^{\A^1}(B_{\text{\'et}} \mu).
\]
\end{corollary}
\begin{proof}
We have a simplicial homotopy principal $\~G$-fibration
\[
\~G \to G \to Q,
\]
which is an $\A^1$-fiber sequence by \cite[Theorem 6.50]{Morel-book}. This gives rise to an exact sequence of sheaves of groups/sets
\begin{equation}
\label{eqn long exact seq}
\cdots \to \pi_1^{\A^1}(Q) \to \pi_0^{\A^1}(\~G) \to \pi_0^{\A^1}(G) \to \pi_0^{\A^1}(Q).
\end{equation}
In this sequence, the terms $\pi_i^{\#A^1}(Q)$ for $i>1$ may be replaced by $\pi_i^{\#A^1}(B_{\text{\'et}} \mu)$ due to Propositions \ref{prop comparing quotients} and \ref{prop Q a1-local}. The term $\pi_0^{\#A^1}(Q)$ may be replaced by $\pi_0^{\#A^1}(B_{\text{\'et}} \mu)$ due to Lemma \ref{lemma monomorphism} and Proposition \ref{prop Q a1-local}. This gives us the desired long exact sequence. 
\end{proof}

\begin{lemma}
\label{lemma correctedch}
Let $k$ be a perfect field. Let $G$ be a strongly $\A^1$-invariant sheaf of groups on $Sm/k$ and $G \xrightarrow{\phi} H$ an epimorphism of sheaves. Further assume that $\Ker(\phi)$ is central in $G$. Then $H$ is strongly $\A^1$-invariant if and only if it is $\A^1$-invariant.
\end{lemma}
\begin{proof}
We only need to show that if $H$ is $\A^1$-invariant, then it is strongly $\A^1$-invariant as the reverse implication is trivial. Let $K:= \Ker(\phi)$. For every smooth $k$-scheme $U$, the short exact sequence of Nisnevich sheaves of groups
\[
1 \to K \to G \xrightarrow{\phi} H \to 1
\]
gives us an exact sequence of pointed cohomology sets
\[
1 \to H^0(U,K) \to H^0(U, G) \to H^0(U, H) \to H^1(U, K) \to H^1(U, G) \to H^1(U, H),
\]
by \cite[Ch. III, Proposition 3.3.1]{Giraud}. Since this exact sequence is functorial in $U$ and since $G$ is strongly $\A^1$-invariant, it follows that $\A^1$-invariance of $H$ is equivalent to strong $\A^1$-invariance of $K$. Since $K$ is a Nisnevich sheaf of abelian groups and $H$ is $\A^1$-invariant by hypothesis, it follows from \cite[Theorem 5.46]{Morel-book} that $K$ is strictly $\A^1$-invariant.

\begin{lemma}\cite[Lemma 5.1]{BHS}
\label{lemma isogeny}
Let $k$ be a field. Let $\~G \to G$ be a central isogeny of semisimple algebraic groups, the kernel of which is a group $\mu$ of multiplicative type. If $\pi_0^{\A^1}(\~G)$ is strongly $\A^1$-invariant, then so is $\pi_0^{\A^1}(G)$.
\end{lemma}
\begin{proof} 
Applying Corollary \ref{cor key LES}, we obtain an exact sequence of sheaves of sets
\begin{equation}
\label{eqn long exact}
\cdots \to \pi_1^{\A^1}(B_{\text{\'et}} \mu)\to \pi_0^{\A^1}(\~G) \to \pi_0^{\A^1}(G) \to \pi_0^{\A^1}(B_{\text{\'et}} \mu).
\end{equation}
From the above exact sequence, we extract the short exact sequence 
\[
1 \to \im\left(\pi_0^{\A^1}(\~G) \to \pi_0^{\A^1}(G)\right) \to \pi_0^{\A^1}(G) \to \im\left(\pi_0^{\A^1}(G) \to \pi_0^{\A^1}(B_{\text{\'et}}\mu)\right) \to 1.
\]
It thus suffices to show that $\im\left(\pi_0^{\A^1}(\~G) \to \pi_0^{\A^1}(G)\right)$ and $\im\left(\pi_0^{\A^1}(G) \to \pi_0^{\A^1}(B_{\text{\'et}}\mu)\right)$ are both strongly $\A^1$-invariant.

\noindent First note that the sheaf $\pi_0^{\A^1}(B_{\text{\'et}}\mu) = \mathcal H^1_{\text{\'et}}(\mu)$ is strongly $\A^1$-invariant by \cite[Example 4.6]{Asok-crelle}. The short exact sequence
\[
1 \to \im\left(\pi_0^{\A^1}(G) \to \pi_0^{\A^1}(B_{\text{\'et}}\mu)\right) \to \pi_0^{\A^1}(B_{\text{\'et}}\mu) \to {\coker} \left(\pi_0^{\A^1}(G) \to \pi_0^{\A^1}(B_{\text{\'et}}\mu)\right) \to 1
\]
shows that it suffices to prove $\A^1$-invariance of ${\coker} \left(\pi_0^{\A^1}(G) \to \pi_0^{\A^1}(B_{\text{\'et}}\mu)\right)$.
For every smooth henselian local $k$-scheme $U$, we have a commutative diagram
\[
\begin{xymatrix}{
