Let $p>1$ and $\Omega$ be a bounded domain with (piecewise) smooth boundary $\partial \Omega \neq \varnothing$ in a complete Riemannian manifold $(M,g).$ Define $\lambda_{1,p}(\Omega)$ to be the principal $p-$frequency of $\Omega$ if it is the first positive eigenvalue of $\Omega$ with the Dirichlet condition:
 $$
 \left\{\begin{array}{ll}
 \Delta_p u = -\lambda_{1,p}(\Omega)|u|^{p-2}u & \quad \text{in $\Omega$}, \\
 u=0 & \quad \text{on $\partial \Omega$}.
 \end{array}\right.
 $$
 We call $u$ the eigenfunction of $\lambda_{1,p}(\Omega)$ with respect to the $p-$Laplace operator $\Delta_p:$
 $$
 \Delta_p v = \operatorname{div}(|\nabla v|^{p-2}\nabla v), \quad v \in W^{1,p}_\mathrm{loc}(M)
 $$
 where the equality holds in the weak $W^{1,p}_\mathrm{loc}(M)$ sense. The principal $p-$frequency is also called the first Dirichlet eigenvalue of $\Delta_p,$ and has the following variational characterization:
 \begin{equation}\label{eq:variational}
 \lambda_{1,p}(\Omega) = \inf_{v \in W^{1,p}_0(\Omega) \setminus \{0\}} \frac{\int_\Omega |\nabla v|^p \,\mathrm{d} v_g}{\int_\Omega |v|^p \,\mathrm{d} v_g}.
 \end{equation}

In this paper, we obtain a sharp estimate of $\lambda_{1,p}(\Omega)$ if the ambient manifold $(M,g)$ is non-compact and its Ricci curvature is bounded from below by a negative constant. To state our main theorem, we first introduce the corresponding one-dimensional ordinary differential equation model:
 \begin{definition}\label{def:barlambda}
 For arbitrary $D>0,\ K<0$ and $n\geq 2,$ let $\bar \lambda = \bar \lambda_{D,K,n}>0$ be the first eigenvalue of $[0,D]$ of the following eigenvalue problem:
 \begin{equation}\label{eq:1-dim-diri}
 \left\{\begin{array}{l}
 \frac{\mathrm{d}}{\mathrm{d} t} (\dot w^{(p-1)}) + (n-1)\sqrt{-K} \dot w^{(p-1)} + \bar\lambda w^{(p-1)} = 0, \\
 w(0) = 0, \dot w(D) = 0,
 \end{array}\right.
 \end{equation}
 where $$w^{(p-1)}:=|w|^{p-2}w.$$
 Proposition \ref{prop:2nd-model-existence} below shows that there is a smallest positive $\bar\lambda$ such that \eqref{eq:1-dim-diri} has a nontrivial solution which is unique in the sense of scaling.
 \end{definition}

\begin{equation}\label{eq:1-dim-diri}
            \left\{\begin{array}{l}
            \frac{\d}{\d t} (\dot w^{(p-1)}) + (n-1)\sqrt{-K} \dot w^{(p-1)} + \bar\lambda w^{(p-1)} = 0, \\
            w(0) = 0, \dot w(D) = 0,
        \end{array}\right.
    \end{equation}

\begin{lemma}\label{prop:2nd-model-existence}
        There exists a unique $\alpha>0$ such that \eqref{eq:prufer-phi} has a solution $\phi$ satisfying that $\phi(D)=\pi_p/2.$ Consequently, there exists a smallest $\bar\lambda>0$ such that \eqref{eq:1-dim-model} has a non-trivial solution $w$ satisfying that $\dot w(D)=0$.
    \end{lemma}

\begin{theorem}\label{thm:1.1}
 Let $(M,g)$ be a complete Riemannian manifold and $\Omega \subseteq M$ a bounded domain. If there exists $f \in W^{1,p}_\loc(\Omega)$ and a constant $\mu > 0$ such that
 $$
 \Delta_p f - (p-1) |\nabla f|^p \geq \mu
 $$
 in the weak $W^{1,p}_\loc$ sense, then
 $$
 \lambda_{1,p}(\Omega) \geq \mu.
 $$
 Moreover, if $\lambda_{1,p}(\Omega) = \mu$, then $e^{-f}$ is a $p$-eigenfunction corresponding to $\lambda_{1,p}(\Omega)$.
 \end{theorem}

\begin{proof}
 We omit the $\varepsilon$'s in subscripts for simplicity of notations and need to prove
 $$
 (n-2)\frac{1-\dot f^2}{f^2} - \frac{\ddot f}{f} \geq -(n-1).
 $$
 The inequality above holds on $x \in [0,\varepsilon/2] \cup [\varepsilon,+\infty]$. So we focus on the situation that $x \in [\varepsilon/2,\varepsilon]$. Note that $h = f'/f$, then the inequality is equivalent to
 \begin{equation}\label{ineq:ricci}
 h' + (n-1)( h^2 - 1) \leq \frac{n-2}{f^2}.
 \end{equation}
 Since $h(t) \leq \coth t$, we have
 $$\begin{aligned}
 f(x) & =\sinh (\varepsilon/2) \exp \int_{\varepsilon/2}^x h_\varepsilon(t) \,\d t
 \\ & \leq \sinh (\varepsilon/2)\exp\int_{\varepsilon/2}^x \coth t \,\d t
 \\ &=\sinh x.
 \end{aligned}
 $$
 Therefore, to prove \eqref{ineq:ricci}, it suffices to prove
 \begin{equation}\label{ineq:ricci1}
 h'(t) + (n-1)(h^2(t) - 1) \leq \frac{n-2}{\sinh^2 t} = \frac{n-1}{\sinh^2 t} + (\coth t)',
 \end{equation}
 which is equivalent to
 $$
 h'(t) - (\coth t)' + (n-1)(h^2 - \coth^2 t) \leq 0.
 $$
 Denote $g(t) = \coth t - h(t) \geq 0$, then \eqref{ineq:ricci1} is equivalent to
 \begin{equation}\label{ineq:ricci2}
 g'(t) + (n-1)g(t)(\coth t + h(t)) \geq 0.
 \end{equation}
 By the definition of $g$,
 \begin{align*}
 g(t) &= \psi(t)(\coth t + 1), \\
 g'(t) &= \psi'(t) (\coth t+1) - \frac{\psi(t)}{\sinh^2 t}.
 \end{align*}
 Insert into the LHS of \eqref{ineq:ricci2}, and using that $h(t)\geq -1,$ we get
 \begin{align*}
 \text{LHS of \eqref{ineq:ricci2}} &= \psi'(t)(\coth t+ 1)- \frac{\psi(t)}{\sinh^2 t} + (n-1)\psi(t)(\coth t + 1)(\coth t + h(t))
 \\ &\geq 0-\frac{\psi(t)}{\sinh^2 t} + (n-1)\psi(t)(\coth t + 1)(\coth t -1) \\
 & =\frac{(n-2) \psi(t)}{\sinh^2 t}\\
 &\geq 0.
 \end{align*}
 Therefore \eqref{ineq:ricci2} is proved, which implies that $\Ric[g_\varepsilon] \geq -(n-1).$
 \end{proof}
 With the preparations above, we can now prove the sharpness of the estimate \eqref{eq:thm1.2}:
 \begin{proof}[Proof of the sharpness]
 Fix a sufficiently small $\varepsilon>0$ and let $o$ be the center of $(M_\varepsilon,g_\varepsilon).$ Assume that
 $$\delta=\delta(\varepsilon)< e^\varepsilon\sinh\varepsilon$$ as defined in \eqref{eq:f} and select a point $z= \exp_o((1-\delta)\theta)$ for some $\theta \in \mathbb{S}^{n-1}.$ We claim that
 \begin{equation}\label{eq:BsubsetB}
 B(o,2-\delta-\pi \delta e^{\delta-1}) \subseteq B(z,1).
 \end{equation}
 Indeed, for any $x \in B(o,2-\delta-\pi \delta e^{\delta-1}),$ we have that
 $$
 x = \exp_o(r_x \theta_x)
 $$ for some $\theta_x \in \mathbb{S}^{n-1}$ and $r_x \leq 2-\delta-\pi \delta e^{\delta-1}.$
 Let $y_x = \exp_o((1-\delta)\theta_x)$, then
 $$\begin{aligned}
 d(x,z) &\leq d(x,\exp_o((1-\delta)\theta_x)) + d(\exp_o((1-\delta)\theta_x),z)
 \\ & \leq |r_x-(1-\delta)|+\pi f_\varepsilon(1-\delta)
 \\ & \leq 2-\delta-\pi \delta e^{\delta-1}-(1-\delta) + \pi \delta e^{\delta-1}
 \\ & = 1.
 \end{aligned}
 $$
 We consider the bounded domain
 $$
 \Omega_\varepsilon=B(o,2-\delta-\pi \delta e^{\delta-1})\subseteq M_\varepsilon
 $$
 with diameter $D_\varepsilon=\text{diam}(\Omega_\varepsilon).$ Then by equation \eqref{eq:BsubsetB},
 \begin{equation}\label{eq:Diameter}
 2-\delta-\pi \delta e^{\delta-1}\leq D_\varepsilon\leq 2
 \end{equation}
 In order to make an estimate of $\lambda_{1,p}(\Omega_\varepsilon),$ we consider the test function in $\Omega_\varepsilon:$
 $$\begin{cases}
 v(x)=w(R_\varepsilon-r(x)) \\
 R_\varepsilon=2-\delta-\pi \delta e^{\delta-1} \\
 r(x)=\text{distance function of $o$}\\
 w=\text{positive solution to \eqref{eq:1-dim-diri} when $D=R_\varepsilon$.}
 \end{cases}$$
 Then $v\in W^{1,p}_0(\Omega_\varepsilon)$ and hence
 \begin{align*}
 \lambda_{1,p}(\Omega_\varepsilon) &\leq \frac{\int_{\Omega_\varepsilon} |\nabla v(x)|^p \,\d v}{\int_{\Omega_\varepsilon} |v(x)|^p \,\d v} \\
 &= \frac{\int_0^{R_\varepsilon} |\dot w(R_\varepsilon-r)|^p \cdot \omega_{n-1}f^{n-1}_\varepsilon(r) \,\d r}{\int_0^{R_\varepsilon} |w(R_\varepsilon-r)|^p\cdot \omega_{n-1}f^{n-1}_\varepsilon(r) \,\d r} \\
 &= \frac{C_1(\varepsilon)+\int_\varepsilon^{R_\varepsilon} |\dot w(R_\varepsilon-r)|^p \cdot (\delta e^{-r})^{n-1} \,\d r}{C_2(\varepsilon)+\int_\varepsilon^{R_\varepsilon} |w(R_\varepsilon-r)|^p\cdot (\delta e^{-r})^{n-1} \,\d r}
 \\
 &= \frac{C_1(\varepsilon)-\int_0^{R_\varepsilon-\varepsilon} |\dot w(t)|^p \cdot (\delta e^{t-R_\varepsilon})^{n-1} \,\d t}{C_2(\varepsilon)-\int_0^{R_\varepsilon-\varepsilon} |w(t)|^p\cdot (\delta e^{t-R_\varepsilon})^{n-1} \,\d t}
 \end{align*}
 where
 $$\begin{cases}
 C_1(\varepsilon) = \int_0^{\varepsilon} |\dot w(R_\varepsilon-r)|^p \cdot \omega_{n-1}f^{n-1}_\varepsilon(r) \,\d r \\
 C_2(\varepsilon) = \int_0^{\varepsilon} | w(R_\varepsilon-r)|^p \cdot \omega_{n-1}f^{n-1}_\varepsilon(r) \,\d r
 \end{cases}\to 0$$
 as $\varepsilon \to 0$. Consequently,
 \begin{equation}\label{eq:9}
 \begin{aligned}
 \limsup_{\varepsilon \to 0} \lambda_{1,p}(\Omega_\varepsilon) &\leq
 \lim_{\varepsilon \to 0}\frac{\int_0^{R_\varepsilon-\varepsilon} |\dot w(t)|^p \cdot (\delta e^{t-R_\varepsilon})^{n-1} \,\d t}{\int_0^{R_\varepsilon-\varepsilon} |w(t)|^p\cdot (\delta e^{t-R_\varepsilon})^{n-1} \,\d t}
 \\ & =\frac{\int_0^2 |\dot w(t)|^p e^{(n-1)t} \,\d t}{\int_0^2 |w(t)|^p e^{(n-1)t} \,\d t}
 \\ & =\bar\lambda_{2,-1,n}.
 \end{aligned}
 \end{equation}
 Here the last equation is due to Remark \ref{rmk:13} (1). Finally, according to \eqref{eq:thm1.2},
 $$
 \liminf_{\varepsilon \to 0} \lambda_{1,p}(\Omega_\varepsilon) \geq \lim_{\varepsilon \to 0}\bar\lambda_{D_\varepsilon,-1,n}=\bar\lambda_{2,-1,n}
 $$
 since $D_\varepsilon\rightarrow 2$ by \eqref{eq:Diameter}.
 \par Finally, we note that the diameter $2$ used in the above construction can be replaced by any $D > 0.$ Thus the sharpness of the estimate \eqref{eq:thm1.2} is established for all $D > 0.$
 \end{proof}

\begin{remark}
 \begin{itemize}
 \item [(1)] Recall the classical McKean’s theorem in \cite{McKean1970AnUB}: If $(M,g)$ is an $n-$dimensional complete simply connected Riemannian manifold such that the sectional curvature is bounded above by $K<0,$ then for any bounded domain $\Omega$ in $M,$
 $$
 \lambda_{1,p}(\Omega)\geq\Big(\frac{(n-1)\sqrt{-K}}{p}\Big)^p.
 $$
 The bound is independent of the size or shape of the domain, and depends only on the curvature upper bound $K$ and the dimension $n.$
 \par In contrast, the main theorem of the paper assumes only a Ricci curvature lower bound
$\Ric\geq (n-1)K$ with $K<0,$ and provides a lower bound $\bar\lambda_{D,K,n}.$ This bound decays exponentially as $D\rightarrow\infty,$ reflecting the fact that in the presence of negative Ricci curvature a domain can be made “long and thin” so that its principal frequency becomes arbitrarily small.
\par The sharpness construction in Section 3 exemplifies this difference: the warped product manifolds satisfy
$\Ric\geq-(n-1)$ but have a cusp-like end where sectional curvature is not bounded above by a negative constant (indeed, spherical sectional curvature becomes positive and large). Hence and the eigenvalue can approach zero as the diameter grows.
 \item [(2)] Ona can see Remark 2.1 in \cite{jin2025estimate}. From the same example, we show that the restriction that $\Omega$ is embedded in a non-compact manifold cannot be dropped.
 \end{itemize}

