ref_dict.local-open:
\begin{theorem}
\label{local-open}
Suppose $t\in [a,b]\mapsto M(t)$
is a standard Brakke
flow in a smooth
Riemannian $3$-manifold~$N$.

Suppose $W$ is an open subset
of~$N$ such that 
\begin{enumerate}
\item
\label{one}
$\partial W$ is smooth.
\item
\label{two}
$\partial W$ is disjoint
from $\Sing M(t)$ for 
 each $t\in I$.
\item
\label{three}
$\Reg M(t)$ is transverse
 to $\partial W$ for
 each $t\in I$.
\item
\label{four}
$\cup_{t\in I}(W\cap M(t))$
is contained in 
a compact subset of~$N$.
\item
\label{five}
Each tangent flow
to~$M(\cdot)$
at each spacetime point in $W\times I$
has multiplicity~one, and
 the corresponding
shrinker is a plane, a sphere,
or a cylinder.
\end{enumerate}
Then 
\begin{equation}
\label{W-conclusion}
 g(t):= \genus(W\cap \Reg M(t))
 \tag{*}
\end{equation}
is a decreasing function
 of $t\in I$.
\end{theorem}

