 \begin{align}
 \dH A=\dH S(A)-1.
 \end{align}

In Section 2, we will see that the Hausdorff dimension on $SM$ can be defined independently of the explicit Riemannian metrics.

In this paper, we shall prove Theorem \ref{Hausdorff dimension, unions of geodesics} for all $d\geq 2$.
 With some parametrizations of $SM$, it suffices to consider unions of smooth curves satisfying the regular condition and the transversal condition.
 \begin{thm}\label{Unions of smooth curves}
 Suppose $A\subset[-1,1]^{d-1}\times[-1,1]^{d-1}$ and $\dH A\geq 2(k-1)+\beta$ for some integer $1\leq k\leq d-1$ and $\beta\in[0,1]$. Let $\{\gamma_y\}_{y\in A}$ be a collection of smooth curves such that $\gamma_y$ joints $(y_1,-1)$ and $(y_2,1)$ and can be parametrized by its last coordinate
 \begin{align*}
 \gamma_y(c)=(P_y(c),c),\;c\in[-1,1].
 \end{align*}
 We assume that $\{\gamma_y\}_{y\in A}$ satisfies the followings.

Now we are ready to give the discretization argument. Suppose $S=\bigcup_{y\in A}\gamma_y$ and $\dH S=\alpha$. Let $k_0$ be a large positive integer, $\epsilon>0$.
we cover $S$ by a union of balls $\bigcup_{k=k_0}^{\infty}\bigcup_{B\in\mathcal{B}_k}B$, where $\mathcal{B}_k$ is a collection of balls with radius $2^{-k}$, and 
\begin{align}
 \sum_{k=k_0}^{\infty}2^{-k(\alpha+\epsilon)}\#\mathcal{B}_k\leq 1.
\end{align}
In particular, we have 
\begin{align}\label{number of balls}
 \#\mathcal{B}_k\lesssim 2^{k(\alpha+\epsilon)}.
\end{align}
For each $y\in A$, by construction, 
\begin{align*}
\H_{\infty}^1\left(\gamma_y\bigcap\left(\bigcup_{k=k_0}^{\infty}\bigcup_{B\in\mathcal{B}_k}B\right)\right)\gtrsim 1.
\end{align*}
Then there exists $k=k(y)$ such that
\begin{align*}
\H_{\infty}^1\left(\gamma_y\bigcap\left(\bigcup_{B\in\mathcal{B}_k}B\right)\right)\gtrsim \frac{1}{k^2}.
\end{align*}
Let 
\begin{align*}
 A_k=\{y\in A:k(y)=k\},
\end{align*}
then 
\begin{align*}
 \sum_{k=k_0}^{\infty}\H_{\infty}^{2(k-1)+\beta-\epsilon}(A_k)\geq \H_{\infty}^{2(k-1)+\beta-\epsilon}(A)>0.
\end{align*}
Then there exists $k_1\geq k_0$ such that
\begin{align}
 H_{\infty}^{2(k-1)+\beta-\epsilon}(A_{k_1})\gtrsim\frac{1}{k_1^2}.
\end{align}
Let $\delta=2^{-k_1}$. By Lemma \ref{Frostman}, there exists a $(\delta,2(k-1)+\beta-\epsilon)$-set $A'\subset A_{k_1}$ such that
\begin{align}\label{Frostman lemma, delta set}
 \#A'\gtrsim k_1^{-2}\cdot\delta^{-(2(k-1)+\beta-\epsilon)}.
\end{align}
Let 
\begin{align*}
 S'=\bigcup_{B\in\mathcal{B}_{k_1}}2B.
\end{align*}
and let
\begin{align*}
 T_y^{\delta}=\{x=(x',x_d)\in[-1,1]^d:|x'-P_y(x_d)|\leq \delta\}.
\end{align*}
$T_y^{\delta}$ is a curved $\delta$-tube and 
\begin{align}\label{intersection}
 |T_y^{\delta}\cap S'|\gtrsim k_1^{-2}\cdot\delta^{d-1},\;y\in A'.
\end{align}
Then 
\begin{align}
 \|\sum_{y\in A'}\chi_{T_{y}^{\delta}}\|_{L^1(S')}\gtrsim\#A'\cdot k_1^{-2}\cdot\delta^{d-1}\gtrsim k_1^{-4}\cdot \delta^{d-1-(2(k-1)+\beta-\epsilon)}.
\end{align}
On the other hand, by H\"older's inequality, we have 
\begin{align}
 \|\sum_{y\in A'}\chi_{T_{y}^{\delta}}\|_{L^1(S')}\lesssim\|\sum_{y\in A'}\chi_{T_y^{\delta}}\|_{L^p}\cdot|S'|^{1/p'}\lesssim\|\sum_{y\in A'}\chi_{T_y^{\delta}}\|_{L^p}\cdot\delta^{\frac{d-\alpha-\epsilon}{p'}}.
\end{align}
Hence
\begin{align}
 \|\sum_{y\in A'}\chi_{T_y^{\delta}}\|_{L^p}\gtrsim\log(\delta^{-1})^{4}\cdot\delta^{d-2k+1-\beta+\epsilon}\cdot\delta^{-\frac{d-\alpha-\epsilon}{p'}},p\geq 1.
\end{align}
Thus, it suffices to show the following curved Kakeya estimate.
\begin{thm}\label{curved Kakeya, discretized}
 Suppose $A\subset[-1,1]^{d-1}\times[-1,1]^{d-1}$ is a $(\delta,2(k-1)+\beta)$-set. Let $\{\gamma_y\}_{y\in A}$ be a collection of smooth curves such that $\gamma_y$ joints $(y_1,-1)$ and $(y_2,1)$ and can be parametrized by its last coordinate
 \begin{align*}
 \gamma_y(c)=(P_y(c),c),\;c\in[-1,1].
 \end{align*}
 We assume that $\{\gamma_y\}_{y\in A}$ satisfies the followings.

\begin{thm}
 Suppose $M$ is a $d$-dimensional complete manifold with constant sectional curvature, and $\pi$ is the projection from $SM$ to $M$. Given an integer $1\leq k\leq d-1$ and $\beta\in[0,1]$, there exists an invariant set $E\subset SM$ with $\dH E=2(k-1)+\beta+1$ and $\dH\pi(E)=k+\beta$.
 \end{thm}
 \begin{proof}
 It is well known that the universal covering of a $d$-dimensional complete manifold with constant sectional curvature is isometric to one of $\R^d$, $\mathbb{H}^d$, and $S^d$, and the covering map is a local isometry. Thus it suffices to consider $M=\R^d$, $\mathbb{H}^d$ and $S^d$.

Now we turn to the Hausdorff dimension of $E$. Note that the projection $\pi|_E$ is Lipschitz and for $p\in\pi(E)$, by construction of $E$,
 \begin{align*}
 \dH\pi|_E^{-1}(\{p\})\geq k-1.
 \end{align*}
 By Lemma in \cite{KM75}, we have 
 \begin{align*}
 \dH E\geq k-1+\dH \pi(E)=2(k-1)+\beta+1.
 \end{align*}
 On the other hand, we consider the map
 \begin{align*}
 \psi:S(S^k)\times A\to E,\;\psi((p,v),\theta)=(g_\theta (p), g_\theta (v)).
 \end{align*}
 It is clear that $\psi$ is Lipschitz and then 
 \begin{align*}
 \dH E\leq \dH (S(S^k)\times A)=2(k-1)+\beta+1.
 \end{align*}
 \end{proof}
 \subsection{Conjecture for manifolds with non-constant sectional curvature}
 When $M$ is a complete manifold with non-constant sectional curvature and dimension $\geq 3$, it is natural to ask whether Theorem \ref{Hausdorff dimension, unions of geodesics} is still sharp. We believe that Theorem \ref{Hausdorff dimension, unions of geodesics} can be improved in this case and give the following conjecture.
 \begin{conj}\label{Hausdorff dimension, unions of geodesics, non-constant sectional curvature}
 Suppose $d\geq 3$ and
 $M$ is a $d$-dimensional complete Riemannian manifold with \textbf{non-constant sectional curvature}. Let $1\leq k\leq d-1$ be an integer and $\beta\in[0,1]$. Then there exists $\epsilon=\epsilon(d,k,\beta, M)>0$ such that if $E\subset SM$ is an invariant set with $\dH E\geq 2(k-1)+1+\beta$, then 
 \begin{align*}
 \dH\pi(E)\geq k+\beta+\epsilon.
 \end{align*}
 \end{conj}

