 $$
 see \cite{translation, Cjabok}.
 \item [$(iii)$] 
 \begin{equation}\label{quad}
 \psi_{m,h,s}:= m \left (X^{q^s}-h^{1-q^{s(t+1)}}X^{q^{s(t+1)}} \right )+X^{q^{s(t-1)}}+h^{1-q^{s(2t-1)}}X^{q^{s(2t-1)}} \in \tilde{\mathcal{L}}_{n,q,s}, 
 \end{equation}
 where $q$ is an odd prime power, $t \geq 3$, $n=2t$, $\gcd(s,n)=1$, and $(m,h) \in \F_{q^t} \times \F_{q^{2t}}$ are such that 
 \begin{itemize}
 \item $m=1$ and $h \in \F_{q^t}$ with $h^2=-1$, see \cite{Bartoli_Zanella_Zullo,longobardi_zanella, neri_santonastaso_zullo,Zanella-Zullo}. Note that $h^2=-1$ implies that $h \in \F_{q^{\gcd(t,2)}}$. So, if $t$ is odd, $q \equiv 1 \pmod 4$.

Our main theorem is the following.

The conditions in Theorem \ref{main} strictly include those introduced in the previous papers on $\psi_{m,h,s}$.\\

\begin{remark}\label{hfqt}
 \textnormal{Note that if $h \in \F_{q^t}$ with $\mathrm{N}_{q^{2t}/q^t}(h)=\pm 1$ and $m \in \F_{q^t} \setminus (\mathscr{P}_s^+ \cup \mathscr{P}_s^-)$, the quadrinomial $\psi_{m,h,s}$ is scattered, indeed:
 \begin{itemize}
 \item [$(i)$] If $h^2=-1$, then $h \in \F_{q^{\gcd(t,2)}}$. For $q \equiv 1 \pmod{4}$, $h \in \F_q$ and 
 $$
 \psi_{m,h,s}=m\Big( X^{q^s}-X^{q^{s(t+1)}}\Big)+X^{q^{s(t-1)}}+X^{q^{s(2t-1)}}.
 $$
 is scattered, see \cite{SmaZaZu}. For $q \equiv 3 \pmod{4}$, then $t$ is even, $h \in \F_{q^2} \setminus \F_q$ and
 $$
 \psi_{m,h,s}=m\Big( X^{q^s}+X^{q^{s(t+1)}}\Big)+X^{q^{s(t-1)}}-X^{q^{s(2t-1)}}.
 $$
 This is scattered if and only if its adjoint polynomial $\hat{\psi}_{m,h,s}$ is scattered. Since 
 $$
 \hat{\psi}_{m,h,s}= \mu \psi_{-\mu,h,s}=-\mu \Big( X^{q^s}-X^{q^{s(t+1)}} \Big)+X^{q^{s(t-1)}}+X^{q^{s(2t-1)}},
 $$ where $\mu=1/m^{q^{s(t-1)}}$, this is scattered because $\mu \in \F_{q^t} \setminus (\mathscr{P}_s^+ \cup \mathscr{P}_s^-)$.
 \item [$(ii)$] if $h^2=1$, then $h = \pm{1}$. In this case, 
 $$
\psi_{m,h,s}=m\Big( X^{q^s}-X^{q^{s(t+1)}}\Big)+X^{q^{s(t-1)}}+X^{q^{s(2t-1)}}
 $$
 and it is scattered again.
 \end{itemize}}
\end{remark}

\begin{theorem}\label{t:main}
Let $t\geq 3$, $q$ be an odd prime power. For each $h \in \F_{q^{2t}} \setminus \F_{q^t}$ with $\mathrm{N}_{q^{2t}/q^t}(h)=-1$ and $$m \in 
\begin{cases}
\mathbb{F}_{q^t} \setminus \bigl(\mathscr{P}_s^+ \cup \mathscr{P}_s^- \bigr),
& \text{if $t$ is even, or $t$ is odd and $q \equiv 1 \pmod{4}$}, \\[2mm]
\mathscr{P}_s^+,
& \text{if $t$ is odd and $q \equiv 3 \pmod{4}$,}
\end{cases}
$$
the $q^s$-linearized polynomial
 \begin{equation*}
 \psi_{m,h,s}=m(X^{q^s}-h^{1-q^{s(t+1)}}X^{q^{s(t+1)}})+X^{q^{s(t-1)}}+h^{1-q^{s(2t-1)}}X^{q^{s(2t-1)}}
 \end{equation*}
 is scattered.
\end{theorem}

\begin{theorem}\label{norma=1}
 Let $t\geq 3$ and $q \equiv 3 \pmod{4}$ and $s$ be an integer such that $\gcd(s,2t)=1$. For each $h \in \F_{q^{2t}} \setminus \F_{q^t}$ such that $\mathrm{N}_{q^{2t}/q^t}(h)=1$ with $h^2 \neq -1$ and $m \in \mathbb{F}_{q^t} \setminus (\mathscr{P}_s^+ \cup \mathscr{P}_s^{-})$, the $q^s$-linearized polynomial
 \begin{equation*}
 \psi_{m,h,s}=m(X^{q^s}-h^{1-q^{s(t+1)}}X^{q^{s(t+1)}})+X^{q^{s(t-1)}}+h^{1-q^{s(2t-1)}}X^{q^{s(2t-1)}}
 \end{equation*}
 is scattered.
\end{theorem}

\begin{theorem}\label{equivalence}
Let $t \geq 5$, $s,\ell$ be positive integers with $\gcd(s,2t)=1=\gcd(\ell,2t)$, $m,\mu\in\F_{q^t}$, $h,k\in\F_{q^{2t}}$ verifying the assumptions of Theorem \ref{main} and let $\psi_{m,h,s},\psi_{\mu,k,\ell}$ be defined as above. Then we have the following results:
\begin{itemize}
 \item[a)] if $ \ell \not\equiv \pm s \pmod{2t}$ and $ \ell \not\equiv t\pm s \pmod{2t}$, then $\psi_{m,h,s}\not\sim_{\mathrm{GL}} \psi_{\mu,k,\ell}$;
 \item[b)] if $ \ell \equiv - s \pmod{2t}$ and $\psi_{m,h,s}\sim_{\mathrm{GL}} \psi_{\mu,k,\ell}$, then we have that $kh\in\mathbb{F}_{q^{\gcd(t-2,2t)}}$ and we have one of the two following properties on $m,\mu$: \begin{itemize}
 \item there exist $z\in\F_{q^{2t}}$ such that $z^{q^{st}}=(kh)^{q^{3s}-1}z$ and $m\mu^\qs=z^{q^{s(t-2)}-1}$;
 \item there exist $z\in\F_{q^{2t}}$ such that $z^{q^{st}}=-(kh)^{q^{3s}-1}z$ and $m\mu=-z^{q^{s(t-2)}-1}$.
 \end{itemize}
 \item[c)] if $ \ell \equiv s \pmod{2t}$ and $\psi_{m,h,s}\sim_{\mathrm{GL}} \psi_{\mu,k,\ell}$, then we have that $h/k\in\mathbb{F}_{q^{\gcd(s(t-2),2t)}}$ and we have one of the two following properties on $m,\mu$: \begin{itemize}
 \item there exist $z\in\F_{q^{2t}}$ such that $z^{q^{st}}=-(h/k)^{q^{3s}-1}z$ and $m\mu^{-q^{s(t-1)}}=-z^{q^{s(t-2)}-1}$;
 \item there exist $z\in\F_{q^{2t}}$ such that $z^{q^{st}}=(h/k)^{q^{3s}-1}z$ and $m/\mu=z^{q^{s(t-2)}-1}$.
 \end{itemize}
 \item[d)] if $ \ell \equiv t- s \pmod{2t}$ and $\psi_{m,h,s}\sim_{\mathrm{GL}} \psi_{\mu,k,\ell}$, then we have that $h/k\in\mathbb{F}_{q^{\gcd(s(t-2),2t)}}$ and we have one of the two following properties on $m,\mu$: \begin{itemize}
 \item there exist $z\in\F_{q^{2t}}$ such that $z^{q^{st}}=(h/k)^{q^{3s}-1}z$ and $m\mu^\qs=-z^{q^{s(t-2)}-1}$;
 \item there exist $z\in\F_{q^{2t}}$ such that $z^{q^{st}}=-(h/k)^{q^{3s}-1}z$ and $m\mu=z^{q^{s(t-2)}-1}$.
\end{itemize}
\item[e)] if $ \ell \equiv t+ s \pmod{2t}$ and $\psi_{m,h,s}\sim_{\mathrm{GL}} \psi_{\mu,k,\ell}$, then we have that $hk\in\mathbb{F}_{q^{\gcd(s(t-2),2t)}}$ and we have one of the two following properties on $m,\mu$: \begin{itemize}
 \item there exist $z\in\F_{q^{2t}}$ such that $z^{q^{st}}=-(hk)^{q^{3s}-1}z$ and $m\mu^{-q^{s(t-1)}}=z^{q^{s(t-2)}-1}$;
 \item there exist $z\in\F_{q^{2t}}$ such that $z^{q^{st}}=(hk)^{q^{3s}-1}z$ and $m/\mu=-z^{q^{s(t-2)}-1}$.
\end{itemize}
\end{itemize}
\end{theorem}

