\label{main}
     Let $t \geq 3$, $q$ an odd prime power, $1 \leq s \leq 2t-1$ an integer such that $\gcd(s,2t)=1$, and $(m,h) \in \F_{q^t} \times \F_{q^{2t}}$. The polynomial $\psi_{m,h,s}$
 is scattered under one of the following assumptions:
 \begin{itemize}
     \item [$i)$] $t$ is even, or $t$ is odd and $q \equiv 1 \pmod 4$, and \begin{equation*}
            m \in \mathbb{F}_{q^t} \setminus (\mathscr{P}^+_{s} \cup \mathscr{P}^-_{s}) \quad \text{ with } \quad \mathrm{N}_{q^{2t}/q^t}(h)=\pm 1;
    \end{equation*}
     \item [$ii)$] $t$ is odd, $q \equiv 3 \pmod 4$ and either
     \begin{itemize}
         \item [$(a)$]  \begin{equation*}
         m \in \mathscr{P}^+_{s} \quad \text{ with } \quad  \mathrm{N}_{q^{2t}/q^t}(h)=-1, \,\, \text{ or } 
            \end{equation*}
         \item [$(b)$] \begin{equation*}
       m \in \mathbb{F}_{q^t} \setminus (\mathscr{P}^+_{s} \cup \mathscr{P}^-_{s})  \quad \text{ with } \quad \mathrm{N}_{q^{2t}/q^t}(h)=1 \text{ and } h^2 \neq -1.  
       \end{equation*}
     \end{itemize}
 \end{itemize}

theorem.content:
\label{intro:thma}(\ref{prop:pgdimineq},\ref{prop:ringepi}, \ref{prop:hringepi})
Let $R$ be a ring, then there is an inequality $\mathsf{pgdim}(\mathsf{D}(R))\geq \mathsf{pgdim}(R)$. As such, $\mathsf{D}(R)$ is not a brown category whenever $\mathsf{pgdim}(R)\geq 2$. Moreover, if $f\colon R\to S$ a ring homomorphism, then
\begin{enumerate}
\item if $f$ is a ring epimorphism, one has $\mathsf{pgdim}(S)\leq \mathsf{pgdim}(R)$;
\item if $f$ is a homological ring epimorphism, one has $\mathsf{pgdim}(\mathsf{D}(S))\leq \mathsf{pgdim}(\mathsf{D}(R))$.
\end{enumerate}

ref_dict.thm:BAfunctoriality:
\begin{thm}\label{thm:BAfunctoriality}
Let $\T$ and $\U$ be compactly generated triangulated categories and $F\colon\Flat{\T^{\c}}\to\Flat{\U^{\c}}$ a definable functor.
\begin{enumerate}
\item Suppose $F$ is essentially surjective up to direct summands, then if $\T$ is a Brown category so is $\U$.
\item Suppose $F$ is fully faithful, then if $\U$ is a Brown category so is $\T$.
\end{enumerate}
\end{thm}

ref_dict.intro:thma:
\begin{thmx}\label{intro:thma}(\ref{prop:pgdimineq},\ref{prop:ringepi}, \ref{prop:hringepi})
Let $R$ be a ring, then there is an inequality $\msf{pgdim}(\D(R))\geq \msf{pgdim}(R)$. As such, $\D(R)$ is not a brown category whenever $\msf{pgdim}(R)\geq 2$. Moreover, if $f\colon R\to S$ a ring homomorphism, then
\begin{enumerate}
\item if $f$ is a ring epimorphism, one has $\msf{pgdim}(S)\leq \msf{pgdim}(R)$;
\item if $f$ is a homological ring epimorphism, one has $\msf{pgdim}(\D(S))\leq \msf{pgdim}(\D(R))$.
\end{enumerate}
\end{thmx}

ref_dict.prop:brownschemes:
\begin{prop}\label{prop:brownschemes}
Let $X$ be a qcqs scheme. Then $\D_{\mrm{qc}}(X)$ is a Brown category only if $\msf{pgdim}(\scr{O}_{X,x})\leq 1$, or $\scr{O}_{X,x}^{\mrm{ab}}$ is a hereditary von Neumann regular ring, for all $x\in X$.
\end{prop}

ref_dict.prop:telescope:
\begin{prop}\label{prop:telescope}
Let $R$ be a von Neumann regular ring, then every Serre subcategory of $\mod{\D(R)^{\c}}$ is perfect. Consequently, there is a bijection between
\begin{enumerate}
\item thick subcategories of $\D(R)^{\c}$;
\item Serre subcategories of $\mod{R}$;
\item $\Sigma$-invariant Serre subcategories of $\mod{\D(R)^{\c}}$;
\item smashing localisations of $\D(R)$;
\end{enumerate}
and all these are in bijection with two-sided ideals of $R$. In particular, the telescope conjecture holds in $\D(R)$.
\end{prop}

ref_dict.prop:fghholds:
\begin{prop}\label{prop:fghholds}
The generating hypothesis holds for $\D(R)$ if and only if $\scr{S}\cap\mod{\D(R)^{\c}}=0$. In particular, if $R$ is right coherent, then $\D(R)$ satisfies the generating hypothesis if and only if $R$ is von Neumann regular.
\end{prop}

ref_dict.ex:fdalgebras:
\begin{ex}[Finite dimensional local algebras]\label{ex:fdalgebras}
Let $k$ be an uncountable algebraically closed field and $A$ a finite dimensional local $k$-algebra. If $A$ is of finite representation type, then it is pure semisimple, meaning every $A$-module is pure injective, and thus $\msf{pgdim}(A)=0$. If $A$ is not of finite representation type, then $\msf{pgdim}(A)\geq 2$ by \cite[Proposition 5.3]{BBL}, and thus $\D(A)$ is not a Brown category by \cref{prop:pgdimineq}. 

It is not clear whether $A$ being pure semisimple implies that $\D(A)$ is Brown without an assumption of $A$ being hereditary. See \cite[\S 12]{belrhap} for this consideration.
\end{ex}

ref_dict.prop:vnrdeterminesbrown:
\begin{prop}\label{prop:vnrdeterminesbrown}
Let $R$ be a ring. If $R^{\mrm{ab}}\neq 0$, then if $R^{\mrm{ab}}$ is not hereditary, $\D(R)$ is not a Brown category.
\end{prop}

ref_dict.prop:hringepi:
\begin{prop}\label{prop:hringepi}
Let $f\colon R\to S$ be a homological ring epimorphism, then $\msf{pgdim}(\D(S))\leq \msf{pgdim}(\D(R))$.
\end{prop}

ref_dict.prop:cosilting:
\begin{prop}\label{prop:cosilting}
Let $\T$ be a compactly generated triangulated category and suppose that $\mbb{t}$ is a compactly generated t-structure that restricts to compact objects. Then $\msf{pgdim}(\T)\geq\msf{pgdim}(\msf{fpInj}(\scr{H}_{\mbb{t}}))$. If, additionally $\mbb{t}$ is non-degenerate, then $\msf{pgdim}(\T)\geq\msf{pgdim}(\scr{H}_{\mbb{t}})$.
\end{prop}

ref_dict.prop:ringepi:
\begin{prop}\label{prop:ringepi}
Let $f\colon R\to S$ be a ring epimorphism. Then $\msf{pgdim}(S)\leq \msf{pgdim}(R)$.
\end{prop}

ref_dict.intro:thmc:
\begin{thmx}\label{intro:thmc}(\ref{thm:BAfunctoriality})
Let $\T$ and $\U$ be compactly generated triangulated categories, and suppose $F\colon\Flat{\T^{\c}}\to\Flat{\U^{\c}}$ is a definable functor. 
\begin{enumerate}
\item If $F$ is essentially surjective up to direct summands and $\T$ is a Brown category, so is $\U$;
\item If $F$ is fully faithful and $\U$ is a Brown category, then so is $\T$.
\end{enumerate}
\end{thmx}

context:
A renowned result in homotopy theory, due to Brown \cite{brown} and Adams \cite{adams}, is that the stable homotopy category of spectra $\mathsf{Sp}$ satisfies Brown--Adams representability. This means that any cohomological functor $F\colon(\mathsf{Sp}^{\omega})^{\mrm{op}}\to\Mod{\mathbb{Z}}$ on finite spectra $\mathsf{Sp}^{\omega}$ is naturally isomorphic to $\Hom_{\mathsf{Sp}}(-,X)\vert_{\mathsf{Sp}^{\omega}}$ for some $X\in\mathsf{Sp}$, and if $\varphi\colon F\to G$ is a natural transformation between cohomological functors, then $\varphi\simeq\Hom_{\mathsf{Sp}}(-,f)$, where $f\colon X\to Y$ is a map in $\mathsf{Sp}$ between objects representing $F$ and $G$.

This statement can be translated into any compactly generated triangulated category $\mathsf{T}$: if $\mathsf{T}^{\mrm{c}}$ denotes the compact objects of $\mathsf{T}$, one says that $\mathsf{T}$ satisfies Brown--Adams representability (or is a Brown category), provided every cohomological functor $F\colon(\mathsf{T}^{\mrm{c}})^{\mrm{op}}\to\Mod{\mathbb{Z}}$ is of the form $\Hom_{\mathsf{T}}(-,X)\vert_{\mathsf{T}^{\mrm{c}}}$ for some object $X$, and any map $\varphi\colon\Hom_{\mathsf{T}}(-,X)\vert_{\mathsf{T}^{\mrm{c}}}\to\Hom_{\mathsf{T}}(-,Y)\vert_{\mathsf{T}^{\mrm{c}}}$ is of the form $\Hom_{\mathsf{T}}(-,f)$ for some $f\colon X\to Y$. In other words, $\mathsf{T}$ is a Brown category, by definition, if and only if the restricted Yoneda functor
\[
\msf{y}\colon\mathsf{T}\to\Flat{\mathsf{T}^{\mrm{c}}}, \, X\mapsto \Hom_{\mathsf{T}}(-,X)\vert_{\mathsf{T}^{\mrm{c}}}
\]
is essentially surjective and full. Here $\Flat{\mathsf{T}^{\mrm{c}}}$ denotes the category of cohomological functors $(\mathsf{T}^{\mrm{c}})^{\mrm{op}}\to\msf{Ab}$, which is expressed this way as it is the ind-completion of the category $\mathsf{T}^{\mrm{c}}$.

It is known that not every compactly generated $\mathsf{T}$ is a Brown category, and determining when a specific one is, or is not, is not elementary. Criteria to approach this problem were proved by Neeman \cite{neemantba} and later expanded by Beligiannis \cite{belrhap}: it was shown that $\mathsf{T}$ satisfies Brown--Adams representability if and only if $\mathsf{pgdim}(\mathsf{T})$, the pure global dimension of $\mathsf{T}$, is at most one.

It is through considering pure global dimension, or more specifically its ascent and descent, that we approach the question of whether or not a triangulated category is Brown. Our main investigation is in revisiting the question of when $\mathsf{D}(R)$ is a Brown category for a ring $R$, and before giving more details and stating results, we provide some historical context.

The question of $\mathsf{D}(R)$ being Brown was first considered in Neeman \cite{neemantba}, where an example credited to Keller showed $\mathsf{D}(\mathbb{C}[x,y])$ is not Brown; the pertinent point is that this ring has a flat module of projective dimension at least two. In \cite{belrhap}, Beligiannis gave some further counterexamples, and provided a relationship between the pure global dimension of $\msf{Mod}(R)$ and $\mathsf{D}(R)$ in the case that $R$ is a (right) hereditary ring, showing the two are equal. This (among other questions) was furthered by Christensen, Keller and Neeman in \cite{ckn} to show that if $R$ is a coherent ring such that every finitely presented $R$-module has finite projective dimension, then $\mathsf{pgdim}(R)\leq\mathsf{pgdim}(\mathsf{D}(R))$. In this paper, the main result in this direction is the following, which removes all assumptions on rings.

\begin{prop}\label{prop:hringepi}
Let $f\colon R\to S$ be a homological ring epimorphism, then $\msf{pgdim}(\D(S))\leq \msf{pgdim}(\D(R))$.
\end{prop}

\begin{prop}\label{prop:pgdimineq}
Let $R$ be a ring. Then $\msf{pgdim}(\D(R))\geq \msf{pgdim}(R)$.
\end{prop}

\begin{prop}\label{prop:ringepi}
Let $f\colon R\to S$ be a ring epimorphism. Then $\msf{pgdim}(S)\leq \msf{pgdim}(R)$.
\end{prop}

