\label{main thm}
	Suppose that the initial data satisfies $a \in H^1(\Omega)$ and $a_z: = \partial_z a \in L^3(\Omega)$, as well as the compatibility conditions: $\operatorname{div}_H \bar a = 0$, the horizontal periodicity, and $a = 0$ on $\Gamma_b$ in case of (\ref{eq: Dirichlet BC}).
	Then the solution of (\ref{eq: PEs})--(\ref{eq: initial condition}) with (\ref{eq: Neumann BC}) or (\ref{eq: Dirichlet BC}) satisfies 
	\begin{equation*}
		\|v(t)\|_{H^1(\Omega)}^2 + \int_0^t \|\nabla^2 v(s)\|_{L^2(\Omega)}^2 \, ds \le B(a) e^{C \|a\|_{L^2(\Omega)}^2} \quad \forall t \in [0, T],
	\end{equation*}
	where $B(a)$ is a polynomial function of $\|a\|_{H^1(\Omega)}$ and $\|a_z\|_{L^3(\Omega)}$, and $C$ is a positive constant dependent only on $\Omega$.

ref_dict.eq: treatment of lower-order term:
\begin{equation} \label{eq: treatment of lower-order term}
\begin{aligned}
	&C (\|\nabla_H \tilde v\|_{L^2(\Omega)}^2 + \|\nabla_H \tilde v\|_{L^2(\Omega)}) \|\tilde v\|_{L^q(\Omega)}^q + \frac{q - 2}{q^2} \big\| \nabla_H |\tilde v|^{\frac{q}2} \big\|_{L^2(\Omega)}^2 \\
	\le \; &C \|\nabla_H \tilde v\|_{L^2(\Omega)}^2 (\|\tilde v\|_{L^q(\Omega)}^q + 1) + \frac{q - 2}{q^2} \big\| \nabla_H |\tilde v|^{\frac{q}2} \big\|_{L^2(\Omega)}^2,
\end{aligned}
\end{equation}

ref_dict.eq: L4 estimate for v in Drichlet BC cas:
\begin{equation} \label{eq: L4 estimate for v in Drichlet BC case}
\begin{aligned}
	&\|v(t)\|_{L^4(\Omega)}^4 + \|v_z(t)\|_{L^2(\Omega)}^2 + \int_0^t \Big( \big\| |v| |\nabla v| \big\|_{L^2(\Omega)}^2 + \|\nabla v_z\|_{L^2(\Omega)}^2 \Big) \, ds \\
	\le \; & C \big( \|a\|_{L^4(\Omega)}^4 + \|a_z\|_{L^2(\Omega)}^2 + \|a\|_{L^2(\Omega)}^2 \big)
		\big( 1 + \|a\|_{L^2(\Omega)}^2 e^{C \|a\|_{L^2(\Omega)}^2} \big) =: B_1(a).
\end{aligned}
\end{equation}

ref_dict.eq: PEs:
\begin{equation} \label{eq: PEs}
\begin{aligned}
	\partial_t v + u \cdot \nabla v - \Delta v + \nabla_H\pi &= 0 \qquad \text{ in }\; \Omega \times (0, T), \\
	\partial_z\pi & = 0  \qquad \text{ in }\; \Omega \times (0, T), \\
	\mathrm{div}\,u & = 0  \qquad \text{ in }\; \Omega \times (0, T),
\end{aligned}
\end{equation}

ref_dict.main prop:
\begin{prop} \label{main prop}
	If $a \in H^1(\Omega) \cap L^8(\Omega)$, $a_z \in L^4(\Omega)$, $\operatorname{div}_H \bar a = 0$, and the horizontal periodicity of $a$ hold, then the solution of \eref{eq: PEs}--\eref{eq: initial condition} with \eref{eq: Neumann BC} satisfies 
	\begin{equation*}
		\|v(t)\|_{H^1(\Omega)} \le B(a, t) e^{C (\sqrt{t} + 1) \|a\|_{L^2(\Omega)}^2} \quad \forall t \in [0, T],
	\end{equation*}
	where $B(a, t)$ is a polynomial functions of $\|a\|_{H^1(\Omega)}, \|a\|_{L^8(\Omega)}, \|a_z\|_{L^4(\Omega)}, \sqrt{t}$, and $C$ is a positive constant dependent only on $\Omega$.
\end{prop}

