	Then the solution of \eref{eq: PEs}--\eref{eq: initial condition} with \eref{eq: Neumann BC} or \eref{eq: Dirichlet BC} satisfies 
	\begin{equation*}
		\|v(t)\|_{H^1(\Omega)}^2 + \int_0^t \|\nabla^2 v(s)\|_{L^2(\Omega)}^2 \, ds \le B(a) e^{C \|a\|_{L^2(\Omega)}^2} \quad \forall t \in [0, T],
