As a building block to prove the theorem above, we first obtain in \sref{sec: proof of main prop} the following result for the Neumann BC case.
\begin{prop} \label{main prop}
 If $a \in H^1(\Omega) \cap L^8(\Omega)$, $a_z \in L^4(\Omega)$, $\operatorname{div}_H \bar a = 0$, and the horizontal periodicity of $a$ hold, then the solution of \eref{eq: PEs}--\eref{eq: initial condition} with \eref{eq: Neumann BC} satisfies 
 \begin{equation*}
 \|v(t)\|_{H^1(\Omega)} \le B(a, t) e^{C (\sqrt{t} + 1) \|a\|_{L^2(\Omega)}^2} \quad \forall t \in [0, T],
 \end{equation*}
 where $B(a, t)$ is a polynomial functions of $\|a\|_{H^1(\Omega)}, \|a\|_{L^8(\Omega)}, \|a_z\|_{L^4(\Omega)}, \sqrt{t}$, and $C$ is a positive constant dependent only on $\Omega$.
\end{prop}

\subsection{Step 1: estimates for $v \in L^\infty_t L^4(\Omega)$ and $v_z \in L^\infty_t L^2(\Omega)$}
The energy equality \eref{eq: energy equality} remains the same, and we also have $\int_0^t \|v\|_{H^1(\Omega)}^2 \, ds \le C \|a\|_{L^2(\Omega)}^2 \, (\forall t \ge 0)$ as a result of the Poincar\'e inequality.
Addressing $\pi_1$ in the same way as before, in place of \eref{eq: start of Lq estimate} for $q = 4$ we obtain
\begin{equation} \label{eq2: proof of main thm for Dirichlet BC case}
 \frac14 \frac{d}{dt} \|v\|_{L^4(\Omega)}^4 + \frac38 \big\| \nabla |v|^2 \big\|_{L^2(\Omega)}^2 + \big\| |v| |\nabla v| \big\|_{L^2(\Omega)}^2 \le C (\|\nabla_H v\|_{L^2(\Omega)}^2 + \|\nabla_H v\|_{L^2(\Omega)}) \|v\|_{L^4(\Omega)}^4 - \Big( \nabla_H \pi_2, \int_{-h}^0 |v|^2 v \, dz \Big)_G.
\end{equation}
By the estimate of $\nabla_H \pi_2$ mentioned above and a trace inequality, we estimate the last term as
\begin{equation} \label{eq1: proof of main thm for Dirichlet BC case}
 C \|v_z\|_{L^2(\Gamma_b)} \int_{-h}^0 \big\| |v|^3 \big\|_{L^2(G)} dz \le C \|v_z\|_{L^2(\Omega)}^{1/2} \|\nabla v_z\|_{L^2(\Omega)}^{1/2}
 \int_{-h}^0 \big\| |v|^2 \big\|_{L^3(G)}^{3/2} \, dz.
\end{equation}
Since $H^{1/3}(G) \hookrightarrow L^3(G)$, we have
\begin{align*}
 \big\| |v|^2 \big\|_{L^3(G)}^{3/2} &\le C \big\| |v|^2 \big\|_{L^2(G)} \big( \big\| |v|^2 \big\|_{L^2(G)} + \big\| \nabla_H |v|^2 \big\|_{L^2(G)} \big)^{1/2} \\
 &\le C \|v\|_{L^4(G)}^2 \big( \|v\|_{L^4(G)} + \big\| \nabla_H |v|^2 \big\|_{L^2(G)}^{1/2} \big).
\end{align*}
Hence the right-hand side of \eref{eq1: proof of main thm for Dirichlet BC case} is bounded by
\begin{align*}
 &C \|v_z\|_{L^2(\Omega)}^{1/2} \|\nabla v_z\|_{L^2(\Omega)}^{1/2} \cdot \|1\|_{L^4_z}
 C \|v\|_{L^4(\Omega)}^2 \big( \|v\|_{L^4(\Omega)} + \big\| \nabla_H |v|^2 \big\|_{L^2(\Omega)}^{1/2} \big) \\
 \le \; & \frac1{10} \|\nabla v_z\|_{L^2(\Omega)}^2 + \frac1{8} \big\| \nabla_H |v|^2 \big\|_{L^2(\Omega)}^2
 + C\|v_z\|_{L^2(\Omega)} \|v\|_{L^4(\Omega)}^4 + C\|v_z\|_{L^2(\Omega)}^{2/3} \|v\|_{L^4(\Omega)}^4.
\end{align*}
This together with \eref{eq2: proof of main thm for Dirichlet BC case}, with $\|v\|_{L^4(\Omega)} \le C \|v\|_{H^1(\Omega)}$, and with $\alpha^2 \beta^3 \le \frac34 \alpha^2 \beta^4 + \frac14 \alpha^2$ leads to
\begin{equation} \label{end of L4 estimate for Dirichlet BC case}
 \frac14 \frac{d}{dt} \|v\|_{L^4(\Omega)}^4 + \frac28 \big\| \nabla |v|^2 \big\|_{L^2(\Omega)}^2 + \big\| |v| |\nabla v| \big\|_{L^2(\Omega)}^2 \le C \|v\|_{H^1(\Omega)}^2 (\|v\|_{L^4(\Omega)}^4 + 1) + \frac1{10} \|\nabla v_z\|_{L^2(\Omega)}^2.
\end{equation}

\section{Proof of \tref{sec1: proof of main thm} for Neumann BC case} \label{sec2: proof of main thm}
Let us return to the Neumann BC case \eref{eq: Neumann BC} and eliminate the factor $e^{\sqrt t}$ from the upper bound of \pref{main prop}.
The cause of this factor is the lower-order term $\|\nabla_H v\|_{L^2(\Omega)} \|v\|_{L^q(\Omega)}^q$ in \eref{eq: lower-order term in Lq estimate}.
To address it we desire a Poincar\'e-type inequality and an embedding $H^1(\Omega) \hookrightarrow L^q(\Omega)$.
For this reason we employ an $L^6(\Omega)$-estimate as in \sref{sec1: proof of main thm} for $\tilde v = v - \bar v$, instead of $v$ itself, which satisfies
\begin{equation} \label{eq: Poincare for tilde v}
 \|\tilde v\|_{L^q(\Omega)} \le C \|v_z\|_{L^q(\Omega)} \quad (q \in [1, \infty]).
\end{equation}
The above inequality follows from integration in $G$ of the one-dimensional Wirtinger inequality
\begin{equation*}
 \int_{-h}^0 |\tilde v(x, y, z)|^q \, dz \le h^q \int_{-h}^0 |v_z(x, y, z)|^q \, dz \quad \text{a.e.} \; (x, y) \in G.
\end{equation*}
We also observe that $\tilde v$ satisfies (cf.\ \cite[(6.4)]{HiKa2016})
\begin{equation*}
 \partial_t \tilde v - \Delta \tilde v + u \cdot \nabla \tilde v = - \tilde v \cdot \nabla_H \bar v + \frac1h \int_{-h}^0 \operatorname{div}_H (\tilde v \otimes \tilde v) \, dz \quad \text{in} \quad \Omega \times (0, T).
\end{equation*}

post_theorem_intro_text:
\begin{rem}
	(i) Since the above $H^1$-bound is independent of $T$, one can even have
	\begin{equation*}
		\|v(t)\|_{H^1(\Omega)}^2 + \int_0^\infty \|\nabla^2 v(s)\|_{L^2(\Omega)}^2 \, ds \le B(a) e^{C \|a\|_{L^2(\Omega)}^2} \quad \forall t \in [0, \infty).
	\end{equation*}

	(ii) $B(a)$ actually depends on $\|a\|_{L^4(\Omega)}$ and $\|a\|_{L^6(\Omega)}$ (see e.g.\ (\ref{eq: L4 estimate for v in Drichlet BC case}) below), which can be bounded by $\|a\|_{H^1(\Omega)}$ in virtue of the Sobolev embedding theorem.

	(iii) For the Neumann BC case, since $\int_\Omega a \, dxdydz \neq 0$ in general, we do not expect for $v$ to satisfy the Poincar\'{e} inequality as in \cite[(3.174) and (3.279)]{PTZ09}.
	To the best of our knowledge, a uniform-in-time $H^1$-upper bound for such a situation was not shown in the existing literature.

	(iv) For the Dirichlet BC case, if the Poincar\'e inequality is taken into account, an exponential decaying bound as $t \to \infty$ could be derived.
	Nevertheless it is not directly addressed in this paper.
\end{rem}

As a building block to prove the theorem above, we first obtain in Section \ref{sec: proof of main prop} the following result for the Neumann BC case.
\begin{prop} \label{main prop}
	If $a \in H^1(\Omega) \cap L^8(\Omega)$, $a_z \in L^4(\Omega)$, $\operatorname{div}_H \bar a = 0$, and the horizontal periodicity of $a$ hold, then the solution of (\ref{eq: PEs})--(\ref{eq: initial condition}) with (\ref{eq: Neumann BC}) satisfies 
	\begin{equation*}
		\|v(t)\|_{H^1(\Omega)} \le B(a, t) e^{C (\sqrt{t} + 1) \|a\|_{L^2(\Omega)}^2} \quad \forall t \in [0, T],
	\end{equation*}
	where $B(a, t)$ is a polynomial functions of $\|a\|_{H^1(\Omega)}, \|a\|_{L^8(\Omega)}, \|a_z\|_{L^4(\Omega)}, \sqrt{t}$, and $C$ is a positive constant dependent only on $\Omega$.
\end{prop}

The proof of Proposition \ref{main prop}, in which we utilize the $L^4(\Omega)$- and $L^8(\Omega)$-estimates for $v$ as well as $L^2(\Omega)$- and $L^4(\Omega)$-estimates for $v_z$, is more straightforward than that of Theorem \ref{main thm}.
In fact, the dissipative parts associated with those estimates are nicely consistent in dealing with the ``most difficult nonlinearity'' of the primitive equations, i.e., $w v_z$ (see (\ref{eq1: treatment of wv_z}) and (\ref{eq2: treatment of wv_z}) below).
However, there are two drawbacks with this approach: 1) the technique is not directly applicable to the Dirichlet BC case, and 2) the bound depends on $t$.

In Section \ref{sec1: proof of main thm} we overcome the first difficulty and prove Theorem \ref{main thm} for the Dirichlet BC case.
The idea is to make use of the $L^6(\Omega)$-estimate for $v$ and $L^3(\Omega)$-estimate for $v_z$ (instead of $L^8$- and $L^4$-estimates).
Employing a similar strategy, in Section \ref{sec2: proof of main thm} we eliminate time dependency from the $H^1$-upper bound and prove Theorem \ref{main thm} for the Neumann BC case.
Since the main issue here is treatment of ``lower order terms'' (see e.g.\ (\ref{eq: treatment of lower-order term})), a Poincar\'e-type inequality is a key ingredient for this observation.
Thus we are led to consider $L^4(\Omega)$- and $L^6(\Omega)$-estimates for $\tilde v = v - \bar v$ in place of $v$, which satisfies $\|\tilde v\|_{L^2(\Omega)} \le h \|v_z\|_{L^2(\Omega)}$ (cf.\ \cite[(6.4)]{GGHHK2020}).

We will exploit the standard notation of the Lebesgue spaces $L^p(D)$ and the Sobolev spaces $W^{s, p}(D)$ in a Lipschitz domain $D$.
Norms of a function $f$ in isotropic spaces are denoted as
\begin{equation*}
	\|f\|_{L^p_z L^q_{x, y}} = \Big( \int_{-h}^0 \|f(z)\|_{L^q(G)}^p \, dz \Big)^{1/p} = \Big( \int_{-h}^0 \Big( \int_G |f(x, y, z)|^q \, dxdy \Big)^{p/q} \, dz \Big)^{1/p},
\end{equation*}
with appropriate modifications for the cases $p, q = \infty$.
For integration in $\Omega$ and $G$, we will omit the symbols of volume elements, i.e., $dx dy dz$ and $dx dy$.
The $L^2$-inner products in $\Omega$ and $G$ are denoted by $(\cdot, \cdot)_\Omega$ and $(\cdot, \cdot)_G$, respectively.

Finally, we recall the Gronwall inequality of the following form: if nonnegative functions $y(t), z(t), \alpha(t)$, and $\beta(t)$ satisfy $\frac{dy}{dt}(t) + z(t) \le \alpha(t) y(t) + \beta(t)$ for $t > 0$, then for all $t \ge 0$ we have
\begin{align*}
	y(t) &\le \Big( y(0) + \int_0^t \beta(s) \, ds \Big) e^{\int_0^t \alpha(s) \, ds}, \\ 
	y(t) + \int_0^t z(s) \, ds &\le \Big( y(0) + \int_0^t \beta(s) \, ds \Big) \Big(1 + \int_0^t \alpha(s) \, ds \, e^{\int_0^t \alpha(s) \, ds} \Big).
\end{align*}

