\begin{theorem}[Corollary \ref{hyperelliptic}]\label{hypell}
    Let $X$ be a smooth projective variety that admits an \'etale Galois cover $Y\to X$, where $Y$ is an abelian variety.
    Then the set-theoretic image of $h^r:M^r_{X,\text{Dol}}\to A^{r,\Omega^1_X}_X$ coincides with the subset $(H^0(Y,\Omega^1_Y)^r\sslash S_r)^G$
    of $A^{r,\Omega^1_Y}_Y$, where $G:=\gal(Y/X)$ and $S_r$ denotes the symmetric group in $r$ letters.

    In particular, if $X$ is an abelian variety, we have $\mathrm{im}(h^r)=H^0(X,\Omega^1_X)^r\sslash S_r$.
\end{theorem}

theorem.content:
\label{thm: simplicial + T(6) implies CAT(0)}
    Let $G=\langle f: \Gamma \rightarrow \Theta\rangle$ be a $T(q)$ graphical small cancellation presentation with $Girth(\Gamma)\geq p$, where $Girth(\Gamma)$ denotes the length of a shortest cycle in $\Gamma$, and let $X$ be the non-thickened graphical complex associated to this presentation. 
    \begin{enumerate}[label=(\arabic*)]
        \item If $(p,q)=(3,6)$, then $X$ admits a locally CAT(0) metric.
        \item If $(p,q)\in \{(4,5), (3,7)\}$, then $X$ admits a locally CAT(-1) metric.
    \end{enumerate}

ref_dict.cor: C(3) + T(6) implies CAT(0):
\begin{corollary}\label{cor: C(3) + T(6) implies CAT(0)}
    Let $\langle f:\Gamma\rightarrow \Theta\rangle$ be a $C(p)$-$T(q)$ graphical small cancellation presentation, then the associated non-thickened graphical complex $X$ can be endowed with a locally CAT(0) metric when $(p,q)=(3,6)$ and a locally $CAT(-1)$ metric when $(p,q)\in \{(3,7), (4,5)\}$.
\end{corollary}

ref_dict.thm: simplicial + T(6) implies CAT(0):
\begin{theorem}\label{thm: simplicial + T(6) implies CAT(0)}
    Let $G=\langle f: \Gamma \rightarrow \Theta\rangle$ be a $T(q)$ graphical small cancellation presentation with $Girth(\Gamma)\geq p$, where $Girth(\Gamma)$ denotes the length of a shortest cycle in $\Gamma$, and let $X$ be the non-thickened graphical complex associated to this presentation. 
    \begin{enumerate}[label=(\arabic*)]
        \item If $(p,q)=(3,6)$, then $X$ admits a locally CAT(0) metric.
        \item If $(p,q)\in \{(4,5), (3,7)\}$, then $X$ admits a locally CAT(-1) metric.
    \end{enumerate}
\end{theorem}

full_context:
Graphical small cancellation is a generalization of the classical small cancellation theory. It provides a method for constructing groups whose Cayley graphs contain certain prescribed graphs, giving rise to groups with interesting properties; see, for example, \cite{Gro-random, OW-Kazhdan, Osajda20, Coulon-Gruber, Osajda-residual}.

A graphical presentation of a group has the form $G=\langle f: \Gamma \rightarrow \Theta \rangle$, where $\Theta$ is a connected graph, $f:\Gamma \rightarrow \Theta$ is a graph immersion (that is, a locally injective graph homomorphism), and $G$ is the fundamental group of $\Theta$ modulo the normal subgroup generated by the images of all immersed cycles in $\Gamma$. 
The use of such presentations goes back to the work of Rips and Segev, who constructed torsion-free groups without the unique product property (see \cite{RS-torsion,Steenbock-torsion}). Small cancellation theory over graphical presentations was later used explicitly by Gromov \cite{Gro-random} in his construction of Gromov's monster---a group that contains an expander graph in a weak sense.

There are two 2-dimensional combinatorial complexes naturally associated to such a presentation: the thickened graphical complex $X_t$, where 2-cells are attached to $\Theta$ to fill the cycles coming from $\Gamma$, and the non-thickened graphical complex $X$, where cones over the connected components of $\Gamma$ are attached to $\Theta$ instead. 
In the latter case, each cone is triangulated so that $X$ admits a 2-dimensional combinatorial complex structure where all 2-cells are triangles.
Both complexes have $G$ as their fundamental group. Precise definitions will be given in Section~\ref{sec: prelimiaries}.

Since Gromov's introduction of hyperbolic groups \cite{Gro87}, the interaction between small cancellation and nonpositive or negative curvature has been an active area of study.
In this article, we focus on non-metric small cancellation conditions.
A classical result by Gersten and Short \cite{GS90} states that classical $C(p)$-$T(q)$ small cancellation groups are hyperbolic when $1/p+1/q<1/2$. 
In the borderline case $1/p+1/q=1/2$, that is, when $(p,q)\in \Set{(3,6),(4,4),(6,3)}$, various links between small cancellation and metric or combinatorial nonpositive curvature have been established: 
classical $C(6)$ groups are systolic \cite{Wise03}, a result extended to the graphical setting in \cite{OP18}; 
graphical $C(4)$-$T(4)$ groups are Helly \cite{Hoda-quadric,CCGHO25}; 
and classical $C(3)$-$T(6)$ groups are CAT(0) \cite{Pride88, BH13, Duda21}. 
In this paper, we extend the last result to the graphical setting.

The proofs rely on the link condition for 2-dimensional complexes. We first show that small cancellation conditions provide lower bounds on the girth of the links in a graphical complex $X$. We then endow every 2-cell in $X$ with a Euclidean or hyperbolic metric and show that $X$ satisfies the link condition.

\begin{definition}
 Let $p,q\in \mathbb{N}_{>0}$. The thickened graphical complex $X_t$ associated to a graphical presentation $G=\langle f:\Gamma \rightarrow \Theta\rangle$ satisfies:
 \begin{itemize}
 \item the \textbf{$C(p)$ small cancellation condition} if there is no immersed cycle $C\rightarrow\Gamma$ such that the composition $C\rightarrow \Gamma \rightarrow \Theta$ is a concatenation of fewer than $p$ pieces in $X_t$;
 \item the \textbf{$T(q)$ small cancellation condition} if for every reduced disk diagram $D\rightarrow X_t$, there is no interior vertex of $D$ whose degree is greater than 2 and less than $q$. 
 \end{itemize} 
 A presentation $\langle f:\Gamma \rightarrow \Theta \rangle$ and its associated non-thickened graphical complex $X$ are said to satisfy the $C(p)$ (respectively, $T(q)$) condition if the associated thickened complex $X_t$ does.
\end{definition}

\begin{lemma} \label{Lem: pieces have length 1}
 Let $\langle f:\Gamma \rightarrow \Theta\rangle$ be a $T(q)$ graphical small cancellation presentation with $q\geq 5$, then every piece in the associated thickened graphical complex $X_t$ has length 1.
\end{lemma}

Second, we show that there is no immersed cycle in $Lk(v,X)$ whose length is greater than 4 and less than $2q$. 
 We discuss only the case of length 6, since the general case is analogous, with heavier notation. 
 Suppose, for contradiction, that $Lk(v,X)$ contains an immersed cycle of length 6, with vertices representing directed edges $\vec{e}_1$, $\vec{e}_2$, $\vec{e}_3$, $\vec{e}_4$, $\vec{e}_5$, $\vec{e}_6$, which connect $v$ to $v_i$, $w$, $v_j$, $x$, $v_k$, $u$, where $v_i, v_j, v_k\in V_{tip}(X)$ and $u,w,x\in V(\Theta)$. In $Cone(\Gamma_i)$, let $(v',v_i)$ be the lift of $\vec{e}_1$, and denote the lifts of the corners corresponding to $\{\vec{e}_1,\vec{e}_6\}$ and $\{\vec{e}_1,\vec{e}_2\}$ by $\angle v_i v' u'$ and $\angle v_i v' w'$ for some $u',w'\in \Gamma_i$. 
 Similarly, in $Cone(\Gamma_j)$, let $(v'',v_j)$ be the lift of $\vec{e}_3$, and denote the lifts of the corners corresponding to $\{\vec{e}_3,\vec{e}_2\}$ and $\{\vec{e}_3,\vec{e}_4\}$ by $\angle v_j v'' w''$ and $\angle v_i v'' x''$, for some $w'', x''\in \Gamma_j$. 
 Finally, in $Cone(\Gamma_k)$, let $(v''',v_k)$ be the lift of $\vec{e}_5$, and denote the lifts of the corners corresponding to $\{\vec{e}_5,\vec{e}_4\}$ and $\{\vec{e}_5,\vec{e}_6\}$ by $\angle v_k v''' x'''$ and $\angle v_k v''' u'''$, for some $x''', u'''\in \Gamma_k$; see Figure \ref{fig:Six cycle in the link}.
 \begin{figure}
 \centering
 \includegraphics[width=0.6\linewidth]{Six_cycle_in_the_link.jpg}
 \caption{6-cycle in $Lk(v,X)$}
 \label{fig:Six cycle in the link}
 \end{figure}
 Let $\gamma_1: P_2\rightarrow \Gamma_i$ be the path from $u'$ to $w'$ via $v'$; $\gamma_2: P_2\rightarrow \Gamma_j$ the path from $w''$ to $x''$ via $v''$; and $\gamma_3: P_2\rightarrow \Gamma_k$ the path from $x'''$ to $u'''$ via $v'''$. 
 Since we began with an immersed cycle in $Lk(v,X)$, each $\gamma_\ell$ is immersed.
 Because $\Gamma$ is path-cycle extensible, for each $\gamma_\ell$, there exists an immersed cycle $\tau_\ell: C_{m_\ell} \rightarrow \Gamma$, $m_\ell\geq 3$, such that $\tau_\ell\circ \gamma_{2,m_\ell}=\gamma_\ell$. 
 Let $R_{m_\ell}\rightarrow X_t$ be the 2-cell in the thickened graphical complex $X_t$ corresponding to the cycle $C_{m_\ell}\rightarrow \Gamma$. 
 Construct a jasmine diagram $D$ with three petals by taking the disjoint union $\coprod_{\ell=1}^3 R_{m_\ell}$ and identifying $\gamma_{2,m_1}\big((0,1)\big)\sim \gamma_{2,m_3}\big((2,1)\big)$, $\gamma_{2,m_2}\big((0,1)\big)\sim \gamma_{2,m_1}\big((2,1)\big)$, $\gamma_{2,m_3}\big((0,1)\big)\sim \gamma_{2,m_2}\big((2,1)\big)$, as illustrated in Figure \ref{fig:Disk diagram with three petals}.
 \begin{figure}
 \centering
 \includegraphics[width=0.25\linewidth]{Disk_diagram_with_three_petals.jpg}
 \caption{Disk diagram with three petals in $X_t$}
 \label{fig:Disk diagram with three petals}
 \end{figure}
 The inclusions $R_{m_\ell}\rightarrow X_t$ induce a map $D\rightarrow X_t$.
 Because the cycle in $Lk(v,X)$ is immersed, the edges $(v',w')$ and $(v'',w'')$ are distinct, so $\vec{e}_2$ is a piece. 
 Similarly, $\vec{e}_4$ and $\vec{e}_6$ are also pieces. 
 It follows that $D\rightarrow X_t$ is a reduced disk diagram. 
 However, $D$ contains an interior vertex of degree 3, contradicting the assumption that $\langle f:\Gamma \rightarrow \Theta\rangle$ is a $T(q)$ small cancellation presentation with $q\geq 4$. 
 Thus, no immersed cycle of length 6 can occur in $Lk(v,X)$. 
 The general case follows by an analogous argument.

\begin{proof}[Proof of Theorem \ref{thm: simplicial + T(6) implies CAT(0)}]\label{proof: main theorem}
 Let $\langle f:\Gamma \rightarrow \Theta\rangle$ be a $T(q)$ graphical presentation with $Girth(\Gamma)\geq p$, and let $X$ be the associated non-thickened graphical complex. 
 Recall that $X = \coprod_\lambda R^\lambda_3 / \sim$ can be realized as a quotient of a disjoint union of triangles. 
 Following the notation introduced in the paragraph preceding Lemma \ref{lem:T condition and the links}, for each $\lambda$, each triangle $R^\lambda_3$ has exactly two edges mapped to $E_{tip}(X)$ and one edge mapped to $E(\Theta)$. 
 For every $v\in V_{tip}(X)$, the link $Lk(v,X)$ is isomorphic to the component of $\Gamma$ corresponding to $v$.
 Hence, $Girth(\Gamma)\geq p$ implies $Girth\big(Lk(v,X)\big)\geq p$. 
 For $v\in V(\Theta)$, Lemma \ref{lem:T condition and the links} shows that if $\langle f:\Gamma \rightarrow \Theta\rangle$ is a $T(q)$ graphical presentation with $q\geq 5$, then $Girth\big(Lk(v,X)\big)\geq 2q$.

\begin{corollary}\label{cor: C(3) + T(6) implies CAT(0)}
 Let $\langle f:\Gamma\rightarrow \Theta\rangle$ be a $C(p)$-$T(q)$ graphical small cancellation presentation, then the associated non-thickened graphical complex $X$ can be endowed with a locally CAT(0) metric when $(p,q)=(3,6)$ and a locally $CAT(-1)$ metric when $(p,q)\in \{(3,7), (4,5)\}$.
\end{corollary}

To begin, we describe subdivisions of $\Gamma$ and $\Theta$, such that the subdivision of $\Gamma$ has girth at least $p$. 
 Define 
 \begin{align*}
 E_1(\Theta) &\coloneqq \{e\in E(\Theta): f^{-1}(e) \ \text{is a single edge}\} \\
 E_1(\Gamma) &\coloneqq \{e\in E(\Gamma): f(e)\in E_1(\Theta)\}.
 \end{align*}
 Subdivide every edge in $E_1(\Theta)$ and in $E_1(\Gamma)$ into $p$ edges, and denote the resulting subdivisions of $\Gamma$ and $\Theta$ by $\Gamma'$ and $\Theta'$, respectively. 
 There is a canonical graph immersion $f': \Gamma'\rightarrow \Theta'$ induced by $f$, and the non-thickened graphical complex $X'$ associated to $\langle f':\Gamma'\rightarrow \Theta'\rangle$ is a subdivision of $X$. 
 Equip $X'$ with a piecewise Euclidean (or hyperbolic) metric $d$ as in the proof of Theorem \ref{thm: simplicial + T(6) implies CAT(0)}, so that every corner at a cone tip $v\in V_{tip}(X')$ has angle $\frac{2\pi}{p}$, and every other corner has angle $\frac{\pi}{q}$. 
 To show that $d$ is locally CAT(0) (respectively, CAT(-1)), it suffices to verify that $Girth(Lk(v,X'))\geq p$ for all $v\in V_{tip}(X')$, and $Girth(Lk(v,X'))\geq 2q$ for all $v\in V(\Theta')$.

post_theorem_intro_text:
The proofs rely on the link condition for 2-dimensional complexes. We first show that small cancellation conditions provide lower bounds on the girth of the links in a graphical complex $X$. We then endow every 2-cell in $X$ with a Euclidean or hyperbolic metric and show that $X$ satisfies the link condition.

Note that any graphical presentation satisfying the assumptions of either statement of Theorem~\ref{thm: simplicial + T(6) implies CAT(0)} also satisfies the corresponding $C(p)$ small cancellation condition. 
If instead we start with the weaker assumption that a graphical presentation is $C(p)$-$T(q)$, then we can sightly modify the proof of Theorem~\ref{thm: simplicial + T(6) implies CAT(0)} so that the conclusions of the theorem still hold; see Corollary~\ref{cor: C(3) + T(6) implies CAT(0)}.

We now consider group actions on simply connected graphical complexes. Let $\widetilde{X}$ be a simply connected non-thickened graphical complex associated to a $C(p)$-$T(q)$ graphical presentation with $(p,q)\in\{(3,6),(4,5)\}$. Then it can be subdivided into a triangle complex $\widetilde{X}'$ (i.e., a 2-dimensional simplicial complex) and endowed with a piecewise Euclidean metric that is CAT(0), recurrent (in the sense of \cite[Definition 2.1]{OP21-recurrent}), and has rational angles (in the sense of \cite{NOP22-torsion}). 

Let $G$ be a group acting on $\widetilde{X}$ by automorphisms (see the definition in Section \ref{sec: prelimiaries}), then it also acts on $\widetilde{X}'$ by combinatorial automorphisms and by isometries with respect to the given metric. Therefore, either by the recurrent structure and \cite[Main Theorem]{OP21-recurrent} or by the CAT(0) structure and \cite[Theorem A]{OP22-Tits}, we obtain:  

\begin{corollary}\label{cor:Tits alternative}
    If the action is almost free (that is, there is a uniform bound on the cardinalities of all cell stabilizers), then $G$ satisfies the Tits alternative; more precisely, every finitely generated subgroup of $G$ is either virtually cyclic, virtually $\mathbb{Z}^2$, or contains a nonabelian free group. In particular, graphical $C(p)$-$T(q)$ small cancellation groups satisfy the Tits alternative for $(p,q)\in \{(3,6),(4,5)\}$.
\end{corollary}  

Additionally, since $\widetilde{X}'$ is a CAT(0) triangle complex with rational angles, applying \cite[Theorem 1.1]{NOP22-torsion}, we obtain the following, which proves a particular case of \cite[Meta-Conjecture, Conjecture]{HO-elliptic}:

\begin{corollary}\label{cor:fixed point}
    If $G$ is finitely generated and every element of $G$ fixes a cell in $\widetilde{X}$, then the entire group $G$ fixes a cell in $\widetilde{X}$. 
\end{corollary}

The paper is organized as follows. In Section \ref{sec: prelimiaries}, we recall the relevant definitions from graphical small cancellation theory; in Section \ref{sec: Small cancellation condition T}, we discuss several implications of the graphical small cancellation condition $T$, in particular how it bounds the girth of some links in a graphical complex; finally, in Section \ref{sec: Proof of the results}, we prove Theorem \ref{thm: simplicial + T(6) implies CAT(0)} and the corollaries.

