Our first result shows that solutions to the system converge smoothly whenever there is a uniform bound on the family of metrics and uniqueness of a cscK metric in the K\"ahler class of the initial metric:

\begin{remark}\label{convergencewhenc1negative}
 If $c_1(X) < 0$ and $\hat \omega \in -r c_1(X)$ for some $r > 0$ or $c_1(X) = 0$ then the hypothesis that $[\hat \omega]$ contains at most one cscK metric is satisfied, since in these cases cscK metrics are K\"ahler-Einstein and are unique in their classes.
\end{remark}

\begin{theorem}[Smooth convergence on Riemann surfaces]\label{riemannsurfacesconvergencefromclass}
 Let $X$ be a Riemann surface with $c_1(X) < 0$, $A \in H^{1,1}(X, \mathbb{R})$ and $\hat \omega$ a K\"ahler metric satisfying \ref{A1}. Then there is an open set of $\hat \alpha \in A$ in the topology of the uniform norm for which the system \eqref{system1}, \eqref{system2} has a unique solution on $[0, \infty)$ which converges smoothly to the unique cscK metric $\omega_\infty$ in $[\hat \omega]$ and the unique $\omega_\infty$-harmonic $(1, 1)$-form $\alpha_\infty$ in $A$.
\end{theorem}

The condition $-c_1(X) + \lambda \Omega + A = 0$ allows us to write
\begin{equation}\label{riccipotential1}
 -\Ric(\omega) + \lambda \omega + \alpha = i \ddb F
\end{equation}
for a function $F(t)$; write $\hat F = F(0)$. In particular
\begin{equation}\label{riccipotential2}
 -R + \lambda n + \tau = \Delta F
\end{equation}
and
\begin{equation}\label{averages}
 -\underline R + \lambda n + \underline \tau = 0.
\end{equation}
This shows that
\begin{equation}\label{lambda}
 \lambda = \frac{1}{n} ( \underline R - \underline \tau ) = \frac{1}{V} \int_X (c_1(X) - A) \wedge \Omega^{n - 1}
\end{equation}
We now prove short-time of existence of solutions:
\begin{lemma}[Short-time existence]\label{shorttimeexistence}
 Let $\hat \omega$ be a K\"ahler metric and $\hat \alpha$ a closed $(1, 1)$-form satisfying $-c_1(X) + \lambda [\hat \omega] + [\hat \alpha] = 0$. Assume that $\omega(t)$, $\alpha(t)$ solve \eqref{system1}, \eqref{system2} on $[0, T)$ for some $T \in (0, \infty)$. Then $\omega(t)$, $\alpha(t)$ can be extended to a solution on $[0, T + \varepsilon)$ for some $\varepsilon > 0$.
\end{lemma}

\begin{lemma}[Higher order estimates]\label{higherorderestimates}
 Let $\hat \omega$, $\hat \alpha$ be a K\"ahler metric and a closed $(1, 1)$-form satisfying $-c_1(X) + \lambda [\hat \omega] + [\hat \alpha] = 0$ with $\lambda \leq 0$. If the system \eqref{system1}, \eqref{system2} satisfies an a priori estimate of the form
 \begin{equation}\label{uniformequivalence}
 C^{-1} \hat \omega \leq \omega(t) \leq C \hat \omega
 \end{equation}
 then we have the following a priori potential estimates for each $k = 0, 1, \dotsc$
 \begin{equation*}
 \| \varphi(t) \|_{C^k} \leq C_k, \quad \| f(t) \|_{C^k} \leq C_k.
 \end{equation*}
\end{lemma}

\begin{proof}[Proof of \cref{convergence}]
 By \cref{higherorderestimates} we obtain $C^k$ estimates of all orders on $\varphi$, $f$. These estimates together with \cref{shorttimeexistence} imply, by the method of continuity, that the set of $t$ for which the system is solvable is both open and closed in $[0, \infty)$ and thus that it is the entire interval. After two applications of the Arzela-Ascoli theorem we obtain a sequence $t_j \to \infty$ such that $\varphi(t_j)$, $f(t_j)$ converge smoothly to functions $\varphi_\infty$, $f_\infty$. Let $\omega_\infty = \hat \omega + i \ddb \varphi_\infty$ and $\alpha_\infty = \hat \alpha + i \ddb f_\infty$. Note $\omega_\infty > 0$ since $\omega \geq C^{-1} \hat \omega$; thus $\omega_\infty \in \Omega$ is a K\"ahler metric and $\alpha_\infty \in A$ is a closed $(1, 1)$-form. Since the left-hand sides of \eqref{system1}, \eqref{system2} tend to zero \cref{stationarypoints} implies that $\omega_\infty$ is cscK and $\alpha_\infty$ is $\omega_\infty$-harmonic. By our assumption there is a unique cscK metric in $[\hat \omega]$, and by the Hodge theorem there is a unique $\omega_\infty$-harmonic $(1, 1)$-form in $[\hat \alpha]$. Thus $\omega_\infty$, $\alpha_\infty$ are independent of the choice of subsequence, so in fact $\omega$, $\alpha$ converge smoothly to $\omega_\infty$, $\alpha_\infty$.
\end{proof}

\begin{lemma}[A priori estimates for conformal factors]\label{conformalestimates}
 Let $X$ be a Riemann surface, $\hat \omega$ a K\"ahler metric, $\hat \alpha$ a closed $(1, 1)$-form, $\lambda = \int_X (c_1(X) - A) / \int_X [\hat \omega]$, and assume that $\hat \tau \maxx^+ - \hat \tau \minn^- < -\hat R \maxx$. Let $\phi(t)$, $\tau(t)$ be functions, set $\omega(t) = e^{\phi(t)} \hat \omega$, $\alpha(t) = \tau(t) \omega(t)$, and assume that $\phi(t)$, $\tau(t)$ solve \eqref{conformalsystem1b}, \eqref{conformalsystem2a} with $\phi(0) = 0$ on $[0, T)$ for some $T \in (0, \infty]$. Then $\lambda < 0$ and
 \begin{equation}\label{conformalestimates1}
 \| \phi(t) \|_{C^0} \leq C, \quad \| \tau(t) \|_{C^0} \leq C
 \end{equation}
 so
 \begin{equation}\label{conformalestimates2}
 C^{-1} \hat \omega \leq \omega(t) \leq C \hat \omega, \quad -C \omega(t) \leq \alpha(t) \leq C \omega(t)
 \end{equation}
 and also
 \begin{equation}\label{conformalestimates3}
 \| R(t) \|_{C^0} \leq C \left( 1 + \frac{1}{t} \right).
 \end{equation}
\end{lemma}

\begin{theorem}[Smooth convergence]\label{riemannsurfacesconvergence}
