\begin{theorem} \label{thm:excal_Slambda}
	For $n \geq 4$, let $0 < \lambda \leq \bar{\lambda}(n)$. Then there exists a vector field $Y \in \frX(S_{\lambda}')$ satisfying the following conditions:
	\begin{itemize}
		\item[(i)] $|Y(p)| \leq 1$, for all $p \in S_{\lambda}'$;
		\medskip
		\item[(ii)] $Y(p) = e_1$, for all $p \in S^0_{\lambda}$;
		\medskip
		\item[(iii)] $Y$ is smooth and $\div^{S_{\lambda}} Y = 0$ on $S_{\lambda}'$.
	\end{itemize}
\end{theorem}

