\begin{theorem}\label{thm12}
For all integers $k\geq 0$ and $n\geq -1$, we have
\begin{align}
 P^\ast(2^{4k}n+2^{4k+1}-1)&\equiv 0\pmod{2^{6k}},\label{eq13}\\
 P^\ast(2^{4k+1}n+2^{4k+2}-1)&\equiv 0\pmod{2^{6k+2}},\label{eq14}\\
 P^\ast(2^{4k+2}n+2^{4k+3}-1)&\equiv 0\pmod{2^{6k+3}},\label{eq15}\\
 P^\ast(2^{4k+3}n+2^{4k+4}-1)&\equiv 0\pmod{2^{6k+6}},\label{eq16}\\
 P^\ast(2^{4k+4}n+3\cdot 2^{4k+3}-1)&=0.\label{eq17}
\end{align}
\end{theorem}

\begin{theorem}\label{thm31}
For all $k\geq 1$, we have that
\begin{align}
 \sum_{n=-1}^\infty M(2^kn+2^{k+1}-1)q^n &= A_k\dfrac{f_1^4f_5^4}{q}-8A_{k-1}f_2^4f_{10}^4+5\cdot 2^kf_1f_2f_5^3f_{10}^3,\label{eq31}\\
 \sum_{n=-1}^\infty T^\ast(2^kn+2^{k+1}-2)q^n &= B_k\dfrac{f_1^4f_5^4}{q}-8B_{k-1}f_2^4f_{10}^4+5\cdot 2^kf_1f_2f_5^3f_{10}^3,\label{eq32}\\
 \sum_{n=-1}^\infty P^\ast(2^kn+2^{k+1}-1)q^n &= C_k\dfrac{f_1^4f_5^4}{q}-8C_{k-1}f_2^4f_{10}^4,\label{eq33}
\end{align}
where for $k\geq 2$, $P_k\in \{A_k, B_k\}$ and $C_k$ satisfy the recurrence 
\begin{align*}
 P_k &= -4P_{k-1}-8P_{k-2}+5\cdot 2^{k-1},\\
 C_k &= -4C_{k-1}-8C_{k-2},
\end{align*}
with initial values $B_0=0, A_0 =A_1=B_1=C_0=1$, and $C_1=-4$.
\end{theorem}

\begin{proof}
We only prove (\ref{eq31}), as the proofs of (\ref{eq32}) and (\ref{eq33}) are similar to that of (\ref{eq31}). We proceed by induction on $k$. In view of Lemmas \ref{lem22} and \ref{lem23}, we note that (\ref{eq31})--(\ref{eq33}) hold for $k=1$. Suppose (\ref{eq31}) holds for some $k\geq 2$. Dividing both sides of (\ref{eq31}) by $q^2$ and employing (\ref{eq23}), we find that
\begin{align}\label{eq34}
 \sum_{n=-3}^\infty &M(2^kn+2^{k+2}-1)q^n \nonumber\\
 &= A_k\dfrac{f_1^4f_5^4}{q^3}-8A_{k-1}\dfrac{f_2^4f_{10}^4}{q^2}+5\cdot 2^k\dfrac{f_1f_2f_5^3f_{10}^3}{q^2}\nonumber\\
 &= A_k\dfrac{f_1^4f_5^4}{q^3}-8A_{k-1}\dfrac{f_2^4f_{10}^4}{q^2}+5\cdot 2^k\dfrac{f_2f_{10}^3}{q^2}\left(f_2^3f_{10}-q\dfrac{f_2f_8^2f_{20}^6}{f_4^2f_{10}f_{40}^2}+2q^2f_4f_{20}^3-q^3\dfrac{f_4^4f_{10}f_{40}^2}{f_2f_8^2}\right).
\end{align}
We read the terms involving $q^{2n}$ in the expansion of (\ref{eq34}). We see from Lemma \ref{lem22} that
\begin{align*}
 \sum_{n=-1}^\infty &M(2^{k+1}n+2^{k+2}-1)q^n \\
 &= A_k\left(-4\dfrac{f_1^4f_5^4}{q}-8f_2^4f_{10}^4\right)-8A_{k-1}\dfrac{f_1^4f_5^4}{q}+5\cdot 2^k\dfrac{f_1^4f_5^4}{q}+5\cdot 2^{k+1}f_1f_2f_5^3f_{10}^3\\
 &= (-4A_k-8A_{k-1}+5\cdot 2^k)\dfrac{f_1^4f_5^4}{q}-8A_kf_2^4f_{10}^4+5\cdot 2^{k+1}f_1f_2f_5^3f_{10}^3\\
 &= A_{k+1}\dfrac{f_1^4f_5^4}{q}-8A_kf_2^4f_{10}^4+5\cdot 2^{k+1}f_1f_2f_5^3f_{10}^3,
\end{align*}
where the last equality follows from the definition of $A_k$. Thus, (\ref{eq31}) holds for $k+1$, so (\ref{eq31}) holds for all $k\geq 1$ by induction.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm11}]
We claim that for all $k\geq 1$ and $P_k\in \{A_k, B_k\}$, $P_k$ is divisible by $2^{k-1}$ but not by $2^k$. We prove this via strong induction on $k$. We compute $A_2=6$ and $B_2=-2$, so the claim holds for $k\in \{1,2\}$. Suppose now that the claim holds for all positive integers at most some $k\geq 3$. Write $P_k = 2^{k-1}a_k$ and $P_{k-1}=2^{k-2}b_k$ for some odd integers $a_k$ and $b_k$. We infer from the definition of $P_k$ that 
\begin{align*}
 P_{k+1} = -4P_k-8P_{k-1}+5\cdot 2^k = 2^k(-2a_k-2b_k+5).
\end{align*}
Since $5-2a_k-2b_k$ is odd, we obtain $2^k\mid P_k$ but $2^{k+1}\nmid P_k$. Thus, the claim holds for $k+1$, and hence for $k\geq 1$ by strong induction. Combining the above claim and the generating functions (\ref{eq31}) and (\ref{eq32}), we arrive at (\ref{eq11}) and (\ref{eq12}), respectively.
\end{proof}

\begin{lemma}\label{lem32}
For all integers $k\geq 0$, we have 
\begin{align*}
 C_{4k} &= (-64)^k,\\
 C_{4k+1} &= -4(-64)^k,\\
 C_{4k+2} &= 8(-64)^k,\\
 C_{4k+3} &= 0
\end{align*}
\end{lemma}

\begin{proof}
Using the definition of $C_k$, we observe that for all $k\geq 0$ and $r\in \{0,1,2,3\}$,
\begin{align}
 C_{4k+r+4}&+64C_{4k+r}\nonumber\\
 &= C_{4k+r+4}+4C_{4k+r+3}+8C_{4k+r+2}-4(C_{4k+r+3}+4C_{4k+r+2}+8C_{4k+r+1})\nonumber\\
 &+8(C_{4k+r+2}+4C_{4k+r+1}+8C_{4k+r})= 0.\label{eq35}
\end{align}
We see from (\ref{eq35}) that $C_{4k+r} = (-64)^kC_r$ for all $k\geq 0$ and $r\in \{0,1,2,3\}$. In view of the computed values $C_2=8$ and $C_3=0$, we arrive at the desired values of $C_k$. 
\end{proof}

