\begin{con}[{\cite{N26}}]\label{ncon}
Let $s\in (1,\infty)$, and let $X$ be an $s$-concave Banach function space. If $M$ is bounded on $X$, then $M$ is bounded on~$X'$.
\end{con}

ref_dict.char:
\begin{theorem}\label{char}
Let $X$ be a Banach function space. Assume that there exists $p_0>1$ such that, for all $p\ge p_0$,
boundedness of the Hardy--Littlewood maximal operator $M$ on $(X')^{1/p}$ implies its boundedness on $\big[(X')^{1/p}\big]'$.
If $m_{\la}$ is bounded on $X$ and $X'$ for some $\la\in (0,1)$, then $M$ is bounded on $X$.
\end{theorem}

ref_dict.assum:
\begin{cor}\label{assum}
Assume Conjecture~\ref{ncon}. Let $X$ be an $r$-convex Banach function space for some $r\in (1,\infty)$.
If $m_{\la}$ is bounded on $X$ and $X'$ for some $\la\in (0,1)$, then $M$ is bounded on $X$.
\end{cor}

