\begin{theorem}\label{thm:approximate_brouwer_turan}
  Let $r\ge 2$. Let $G=(V,E)$ be a $K_{r+1}$-free graph, and let $1\le k\le |V|$. Then,
\[
    \eps_k(G) \le \left(1-\frac{1}{r}\right)\frac{k^2}{2}+ (4k-2)\sqrt{k}.
\]  
\end{theorem}

