\begin{theorem}\label{thm:main_density_version}
Let $G=(V,E)$ be a graph, and let $1\le k\le |V|$. Then,
\[
    \eps_k(G) \le \max_{U\subset V,\, |U|=k} |E_G(U)| + (4k-2)\sqrt{k}.
\]
\end{theorem}

