\begin{lemma}\label{L2.2}
     Let $l, j\geq 2$ be integers such that $lj$ is even. Then, for each prime $p$, we have
     \begin{equation*}
         \lambda_{{\rm{sym}}^j}^l(p)=
         \begin{cases}
            \displaystyle \sum_{m=0}^{\frac{lj}{2}}d_m \lambda_{{\rm{sym}}^{lj-2m}}(p)&\text{ if $lj$ is even}\\
             \displaystyle \sum_{m=0}^{\frac{lj-1}{2}}e_m \lambda_{{\rm{sym}}^{lj-2m}}(p)&\text{ if $lj$ is odd}
         \end{cases}
     \end{equation*}
     where 
     \begin{align*}
        &d_m:=c_m(l,j)-c_{m-1}(l,j)=\sum_{r=0}^{\left\lfloor \frac{m}{\,j+1\,} \right\rfloor}(-1)^{r}\binom{l}{r}\binom{m-r(j+1)+l-2}{\,l-2\,}\\
        &e_m:=c_m(l,j)-c_{m-1}(l,j)=\sum_{r=0}^{\left\lfloor \frac{m}{\,j+1\,} \right\rfloor}(-1)^{r}\binom{l}{r}\binom{m-r(j+1)+l-2}{\,l-2\,}
     \end{align*}
    with $c_{-1}=0$. Note that even though $d_m$ and $ e_m$ are given by the same formula, $d_m\neq e_m$ for any $m$, because they are dependent on $l$ and $j$.
\end{lemma}

