\section{Lemma's}
\begin{lemma}\label{L2.1}
    For any $x$ we have
    \begin{equation}
        (1+x^2+x^4+\cdots+x^{2j})^l=\sum_{m=0}^{lj}c_mx^{2m},\label{E1}
    \end{equation}
    where $c_{m}:=c_m(l,j)$ denotes the number of integral solutions of the equation 
    \begin{equation*}
        m_1+m_2+\cdots+m_l=m\qquad 0\leq m_i\leq j. 
    \end{equation*}
    By the inclusion-exclusion principle, 
    \begin{equation}
       c_{m}=
\sum_{r=0}^{\left\lfloor \frac{m}{\,j+1\,} \right\rfloor}
(-1)^{r}\binom{l}{r}
\binom{m-r(j+1)+l-1}{\,l-1\,},
\qquad 0\le m\le lj \label{E2}
    \end{equation} 
    with $\binom{n}{r}=0$ if $n<r$.
    Moreover, the coefficients $c_m$'s are Palindromic, that is, $c_m=c_{lj-m}$ and satisfy the chain of inequalities $c_0\leq c_1\leq c_2\leq \cdots\leq c_{\frac{lj}{2}}$ and $c_{\frac{lj}{2}}\geq c_{\frac{lj}{2}+1}\geq \cdots\geq c_{lj-1}\geq c_{lj}$ when $lj$ is even and $c_0\leq c_1\leq c_2\leq \cdots\leq c_{\frac{lj-1}{2}}$ and $c_{\frac{lj-1}{2}}\geq c_{\frac{lj+1}{2}}\geq \cdots\geq c_{lj-1}\geq c_{lj}$ when $lj$ is odd.
\end{lemma}
\begin{proof}
   We write 
   \begin{align*}
        (1+x^2+x^4+\cdots+x^{2j})^l&=\left(\sum_{m=0}^jx^{2m}\right)^l\\
        &=\sum_{m_1=0}^j\sum_{m_2=0}^j\cdots\sum_{m_l=0}^j x^{2(m_1+m_2+\cdots+m_l)}\\
        &=\sum_{m=0}^{lj}c_mx^{2m},
   \end{align*}
    where $c_m$ denotes the number of ways of writing $m$ as the sum of $l$ integers $m_i$ with $0\leq m_i\leq j$. We can also see \eqref{E1} in \cite{Fahssi} through polynomial expansion. The formula \eqref{E2} for $c_m$ follows from \cite[Section 6]{Eger}. 

    To prove the Palindromic property, let $0\leq m\leq lj$. Then ,corresponding to every solution $ (m_1,m_2,\cdots,m_l)$ of $m$, we can always find a solution $ (j-m_1,j-m_2,\cdots,j-m_l)$ of $lj-m$ with $0\leq j-m_i\leq j$, and conversely. This makes a bijection between the set of solutions of $m$ and $lj-m$, implying $c_m=c_{lj-m}$. 

    Now, to prove the chain of inequalities, assume $lj$ is even and let $0\leq  m< \frac{lj}{2}$. For every solution $(m_1,m_2,\cdots,m_l)$ of $m$, note that not all $m_i$'s can be $j$, that is, at least one $m_i$ is less than $j$ because $m<\frac{lj}{2}$. Let $i_0$ be the least index such that $m_{i_0}<j$ and define the map
    \begin{equation*}
        \Phi(m_1,m_2,\cdots,m_l)=(m_1,\cdots,m_{i_0}+1,\cdots,m_l).
    \end{equation*}
    Then $\Phi(m_1,m_2,\cdots,m_l)$ is a solution of $m+1$ and the map $\Phi$ is injective, since from $\Phi(m_1,m_2,\cdots,m_l)$ one can uniquely recover $(m_1,m_2,\cdots,m_l)$ by subtracting 1 from the least index whose entry was increased. Hence $c_m\leq c_{m+1}$ for $0\leq m< \frac{lj}{2}$. The remaining inequalities follow from the Palindromic property. The other case, when $lj$ is odd, follows similarly.
\end{proof}

\begin{lemma}\label{L2.2}
     Let $l, j\geq 2$ be integers such that $lj$ is even. Then, for each prime $p$, we have
     \begin{equation*}
         \lambda_{{\rm{sym}}^j}^l(p)=
         \begin{cases}
            \displaystyle \sum_{m=0}^{\frac{lj}{2}}d_m \lambda_{{\rm{sym}}^{lj-2m}}(p)&\text{ if $lj$ is even}\\
             \displaystyle \sum_{m=0}^{\frac{lj-1}{2}}e_m \lambda_{{\rm{sym}}^{lj-2m}}(p)&\text{ if $lj$ is odd}
