To prove the Palindromic property, let $0\leq m\leq lj$. Then ,corresponding to every solution $ (m_1,m_2,\cdots,m_l)$ of $m$, we can always find a solution $ (j-m_1,j-m_2,\cdots,j-m_l)$ of $lj-m$ with $0\leq j-m_i\leq j$, and conversely. This makes a bijection between the set of solutions of $m$ and $lj-m$, implying $c_m=c_{lj-m}$.

\begin{lemma}\label{L2.3}
For $\Re(s)>1$, we have
 \begin{align*}
 L_{l,j}(s):&=\sum_{n=1}^\infty\frac{\lambda_{{\rm{sym}}^{j}}^l(n)}{n^s}\\
 &=
 \begin{cases}
 \displaystyle \zeta^{d_{\frac{lj}{2}}}(s)\prod_{m=0}^{\frac{lj}{2}-1}L^{d_m}(s, {\rm{sym}}^{lj-2m}f)U_{l,j}(s)& \text{if $lj$ is even}\\
 \displaystyle\prod_{m=0}^{\frac{lj-1}{2}}L^{e_m}(s, {\rm{sym}}^{lj-2m}f)V_{l,j}(s)& \text{if $lj$ is even}
 \end{cases}
 \end{align*}
 where $U_{l,j(s)}$ and $U_{l,j(s)}$ are some harmless Dirichlet serieses, which converges absolutely in the half plane $\Re(s)\geq \frac{1}{2}+\varepsilon$ and $U_{l,j}(1)\neq 0$, $V_{l,j}(1)\neq 0$. Moreover, the degree of the $L$-function $L_{l,j}(s)$ is $ D:=(j+1)^l$.
\end{lemma}
\begin{proof}
 Since the Fourier coefficients $\lambda_{{\rm{sym}}^{j}}(n)$ are multiplicative and satisfies the bound $\lambda_{{\rm{sym}}^{j}}(n)\ll n^\varepsilon$, for $\Re(s)>1$ we have the Euler product representation of $ L_{l,j}(s)$ as
 \begin{equation*}
 L_{l,j}(s)=\prod_p\left(1+\frac{\lambda_{{\rm{sym}}^{j}}^l(p)}{p^s}+\frac{\lambda_{{\rm{sym}}^{j}}^l(p^2)}{p^{2s}}+\cdots\right). 
 \end{equation*}
 Note that the series 
 \begin{equation*}
 \frac{\lambda_{{\rm{sym}}^{j}}^l(p^2)}{p^{2s}}+ \frac{\lambda_{{\rm{sym}}^{j}}^l(p^3)}{p^{3s}}+\cdots
 \end{equation*}
 converges absolutely in the half plane $\Re(s)\geq \frac{1}{2}+\varepsilon$. Thus, the coefficient of $p^{-s}$ in the Euler product above decides the decomposition of the $L$-function $L_{l,j}(s)$. Thus, the lemma follows from the above lemma.

Assume $lj$ is even. We know that the degree of the $L$-function $L(s, {\rm{sym}}^{j}f)$ is $j+1$, so \begin{align*}
 D=&\sum_{m=0}^{\frac{lj}{2}}d_m(lj-2m+1)=\sum_{m=0}^{\frac{lj}{2}}(c_m-c_{m-1})(lj-2m+1)\\
