\section{Proof of Theorem \ref{T1}}
Firstly, we consider the case where $lj$ is even and $lj\geq 6$. Applying Perron's formula to $L_{l,j}(s)$, we get 
\begin{equation*}
 \sum_{n\leq x} \lambda_{{\rm{sym}}^j}^l(n)=\frac{1}{2\pi i}\int_{1+\varepsilon-iT}^{1+\varepsilon+iT}L_{l,j}(s)\frac{x^s}{s}ds+O\left(\frac{x^{1+\varepsilon}}{T}\right),
\end{equation*}
where $10\leq T\leq x$ is a parameter that will be chosen later. We now move the line of integration to $\Re(s)=1-\frac{1}{j^3}$. Then in the rectangle formed by the vertices $1+\varepsilon+iT, 1-\frac{1}{j^3}+iT, 1-\frac{1}{j^3}-iT, 1+\varepsilon-iT$, the $L$-function $L_{l,j}(s)$ has a pole at $s=1$ of order $d_{\frac{lj}{2}}$ coming from the factor $\zeta^{d_{\frac{lj}{2}}}(s)$. The Cauchy residue theorem implies
\begin{align*}
 \sum_{n\leq x} \lambda_{{\rm{sym}}^j}^l(n)=&\frac{1}{2\pi i}\left\{\int_{1-\frac{1}{j^3}-iT}^{1-\frac{1}{j^3}+iT}+\int_{1-\frac{1}{j^3}+iT}^{1+\varepsilon+iT}+\int_{1+\varepsilon-iT}^{1-\frac{1}{j^3}-iT}\right\}L_{l,j}(s)\frac{x^s}{s}ds\\
 &+xP_{d_{\frac{lj}{2}}-1}(\log x)+O\left(\frac{x^{1+\varepsilon}}{T}\right)\\
 =&xP_{d_{\frac{lj}{2}}-1}(\log x)+I_{l,j}^1+I_{l,j}^2+I_{l,j}^3+O\left(\frac{x^{1+\varepsilon}}{T}\right),
\end{align*}
where $P_{d_{\frac{lj}{2}}-1}(y)$ is a polynomial of degree $d_{\frac{lj}{2}}-1$ in $y$.

Thus, we obtain
\begin{align*}
 \sum_{n\leq x} \lambda_{{\rm{sym}}^j}^l(n)=&xP_{d_{\frac{lj}{2}}-1}(\log x)+O\left(x^{\theta_{l,j}+\varepsilon}\right),
\end{align*}
where $P_k(y)$ is a polynomial of degree $k$ in $y$ and 
\begin{equation*}
 \theta_{l,j}=1-\frac{630j^\frac{3}{2}}{j^\frac{3}{2}\left(315D-315d_{\frac{{lj}}{2}}-189d_{\frac{{lj}}{2}-1}\right)+80\sqrt{15}d_\frac{lj}{2}}.
\end{equation*}

We now consider the case $l=j=2$. In this case, by Note \ref{N2.1} the $L$-function is
\begin{equation*}
 L_{2,2}(s)=\zeta(s)L(s, {\rm{sym}}^{2}f)L(s, {\rm{sym}}^{4}f)U_{2,2}(s).
\end{equation*}
By applying the Perron's formula to $L_{2,2}(s)$, we get
\begin{equation*}
