            O\left(x^{\theta_{l,j}+\varepsilon}\right)&\text{if $lj$ is odd},
        \end{cases}
    \end{equation*}
    where $P_k(y)$ is a polynomial of degree $k$ in $y$, when $k=0$, $P_k(y)$ denotes some constant, and 
    \begin{equation*}
        \theta_{l,j}=
        \begin{cases}
        1-\frac{63\sqrt{2}}{252\sqrt{2}+4\sqrt{15}}&\text{ if $lj=4$}\\
        1-\frac{630j^{3/2}}{j^{3/2}(315D-315d_{\frac{lj}{2}}-189d_{\frac{lj}{2}-1})+80\sqrt{15}d_{\frac{lj}{2}}}&\text{ if $lj\geq6$ is even}\\
        1-\frac{6}{3D-2e_{\frac{lj-1}{2}}}&\text{ if $lj\geq5$ is odd},
        \end{cases}
    \end{equation*}
    where the degree $D$ comes from the following lemma.

\begin{lemma}\label{L2.3}
For $\Re(s)>1$, we have
    \begin{align*}
        L_{l,j}(s):&=\sum_{n=1}^\infty\frac{\lambda_{{\rm{sym}}^{j}}^l(n)}{n^s}\\
        &=
        \begin{cases}
           \displaystyle \zeta^{d_{\frac{lj}{2}}}(s)\prod_{m=0}^{\frac{lj}{2}-1}L^{d_m}(s, {\rm{sym}}^{lj-2m}f)U_{l,j}(s)& \text{if $lj$ is even}\\
           \displaystyle\prod_{m=0}^{\frac{lj-1}{2}}L^{e_m}(s, {\rm{sym}}^{lj-2m}f)V_{l,j}(s)& \text{if $lj$ is even}
        \end{cases}
    \end{align*}
    where $U_{l,j(s)}$ and $U_{l,j(s)}$ are some harmless Dirichlet serieses, which converges absolutely in the half plane $\Re(s)\geq \frac{1}{2}+\varepsilon$ and $U_{l,j}(1)\neq 0$, $V_{l,j}(1)\neq 0$. Moreover, the degree of the $L$-function $L_{l,j}(s)$ is $ D:=(j+1)^l$.
\end{lemma}

The coefficients $d_i$'s and $e_i$'s are given by the following lemma.

\begin{lemma}\label{L2.2}
     Let $l, j\geq 2$ be integers such that $lj$ is even. Then, for each prime $p$, we have
     \begin{equation*}
         \lambda_{{\rm{sym}}^j}^l(p)=
         \begin{cases}
            \displaystyle \sum_{m=0}^{\frac{lj}{2}}d_m \lambda_{{\rm{sym}}^{lj-2m}}(p)&\text{ if $lj$ is even}\\
             \displaystyle \sum_{m=0}^{\frac{lj-1}{2}}e_m \lambda_{{\rm{sym}}^{lj-2m}}(p)&\text{ if $lj$ is odd}
         \end{cases}
     \end{equation*}
     where 
     \begin{align*}
        &d_m:=c_m(l,j)-c_{m-1}(l,j)=\sum_{r=0}^{\left\lfloor \frac{m}{\,j+1\,} \right\rfloor}(-1)^{r}\binom{l}{r}\binom{m-r(j+1)+l-2}{\,l-2\,}\\
        &e_m:=c_m(l,j)-c_{m-1}(l,j)=\sum_{r=0}^{\left\lfloor \frac{m}{\,j+1\,} \right\rfloor}(-1)^{r}\binom{l}{r}\binom{m-r(j+1)+l-2}{\,l-2\,}
     \end{align*}
    with $c_{-1}=0$. Note that even though $d_m$ and $ e_m$ are given by the same formula, $d_m\neq e_m$ for any $m$, because they are dependent on $l$ and $j$.
\end{lemma}
\label{T1}

