	$$
		\|k*[u-u_0]\|_{H^1(0,T; H^{-1}(\Omega))} + \|u\|_{L^2(0,T; H_0^1(\Omega))} 
		\le C\|u_0\|_{L^2(\Omega)},
	$$
	where $C$ depends only on $c_1$, $c_2$, $T$, and $\|\ell\|_{L^1(0,T)}$.
\end{Proposition}

