Next, we discuss an application to abelian varieties with complex multiplication by a cyclotomic field. Let $n\ge 3$ be an odd integer and $\zeta_n\in\mathbb{C}$ a primitive $n$-th root of unity. The number field $\mathbb{Q}(\zeta_n)$ is a \emph{CM field}, that is a totally imaginary quadratic extension of a totally real number field. A \emph{CM type} $\Sigma$ of $\mathbb{Q}(\zeta_n)$ is a subset $\Sigma\subseteq \mathrm{Hom}(\mathbb{Q}(\zeta_n),\mathbb{C})$ such that $\Sigma\sqcup (\Sigma\circ c)=\mathrm{Hom}(\mathbb{Q}(\zeta_n),\mathbb{C})$, where $c\colon \mathbb{Q}(\zeta_n)\to\mathbb{Q}(\zeta_n)$ denotes the complex conjugation.
 Up to translation by a field automorphism in $\mathrm{Gal}(\mathbb{Q}(\zeta_n)/\mathbb{Q})$, we get a \emph{canonical CM type} 
 $$\Sigma_n=\{\sigma\in \mathrm{Hom}(\mathbb{Q}(\zeta_n),\mathbb{C})~|~\mathrm{Im}\,\sigma(\zeta_n)>0\}$$
 of $\mathbb{Q}(\zeta_n)$.

\section{Proof of Corollary \ref{cor_bounds}}\label{sec_proof-corollary}
 We bound the terms in the formula for the Faltings height in Theorem \ref{thm_faltings-height-hyperelliptic} to prove Corollary \ref{cor_bounds}. After establishing the bound for the values of the gamma function in the previous section, it remains to find a good bound for the sum over the primes dividing $n$ in the expression for the Faltings height of $X_n$. This is done by the following lemma.
 \begin{Lem}\label{lem_bound-finite}
 For every odd integer $n\ge 3$ it holds
 $$\frac{\log n}{n}\le\sum_{\substack{p\text{ prime}\\ p\mid n}}\frac{p^{2\mathrm{ord}_p(n)}-1}{p^{2\mathrm{ord}_p(n)-1}(p^2-1)}\log p< \tfrac{9}{8}\log\log n+0.7405.$$
 \end{Lem}
 \begin{proof}
 We first show the lower bound. We have
 $$\sum_{\substack{p\text{ prime}\\ p\mid n}}\frac{p^{2\mathrm{ord}_p(n)}-1}{p^{2\mathrm{ord}_p(n)-1}(p^2-1)}\log p\ge\sum_{\substack{p\text{ prime}\\ p\mid n}}\frac{\log p}{p}.$$
 Since the function $\frac{\log x}{x}$ is monotonically decreasing for $x\ge e$ and since $p\ge3$, we obtain
 $$\sum_{\substack{p\text{ prime}\\ p\mid n}} \frac{\log p}{p}\ge\sum_{\substack{p\text{ prime}\\ p\mid n}}\frac{\log p^{\mathrm{ord}_p(n)}}{p^{\mathrm{ord}_p(n)}}\ge \sum_{\substack{p\text{ prime}\\ p\mid n}}\frac{\log p^{\mathrm{ord}_p(n)}}{n}=\frac{\log n}{n}.$$
 This shows the lower bound of the lemma.

Now we can give the proof of Corollary \ref{cor_bounds}.
 \begin{proof}[Proof of Corollary \ref{cor_bounds}]
 If we apply Lemmas \ref{lem_bound-gamma} and \ref{lem_bound-finite} to the expression of $h_{\mathrm{Fal}}(X_n)$ in Theorem \ref{thm_faltings-height-hyperelliptic}, we obtain the lower bound
 \begin{align*}
 h_{\mathrm{Fal}}(X_n)&\ge \tfrac{n}{8}\log n-\tfrac{3-\log 2-36\zeta'(-1)}{12}n-\tfrac{g}{2}\log \pi+\tfrac{1}{8}\log n+\tfrac{g}{2n}\log 2\\
 &\ge \tfrac{n}{8}\log n-\tfrac{3-\log 2-36\zeta'(-1)+3\log \pi}{12}n\\
 &> \tfrac{n}{8}\log n-0.975n
 \end{align*}
 and the upper bound
 \begin{align}\label{equ_upper-bound}
 h_{\mathrm{Fal}}(X_n)\le &\tfrac{n}{8}\log n +\tfrac{9}{64}n\log\log n+\tfrac{0.7405}{8}n-\tfrac{3-\log2-36\zeta'(-1)}{12}n\\
 &-\tfrac{g}{2}\log \pi+\tfrac{\log 2n}{2}+\tfrac{g}{2n}\log 2+\tfrac{1}{2}\nonumber\\
 \le &\tfrac{n}{8}\log n+\tfrac{9}{64}n\log\log n-\left(\tfrac{3-\log 2-36\zeta'(-1)+3\log \pi-1.1108}{12}\right)n\nonumber\\
 &+\tfrac{1}{2}\log n+\left(\tfrac{1}{4}\log\pi+\tfrac{3}{4}\log 2+\tfrac{1}{2}\right)-\tfrac{1}{4n}\log 2\nonumber\\
 < &\tfrac{n}{8}\log n+\tfrac{9}{64}n\log\log n-0.8821n+\tfrac{1}{2}\log n+1.3061.\nonumber
 \end{align}
 Since $n\ge 3$, we have $\log n\le \frac{\log 3}{3}n\le 0.3663n$. Thus, we can further estimate the upper bound using $n\ge 3$ by
 $$h_{\mathrm{Fal}}(X_n)<\tfrac{n}{8}\log n+\tfrac{9}{64}n\log\log n-0.263n.$$
 The first statement of the corollary follows from these bounds.
 The second statement on the asymptotic behavior
 $$h_{\mathrm{Fal}}(X_n)=\tfrac{1}{8}n \log n+O(n\log \log n)$$
 is a direct consequence of the first statement.
 \end{proof}

Finally, we have to show that $T_0A_n\cong\bigoplus_{\tau\in\Sigma_n}\mathbb{C}_{\tau}$ as $\mathbb{Q}(\zeta_n)\otimes_\mathbb{Q}\mathbb{C}$-modules. We have already seen that there is an isomorphism
 $$H^0(A_n,\Omega_{A_n}^1)\cong\bigoplus_{\substack{1\le j\le g\\ \gcd(j,n)=1}}\mathbb{C}\cdot\eta_j$$
 of $\mathbb{Q}(\zeta_n)\otimes_\mathbb{Q}\mathbb{C}$-modules, where $\zeta_n$ acts on $\eta_j$ by the scalar $\zeta_n^j$. Hence, on every $\mathbb{C}\cdot \eta_j$ we get a structure of an $\mathbb{Q}(\zeta_n)$-module by sending $\zeta_n$ to $\zeta_n^j=e^{2\pi i j/n}$. Thus, it is induced by a morphism $\tau\in \mathrm{Hom}(\mathbb{Q}(\zeta_n),\mathbb{C})$ with $\mathrm{Im}\,\tau(\zeta_n)>0$. We conclude that there is an isomorphism
 $$H^0(A_n,\Omega_{A_n}^1)\cong \bigoplus_{\tau\in\Sigma_n}\mathbb{C}_{\tau}.$$ 
 of $\mathbb{Q}(\zeta_n)\otimes_\mathbb{Q}\mathbb{C}$-modules. Since the restriction of holomorphic one-forms to the origin induces an isomorphism $H^0(A_n,\Omega_{A_n}^1)\xrightarrow{\sim} (T_0A_n)^\vee$, we also obtain an isomorphism $T_0A_n\cong\bigoplus_{\tau\in\Sigma_n}\mathbb{C}_{\tau}$ of $\mathbb{Q}(\zeta_n)\otimes_\mathbb{Q}\mathbb{C}$-modules by duality. This completes the proof of the lemma.
 \end{proof}
 Let us emphasize the special situation of $n=p$ being a prime.
 \begin{Rem}\label{rem_CM}
 If $n=p\ge 3$ is a prime, then it holds $$\dim \mathrm{Jac}(X_p)=\frac{p-1}{2}=\frac{\varphi(p)}{2}=\dim A_p$$ for the abelian subvariety $A_p\subseteq \mathrm{Jac}(X_p)$ in Lemma \ref{lem_subvariety}. This implies $A_p=\mathrm{Jac}(X_p)$. Thus, $\mathrm{Jac}(X_p)$ has complex multiplication by the CM type $(\mathbb{Q}(\zeta_p),\Sigma_p)$. A theorem by Colmez \cite[Theorem 0.3 (ii)]{Col93} states that the Faltings height $h_{\mathrm{Fal}}(\mathrm{Jac}(X_p))$ only depends on the CM type $(\mathbb{Q}(\zeta_p),\Sigma_p)$. Thus, Theorem \ref{thm_faltings-height-hyperelliptic} gives an explicit expression for the stable Faltings height of any abelian variety having complex multiplication by the CM type $(\mathbb{Q}(\zeta_p),\Sigma_p)$ for any prime $p\ge 3$.
 \end{Rem}
 Next, we want to bound the stable Faltings height $h_{\mathrm{Fal}}(A_n)$ for a general odd integer $n\ge 3$ to prove Corollary \ref{cor_faltings-height-cyclotomic}. Since $A_n$ in Lemma \ref{lem_subvariety} is an abelian subvariety of $\mathrm{Jac}(X_n)$, we deduce from a result by Rémond \cite{Rem22} that 
 \begin{align}\label{equ_remond}
 h_{\mathrm{Fal}}(A_n)&\le h_{\mathrm{Fal}}(X_n)+(\dim \mathrm{Jac}(X_n)-\dim A_n)\log(\pi\sqrt{2})\\
 &=h_{\mathrm{Fal}}(X_n)+\tfrac{n-1-\varphi(n)}{2}\log(\pi\sqrt{2}).\nonumber
 \end{align}
 This bound now allows us to give the proof of Corollary \ref{cor_faltings-height-cyclotomic}.
 \begin{proof}[Proof of Corollary \ref{cor_faltings-height-cyclotomic}]
 By a theorem of Colmez \cite[Theorem 0.3 (ii)]{Col93} the stable Faltings height of an abelian variety having complex multiplication by $(\mathbb{Q}(\zeta_n),\Sigma_n)$ only depends on the CM type $(\mathbb{Q}(\zeta_n),\Sigma_n)$. Thus, we can assume that the abelian variety $A_n$ given in the statement of the corollary is obtained as the abelian subvariety $A_n\subseteq \mathrm{Jac}(X_n)$ in Lemma \ref{lem_subvariety}. In particular, we can use the bound in (\ref{equ_remond}).

