{\left(1+\bar\gamma_n\bar \theta_n^{2(1+\al_{n})}|x_n|^{-\frac{\lm_n}{4\pi}} |x-{x_n}|^{\frac{\lm_n}{4\pi}}\right)^2}\right)+O(1),\quad z\in B_{r}(0),
\end{equation}
where $\bar \theta_n^{2(1+\al_{n})}=\left(\tfrac{|x_{n}|}{\delta_n}\right)^{2(1+\al_{n})}\to +\ii$,
$8\bar\gamma_n={((\tfrac{\epsilon_n}{|x_n|})^2+1)^{\bns}}V_n(x_n)$, or
\begin{itemize}
 \item \mbox{\rm (III):} there exists a subsequence such that $\tfrac{\epsilon_n}{t_n}\leq C$ and
