 &\leq \frac{2c_2}{a}\int_\Omega n \ln \frac{n}{\bar{n}}+ \frac{c_2a}{2 \pi} \cdot \left \{ \int_\Omega n \right \} \cdot \int_\Omega |\nabla u|^2 \notag \\
 &\quad+2Mac_1c_2 |\Omega| \cdot \left \{ \int_\Omega n \right \} \cdot \int_\Omega |\nabla u|^2 +\frac{2c_2M}{a} \int_\Omega n.
 \end{align}
 Employing Lemma \ref{Local}[\eqref{Local.2}] and choosing $a$ such that $\frac{c_2a m}{2 \pi}+2Mac_1c_2|\Omega|m= \frac{1}{2}$ where $m =\int_\Omega n_0 $ 
 \begin{align}\label{L2u.4}
