\label{thm1}
    Let $\kappa=0$, $\Omega \subset \mathbb{R}^2$ be a bounded domain with smooth boundary and assume that 
\begin{equation}\label{S}
    \begin{cases}
        \lim_{\xi \to \infty}S(\xi) =0 ,  &\text{ if }N=2,\\
         |S(\xi)| \leq K_S (\xi+1)^{-\alpha} \qquad \text{for all }\xi \geq 0,  &\text{ if }N=3,
    \end{cases}
\end{equation}
 and 
\begin{align} \label{phi}
    \phi \in W^{2, \infty}(\Omega).
\end{align}
 hold. Then for any choice of $n_0$ and $u_0$ fulfilling 
\begin{equation} \label{initial}
    \begin{cases}
        n_0 \in C^{0} (\bar{\Omega}) &\text{ with } n_0\geq 0   \\
      u_0 \in D(A^\beta) &\text{with } \beta \in \left ( \frac{3}{4}, 1\right ) \text{when }n=3 \quad \text{and }  \beta \in \left ( \frac{1}{2}, 1\right ) \text{when }n=2,
    \end{cases}
\end{equation}
, the problem 
\begin{equation}  \label{1} 
    \begin{cases}
        n_t + u \cdot \nabla n = \Delta n - \nabla \cdot \left( n S(n)\nabla c \right), \qquad &x\in \Omega, t>0,\\
       u\cdot \nabla c = \Delta c - c + n, \qquad &x\in \Omega, t>0,\\
        u_t + \kappa ( u \cdot \nabla ) u +\nabla P = \Delta u + n \nabla \phi ,\quad \nabla \cdot u =0,\qquad &x\in \Omega, t>0,
    \end{cases}
\end{equation}
 under the boundary conditions 
\begin{equation} \label{bdry}
    \frac{\partial n}{\partial \nu} =0, \quad \frac{\partial c}{\partial \nu} =0, \quad \text{and } u=0 ,\qquad x \in \partial \Omega, t>0,
\end{equation}
 possesses a global classical solution $(u,c,u,P)$ satisfying 
    \begin{equation*}
        \begin{cases}
            n \in C^0 \left (\bar{\Omega} \times [0,\infty) \right ) \cap C^{2,1} \left ( \bar{\Omega} \times (0,\infty) \right ), \\
            c \in C^{2,0}\left ( \bar{\Omega} \times (0,\infty) \right ) , \\
            u \in C^0 \left ([0,\infty); D(A^\beta)  \right ) \cap C^{2,1}\left ( \bar{\Omega} \times (0,\infty); \mathbb{R}^2 \right ) \quad \text{and }\\
            P \in C^{1,0} \left ( \bar{\Omega}\times (0,\infty) \right ),
        \end{cases}
    \end{equation*}
    as well as $n$ and $c$ are positive in $\bar{\Omega}\times (0, \infty)$. Moreover, the solution is globally bounded in the sense that 
    \begin{align} \label{thm1-1}
    \sup_{t>0} \left \{    \left \| n(\cdot,t) \right \|_{L^\infty(\Omega)} +    \left \| c(\cdot,t) \right \|_{W^{1,\infty}(\Omega)} +  \left \| u(\cdot,t) \right \|_{L^\infty(\Omega)} \right \} < \infty. 
    \end{align}

ref_dict.various positivity:
\begin{defn}\label{various positivity}
A form \(\nu\in \Lambda^{n,n}V^*\) is called a non-negative (resp.\ positive) volume form if
\[
\nu=\tau\,(\sqrt{-1})^n\,e^1\wedge \overline{e^1}\wedge \cdots \wedge e^n\wedge \overline{e^n}
\]
for some \(\tau\in\mathbb R\) with \(\tau\ge 0\) (resp.\ \(\tau>0\)).
\end{defn}

ref_dict.rem01:
\begin{rem}\label{rem01}
By \cite[Proposition~2.21]{Fin}, the case \(\dim V=\dim W=3\) is the first dimension in which a positive map is not necessarily decomposable in the sense of \cite[(2.40)]{Fin} (as shown by Choi's example~\cite{MR379365}).
Thus Theorem~\ref{thm:main} verifies Finski's open problem in the first genuinely new dimension and provides a strong indication that the general statement may also hold.
\end{rem}

