    \begin{align*}
        1 - c(d) &= \PP(\overline{X}(-\infty,0] \cap \overline{X}[1,\infty) \ne \emptyset)\\
        &= \PP(\overline{X}_i = \overline{X}_j \text{ for some integers } i \le 0, j \ge 1)\\
