\begin{problem}[Jarden and Narkiewicz, 2007]\label{prob:JN}
Let $L$ be a number field. Obtain an asymptotical formula for the number of positive rational integers $n\leq X$ which are sums of at most $k$ units of $\OO_L$. 
\end{problem}

ref_dict.cor:exact_eqn:
\begin{corollary}\label{cor:exact_eqn}
  Let $\eta>1$ be the fundamental unit of the real quadratic field $L$, let
  $k\in\N$ and define $\rho:=\lfloor k/2\rfloor$. Then, for $X\geq 2$,
  \begin{equation*}
   \eNLk(X)= \tilde c_k\left(\frac{2\log X}{\log\eta}\right)^\rho+O_{k,L}((\log X)^{\rho-1}),
  \end{equation*}
  where
  \begin{equation*}
   \tilde c_k=
    \begin{cases}
      1/\rho! &\text{ if $k$ is even,}\\
      2/\rho! &\text{ if $k$ is odd.}
    \end{cases}
  \end{equation*}
\end{corollary}

