theorem.content:
\label{th:OK}
Consider the Ohta--Kawasaki equation~\eqref{eq:OK}	
with $\gamma = \sqrt{8}$, $\sigma=1/5$, $m=1/10$, $L=2\pi$, and $\uin(x) = m+\frac{2}{10}\cos\left(\frac{2\pi x}{L}\right)+\frac{2}{10}\cos\left(\frac{4\pi x}{L}\right)$. The solution $u=u(t,x)$ satisfies
\begin{align*}
\sup_{t\in [0,\infty)} \sup_{x\in [0,L]} \vert u(t,x)-\bar{u}(t,x) \vert \leq 9\times 10^{-7},
\end{align*}
where the precise description of the approximate solution $\bar{u}=\bar{u}(t,x)$ in terms of Chebyshev$\times$Fourier coefficients can be downloaded
 at~\cite{integratorcode_new}. This approximate solution $\bar{u}$ is represented in Figure~\ref{fig:OK} for $t\in[0,\tau]$ with $\tau=30$, and satisfies $\bar{u}(t,x) = \bar{u}(\tau,x)$ for all $t\geq \tau$ and all $x\in[0,L]$. Moreover, there exists a stationary solution $u^\mathrm{stat}=u^\mathrm{stat}(x)$ of the Otha--Kawasaki equation, such that
\begin{align*}
\sup_{x\in [0,L]} \vert u^\mathrm{stat}(x)-\bar{u}(\tau,x) \vert \leq 9\times 10^{-7}.
\end{align*}
Finally, the solution $u$ of~\eqref{eq:OK} converges to $u^\mathrm{stat}$ as $t\to\infty$, and $u^\mathrm{stat}$ is locally asymptotically stable.

ref_dict.th:OK:
\begin{theorem}
\label{th:OK}
Consider the Ohta--Kawasaki equation~\eqref{eq:OK}	
with $\gamma = \sqrt{8}$, $\sigma=1/5$, $m=1/10$, $L=2\pi$, and $\uin(x) = m+\frac{2}{10}\cos\left(\frac{2\pi x}{L}\right)+\frac{2}{10}\cos\left(\frac{4\pi x}{L}\right)$. The solution $u=u(t,x)$ satisfies
\begin{align*}
\sup_{t\in [0,\infty)} \sup_{x\in [0,L]} \vert u(t,x)-\bu(t,x) \vert \leq 9\times 10^{-7},
\end{align*}
where the precise description of the approximate solution $\bu=\bu(t,x)$ in terms of Chebyshev$\times$Fourier coefficients can be downloaded
 at~\cite{integratorcode_new}. This approximate solution $\bu$ is represented in Figure~\ref{fig:OK} for $t\in[0,\tau]$ with $\tau=30$, and satisfies $\bu(t,x) = \bu(\tau,x)$ for all $t\geq \tau$ and all $x\in[0,L]$. Moreover, there exists a stationary solution $u^\stat=u^\stat(x)$ of the Otha--Kawasaki equation, such that
\begin{align*}
