\label{thm:main}
Assume that $p=\frac 12|\xi|^2+V(x)$ with real $V$ satisfying \eqref{eqn:Vbounds}, and $Q$ is of the form \eqref{eqn:Qdef}, where \eqref{eqn:cholesky} holds with non-singular $B$.
Then for all $N\in\Z_+$ there is $C_N$  such that, with $u=e^{tQ}u_0$ and
$\epsilon=\sqrt{\gamma h/2}$, for all $1\le p\le\infty$, and all $\epsilon,\gamma\in(0,1]$,
\begin{multline}\label{eqn:localest}
\sup_{0\le t\le \infty}\,\sum_{|\alpha|+3|\beta|\le 3N}
\|(\epsilon\partial_\xi)^\alpha(\epsilon\partial_x)^\beta u(t,\cdot)\|_{L^p(\mathbb R^n)}\\
\le 
C_N\sum_{|\alpha|+3|\beta|\le 3N}\|(\epsilon\partial_\xi)^\alpha(\epsilon\partial_x)^\beta u_0\|_{L^p(\mathbb R^n)}.
\end{multline}
Additionally, for all $N\in\Z_+$ and $T>0$ there is $C_{N,T}$ so that
\begin{equation}\label{eqn:globalest}
\sup_{T\le t\le \infty}\,\sum_{|\alpha|+3|\beta|\le N}
\|(\epsilon\partial_\xi)^\alpha(\epsilon\partial_x)^\beta u(t,\cdot)\|_{L^p(\mathbb R^n)}
\le 
C_{N,T}\|u_0\|_{L^p(\mathbb R^n)},
\end{equation}
where $C_{N,T}=\mathcal{O}(T^{-\frac 12 N})$ as $T\rightarrow 0^+$.

