\noindent
\textbf{Structure of the paper.}
In Section~2, we introduce the precise functional framework and recall auxiliary results from the regularity theory of degenerate and singular parabolic equations. Sections~3-6 are devoted to prove suitable energy estimates in order to adaptat De Giorgi--Di Benedetto method (\cite{degiorgi, DIB}) to the chemotaxis system. In Section~7 we prove logarithmic estimates. In Section~8, we prove our main H\"older continuity result.

We now recall an alternative formulation of weak solutions to (1.1): fix $t \in (0,T)$, let $h > 0$ with $0 < t < t+h < T$, and replace in \eqref{1.3} the interval $(t_{1},t_{2})$ with $(t,t+h)$. Choosing a test function $\psi$ independent of $\tau \in (t,t+h)$, dividing by $h$, and using the Steklov averages, we obtain
\begin{equation}\label{weak:Steklov}
 \int_{{\cal{K}}\times \{ t \}} \Big[ (u^{h})_{\tau}\psi + \big( (\nabla u^{m})^{h}, \nabla \psi \big) 
- \chi \big( (u^{{\mathfrak q}-1}\nabla v)^{h}, \nabla \psi \big) \Big] \, dx = 0,
\end{equation}
for all $0<t<T-h$ and 
for all locally bounded, nonnegative test functions
\[
\psi \in W^{1,2}_{\mathrm{loc}}(0,T;L^{2}({\cal{K}})) \cap L^{2}_{\mathrm{loc}}(0,T; W^{1,2}_{0}({\cal{K}})).
\]
Fix a subinterval $0<t_1<t_2<T$, integrating over $[t_{1},t_{2}]$ and letting $h \to 0$ \eqref{weak:Steklov} recovers \eqref{1.3}.

\begin{lemma}[Heat Estimate]\label{lemma:heat}
Let $v$ be the solution of \eqref{eq:heat}. 
If $v_{0} \in W^{1,p}(\mathbb{R}^{N})$ and $w \in L^{\infty}(0,\infty; L^{p_{0}}(\mathbb{R}^{N}))$, with $1 \leq p_{0} \leq p \leq \infty$ and
\begin{equation}\label{m+1}
\frac{1}{p_{0}} - \frac{1}{p} < \frac{1}{N},
\end{equation}
then for $t \in [0,\infty)$ there exist constants $C_{0}, \overline{C}_{0} > 0$, depending only on $p,p_{0},N$, such that
\begin{equation}\label{ineq:heat}
\begin{aligned}
\|v(t)\|_{L^{p}(\mathbb{R}^{N})} &\leq \|v_{0}\|_{L^{p}(\mathbb{R}^{N})} 
+ C_{0} \|w\|_{L^{\infty}(0,T;L^{p_{0}}(\mathbb{R}^{N}))}, \\
\|\nabla v(t)\|_{L^{p}(\mathbb{R}^{N})} &\leq \|\nabla v_{0}\|_{L^{p}(\mathbb{R}^{N})} 
+ \overline{C}_{0} \|w\|_{L^{\infty}(0,T;L^{p_{0}}(\mathbb{R}^{N}))}.
\end{aligned}
\end{equation}
\end{lemma}

\begin{lemma}[Local Energy Estimates for $u > k$]\label{lem:energy2}
Let $(u,v)$ be a locally bounded weak solution of problem \eqref{1.1}. 
 There exist a constant $\gamma>0$ and a constant $I_{{\mathfrak d}}>0$ depending only on the data, such that, for any cut-off function $\eta \geq 0$ vanishing on $\partial K_{R}$, for every level $k > 0$ and for every cylinder $Q$, the following inequality holds:
\begin{align}
\label{EEu>k}
& \underset{-\theta R^2<t\leq 0}{\text{ess\,sup}} \int_{K_{R}} (u-k)^{2}\eta^{2}(x,t)\,dx 
+ \iint_{Q} u^{m-1}\,|\nabla((u-k)\eta)|^{2}\,dx\,dt \\
& \leq \gamma \iint_{Q} u^{m-1}(u-k)^{2}|\nabla \eta|^{2}\,dx\,dt 
+ I_{{\mathfrak d}}\,\mu_+^{\,2{\mathfrak q}-m-1} \left(\int_{-\theta R^{2}}^{0} 
\big|A_{k,R}(t)\big|^{\frac{\tilde r}{ \tilde \ell}}\,dt \right)^
{\!\frac{2}{\tilde r}(1+\kappa)} \nonumber \\
& \qquad \quad + \int_{K_{R}} (u-k)^{2}\eta^{2}(x,-\theta R^{2})\,dx 
+ \iint_{Q} (u-k)^{2}\eta\,\eta_{t}\,dx\,dt, \nonumber
\end{align}
\end{lemma}
with $A_{k,R}(t)=\{x\in K_{R}:\,u^{m}-k^{m}(x,t)>0\} $.
\begin{proof}
For $u>k$, consider the test function 
$
