 \end{aligned}\right.
 \end{equation}
The specificity is to work on the full line with a flux of firing neurons $h(x)u(x)$ at infinity which occurs because we assume that $\int_{\cdot}^{\infty} \frac{1}{h(x)}dx <+\infty$. This specificity also makes the mathematical interest and new difficulty for the analysis of the model.

\subsection{Motivations}
The study of this equation fundamentally differs, in its structure, from the classical linear-drift I\&F model introduced in \cite{BrHa}, 
 \begin{equation*}
 \left\{\begin{aligned}
 & \frac{\partial p}{\partial t}(t,x) +\frac{\partial}{\partial x}(h(x) p(t,x)) - \frac{\partial ^2p}{\partial x}(t,x) = \delta_{V_R}(x)N(t), \qquad t\geq 0, \; x\leq V_F,\\
 & p(t,V_F) = 0\\
 & N(t) = -\frac{\partial p}{\partial x}(t,V_F).
 \end{aligned}\right.
 \end{equation*}
This equation describes the probability density of neurons, according to their membrane potential~$x$. When a neuron reaches the potential of firing, $V_F$, then it is instantaneously re-injected with a membrane potential of reset, $V_R< V_F$ 
(we have chosen $V_R=0$ in~\eqref{eq:FPSL lin} for simplicity).

In order to catch the superlinear behaviour of the drift, we consider a generalized drift function $h\in \mathcal{C}^1$ that satisfies the following asymptotic behavior.
 \\
 \textbf{Behavior at $-\infty$:}
 \begin{equation}\label{eq:comportement h -infty}
 \exists x_0 \leq 0,\; h_0\in \mathbb{R} \quad \text{such that} \quad \forall x\leq x_0,\quad h(x) = -x+h_0.
 \end{equation}
 This assumption could be generalized, this specific form allows us to perform explicit calculations which avoid some technicalities.
 \\
 \textbf{Behavior at $+\infty$:}
 \begin{equation}\label{eq:comportement h +infty}
 \begin{cases}
 \exists x_1 \geq 0,\; \forall x\geq x_1, \quad h(x)>0, \quad h'(x)>0, 
 \\[2pt]
 \displaystyle \int_{x_1}^\infty\frac{dx}{h(x)}<\infty,
 \\[2pt]
 h(x)\sup_{y\geq x}\frac{h'(y)^2}{h(y)^4}\in L^1(x_1,\infty).
 \end{cases}
 \end{equation}
Both the quadratic and exponential models used in the literature satisfy these assumption. Throughout this paper we use these two assumptions without necessarily mentioning them. We also use the notation, 
\begin{equation}\label{def:calV}
\mathcal{H}(x) = \int_0^x h(y)dy, \quad \text{hence} \quad \mathcal{H}(x) \underset{-\infty}{\sim} -\frac{x^2}{2}, \quad \lim_{x\to \infty} \mathcal{H}(x) = +\infty .
\end{equation}
 The third line of assumptions \eqref{eq:comportement h +infty} ensures that 
 \begin{equation}\label{eq:limh'/h^2}
 \zeta(x):= \sup_{y\geq x}\frac{h'(y)}{h(y)^2}\in L^1(x_1,\infty) \qquad \text{and} \qquad \zeta(x) \to 0, \quad \text{as}\quad x\rightarrow \infty.
 \end{equation}
 Indeed, we define $f(x):= h(x)\sup_{y\geq x}\frac{h'(y)^2}{h(y)^4}$ and then, for $x\geq x_1$, $\zeta(x) = \big(\frac{f(x)}{h(x)}\big)^{1/2}$. According to assumption \eqref{eq:comportement h +infty}, both $\frac{1}{h}$ and $f$ belong to $L^1(x_1,\infty)$ so does $\zeta$. Since it is non-increasing, the result follows.

Such a drift $h$ has the property to send any potential that is located after $x_1$ to $+\infty$ in finite time. Indeed, ignoring the diffusion, the characteristics, $X(t)$, are determined by
 \[
 \frac{dX}{dt} = h(X(t)).
 \]
 When $X(0)>x_1$, the solution $X(t)$ blows-up in finite time, given by
 \[
 \lim_{t\rightarrow t_0}X(t) = +\infty, \qquad \text{with}\qquad t_0= \int_{X(0)}^\infty\frac{dy}{h(y)}.
 \]
 This kind of property is still true, with non-zero probability, when the membrane potential evolves according to the stochastic differential equation 
 \begin{equation}\label{eq:EDS IF}
 dX_t = h(X_t)\,dt +\sqrt{2} dB_t .
 \end{equation}
In both cases, the reset is obtained by setting $X_{t^+} = 0$ when $\lim_{t\to t^-} X_{t} =+\infty$.
 The interest of the linear model lies in building a solid theoretical foundation for the existence and regularity of solutions, as well as their asymptotic behavior, on order to better address the nonlinear case.
 \\
 One of the main difficulty is to make sense of the flux $N(t)$ of particles reaching $+\infty$ when we only handle a weak solution, $u(t)\in L^1(\mathbb{R})$ which is not defined pointwise.

\subsection{Main results}

Our first result concerns well-posedness in $L^1$ with minimal assumptions.

\subsection{Main results}

\begin{proof}
 Let $u_0 \in \mathcal{C}^1_c(\mathbb{R})$. By Proposition \ref{prop:regularity of u}, $u$ is continuous on $\mathbb{R}^+ \times \mathbb{R}$, which implies that the trace $t \mapsto w(t,0)$ is well-defined. Notice in addition that according to Proposition \ref{prop:MaxPrinc}, $w$ satisfies $w\in L^\infty(\R^+\times \R)$.
 Using Eq. \eqref{eq:FPSL lin}, $w$ satisfies the following equation
 \begin{align*}
 \partial_t w &= \frac{1}{u_\infty} \left( \partial^2_x(w u_\infty) - \partial_x(h w u_\infty) + N_u \delta_0 \right) \\
 &= \partial_x^2 w + \partial_x w \left( 2 \frac{u'_\infty}{u_\infty} - h \right) + \frac{w}{u_\infty} \underbrace{(u''_\infty - \partial_x(h u_\infty))}_{= -N_\infty \delta_0} + \frac{N_u}{u_\infty} \delta_0 \\
 &= \partial_x^2 w + \partial_x w \left( 2 \frac{u'_\infty}{u_\infty} - h \right) + \left( \frac{N_u}{u_\infty} - N_\infty \frac{w}{u_\infty} \right) \delta_0.
 \end{align*}
 Let $R > 0$ and let $\chi$ be defined as in Theorem \ref{th:entropy}. We introduce the cut-off function $\rho_R(x) = \int_x^\infty \chi(y-R) \, dy$.
 Define the truncated entropy functional by
 \[
 I_R(t) = \int_{\mathbb{R}} \rho_R(x) H(w(t,x)) u_\infty(x) \, dx.
 \]
 Differentiating with respect to time for $t \geq 0$, we obtain:
 \begin{align*}
 I'_R(t) &= \int_{\mathbb{R}} \rho_R(x) \left\{ \partial_x^2 w + \partial_x w \left( 2 \frac{u'_\infty}{u_\infty} - h \right) + \left( \frac{N_u}{u_\infty} - N_\infty \frac{w}{u_\infty} \right) \delta_0 \right\} H'(w) u_\infty \, dx.
 \end{align*}
 Handling the Dirac term at $x=0$, the expression becomes
 \begin{equation} \label{eq:IR_deriv_interm}
 \begin{aligned}
 I'_R(t) &= - \rho_R(0) N_\infty H'(w(t,0)) \left( w(t,0) - \frac{N_u(t)}{N_\infty} \right) \\
 &\quad + \int_{\mathbb{R}} \rho_R(x) \left\{ \partial_x^2 w u_\infty + \partial_x w (2 u'_\infty - h u_\infty) \right\} H'(w) \, dx.
 \end{aligned}
 \end{equation}
 Next we use the identity $H'(w) \partial_x^2 w = \partial_x^2 H(w) - (\partial_x w)^2 H''(w)$ and integrating by parts, the term involving $\partial_x^2 H(w)$ becomes
 \begin{align*}
 \int_{\mathbb{R}} \rho_R u_\infty \partial_x^2 H(w) \, dx
 &= - \int_{\mathbb{R}} \rho'_R u_\infty \partial_x w H'(w) \, dx - \int_{\mathbb{R}} \rho_R u'_\infty \partial_x w H'(w) \, dx.
 \end{align*}
 Substituting this back into \eqref{eq:IR_deriv_interm}, we get
 \begin{align*}
 I'_R(t) &= - \rho_R(0) N_\infty H'(w(t,0)) \left( w(t,0) - \frac{N_u(t)}{N_\infty} \right) - \int_{\mathbb{R}} \rho'_R u_\infty \partial_x w H'(w) \, dx\\
 &\quad - \int_{\mathbb{R}} \rho_R (\partial_x w)^2 H''(w) u_\infty \, dx + \int_{\mathbb{R}} \rho_R \partial_x w H'(w) \underbrace{(u'_\infty - h u_\infty)}_{= -N_\infty \mathbf{1}_{x \geq 0}} \, dx.
 \end{align*}
 Let us analyze the last integral involving the indicator function. We compute
 \begin{align*}
 \int_{\mathbb{R}} \rho_R \partial_x w H'(w) (-N_\infty \mathbf{1}_{x \geq 0}) \, dx
 &= - N_\infty \int_0^\infty \rho_R(x) \partial_x H(w(t,x)) \, dx \\
 &= - N_\infty \left[ \rho_R(x) H(w(t,x)) \right]_{0}^\infty + N_\infty \int_0^\infty \rho'_R(x) H(w(t,x)) \, dx \\
 &= N_\infty \rho_R(0) H(w(t,0)) + N_\infty \int_{\mathbb{R}} \rho'_R(x) H(w(t,x)) \, dx.
 \end{align*}
 Now we pass to the limit as $R \to \infty$.
 Using the bound $u_\infty^{1/2} \partial_x w \in L^2(\mathbb{R}^+ \times \mathbb{R})$ from \eqref{eq: borne d_x w } and that $H'(w) \in L^\infty$, the Cauchy-Schwarz inequality gives
 \[
 \left| \int_{\mathbb{R}} \rho'_R u_\infty \partial_x w H'(w) \, dx \right| \leq C \left( \int_{\mathbb{R}} |\rho'_R| u_\infty \, dx \right)^{1/2} \left( \int_{\mathbb{R}} |\rho'_R| u_\infty (\partial_x w)^2 \, dx \right)^{1/2}.
 \]
 Thus, for almost every $t \geq 0$, this term vanishes as $R \to \infty$.
 Furthermore, $\lim_{R \to \infty} \rho_R(0) = 1$, and by the definition of $\rho_R$ we have
 \[
 \lim_{R \to \infty} N_\infty \int_{\mathbb{R}} \rho'_R(x) H(w(t,x)) \, dx = \lim_{R \to \infty} - N_\infty \int_{\mathbb{R}} \chi(x-R) H(w(t,x)) \, dx.
 \]
 Recalling that in the weak sense $\lim_{R \to \infty} \int_{\mathbb{R}} \chi(x-R) w(t,x) \, dx = \frac{N_u(t)}{N_\infty}$, and using Jensen's inequality, we have
 \[
 \liminf_{R \to \infty} \int_{\mathbb{R}} \chi(x-R) H(w(t,x)) \, dx \geq H \left( \frac{N_u(t)}{N_\infty} \right).
 \]
 Finally, gathering all terms and taking the limit $R \to \infty$, we obtain
 \begin{align*}
 \frac{d}{dt} \int_{\mathbb{R}} H(w) u_\infty \, dx
 &\leq - N_\infty \left[ H \left( \frac{N_u}{N_\infty} \right) - H(w(t,0)) - H'(w(t,0)) \left( \frac{N_u}{N_\infty} - w(t,0) \right) \right]
 \\
 &\quad - \int_{\mathbb{R}} (\partial_x w)^2 H''(w) u_\infty \, dx.
 \end{align*}
 Since $H$ is convex, the term in bracket is non-negative, as well as the integral term. \\

\begin{proof}
 To get the desired lower bound, we first introduce the function $\varphi$. For $x \in \mathbb{R}$, define
 \[
 \varphi(x)
 = \int_{0}^{x} e^{-\mathcal{H}(y)}
 \left( \int_{-\infty}^{y} e^{\mathcal{H}(z)}\,dz \right) dy .
 \] 
 This function satisfies the following properties
 \begin{equation}\label{eq:eqdif sur phi}
 \fa x \in \R, \qquad\varphi''(x)+h(x)\varphi'(x) = 1,
 \end{equation}
 \begin{equation}\label{eq:behavior phi}
 \varphi(x) \sim_{x\rightarrow -\infty}- \log|x|\:\:,\:\:
 \lim_{x\rightarrow \infty} \varphi(x) = c_\varphi <\infty \text{ and } \varphi \text{ is non-decreasing on }\R, 
 \end{equation}
 \begin{equation}\label{eq:signe phi}
 \varphi(x) \geq 0\Longleftrightarrow x\geq 0.
 \end{equation}
Also, since $|\varphi(x)| \leq M \big((-x)_++1\big)$, for a constant $M\geq 0$, for any $f\in E$, we have
 \begin{equation}\label{eq:encadrement phi E}
 \int_\R|\varphi(x)f(x)|dx\leq M\int_\R\big((-x)_++1\big)|f(x)|dx=M\|f\|_E.
 \end{equation}
 Now, let $I(t) = \int_\R\varphi(x)u(t,x)\,dx$. By \eqref{eq:encadrement phi E} together with point~2 of Lemma~\ref{lem:estimation u_E}, this quantity is well defined for all $t \geq 0$. Then, differentiating $I(t)$, we obtain
 \begin{align*}
 I'(t) &= \int_\R\big(-\partial_x\big(h(x)u\big)+\partial_x^2u + N_u(t)\delta_0\big)\varphi(x)\,dx \\
 &= \int_\R u(t,x)\big(h(x)\varphi'(x)+\varphi''(x)\big)\,dx - \varphi(0)N_u(t) \\
 &= \int_\R u(t,x)\,dx - c_\varphi N_u(t) =1-c_\varphi N_u(t).
 \end{align*}
 Therefore, integrating on $(0,t)$ we obtain thanks to \eqref{eq:signe phi}
 $$
 \fa t\geq 0,\qquad \int_0^t N_u(\tau)\,d\tau = \frac{1}{c_\varphi}\big(t+I(0)-I(t)\big).
 $$
 Now, using the properties \eqref{eq:encadrement phi E} and \eqref{eq:behavior phi} for $I(t)$, we estimate 
 \begin{align*}
 I(0)-I(t) &= \int_\R\varphi(x)\big(u_0(x)-u(t,x)\big)\,dx 
 \\
 &\geq -\int_{-\infty}^0|\varphi(x)|u_0(x)\,dx - \int_{0}^\infty|\varphi(x)|u(t,x)\,dx \\
 &\geq -M \|u_0\|_{E} - c_\varphi \int_0^\infty u(t,x)\,dx \quad \text{according to \eqref{eq:encadrement phi E}} \text{ and } \eqref{eq:behavior phi},\\
 &\geq -M C - c_\varphi \qquad\text{since}\quad \int_0^\infty u(t,x)dx \leq 1. \\
 \end{align*}
 Therefore, taking $t_C = MC+1+c_\varphi$, we get, for any $t\geq t_C$,
 $$
 \int_0^t N_u(\tau)\,d\tau \geq \frac{1}{c_\varphi}>0.
 $$
\end{proof}
Using this lower bound on the source term, we construct an explicit subsolution which allows us to establish the Doeblin condition.
\begin{prop}\label{prop:minoration S(t)u}
 For any $ C\geq 0$, there exists a time $t'_C\geq 0$, and a probability density $\mu\in L^1(\R)$ such that for any probability density $u_0\in E$ that satisfies $\|u_0\|_E\leq C$, we have
 \[
 \fa t \geq t_C',\quad S(t)u_0\geq \eta(t) \times \mu.
 \]
 where $\eta$ is a strictly positive continuous function. 
 \end{prop}

