[Well-posedness in $L^1$] \label{th:existence weak sol}
	Assume that $h$ satisfies
	\begin{equation}\label{eq:comportement h -infty}
		\exists x_0 \leq 0,\; h_0\in \R \quad \text{such that} \quad \fa x\leq x_0,\quad h(x) = -x+h_0.
	\end{equation}
	and
	\begin{equation}\label{eq:comportement h +infty}
	\begin{cases}
		\exists x_1 \geq 0,\; \fa x\geq x_1,  \quad h(x)>0, \quad h'(x)>0, 
		\\[2pt]
		\displaystyle \int_{x_1}^\infty\frac{dx}{h(x)}<\infty,
		\\[2pt]
		h(x)\sup_{y\geq x}\frac{h'(y)^2}{h(y)^4}\in L^1(x_1,\infty).
		\end{cases}
	\end{equation}
	Then, for any initial data $u_0\in L^1(\mathbb{R})$, there exists a unique weak solution $(u,N_u)\in L^\infty(\mathbb{R}^+;L^1(\mathbb{R}))\times L^1_{loc}(\mathbb{R}^+)$ of
	\begin{equation}\label{eq:FPSL lin}
		\left\{\begin{aligned}
			& \frac{\partial u}{\partial t}(t,x) +\frac{\partial}{\partial x}\big((h(x)u(t,x)\big) - \frac{\partial ^2u}{\partial x^2}(t,x) = \delta_{0}(x)N(t), \quad x\in \mathbb{R}, t\geq 0,
			\\
			& N(t) = \lim_{x\rightarrow \infty}h(x)u(t,x),
			\\
			& u(t=0,x) = u_0(x)\in L^1(\R).
		\end{aligned}\right.
	\end{equation}
	i.e., that satisfies
	\begin{align} 
				\int_0^\infty \! \int_\R u(t,x)\Big(-\partial_t\varphi(t,x)&-h(x)\partial_x\varphi(t,x)-\partial_x^2\varphi(t,x)\Big)\,dx\,dt \notag
				\\
				& = \int_0^\infty N_u(t)\varphi(t,0)\,dt
				+\int_\R u_0(x)\varphi(0,x)\,dx. \label{eq:formulation faible FPS} 
			\end{align}
	and
	\begin{equation}\label{eq:Conservation mass}
			\text{for } a.e. \; t\geq0 \quad 
			\int_\R u(t,x)\,dx =  \int_\R u_0(x)\,dx .
			\end{equation}
	In addition, we have 
	 	\begin{equation}\label{eq:L1Contract}
	    \text{for a.e. }  t > 0, \quad \int_\mathbb{R} |u(t,x)|\,dx \leq  \int_\mathbb{R} |u_0(x)| \,dx,
	\end{equation}
	\begin{equation}\label{eq: U_T bound}
	    \forall T\geq 0, \quad \sup_{x\in \mathbb{R}}\int_0^T|h(x)u(t,x)|\,dt <\infty \quad \text{and}\quad U_T = \int_0^Tu(t)\,dt \in W^{1,\infty}(\mathbb{R}).
	\end{equation}

