\begin{Proposition}
\label{Proposition:3.1}{\cites{VZ2, WWZ, Z4}}
	Let $u_0 \in L^2(\Omega)$. 
	Suppose that $\Phi\in C^1(\R)$ satisfies that there exist $c_1, c_2>0$ such that
	\begin{equation}
	\label{phi}\tag{H$\Phi$}
		c_1 \le \Phi'(r) \le c_2,\qquad r\in\R.
	\end{equation}
	Then problem \eqref{eq:IBP} possesses a weak solution $u \in L^2_{\rm loc}(0,\infty; H_0^1(\Omega))$.
