\label{main}  Let $q(x,u)$ be supported on $\{|x|\leq R\} \times {\mathbb R}$. 
 Let  $\varphi , \chi\in C_0^\infty({\mathbb R})$  be real valued, let $\omega, \theta\in {\mathbb S}^{n-1}$,  $V=(\pm 1,\theta)$ and  $W=( -1,\omega)$. Let $\vphi_{{}_V}(x)$ and $\chi_{{}_W}(x)$  be defined as in \eqref{defphi}.  For $A,B\in {\mathbb R}$,
 \[
\begin{split}
 u_{inc}(h,V,W,x)= \vphi_{{}_V}(x) +  h \chi_{{}_W}(x) \biggl( A \cos\biggl(\frac{i}{h} \bigl( \langle x,W\ran_{{}_M}\bigr)\biggr)+ B \sin\biggl(\frac{i}{h} \bigl( \langle x,W\ran_{{}_M}\bigr)\biggr)\biggr),
\end{split}
 \]
which satisfies \eqref{NLWE} if $x$ is not on the support of $\chi_{{}_W}$.  For any $N\in {\mathbb N}$ and any interval $[T_0,T]_{x_0}$,  there exists a unique solution $u(h,V,W,x)$ of \eqref{NLWE}  such that 
\[
u(h,V,W,x)= u_{inc}(h,V,W,x) \text{ for } x_0\ll 0 \text{ outside the support of } q(x,u),
\]
which has an expansion of the form
\begin{equation}\label{defuh}
\begin{split}
& u_{N}(h,V,W,x)=  \vphi_{{}_V}(x) +  h \sum_{p=0}^N h^p \sum_{\pm m=0}^N  e^{\frac{im}{h} \langle x,W\ran_{{}_M}}  A_{m,p}(V,W,x)+ h^{N+1} \mce_N(h,V,W,x),\\
& \text{ where } A_{m,p} \in C^\infty, \;\ \overline{A_{m,p}}= A_{-m,p},  \text{ so  the expansion is real valued,} 
\end{split}
\end{equation}
and satisfy the following initial conditions when $x_0\ll 0$:
\begin{equation}\label{defcoeff}
\begin{split}
& A_{0,p}(V,W,x)=0, \\
&  A_{1,0}(V,W,x)= \frac{1}{2} \chi_{{}_W}(x)(A-i B), \;\    A_{m,0}(V,W,x)=0, \;\ \text{ if } m \ge 2,\\
 & A_{m,p}(V,W,x)=0, \text{ if } p\ge1.
\end{split}
 \end{equation}
The coefficient $A_{1,0}$ satisfies the transport equation
\begin{equation}\label{eqa1p0}
\begin{split}
& \bigl( \p_{x_0}- \omega\cdot \nabla_{x^{\prime}} \bigr) A_{1,0}= F(V,W,x) A_{1,0}, \text{ where } \\
& F(V,W,x)=\langle  q\bigl(x, \vphi_{{}_V}(x)\bigr)  \vphi_{{}_V}^\prime(x)   \widetilde V,\widetilde W \ran_M, \;\ \widetilde W=(1,\omega).
\end{split}
\end{equation}
Moreover, for any $\tau>0$, the error term satisfies
\[
\begin{split}
& \sup_{x_0\in [-\tau,\tau]}\| \mce_N\|_{{}_{L^2({\mathbb R}^n)}}\leq C(N,\tau), \;\  
\sup_{x_0\in [-\tau,\tau]}\| \mce_N\|_{{}_{L^\infty ({\mathbb R}^n)}}\leq C(N,\tau), \\
& \sup_{x_0\in [-\tau,\tau]}\| D_x^\alpha \mce_N\|_{{}_{L^2({\mathbb R}^n)}}\leq C_\alpha(N,\tau) h^{1-|\alpha|}, \;\
\sup_{x_0\in [-\tau,\tau]}\| D_x^\alpha \mce_N\|_{{}_{L^2({\mathbb R}^n)}}\leq C_\alpha(N,\tau) h^{1-|\alpha|}, \;\ |\alpha|\geq 1.
\end{split}
\]

