To prove the main theorem, the authors combine the following steps.
\begin{itemize}
\item \emph{Existence:} later, for all $c>0$ they prove existence of a minimizer $\rho_c\in X$ for $\mathcal{F}_c$.
\item \emph{Uniqueness/monotonicity/shape via a BVP:} next they show the minimizer $\rho_c$ is unique; they also “provide the monotonicity property with respect to the parameter $c$” and “characterize the shape of the minimizer $\rho_c$ solving a boundary value problem.” Concretely, by deriving the Euler–Lagrange equation they obtain that any minimizer solves
\[
\left\{
\begin{aligned}
&\varrho''=\frac{(\varrho^2-c)(1+(\varrho')^2)}{\varrho(\varrho^2+c)}\\
&\varrho(\pm h)=r.
\end{aligned}
\right.
\]
We first use the following proposition.
\begin{proposition}
\label{prop:proprieta_bvp}
Let $\rho \in C^2([-h,h])$ be a strictly positive solution of the boundary value problem 
\begin{equation}\label{bvp}
\left\{\begin{array}{ll}
\displaystyle \rho''=\frac{(\rho^2-c)(1+(\rho')^2)}{\rho(\rho^2+c)}\\
\\
\rho(-h)=\rho(h)=r.
\end{array}\right.
\end{equation}
Then the following facts hold true.
\begin{itemize}
\item[a)] If $c<r^2$, then 
\begin{equation}\label{rho-}
\rho(x)=\sqrt{ \frac{E}{2}\sqrt{E^2-4c}\cosh\frac{2x}{E}+\frac{E^2}{2}-c}
\end{equation}
where $E= E(c)$ is a positive constant that satisfies 
\begin{equation}\label{p-}
\cosh\frac{2h}{E}=\frac{2r^2-E^2+2c}{E\sqrt{E^2-4c}}.
\end{equation}
Moreover, $\rho$ is even, strictly convex and $\rho_0<\rho<r$ on $(-h,h)$.
\item[b)] If $c>r^2$, then 
\begin{equation}\label{rho+}
\rho(x)=\sqrt{-\frac{E}{2}\sqrt{E^2-4c}\cosh\frac{2x}{E}+\frac{E^2}{2}-c}
\end{equation}
where $E= E(c)$ is a positive constant that satisfies 
\begin{equation}\label{p+}
\cosh\frac{2h}{E}=-\frac{2r^2-E^2+2c}{E\sqrt{E^2-4c}}.
\end{equation} 
Moreover, $\rho$ is even, strictly concave and $r<\rho$ on $(-h,h)$.
\end{itemize}
Moreover, both in cases a) and c), it holds 
\begin{equation}\label{Ec}
E^2-4c>0.
\end{equation}
\end{proposition}
They compute explicit solution families (with a parameter $E=E(c)>0$ fixed by a transcendental equation from the boundary conditions), and although the transcendental equation may have multiple solutions (so “we do not have uniqueness of critical points”), in both regimes $c<r^2$ and $c>r^2$ they prove there is a unique critical point lying above $\rho_0$, yielding uniqueness of the minimizer. More precisely, for $c\in(0,r^2)$ they use the following lemma: 
\begin{lemma}
\label{lemma:unicita_soluzioni_1}
Let $h,r>0$ be such that $\sfrac{h}{r}\in (0,\omega]$ and let $c\in (0,r^2)$. Then, there exists a unique
$$\smileacc{E}_c(h,r)>\Pi_0(h,r)$$
which solves \eqref{e:caso_c<r^2}.
\end{lemma}
For $c>r^2$ they use the following lemma:
\begin{lemma}
\label{lemma:unicita_soluzioni_2}
Let $h,r>0$ be such that $\sfrac{h}{r}\in (0,\omega]$ and let $c>r^2$. Then, there exists a unique 
$$\frownacc{E}_c(h,r)>0$$
solution of \eqref{e:caso_c>r^2}.
\end{lemma}
\item \emph{Large-$c$ behavior:} later, “by essentially a $\Gamma$-convergence procedure,” they characterize minimizers as $c\to\infty$, noting that “$c\mapsto \rho_c$ is an increasing function and $\rho_c\to \rho_\infty$ uniformly on $[-h,h]$,” and that this matches the expectation that $\mathcal{F}_c/c$ $\Gamma$-converges to $\mathcal{F}_\infty$.
\end{itemize}
A key technical point is that the energy density is “not coercive” and has “linear growth in $\varrho'$,” so they “relax $\mathcal{F}_c$ weakly in $W^{1,1}_{\rm loc}(-h,h)$” (later) and then prevent vanishing of $\varrho$ by splitting cases.
\begin{itemize}
\item If $c\in(0,r^2)$ (later), they show it is “energetically convenient to lie above $\sqrt c$,” proving $\mathcal{F}_c(\varrho\vee\sqrt c)\le\mathcal{F}_c(\varrho)$, hence they minimize the relaxed functional over $\{\varrho\in W^{1,1}_{\rm loc}(-h,h):\varrho\ge\sqrt c\}$. A first variation argument gives convexity and Sobolev boundary conditions; moreover (when 
\begin{equation}\label{cond_catenaria}
\frac{h}{r}\le \omega,
\end{equation}
holds) they use the following lemma to show $\mathcal{F}_c(\varrho\vee\rho_0)\le\mathcal{F}_c(\varrho)$, implying minimizers belong to $W^{1,1}(-h,h)$:
\begin{lemma}\label{tilli1}
For all $c>0$ and for all $\rho \in X$ we have $\mathcal F_c(\rho \vee \rho_0)\le \mathcal F_c(\rho)$.
\end{lemma}
\item If $c>r^2$ (later), they minimize the relaxed functional over $\{\varrho\in W^{1,1}_{\rm loc}(-h,h):\varrho\ge c_0\}$ with $c_0=\min\rho_0$; a first variation argument yields concavity and the boundary conditions. To conclude they show an upper bound is convenient: by the following lemma, $\mathcal{F}_c(\varrho\wedge\rho_\infty)\le\mathcal{F}_c(\varrho)$:
\begin{lemma}\label{tilli2}
For all $c>0$ and for all $\rho \in X$, we have $\mathcal F_c(\rho \wedge \rho_\infty)\le \mathcal F_c(\rho)$.
\end{lemma}
Here $\rho_\infty$ is the unique minimizer of $\mathcal{F}_\infty(\varrho)=\int_{-h}^h \frac{\sqrt{1+(\varrho')^2}}{\varrho}\,dx$, as ensured by the following lemma:
\begin{lemma}
\label{lemma:esiste_minimo_Finfty}
    The energy functional $\mathcal{F}_\infty$ defined in \eqref{e:F_infty} admits a unique minimizer which is given by 
    \[
    \rho_\infty(x)=\sqrt{h^2+r^2-x^2}.
    \]
\end{lemma}
\end{itemize}
They also note the special case $c=r^2$ where “the constant function $\varrho=\sqrt c$ is the unique minimizer,” matching the statement in the main theorem.

expanded_theorem:
\label{thm_existence}
The functional $\mathcal F_c$ admits a unique minimizer $\rho_c \in X$. Moreover, the following complete characterization of the minimizer $\rho_c$ holds true.
\begin{itemize}
\item[a)] If $c<r^2$, in the equation 
\begin{equation*}
\cosh\frac{2h}{E}=\frac{2r^2-E^2+2c}{E\sqrt{E^2-4c}},
\end{equation*}
there exists only one solution $\smileacc{E}(c)>\Pi_0(h,r)$ and 
\[
\rho_c(x)=\sqrt{
    \frac{\smileacc{E}}{2}\sqrt{\smileacc{E}^2-4c}\cosh\frac{2x}{\smileacc{E}}+\frac{\smileacc{E}^2}{2}-c}.
\]
In this case, $\rho_c\in C^\infty([-h,h])$, it is even, strictly convex and $\rho_0<\rho_c<r$ on $(-h,h)$.
\item[b)] If $c=r^2$, then $\rho_c(x)=r$ for all $x \in [-h,h]$.
\item[c)] If $c>r^2$, the equation 
\begin{equation*}
\cosh\frac{2h}{E}=\frac{-2r^2+E^2-4c}{E\sqrt{E^2-4c}}
\end{equation*}
has a unique solution $\frownacc{E}(c)$ which is positive and 
\[
\rho_c(x)=\sqrt{
    -\frac{\frownacc{E}}{2}\sqrt{\frownacc{E}^2-4c}\cosh\frac{2x}{\frownacc{E}}+\frac{\frownacc{E}^2}{2}-c}.
\]
In this case, $\rho_c\in C^\infty([-h,h])$, it is even, strictly concave and $r<\rho_c<\rho_\infty$ on $(-h,h)$ where 
$$\rho_\infty(x)=\sqrt{h^2+r^2-x^2}.$$
Moreover, $\rho_c\to \rho_\infty$ uniformly on $[-h,h]$ as $c\to +\infty$. 
\end{itemize}
Finally, $\rho_{c_1}<\rho_{c_2}$ on $(-h,h)$ whenever $c_1<c_2$.

