theorem.content:
[Counterexample to the Berger--Coburn conjecture]\label{thm:main}
There exists a measurable symbol $g$ on $\mathbb C^n$ such that:
\begin{enumerate}
\item $gk_a\in L^2(d\mu)$ for every $a\in\mathbb C^n$;
\item the Toeplitz operator $T_g$ extends to a bounded operator on $H^2(\mathbb C^n,d\mu)$;
\item the heat transform $g^{(1/4)}$ is unbounded on $\mathbb C^n$.
\end{enumerate}

ref_dict.conj:BC:
\begin{conjecture}[Berger--Coburn {\cite[\S 6]{BC94}}]\label{conj:BC}
Assume that $g$ is measurable and that $gk_a\in L^2(d\mu)$ for every $a\in\mathbb C^n$.
Then $T_g$ extends to a bounded operator on $H^2(\mathbb C^n,d\mu)$ if and only if
$g^{(1/4)}$ is bounded on $\mathbb C^n$.\footnote{We use ``extends to'' to account for the dense domain of $T_g$ noted in \cite[\S 1]{BC94}.}
\end{conjecture}

full_context:
Fix $n\ge 1$. Let $H^2(\mathbb C^n,d\mu)$ be the Bargmann space of entire functions square-integrable with respect to the Gaussian measure
\[
d\mu(z)=(2\pi)^{-n}e^{-|z|^2/2}\,dv(z),
\]
where $dv$ is Lebesgue measure on $\mathbb C^n\simeq \mathbb R^{2n}$.
Let $P\colon L^2(d\mu)\to H^2(d\mu)$ be the orthogonal projection with reproducing kernel $K(z,w)=e^{z\cdot\overline w/2}$. Following \cite[\S 1]{BC94}, if $g$ is measurable and satisfies
\[
gK(\cdot,a)\in L^2(d\mu)\qquad\text{for every }a\in\mathbb C^n,
\]
one can define a densely defined Toeplitz operator by
\[
T_g f=P(gf),
\qquad
(T_g f)(z)=\int_{\mathbb C^n} g(w)\,K(z,w)\,f(w)\,d\mu(w),
\]
with natural domain $\{f\in H^2(d\mu): gf\in L^2(d\mu)\}$.
The guiding question is to characterize those symbols $g$ for which $T_g$ extends to a bounded operator on $H^2(\mathbb C^n,d\mu)$.

\subsection*{Heat flow and the endpoint problem}
A convenient way to package information about a symbol is via Gaussian convolution.
For $t>0$, the heat transform of $g$ is
\begin{equation}\label{eq:intro-heat}
g^{(t)}(a)=(4\pi t)^{-n}\int_{\mathbb C^n} g(w)\,e^{-|w-a|^2/(4t)}\,dv(w),
\end{equation}
whenever the integral is absolutely convergent. Let $k_a$ be the normalized reproducing kernel at $a$.
Then the Berezin transform identity gives
\begin{equation}\label{eq:intro-berezin}
(T_g k_a,k_a)=g^{(1/2)}(a),
\end{equation}
so boundedness of $T_g$ forces boundedness of $g^{(1/2)}$. For positive symbols $g$ this necessary condition is also sufficient: $T_g$ is bounded if and only if $g^{(1/2)}$ is bounded \cite{BC94}.

For general complex-valued symbols, Berger and Coburn established two complementary norm estimates that leave only a single endpoint unresolved \cite{BC94}. In the normalization \eqref{eq:intro-heat}, for every $t\in(\tfrac14,1)$ there exists $C(t)$ such that
\begin{equation}\label{eq:intro-est-upper}
\|g^{(t)}\|_\infty \le C(t)\,\|T_g\|,
\end{equation}
and for every $t\in(0,\tfrac14)$ there exists $C(t)$ such that
\begin{equation}\label{eq:intro-est-lower}
\|T_g\| \le C(t)\,\|g^{(t)}\|_\infty .
\end{equation}
Thus the boundedness problem reduces to the borderline time $t=\tfrac14$.

\begin{conjecture}[Berger--Coburn {\cite[\S 6]{BC94}}]\label{conj:BC}
Assume that $g$ is measurable and that $gk_a\in L^2(d\mu)$ for every $a\in\mathbb C^n$.
Then $T_g$ extends to a bounded operator on $H^2(\mathbb C^n,d\mu)$ if and only if
$g^{(1/4)}$ is bounded on $\mathbb C^n$.\footnote{We use ``extends to'' to account for the dense domain of $T_g$ noted in \cite[\S 1]{BC94}.}
\end{conjecture}

\subsection*{Related work}
There is a large literature on boundedness and compactness of Toeplitz operators on Fock space;
general background can be found in \cite{ZhuFock,IsralowitzZhu2010Toeplitz}.
Heat-flow methods have also been developed for structured symbol classes, notably BMO-type symbols and
compactness criteria; see \cite{BCI2010,CoburnIsralowitzLi2011}. Other approaches exploit additional
symmetry or algebraic structure, such as radial and invariant classes
\cite{GrudskyVasilevski2002RadialComponentEffects,EsmeralRozenblumVasilevski2019LinvariantFockCarleson}
or operator-algebraic perspectives \cite{Bauer2005PsiFrechetThesis,BauerFulscheRodriguezRodriguez2024OperatorsFockToeplitzAlgebra}.
In a different direction, the endpoint philosophy behind Conjecture~\ref{conj:BC} has been verified for
metaplectic Toeplitz operators, where the symbols are given by quadratic-exponential data and the Weyl
calculus can be made essentially explicit; see \cite{CHS2019,CHSW2021,CHS2023,Xiong2023}.

\subsection*{Main result}
The purpose of this paper is to show that Conjecture~\ref{conj:BC} fails for general measurable symbols. 
More precisely, we disprove the implication
\[
T_g\in B\big(H^2(\mathbb C^n,d\mu)\big)\ \Longrightarrow\ g^{(1/4)}\in L^\infty(\mathbb C^n)
\]
even for a symbol in the natural class $L^2(\mathbb C^n,d\mu)$.

\begin{abstract}
Berger and Coburn proposed an endpoint boundedness criterion for Toeplitz operators on the Bargmann--Fock space in which the decisive quantity is the heat transform of the symbol at the borderline time $t=\tfrac14$, the time naturally singled out by the Weyl calculus under the Bargmann transform. We show that this criterion fails for general measurable symbols in every complex dimension $n\ge 1$. Concretely, we construct a measurable symbol $g\in L^2(\mathbb C^n,d\mu)$ such that $gk_a\in L^2(d\mu)$ for every normalized reproducing kernel $k_a$, and the associated Toeplitz form extends to a bounded operator on $H^2(\mathbb C^n,d\mu)$, but the heat transform $g^{(1/4)}$ is unbounded on $\mathbb C^n$. The example is obtained by summing translated bounded ``blocks'' whose Toeplitz norms are summable while their $t=\tfrac14$ heat profiles have fixed size. The blocks are produced by combining a Hilbert--Schmidt estimate for Weyl quantization with the Bargmann correspondence between Weyl and Toeplitz operators.
\end{abstract}

\subsection*{Heat flow and the endpoint problem}
A convenient way to package information about a symbol is via Gaussian convolution.
For $t>0$, the heat transform of $g$ is
\begin{equation}\label{eq:intro-heat}
g^{(t)}(a)=(4\pi t)^{-n}\int_{\mathbb C^n} g(w)\,e^{-|w-a|^2/(4t)}\,dv(w),
\end{equation}
whenever the integral is absolutely convergent. Let $k_a$ be the normalized reproducing kernel at $a$.
Then the Berezin transform identity gives
\begin{equation}\label{eq:intro-berezin}
(T_g k_a,k_a)=g^{(1/2)}(a),
\end{equation}
so boundedness of $T_g$ forces boundedness of $g^{(1/2)}$. For positive symbols $g$ this necessary condition is also sufficient: $T_g$ is bounded if and only if $g^{(1/2)}$ is bounded \cite{BC94}.

\begin{conjecture}[Berger--Coburn {\cite[\S 6]{BC94}}]\label{conj:BC}
Assume that $g$ is measurable and that $gk_a\in L^2(d\mu)$ for every $a\in\mathbb C^n$.
Then $T_g$ extends to a bounded operator on $H^2(\mathbb C^n,d\mu)$ if and only if
$g^{(1/4)}$ is bounded on $\mathbb C^n$.\footnote{We use ``extends to'' to account for the dense domain of $T_g$ noted in \cite[\S 1]{BC94}.}
\end{conjecture}

\subsection*{Main result}
The purpose of this paper is to show that Conjecture~\ref{conj:BC} fails for general measurable symbols. 
More precisely, we disprove the implication
\[
T_g\in B\big(H^2(\mathbb C^n,d\mu)\big)\ \Longrightarrow\ g^{(1/4)}\in L^\infty(\mathbb C^n)
\]
even for a symbol in the natural class $L^2(\mathbb C^n,d\mu)$.

Because $g$ need not be bounded, the integral formula for $T_g$ is not \emph{a priori} meaningful on all
of $H^2(d\mu)$. In our construction, $gk_a\in L^2(d\mu)$ for every $a$, so the Toeplitz matrix
coefficients
\[
(T_g k_a,k_b)=(gk_a,k_b)
\]
are well defined on the span of the kernel vectors. We show that these coefficients define a bounded
operator on $H^2(d\mu)$, and we denote its bounded extension again by $T_g$.

Define a Schwartz symbol
\begin{equation}\label{eq:gR}
g_R=e^{-(1/4)\Delta}a_R,
\end{equation}
where $\Delta$ is the Euclidean Laplacian on $\mathbb R^{2n}$. Then by the heat semigroup property,
\begin{equation}\label{eq:gR-quarter}
g_R^{(1/4)}=a_R.
\end{equation}
In particular, $\|g_R^{(1/4)}\|_\infty=1$. Since $g_R$ is bounded, $T_{g_R}$ is a bounded Toeplitz operator with $\|T_{g_R}\|\le \|g_R\|_\infty$.

\begin{lemma}\label{lem:sum}
Assume $(g_m)$ satisfies $(\star)$ and that each $T_{g_m}$ is bounded with $\sum_m \|T_{g_m}\|<\infty$. Let $X=\sum_m T_{g_m}$ (operator-norm convergence). Then there exists a measurable $g$ such that:
\begin{enumerate}
\item $gk_a\in L^2(d\mu)$ for every $a$ and, for each $a$, the series $\sum_m g_mk_a$ converges in $L^2(d\mu)$ to $gk_a$;
\item $T_g$ is bounded and $T_g=X$;
\item for every $a\in\mathbb C^n$, the series $\sum_m g_m^{(1/4)}(a)$ converges absolutely and
\begin{equation}\label{eq:sum-heat}
g^{(1/4)}(a)=\sum_{m=1}^\infty g_m^{(1/4)}(a).
\end{equation}
\end{enumerate}
\end{lemma}

\begin{theorem}\label{thm:main}
There exists a measurable symbol $g$ on $\mathbb C^n$ such that:
\begin{enumerate}
\item $gk_a\in L^2(d\mu)$ for every $a\in\mathbb C^n$;
\item $T_g$ is bounded on $H^2(\mathbb C^n,d\mu)$;
\item $g^{(1/4)}$ is unbounded on $\mathbb C^n$.
\end{enumerate}
\end{theorem}

