\subsection{Applications} The description of the skew fields in terms of skew power series allows one to describe all maximal orders in $\Q^F(\G)$, which will be done in \cref{cor:max-orders}. This has applications in non-commutative Iwasawa theory. Indeed, employing Venjakob's Weierstraß theory for skew power series rings, it is possible to verify integrality of certain characteristic elements attached to number fields \cite{epac} or to elliptic curves \cite{FM}.

Finally, we record a description of $\DFchi$ in terms of $\gcpf$ under the total ramification assumption.
\begin{proposition}[{\cite[Corollary 6.11]{W}}] \label{DchiW-bigoplus}
 Let $\chi\in\Irr(\G)$ and let $\eta\mid\res^\G_H\chi$ be an irreducible constituent thereof. Suppose that the extension $F(\eta)/F_\chi$ is \textbf{totally ramified}. Then there is an isomorphism of rings
 \[\DFchi \simeq \bigoplus_{\substack{\ell=0\\ \vf\mid \ell}}^{p^{n_0}-1} \tD_\eta \left(\gcpf\right)^{\ell/\vf}\]
 where conjugation by $\gcpf$ acts as $\tauf$ on $\tD_\eta$. Moreover, the statements of \cref{thm:main} hold in this case.
\end{proposition}

Recall that in the Wedderburn decomposition \eqref{eq:QFG-Wedderburn} of $\Q^F(\G)$, the character $\chi$ runs through the $\sim_F$-equivalence classes of irreducible characters of $\G$ with open kernel, and $\chi\sim_F\chi'$ if there is a $\sigma\in\Gal( F_\chi/ F)$ such that ${}^\sigma(\res^\G_H \chi)=\res^\G_H \chi'$. 
Heuristically, the centre $\cent(\DFchi)$ is closely connected to $F_\chi$: this is \cite[Lemma~6.8 and Corollary~6.11]{W} in the totally ramified case, and see also \cite[Proposition~1.5]{NickelConductor}.
As $\DFchi$ is cut out by $\ff$-idempotents (\cref{prop:ff-E-j-eta-i}), it is therefore opportune to work with $\ff$-idempotents defined over $F_\chi$ rather than $F$. This can be done by making an appropriate choice for the representative of the $\sim_F$-equivalence class of $\chi$:
\begin{corollary} \label{DFchichi}
 For every $\chi\in\Irr(\G)$, there is a $\chi^*\in\Irr(\G)$ such that $\chi^*\sim_ F\chi$ and $\DFchi = D_{F_{\chi^*},\chi^*}$.
\end{corollary}
\begin{proof}
 Let $1\le j\le n_\eta$ be arbitrary.
 The inclusion $\Q^ F(\G)\subseteq\Q^{ F_\chi}(\G)$ together with \cref{prop:ff-E-j-eta-i} induces an inclusion
 \[\DFchi = \ffFjeta \Q^ F(\G) \ffFjeta \hookrightarrow \ffFjeta \Q^{ F_\chi}(\G) \ffFjeta=\bigoplus_{\chi'\sim_ F \chi} D_{F_{\chi'},\chi'}.\]
 Here the sum is taken over $F_\chi$-equivalence classes of irreducible characters which are $ F$-equivalent to $\chi$. Projecting to the components on the right, we have maps $\DFchi\to D_{F_{\chi'},\chi'}$. A homomorphism of skew fields is either injective or zero, and since the displayed map above is injective, there is a character $\chi^*$ on the right hand side such that $\DFchi\hookrightarrow D_{F_{\chi^*},\chi^*}$. {We have $\sigma\circ\res^\G_H\chi=\res^\G_H\chi^*$ for some $\sigma\in\Gal(F_\chi/F)$, and therefore
 \begin{align*}
 F_{\chi^*}=F\big(\chi^*(h):h\in H\big)=F\big(\sigma(\chi(h)):h\in H\big)=F\big(\chi(h):h\in H\big)=F_\chi.
 \end{align*}
 Similarly, if $\eta^*\mid\res^G_H\chi^*$ is an irreducible constituent, then $\eta^*=\sigma\circ\eta$ for some irreducible constituent $\eta\mid\res^G_H\eta$, and have $F(\eta^*)=F(\eta)$. It follows that $s_\eta$ and $(F(\eta):F_\chi)=w_\chi/\vf$ are the same for $\chi$ and $\chi^*$, and \cref{invariants-of-DFchi} now shows that $\DFchi$ and $D_{F_{\chi^*},\chi^*}$ have the same Schur indices. This forces the injection to be an isomorphism.}
\end{proof}

Let $H$ be the cyclic group of order $2p+1$, and let $C_p=\langle g\rangle$ act on $H$ as the $m$th power map, that is, $ghg^{-1}=h^m$ for all $h\in H$. Let $\G\colonequals H\rtimes \Gamma$ where $\Gamma$ acts on $H$ via the natural projection $\Gamma\simeq\ZZ_p\twoheadrightarrow\ZZ_p/p\ZZ_p\simeq C_p$. Let $\chi\in\Irr(\G)$ be an irreducible character of degree $p$. Let $\eta\mid\res^G_H\chi$ be an irreducible constituent of its restriction to $H$. By definition of the group action, we have $w_\chi=p$.
By Clifford theory, see \cite[(3)]{NickelConductor}, we have the following for all $h\in H$:
\begin{equation} \label{eq:ex-res}
 \left(\res^\G_H\chi\right)(h)=\sum_{i=0}^{p-1} {}^{g^i}\eta(h)=\sum_{i=0}^{p-1} \eta\left(g^i h g^{-i}\right)=\sum_{i=0}^{p-1} \eta\left(h^{m^i}\right)=\sum_{i=0}^{p-1} \eta(h)^{m^i}.
\end{equation}
Since $\eta$ is a nontrivial character of the cyclic group of order $2p+1$, we have $\QQ_p(\eta)=\QQ_p(\zeta_{2p+1})$. Moreover, \eqref{eq:ex-res} combined with the discussion above shows that $\QQ_{p,\chi}$ is a quadratic extension of $\QQ_p$. The extension $\QQ_p(\zeta_{2p+1})/\QQ_p$ is unramified of degree $2p$, hence $\QQ_p(\eta)$ is an unramified extension of $\QQ_{p,\chi}$ of degree $p$. More generally, if $F/\QQ_p$ is a finite extension whose inertia degree is coprime to $p$, then $F(\eta)/F_\chi$ is also unramified of degree $p$.

\subsection{Trivial Schur index}
The author's previous work \cite{W} on the totally ramified case also assumed $p=2$. This assumption is actually used, namely in the construction of extensions of Galois automorphisms to skew fields as described in \cref{extending-tau}. 
As explained at the end of \S4.2 of \cite{
W}, this relies on Witt's result \cite[Satz~10]{Witt} that the Schur index $s_\eta$ divides $p-1$, which is false for $p=2$. In this case, it is known that $s_\eta\in\{1,2\}$, and we have $s_\eta=1$ if one of the following conditions holds:
\begin{enumerate}
 \item the base field $F$ contains a primitive 4th root of unity \cite[Satz~11]{Witt},
 \item all $2$-Sylow subgroups of $H$ are abelian \cite{Yamada78}.
\end{enumerate}
In fact, Yamada \cite{Yamada2,Yamada2B} gave an explicit description of the cases when $s_\eta=2$.
