ref_dict.prop:finite-kodaira-strat:
\begin{prop}\label{prop:finite-kodaira-strat}
    Fix $n\ge 1$. The discriminant degree constraint $\sum_v e(F_v)=12n$ implies that only finitely many
    geometric fiber configurations $\mathfrak f$ occur among surfaces parametrized by
    $\cW_n^{\min}$. Consequently,
    \[
    \cW_n^{\min}=\bigsqcup_{\mathfrak f}\cW_n^{\min,(\mathfrak f)}
    \]
    is a finite constructible stratification. Moreover, the trivial lattice rank $T(S)$
    is constant on each stratum $\cW_n^{\min,(\mathfrak f)}$.
    \end{prop}

pre_theorem_intro_text:
\label{sec:Intro}

    Let $k$ be a perfect field with $\mathrm{char}(k)\neq 2,3$, and set $K\coloneqq k(t)$. An elliptic curve $E/K$ determines a relatively minimal elliptic surface with section
    \[
    f \colon S \longrightarrow \mathbb{P}^1_k
    \]
    unique up to isomorphism (see \cite{Miranda2, SS} for background on elliptic surfaces).

    \medskip

    The arithmetic of $E/K$ is reflected in the geometry of $S$, and a basic organizing principle is the Shioda--Tate formula~\cite{Shioda}
    \begin{equation}\label{eq:ST}
    \rho(S)\;=\;T(S)\;+\;\rk(E/K),
    \end{equation}
    where $\rho(S)=\rk \NS(S_{\bar k})$ is the \emph{geometric Picard rank}, $T(S)$ is the \emph{rank of the geometric trivial lattice} generated by the zero section, a fiber class, and the components of reducible fibers not meeting the zero section, and $\rk(E/K)$ is the \emph{Mordell--Weil rank}. For the relatively minimal elliptic surfaces $f:S\to \mathbb{P}^1_k$ with section considered in this paper, we have $q(S)=0$ and $p_g(S)=n-1$, hence the standard bounds     \begin{align}\label{eq:bounds-intro}
    2 \le \rho(S) \le 10n,\qquad
    2 \le T(S) \le 10n,\qquad
    0 \le \rk(E/K) \le 10n-2,
    \end{align}
    where $\rho(S)\le 10n=h^{1,1}(S)$ is the Lefschetz bound over $k=\mathbb{C}$ (or in general the Igusa's inequality $\rho(S)\le b_2(S)=12n-2$).

    \medskip

    In~\cite{BPS}, Bejleri--Park--Satriano construct height-moduli stacks of rational points on proper polarized cyclotomic stacks.  In the fundamental modular curve example
    \[
    \Me \simeq \mathcal{P}(4,6),
    \qquad
    \lambda \simeq \Oc_{\mathcal{P}(4,6)}(1),
    \]
    a minimal elliptic curve over $K$ can be viewed as a rational point of $\lambda$--height $n$ on $\Me$ over $K$.  This yields a separated Deligne--Mumford stack of finite type
    \[
    \cW_n^{\min}
    \;\coloneqq\;
    \cW_{n,\mathbb{P}^1_k}^{\min}\bigl(\mathcal{P}(4,6),\mathcal{O}(1)\bigr)
    \]
    parametrizing minimal elliptic curves over $K$ of discriminant degree $12n$. Here a $K$-rational point of $\Me$ of $\lambda$-height $n$ means the stacky height $n$ with respect to the Hodge line bundle $\lambda$, in the sense of \cite{ESZB}. Under the identification $\overline{\mathcal{M}}_{1,1}\cong \mathcal{P}(4,6)$ one has $\lambda\simeq \Oc_{\mathcal{P}(4,6)}(1)$, and this height agrees with the Faltings height of the corresponding elliptic curve by \cite[Cor.~7.6]{BPS}.

    \medskip

    Guided by~\eqref{eq:ST}, we introduce the following motivic generating series (see~\cite{Ekedahl} for background on the Grothendieck ring of stacks) refining the height generating series in~\cite[\S 8]{BPS} by weighting each height stratum with the \emph{lattice ranks} of the associated relatively minimal elliptic surface.

    \begin{defn}\label{def:tri-motivic-HZF}
    Let $k$ be a perfect field of characteristic $\neq 2,3$, and consider the height--moduli stack
    \[
      \mathcal{W}^{\min}_{n} = \cW_{n,\mathbb{P}^1_k}^{\min}\bigl(\mathcal{P}(4,6),\mathcal{O}(1)\bigr)
    \]
    parametrizing minimal elliptic curves over $K = k(t)$ of discriminant height $12n$.  The \emph{trivariate height zeta function} is
    \[
      \mathcal{Z}(u,v;t)
      \;\coloneqq\;
      \sum_{n \ge 0}
        \left(
          \sum_{[E] \in \cW_n^{\min}}
            u^{\,T(S)} \, v^{\,\rk(E/K)}
        \right)
      t^n
      \;\in\;
      K_0(\Stck_k)[u,v]\llbracket t \rrbracket,
    \]
    where for each $[E]\in\cW_n^{\min}$ we write $S\to\mathbb{P}^1_k$ for the associated relatively minimal elliptic surfaces $f:S\to \mathbb{P}^1_k$ with section, and:
    \begin{itemize}
      \item $T(S)$ is the rank of the trivial lattice of $S$;
      \item $\rk(E/K)$ is the Mordell--Weil rank.
    \end{itemize}
    The following specializations are the associated \emph{bivariate
    height zeta functions}:
    \begin{align}
      Z_{\Triv}(u;t) &\coloneqq \mathcal{Z}(u,1;t),\\
      Z_{\MW}(v;t) &\coloneqq \mathcal{Z}(1,v;t),\\
      Z_{\NS}(w;t) &\coloneqq \mathcal{Z}(w,w;t).
    \end{align}
    \end{defn}

    \begin{rmk}
    Setting $u=v=1$ forgets the lattice rank grading and specializes to the \emph{univariate motivic height zeta function} $Z_{\lambdavec}(t)=\mathcal{Z}(1,1;t)\in K_0(\Stck_k)\llbracket t\rrbracket$ and likewise to its inertial refinement $\mathcal{I} Z_{\lambdavec}(t)$ which encodes the totality of rational points on $\Me$ over $K=k(t)$. \cite[Thm.~8.9]{BPS} shows that both series are in fact rational in $t$, i.e.\ lie in $K_0(\Stck_k)(t)$, and gives explicit formulas.
    \end{rmk}

    In this paper we focus on $Z_{\Triv}(u;t)$. The key point is that the trivial lattice is governed by
    \emph{local bad reduction}: its rank is determined by the geometric Kodaira fiber configuration of
    $\pi_{\bar k}\colon S_{\bar k}\to \mathbb{P}^1_{\bar k}$. Writing $\Triv(S)\subset \NS(S_{\bar k})$ for the geometric trivial lattice and $T(S)\coloneqq \rk(\Triv(S))$, we have the following explicit formula.

    \begin{lem}\label{lem:T-from-fibers}
    Let $\pi\colon S\to \mathbb{P}^1_k$ be a relatively minimal elliptic surface with section, and let
    $\mathfrak f$ be the multiset of singular fibers of $\pi_{\bar k}\colon S_{\bar k}\to \mathbb{P}^1_{\bar k}$.
    If $m_v$ denotes the number of irreducible components of the fiber at $v$, then
    \[
    T(S)\;=\;2+\sum_{v\in \mathfrak f}(m_v-1).
    \]
    \end{lem}

    \begin{defn}\label{def:kodaira-strata}
    Fix $n\ge 1$. For a geometric fiber configuration $\mathfrak f$, let $\cW_n^{\min,(\mathfrak f)}\subset \cW_n^{\min}$ denote the locus parametrizing those $[E]\in\cW_n^{\min}$ whose associated surface $S_{\bar k}\to \mathbb{P}^1_{\bar k}$ has singular fiber configuration $\mathfrak f$ (cf.\ \cite[Thm.~7.16]{BPS}).
    \end{defn}

    \begin{defn}\label{def:Ztriv}
    Fix $n\ge 0$. By Proposition~\ref{prop:finite-kodaira-strat}, $\cW_n^{\min}$ admits a \emph{finite}
    constructible stratification by Kodaira data, and $T(S)$ is constant on each stratum. For $n\ge 1$ and each $T$ with $2\le T\le 10n$, let
    \[
    \cW_n^{\min}(T)\subset \cW_n^{\min}
    \]
    be the finite union of those Kodaira strata on which $T(S)=T$ (hence a finite union of locally closed substacks).
    For $n=0$, set $\cW_0^{\min} \coloneqq \cW_0^{\min}(2)$.

    The trivial--lattice--rank--weighted motivic height zeta function is
    \[
    Z_{\Triv}(u;t)\coloneqq \sum_{n\ge 0}\ \sum_{T\ge 2} u^T\,\{\cW_n^{\min}(T)\}\,t^n
    \ \in\ K_0(\Stck_k)[u]\llbracket t\rrbracket.
    \]
    \end{defn}

    We prove that $Z_{\Triv}(u;t)$ is rational after inverting $\mathbb{L}$ (see Remark~\ref{rmk:localization}), and we give an explicit finite Euler product (Theorem~\ref{thm:rationality-Ztriv}).

