In this paper, we investigate the stability of quasi $K$-amenability for Hecke pairs. Our main theorem is stated as follows:

\begin{definition}\label{defheckepair}
  Let $\Lambda$ be a subgroup of a group $\Gamma$. We say that $\Lambda$ is almost normal in $\Gamma$ if one of the following equivalent conditions holds:
  \begin{itemize}
    \item For any $\gamma \in \Gamma$, the subgroups $\Lambda$ and $\Lambda^{\gamma}:=\gamma \Lambda \gamma^{-1}$ are commensurable. That is, the indices $\left[ \Lambda: \Lambda \cap \gamma\Lambda\gamma^{-1} \right] $ and $\left[ \gamma\Lambda\gamma^{-1}: \Lambda \cap \gamma\Lambda\gamma^{-1} \right] $ are finite.
    \item The left action of $\Lambda$ on the coset space $\Gamma /\Lambda$ has finite orbits, i.e., every double coset $\Lambda s \Lambda$ is a finite union of left cosets $\gamma\Lambda$.
  \end{itemize}
  In this case, the pair $(\Gamma,\Lambda)$ is called a Hecke pair.
\end{definition}

In this paper, we investigate the stability of quasi $K$-amenability for Hecke pairs. Our main theorem is stated as follows:

The class of a-T-menable groups is known to be closed under extensions by amenable \emph{quotients}. However, as noted in \cite[Corollary 1.4.13]{BHV-2008}, this stability does not hold for extensions by amenable \emph{kernels}. A standard counterexample is the group pair $(SL(2, \mathbb{Z}) \ltimes \mathbb{Z}^2, \mathbb{Z}^2)$, which has relative Property (T) and thus fails to be a-T-menable.
We observe that while Property (T) is an obstruction to quasi $K$-amenability due to the existence of the Kazhdan projection (as shown by Julg and Valette in \cite[Corollary 3.7]{Julg-Valette-1985}). In this context, Theorem \ref{A} implies that extensions of a-T-menable groups are quasi $K$-amenable, even in cases where the group fails to be a-T-menable due to relative Property (T).

\begin{corollary}\label{B}
Let $(\Gamma, \Lambda)$ be a Hecke pair of discrete groups and $X = \Gamma/\Lambda$ the quotient space.\begin{itemize}
\item (Theorem \ref{BCC}) If $\Lambda$ is a-T-menable and $X$ admits a $\Gamma$-equivariant coarse embedding into Hilbert space, then $\Gamma$ satisfies the Baum--Connes conjecture with coefficients.
\item (Theorem \ref{strongNovikov}) If $\Lambda$ admits a coarse embedding into Hilbert space and $X$ admits a $\Gamma$-equivariant coarse embedding into Hilbert space, then $\Gamma$ satisfies the strong Novikov conjecture with coefficients.
\item (Theorem \ref{coarseBCC}) If both $\Lambda$ and $\Gamma$ admit coarse embeddings into Hilbert space, then $\Gamma$ satisfies the coarse Baum--Connes conjecture and consequently the Novikov conjecture.
\end{itemize}\end{corollary}

\begin{theorem}
 \label{1st thm}
 Let $(\Gamma, \Lambda)$ be a Hecke pair and $X = \Gamma/\Lambda$. If $X$ admits a $\Gamma$-equivariant coarse embedding into a Hilbert space and $\Lambda$ is a-T-menable, then for any $\Gamma$-$C^*$-algebra $B$, the canonical quotient map induces an isomorphism in $K$-theory 
 $$
 \lambda_{*}:K_{*}(C_{\max}^{*}(\Gamma,\mathcal{A}(\mathcal{H})\hat{\otimes}B)^{\Gamma} ) \to K_{*}(C^{*}(\Gamma,\mathcal{A}(\mathcal{H})\hat{\otimes}B)^{\Gamma} ).
 $$
\end{theorem}

Now we are in a position to prove the Theorem \ref{A}. 
\begin{theorem}\label{main theorem}
 Let $(\Gamma,\Lambda)$ be a Hecke pair of discrete groups. Assume that $\Lambda$ is a-T-menable and that the quotient space $X = \Gamma/\Lambda$ admits a $\Gamma$-equivariant coarse embedding into Hilbert space. Then for every $\Gamma$-$C^{*}$-algebra $B$ the canonical map
 \begin{equation}\label{main-thm-iso}
 K_{*}(C^{*}_{\max}(\Gamma,B)^{\Gamma}) \longrightarrow K_{*}(C^{*}(\Gamma,B)^{\Gamma})
 \end{equation}
is an isomorphism.
\end{theorem}
\begin{proof}
 We have constructed the following commutative diagram:
 \begin{equation}\label{cmmu2}
 \begin{tikzcd}
 { K_{*}(C^{*}_{\max}(\Gamma, B)^{\Gamma} \hat{\otimes}\mathcal{S})} && { K_{*}(C^{*}(\Gamma, B)^{\Gamma} \hat{\otimes}\mathcal{S})} \\
 { K_{*}(C^{*}_{\max}(\Gamma,\mathcal{A}(\mathcal{H})\hat{\otimes}B)^{\Gamma} )} && { K_{*}(C^{*}(\Gamma,\mathcal{A}(\mathcal{H})\hat{\otimes}B)^{\Gamma} )} \\
 { K_{*}(C^{*}_{\max}(\Gamma, B)^{\Gamma} \hat{\otimes}\mathcal{S})} && { K_{*}(C^{*}(\Gamma, B)^{\Gamma} \hat{\otimes}\mathcal{S})}
 \arrow["{{\lambda_{*}}}", from=1-1, to=1-3]
 \arrow["{{\beta_{*}}}"', from=1-1, to=2-1]
 \arrow["{{\beta_{*}}}", from=1-3, to=2-3]
 \arrow["{{\lambda_{*}}}", from=2-1, to=2-3]
 \arrow["{\alpha_{*}}"', from=2-1, to=3-1]
 \arrow["{\alpha_{*}}", from=2-3, to=3-3]
 \arrow["{\lambda_{*}}", from=3-1, to=3-3]
\end{tikzcd}
 \end{equation}

\begin{corollary}
Let $1\to \Lambda\to \Gamma\to \Gamma/\Lambda\to 1$ be an extension of countable discrete groups. If both $\Lambda$ and $\Gamma/\Lambda$ are a-T-menable, then for any $\Gamma$-$C^*$-algebra $B$, the canonical quotient map induces an isomorphism in $K$-theory
 $$
 \lambda_*: K_*(B \rtimes \Gamma) \xrightarrow{\cong} K_*(B \rtimes_{r} \Gamma).
 $$
\end{corollary}

\begin{theorem}\label{BCC}
 Let $(\Gamma, \Lambda)$ be a Hecke pair of discrete groups. If $\Lambda$ is a-T-menable and the quotient space $X=\Gamma /\Lambda$ admits a $\Gamma$-equivariant coarse embedding into Hilbert space, then $\Gamma$ satisfies the Baum--Connes conjecture with coefficients in any $\Gamma$-$C^{*}$-algebra $B$.
\end{theorem}

In addition to the Dirac-dual-Dirac method, one can also employ the results of \cite{MR4422220} to establish the strong Novikov conjecture for $\Gamma$ with coefficients in any $\Gamma$-$C^{*}$-algebra $B$. The precise statement is as follows.
\begin{theorem}\label{strongNovikov}
 Let $(\Gamma, \Lambda)$ be a Hecke pair of discrete groups. If $\Lambda$ admits a coarse embedding into Hilbert space, and the quotient space $X=\Gamma /\Lambda$ admits a $\Gamma$-equivariant coarse embedding into Hilbert space, then $\Gamma$ satisfies the strong Novikov conjecture with coefficients in any $\Gamma$-$C^{*}$-algebra $B$.
\end{theorem}

\begin{theorem}\label{A}
Let $(\Gamma, \Lambda)$ be a Hecke pair of discrete groups and let $X = \Gamma/\Lambda$. If $X$ admits a $\Gamma$-equivariant coarse embedding into a Hilbert space and $\Lambda$ is a-T-menable, then $\Gamma$ is quasi $K$-amenable, i.e., for any $\Gamma$-$C^*$-algebra $B$, the canonical quotient map induces an isomorphism in $K$-theory:
\[
K_*(B \rtimes \Gamma) \cong K_*(B \rtimes_r \Gamma).
\]

In particular, assume that $\Lambda\trianglelefteq\Gamma$ is a normal subgroup. If $\Lambda$ and $\Gamma/\Lambda$ are both a-T-menable, then $\Gamma$ is quasi $K$-amenable.
\end{theorem}

\begin{theorem}\label{BCC}
   Let $(\Gamma, \Lambda)$ be a Hecke pair of discrete groups. If $\Lambda$ is a-T-menable and the quotient space $X=\Gamma /\Lambda$ admits a $\Gamma$-equivariant coarse embedding into Hilbert space, then $\Gamma$ satisfies the Baum--Connes conjecture with coefficients in any $\Gamma$-$C^{*}$-algebra $B$.
\end{theorem}

\begin{theorem}\label{coarseBCC}
    Let $(\Gamma, \Lambda)$ be a Hecke pair of discrete groups. If both $\Lambda$ and $X$ admit coarse embeddings into Hilbert space, then $\Gamma$ satisfies the coarse Baum--Connes conjecture and consequently the Novikov conjecture. \qed
\end{theorem}

\begin{theorem}\label{strongNovikov}
  Let $(\Gamma, \Lambda)$ be a Hecke pair of discrete groups. If $\Lambda$ admits a coarse embedding into Hilbert space, and the quotient space $X=\Gamma /\Lambda$ admits a $\Gamma$-equivariant coarse embedding into Hilbert space, then $\Gamma$ satisfies the strong Novikov conjecture with coefficients in any $\Gamma$-$C^{*}$-algebra $B$.
\end{theorem}

