\end{conjecture}

\begin{thm}[Main Theorem]\label{main 1}
	For every integer $k\ge 6$, let $G$ be a graph with minimum degree at least $k$.
    Then exactly one of the following holds:
    \begin{itemize}
        \item[(1)] $G$ contains a cycle of length $r \pmod k$ for every even integer $r$;
        \item[(2)] $k$ is odd, every end-block of $G$ is isomorphic to a graph in $\{K_{k+1}, K_{k,k}\}\cup \mathcal{H}_{k}$, and every non-end-block contains no cycle of length $2 \pmod k$;
        \item[(3)] $k$ is even, every end-block of $G$ is isomorphic to $K_{k+1}$, and every non-end-block contains no cycle of length $2 \pmod k$.
    \end{itemize}
\end{thm}

