\label{four}
$\cup_{t\in I}(W\cap M(t))$
is contained in 
a compact subset of~$N$.
\item
\label{five}
Each tangent flow
to~$M(\cdot)$
at each spacetime point in $W\times I$
has multiplicity~one, and
 the corresponding
shrinker is a plane, a sphere,
or a cylinder.
\end{enumerate}
Then 
\begin{equation}
\label{W-conclusion}
 g(t):= \genus(W\cap \Reg M(t))
 \tag{*}
\end{equation}
is a decreasing function
 of $t\in I$.
\end{theorem}

