Given an abelian group ${\mathbf G}$ and two sets $A, B\subseteq {\mathbf G}$, define 
the {\it sumset} of $A$ and $B$ as 
\begin{equation}\label{def:A+B_intr}
 A+B:=\{a+b ~:~ a\in{A}, b\in{B}\}.
\end{equation}
In a similar way we define the \emph{difference sets} and \emph{higher sumsets}, e.g., $A-A$, $A+A-A$, and so on.
The \emph{doubling constant} of a finite set $A$ is 
\begin{equation}\label{def:doubling}
 \mathcal{D} [A] := \frac{|A+A|}{|A|}, 
\end{equation}
an important additive--combinatorial characteristic of $A$.

\subsection{Main conjecture}
In this paper we limit ourselves to considering the field $\F_p$.
Let $p$ be a prime number and let $A \subseteq \F_p$. 
Denote by
\[
 A^* := A^{-1} = \{1/a \bmod p : a \in A, a \neq 0\}
\]
its inverse set. In~\cite{Semchankau_wrappers}, we proved the lower bound
\begin{equation}\label{eq:lower-bound-a-a*}
 |A + A^*| \geqslant (1 - o(1)) \min\{ 2\sqrt{p|A|}, p \},
\end{equation}
valid whenever $|A| \gg p(\log p)^{-1/2 + o(1)}$. 
The archetypal 
question of the present work is the corresponding \emph{inverse problem} for a simple rational function \eqref{def:rational_sp}:
given that
\begin{equation}\label{as:A+A*_intr}
 |A + A^*| \leqslant K\sqrt{p|A|},
\end{equation}
for a fixed parameter $K\geqslant 2$, what structural information can we deduce about $A$?

This heuristic suggests the following: 
\begin{conjecture}
Let $A \subseteq \F_p$ be a set of size at least $p^{1 - c}$ for some absolute constant $c > 0$, and suppose that
\[
 |A + A^*| \leqslant K\sqrt{p|A|}.
\]
Then there exist sets $P, Q \subseteq \F_p$ such that, after removing $O_{K,\alpha}(1)$ elements from $A$, the following holds:
\begin{itemize}[itemsep=0.5em]
 \item $A \subseteq P \cap Q^*$;
 \item $|P \cap Q^*| = \tfrac{1 + o(1)}{p}|P||Q|$;
 \item $|P + Q| \leqslant (1 + o(1)) K\sqrt{p|A|}$.
\end{itemize}
\end{conjecture}

Let $r$ be an exponent (non--zero integer), and $A \subseteq \F_p$. 
Define $A^r := \{a^r : a \in A\}$ (note that this notation is not standard, and should not be confused with the $r$-fold product set or the set of $r$-tuples). Since we work in $\F_p$, an exponent $r$ might be treated as an element of $\Z_{p - 1}$. 
\begin{definition}
Exponent $r$ is called \emph{generic} if $(r, p - 1) = O(1)$, and \emph{coprime} if $(r, p - 1) = 1$. More generally, a tuple $(r_1, \ldots, r_k)$ of distinct exponents satisfying $(r_i - r_j, p - 1) < p^{1 - \delta}$ for some $\delta > 0$ is \emph{generic} or \emph{coprime} if all individual $r_i$'s are generic or coprime, respectively.
\end{definition}

Define $\sqrt[r]{A} := \{x: x^r \in A\}$. We will work only with generic $r$, implying that always $|\sqrt[r]{A}| \leqslant (r, p - 1)|A| \ll |A|$.

The following result generalizes the lower bound~\eqref{eq:lower-bound-a-a*}.

\begin{equation}\label{def:rational_sp}
    \left\{ \frac{f(a_1,\dots,a_n)}{g(a_1,\dots,a_n)} ~:~ a_1,\dots, a_n \in A \right\}.
\end{equation}

\begin{equation}\label{eq:lower-bound-a-a*}
 |A + A^*| \ge (1 - o(1)) \min\{ 2\sqrt{p|A|}, p \},
\end{equation}

