\begin{lemma}\label{lemma:aip}
Let $W_1, \ldots, W_k$ be sets with Wiener norms bounded by $M$. Let tuple $(r_1, \ldots, r_k)$ be generic. Then
\[
\bigl|\sqrt[r_1]{W_1} \cap \cdots \cap \sqrt[r_k]{W_k}\bigr|
= \frac{1}{p^{\,k-1}}\,|W_1|\cdots|W_k|
 + O\left(M^{k} p^{1 - \eps}\right),
\]
where $\eps = \eps(k) > 0$.
\end{lemma}
\begin{proof}
Identifying sets $W_i$'s with their indicator functions, we write
\begin{equation}\label{eq:aip}
\bigl|\sqrt[r_1]{W_1} \cap \cdots \cap \sqrt[r_k]{W_k}\bigr|
= \sum_{x \in \F_p} W_1(x^{r_1}) \cdots W_k(x^{r_k}).
\end{equation}

The family $\mathcal{F}$ provides a much broader source of sets with AIP:
\begin{proposition}
\label{proposition:aip}
 Any collection of sets $P_1, \ldots, P_k$ from the family $\mathcal{F}$ has AIP.
\end{proposition}
\begin{proof}
Let $(r_1, \ldots, r_k)$ be an arbitrary generic tuple, and let $W_1, \ldots, W_k$ be sets approximating $P_1, \ldots, P_k$. Then, for all $i$, the symmetric difference $\sqrt[r]{P_i} \triangle \sqrt[r]{W_i}$ is a subset of $\sqrt[r]{P_i \triangle W_i}$, and therefore its size does not execeed $(r, p - 1)|P_i \triangle W_i| = o(p)$. Thus,
\begin{multline*}
\bigl|\sqrt[r_1]{P_1} \cap \cdots \cap \sqrt[r_k]{P_k}\bigr| 
\oversetgap{\text{Proposition~\ref{proposition:set-triangles}}}{=}
\bigl|\sqrt[r_1]{W_1} \cap \cdots \cap \sqrt[r_k]{W_k}\bigr| + o(p) = \\
\oversetgap{\text{Lemma~\ref{lemma:aip}}}{=} 
\frac{1}{p^{k-1}}|W_1|\ldots|W_k| + o(p) 
\oversetgap{\text{Proposition~\ref{proposition:prods-and-diffs}}}{=} 
\frac{1}{p^{k - 1}}|P_1|\ldots|P_k| + o(p) = \\
\oversetgap{|P_i| \gg p}{=}
\frac{1 + o(1)}{p^{k - 1}}|P_1|\ldots|P_k|.
\end{multline*}
\end{proof}

