ref_dict.main2:
\begin{theorem}\label{main2}
Let $\Gamma$ be a geometric distance-regular graph with valency $k$, diameter $D \geq 3$, distinct eigenvalues
$k = \theta_0 > \theta_1 > \cdots > \theta_D$, and $c_2 \geq 2$.
Let $r = -\theta_D$, $\beta = \frac{k}{-\theta_D}$, and $b = \frac{b_1}{\theta_1 + 1}$.
Then one of the following holds: 
\begin{enumerate}
    \item $\phi_1 = 1$, and $\Gamma$ is locally the disjoint union of cliques of order $\beta$.
    \item $\phi_1 = \tau_2 = 2$, and $\Gamma$ is a Johnson graph. In particular, $b = 1$.
    \item $\phi_1 = \tau_2 \geq 3$, and $\Gamma$ is a Grassmann graph defined over the field $\mathbb{F}_{\phi_1-1}$. In particular, $b = \phi_1 - 1$.
    \item $\phi_1 = \tau_2 - 1 \geq 2$, and for each vertex $x$ of $\Gamma$, the local graph $\Delta_x$ at vertex $x$ is the $(\phi_1 - 1)$-clique extension of a $\frac{\beta}{\phi_1 - 1} \times r$-grid. In particular, if $r(\phi_1 - 1) > 2b^2 + 2b + 1$, then $\phi_1 \leq b + 1$.

    \item $ 2 \leq \phi_1 \leq \tau_2-1$, and $\beta < (r - \tau_2 + 1)(\phi_2 - \phi_1) + \phi_1$.
\end{enumerate}
\end{theorem}

