\]
Let us compute the polarization of $\mathcal{L}\mathcal{S}$ following \cite{MarklRemm}; this construction will be used throughout the paper.

Since there is a one-to-one correspondence between a variety of algebras
defined by identities of degrees two and three $\Var$ and the associated quadratic operad,
we will use the same terminology for both objects throughout the paper. We consider all algebras over a field $K$ of characteristic $0$.

\begin{proposition}
The polarization of $\mathcal{L}\mathcal{S}_{\mathfrak{A}_1}\<X\>$ is defined by (\ref{pol1}), (\ref{pol2}) and
\begin{multline*}
\{a,\{b,c\}\}=\{[a,b],c\}+\{[a,c],b\}-3/2[\{a,b\},c]-3/2[\{a,c\},b]\\
+3/2[[a,c],b]-1/3[a,\{b,c\}]+1/3[a,[b,c]].
\end{multline*}
\end{proposition}
\begin{proof}
The proof is analogous to Proposition \ref{polarization}.
\end{proof}

Let $\mathcal{L}\mathcal{S}_{\mathfrak{A}_1}^{\;\;(!)}\<X\>$ be a free algebra of the variety $\mathcal{L}\mathcal{S}_{\mathfrak{A}_1}^{\;\;(!)}$.
\begin{lemma}\label{lemmaA1}
In algebra $\mathcal{L}\mathcal{S}_{\mathfrak{A}_1}^{\;\;(!)}\<X\>$ the following identities hold:
\[
((ba)c)d=((ac)b)d,
\]
\[
(((ab)c)d)e=(((ac)b)d)e
\]
and
\[
(((ab)c)d)e=(((ab)d)c)e.
\]
\end{lemma}
\begin{proof}
It can be proved using computer algebra as software programs Albert \cite{Albert}. \end{proof}

To prove the linear independence of the set $\overline{\mathfrak{A}^{((!))}}_1$, we construct the multiplication table for the algebra $A_1\<X\>$ with the basis $\overline{\mathfrak{A}^{((!))}}_1$ and show that such an algebra $A_1\<X\>$ belongs to the variety $\mathcal{L}\mathcal{S}_{\mathfrak{A}_1}^{\;\;(!)}\<X\>$. Up to degree 4, we define multiplication in $A_1\<X\>$ that is consistent with the defining identities of $\mathcal{L}\mathcal{S}_{\mathfrak{A}_1}^{\;\;(!)}\<X\>$. Starting from degree $5$, the multiplication is defined as follows:
\begin{multline}\label{mult1}
(((\cdots((x_{i_1}x_{i_2})x_{i_3})\cdots )x_{i_{n-1}})x_{i_n})(((\cdots((x_{j_1}x_{j_2})x_{j_3})\cdots )x_{j_{m-1}})x_{j_m})=\\
((\cdots((x_{k_1}x_{k_2})x_{k_3})\cdots )x_{k_{n+m-1}})x_{j_{m}},
\end{multline}
where $\{k_1,k_2,\ldots,k_{n+m-1}\}=\{i_1,i_2,\ldots,i_{n},j_1,j_2,\ldots,j_{m-1}\}$ and $k_1\leq k_2\leq\ldots\leq k_{n+m-1}$. It remains to check that the algebra $A_1\<X\>$ satisfies the left-alternative, right-alternative, and left-commutative identities.

\begin{proposition}
The polarization of $\mathcal{L}\mathcal{S}_{\mathfrak{B}_1}\<X\>$ is defined by (\ref{pol1}), (\ref{pol2}) and
\[
\{[a,b],c\}+\{[b,c],a\}+\{[c,a],b\}=0.
\]
\end{proposition}
\begin{proof}
The proof is analogous to Proposition \ref{polarization}.
\end{proof}

\section{$\mathfrak{A}_2$-left-symmetric algebras}
In this section, we consider algebras from the variety $\mathcal{L}\mathcal{S}_{\mathfrak{A}_2}$. Let us compute the dual operad for $\mathcal{L}\mathcal{S}_{\mathfrak{A}_2}$. The Lie-admissibility condition for $S\otimes U$ gives the defining identities of the operad $\mathcal{L}\mathcal{S}_{\mathfrak{A}_2}^{\;\;(!)}$, where $S$ is an algebra from $\mathcal{L}\mathcal{S}_{\mathfrak{A}_2}$. So, we have
\begin{multline*}
[[a\otimes u,b\otimes v],c\otimes w]=(ab)c\otimes (uv)w-(ba)c\otimes (vu)w-
c(ab)\otimes w(uv)+c(ba)\otimes w(vu)=\\
((ba)c-(ac)b+(ca)b-(bc)a+(cb)a-2b(ac)-2c(ab)-2c(ba))\otimes (uv)w\\
-(ba)c\otimes (vu)w-c(ab)\otimes w(uv)+c(ba)\otimes w(vu),
\end{multline*}
\begin{multline*}
[[b\otimes v,c\otimes w],a\otimes u]=(bc)a\otimes (vw)u-(cb)a\otimes (wv)u-
a(bc)\otimes u(vw)+a(cb)\otimes u(wv)=\\
(bc)a\otimes (vw)u-(cb)a\otimes (wv)u
-(-(ac)b+(ca)b-(bc)a+(cb)a-b(ac)-2c(ab)-2c(ba))\otimes u(vw)\\
+((ac)b-(ca)b+c(ab))\otimes u(wv)
\end{multline*}
and
\begin{multline*}
[[c\otimes w,a\otimes u],b\otimes v]=(ca)b\otimes (wu)v-(ac)b\otimes (uw)v-
b(ca)\otimes v(wu)+b(ac)\otimes v(uw)=\\
 (ca)b\otimes (wu)v-(ac)b\otimes (uw)v-
((bc)a-(cb)a+c(ba))\otimes v(wu)+b(ac)\otimes v(uw).
\end{multline*}
The sum of the same elements on the left side of the tensors, we obtain the following result: 
\begin{proposition}
The operad $\mathcal{L}\mathcal{S}_{\mathfrak{A}_2}^{\;\;(!)}$ is the alternative operad with an identity
\[
(ab)c=(ba)c
\]
\end{proposition}
\begin{proposition}
The polarization of $\mathcal{L}\mathcal{S}_{\mathfrak{A}_2}\<X\>$ is defined by (\ref{pol1}), (\ref{pol2}) and
\[
\{a,\{b,c\}\}=\{[a,b],c\}+\{[a,c],b\}+[\{b,c\},a]+2/3[[a,c],b]+1/3[a,[b,c]].
\]
\end{proposition}
\begin{proof}
The proof is analogous to Proposition \ref{polarization}.
\end{proof}

