\begin{theorem}[Theorem 1 in \cite{courtade2014boolean}]\label{thm:CK_Thm1}
If $b$ is a balanced Boolean function ($\E[b]=0$), 
$$ \sum_{i=1}^n I(b(X); Y_i) \leq 1 - H(\alpha). $$
\end{theorem}

