\begin{conjecture}[Courtade-Kumar Conjecture \cite{courtade2014boolean}]\label{conj:CK}
For any Boolean function $b : \{-1, 1\}^n \to \{-1, 1\}$,
$$ I(b(X); Y) \leq 1 - H(\alpha). $$
\end{conjecture}

