\section{Preliminary Results}\label{ScattCond}
In this section we will collect some preliminary results that will be used to prove Theorem \ref{main}.
From now on, let $q$ be  an odd prime power, $t \geq 3$ and $1 \leq s \leq  2t-1$ with $\gcd(s,2t)=1$. We will consider the $q^s$-linearized polynomial of $\mathcal{\tilde{L}}_{2t,q,s}$
 \begin{equation}\label{quadrinomial}
 \psi_{m,h,s}=m(X^{q^s}-h^{1-q^{s(t+1)}}X^{q^{s(t+1)}})+X^{q^{s(t-1)}}+h^{1-q^{s(2t-1)}}X^{q^{s(2t-1)}}
 \end{equation}
where $(m,h) \in \F^*_{q^t} \times \F^*_{q^{2t}}$. The following result can be found in \cite[Lemma 2.1]{SmaZaZu}.

\begin{lemma}\label{power}
Let $\F_{q^{2t}}$ be the finite field of $q^{2t}$ elements, $t \geq 3$ and $q$ an odd prime power. Then,
\begin{itemize}
\item [$(i)$] the additive group of $\F_{q^{2t}}$ is the the direct sum of $\F_{q^t}$ and $\ker \mathrm{Tr}_{q^{2t}/q^t}$;
\item [$(ii)$] the product of two elements in $\ker \mathrm{Tr}_{q^{2t}/q^t}$ belongs to $\F_{q^t}$;
\item [$(iii)$] if $w\in \ker \mathrm{Tr}_{q^{2t}/q^t}$  and $\ell$ is a non-negative integer 
    \begin{equation*}
        w^\ell\in\begin{cases}
            \ker \mathrm{Tr}_{q^{2t}/q^t}  & \text{if}\,\,\ell\,\,\text{is}\,\,\text{odd},\\
            \mathbb{F}_{q^t} & otherwise.
        \end{cases}
    \end{equation*}
\end{itemize}

