\end{theorem}

\begin{theorem}\label{norma=1}
 Let $t\geq 3$ and $q \equiv 3 \pmod{4}$ and $s$ be an integer such that $\gcd(s,2t)=1$. For each $h \in \F_{q^{2t}} \setminus \F_{q^t}$ such that $\mathrm{N}_{q^{2t}/q^t}(h)=1$ with $h^2 \neq -1$ and $m \in \mathbb{F}_{q^t} \setminus (\mathscr{P}_s^+ \cup \mathscr{P}_s^{-})$, the $q^s$-linearized polynomial
 \begin{equation*}
 \psi_{m,h,s}=m(X^{q^s}-h^{1-q^{s(t+1)}}X^{q^{s(t+1)}})+X^{q^{s(t-1)}}+h^{1-q^{s(2t-1)}}X^{q^{s(2t-1)}}
 \end{equation*}
 is scattered.
