When $\alpha=2$, by a recent work of Rizzi and Rossi \cite{RizziRossi2021}, the asymptotic expansion of $Q^{(2)}_\Omega(t)$ holds on any sub-Riemannian manifold, and $\Omega$ is required to have $C^\infty$ boundary with no characteristic points. In the aforementioned paper, the authors used Savo's technique, see \cite{Savo1999}, adapted to the sub-Riemannian setting, and they obtained asymptotic expansion up to order $5$. Moreover, the first two coefficients in the asymptotic expansion are given in terms of the perimeter and horizontal mean curvature of the domain at boundary points. We also refer to \cite{CaputoRossi2024}, where the results in \cite{RizziRossi2021} have been generalized to RCD spaces with a local Dirichlet form. However, our framework is different from the aforementioned work as fractional sub-Laplacians are non-local operators.

\subsection{Homogeneous norms and distances}We call a norm $\|\cdot\|: \mathbb{G}\to [0,\infty)$ homogeneous if
 \begin{enumerate}
 \item $\|\delta_\lambda x\|=\lambda \|x\|$ for any $\lambda>0$ and $x\in\mathbb{G}$.
 \item $\|x\|=0$ if and only if $x=0$.
 \end{enumerate}
 Any homogeneous norm induces a pseudo-metric on $\mathbb{G}$ defined by
 \begin{align*}
 d(x,y)=\|y^{-1}\star x\|, \quad \mbox{$x,y\in\mathbb{G}$}.
 \end{align*}
 A metric $d$ defined above is also homogeneous, that is, $d(\delta_\lambda x,\delta_\lambda y)=\lambda d(x,y)$ for all $x,y\in\mathbb{G}$ and $\lambda>0$. Any Carnot group $\mathbb G$ with a sub-Riemannian structure described in the introduction above can be equipped with a Carnot-Carath\'eodory metric defined by
 \begin{align}
 d_c(x,y)=\inf\left\{\int_0^1 |\dot{\gamma}(t)|_{H} dt: \gamma(0)=x, \gamma(1)=y, \ \dot{\gamma}(t)\in H_{\gamma(t)}(\mathbb G)\right\}.
 \end{align}
 It is known that $(\mathbb{G}, d_c)$ is a path connected metric space, see \cite[Chapter~19]{BonfiglioliLanconelliUguzzoniBook}, and $d_c$ is a homogeneous distance.
 By \cite[Proposition~5.1.4]{BonfiglioliLanconelliUguzzoniBook}, any two homogeneous norms on $\mathbb{G}$ are equivalent. If $d_\infty$ denotes the homogeneous pseudo-metric on $\mathbb{G}$ induced by the homogeneous norm
 \begin{align}\label{eq:d_infinity}
 \|x\|_\infty=\sup_{1\le j\le k}\{\epsilon_j|(x_{n_{j-1}+1},\ldots, x_{n_{j}})|^{\frac{1}{j}}\}, \quad \epsilon_j>0,
 \end{align}
 it was proved in \cite[Theorem~5.1]{FranchiSerapioniCassano2003} that one can choose $\epsilon_1=1$ and $\epsilon_j\in (0,1), j\ge 2$, depending on the group $\mathbb{G}$ so that $d_\infty$ becomes a metric. Therefore, any homogeneous metric $d$ satisfies
 \begin{align*}
 c^{-1} d_\infty(x,y)\le d(x,y)\le c d_\infty(x,y) \quad \mbox{for all $x,y\in\mathbb{G}$}
 \end{align*}
 for some positive constant $c$ independent of $x,y$.
 Throughout the paper, we work with an arbitrary homogeneous metric $d$ unless stated otherwise.
 \subsection{Horizontal perimeter} We start by recalling the definition of functions with bounded variation. For $f\in L^1(\mathbb G)$, the \emph{horizontal variation} of $f$ is defined as
 \begin{align*}
 \mathrm{Var}_H(f)=\sup\left\{\sum_{i=1}^m\int_{\mathbb G} fX_i\phi_i dx: \phi_i\in C^\infty_c(\mathbb G), \sum_{i=1}^m |\phi_i|^2\le 1\right\}.
 \end{align*}
 $f$ is said to have bounded variation if $\mathrm{Var}_H(f)<\infty$. The space of all functions with bounded variation, denoted by $\BV(\mathbb{G})$, is a Banach space with the norm
 \begin{align*}
 \|f\|_{\BV(\mathbb G)}=\|f\|_{L^1(\mathbb G)}+\mathrm{Var}_H(f).
 \end{align*}
 Variation is lower semicontinuous, that is, for any $(f_n),f\in L^1(\mathbb G)$ with $\|f_n-f\|_{L^1(\mathbb G)}\to 0$ implies $\liminf_{n\to\infty }\mathrm{Var}_H(f_n)\ge \mathrm{Var}_H(f)$.
 A measurable set $\Omega\subset \mathbb{G}$ is called \emph{Caccioppoli set} if $\mathbbm{1}_\Omega\in\BV(\mathbb G)$. In this case, the \emph{horizontal perimeter} of $\Omega$ is defined as 
 \begin{align*}
 |\partial\Omega|_H:=\mathrm{Var}_H(\mathbbm{1}_\Omega).
 \end{align*}
 When $\Omega$ is bounded with $C^1$ boundary, $|\partial\Omega|_H<\infty$, and by \cite[Equation~(3.2)]{CapognaDanielliGarofalo1994}
 \begin{align}\label{eq:per_hausdorff_1}
 |\partial\Omega|_H=\int_{\partial\Omega}\left[\sum_{i=1}^m \langle X_i,\nu\rangle^2\right]^{\frac12}d\mathcal{H}^{N-1},
 \end{align}
 where $\nu$ is the Euclidean unit outward normal to the boundary, and $\mathcal{H}^{N-1}$ is the $(N-1)$-dimensional Euclidean Hausdorff measure. While \eqref{eq:per_hausdorff_1} provides an explicit relationship between the perimeter and Euclidean Hausdorff measure, it is also possible to represent the horizontal perimeter in terms of the Hausdorff measure with respect to a homogeneous distance on $\mathbb{G}$.
 Let $d_\infty$ be the homogeneous metric defined in \eqref{eq:d_infinity}, and let $\mathcal{S}^{Q-1}_\infty$ denote the $(Q-1)$-dimensional spherical Hausdorff measure on $\mathbb G$ with respect to that metric, that is,
 \begin{align}
 S^{Q-1}_\infty(E)=\lim_{\epsilon\to 0+}\inf\left\{\sum_{i=1}^\infty\frac{\mathrm{diam}(D_{x_i}(t_i))^{Q-1}}{2^{Q-1}}: E\subset \bigcup_{i=1}^\infty D_{x_i}(t_i), \quad t_i\le \epsilon\right\},
 \end{align}
 where $D_{x_i}(t_i)=\{x\in\mathbb G: d_\infty(x,x_i)\le t_i\}$ and the diameter is with respect to $d_\infty$.
 Then by \cite[Proposition~1.9]{Magnani2005} and \cite[Theorem~2.5]{Magnani2005}, we have the following relationship between the horizontal perimeter and $\mathcal{S}^{Q-1}_\infty$.
 \begin{lemma}\label{lem:per_hausdorff}
 Let $\phi\in C^1(\mathbb G)$, $s\in\R$, and $E=\{x\in\Omega: \phi(x)>s\}$. Assume that $\nabla_H \phi(x)\neq 0$ for all $x\in \partial E$, and $|\partial E|_{H}<\infty$. Then there exists a positive constant $c(\mathbb G)$ depending on $\mathbb G$ such that 
 \begin{align*}
 |\partial E|_{H}=c(\mathbb G) S^{Q-1}_\infty(\partial E).
 \end{align*}
 \end{lemma}
 \begin{remark}
 \cite[Theorem~2.5]{Magnani2005} is stated for $H$-differentiable functions and from the discussion after \cite[Defintion~1.12]{Magnani2005} it follows that any $C^1$ function is $H$-differentiable.
 \end{remark}
 Another important fact we need in the proof of Theorem~\ref{thm:main} is the continuity of perimeter of hypersurfaces in $\mathbb{G}$. The following result follows directly from \cite[Theorem~9.1]{DanielliGarofaloNhieu2007}.
 \begin{lemma}\label{lem:per_cont}
 Let $\phi\in C^2(\mathbb G)$ be such that $E=\{x: \phi(x)>0\}$ is pre-compact in $\mathbb{G}$ and $|\nabla_{H} \phi|$ is bounded away from $0$ in a neighborhood of $\partial E$. Assume that there exists $r_0>0$ such that for all $r\in [-r_0,r_0]$, the family of domains $E_r=\{x\in\mathbb{G}: \phi(x)>r\}$ have $C^2$ boundary. Then, $\lim_{r\to 0} |\partial E_r|_{H} = |\partial E|_{H}$.

\begin{theorem}\label{thm:smooth_function}
 Let $f\in C^\infty_c(\mathbb G)$ be nonnegative. Then for any $1\le \alpha\le 2$, 
 \begin{align*}
 \lim_{t\to 0} \frac{|\Omega|-Q^{(\alpha)}_f(t)}{\mu_\alpha(t)}=\mathrm{Var}_H(f).
 \end{align*}
 where $\mu_\alpha$ is defined in \eqref{eq:mu_alpha}.
 \end{theorem}
 The proof of this theorem will use Taylor formula on Carnot groups and several small time estimates of the supremum process $\sup_{0\le s\le t} d(B^\alpha(s),0)$, which are proved in subsequent lemmas. We start with a straightforward consequence of Theorem~\ref{thm:taylor} applied to functions of left translation invariant processes on $\mathbb{G}$.
 \begin{lemma}\label{lem:taylor_bound}
 Fix a homogeneous metric $d$ on $\mathbb{G}$. Let $Z=(Z(t))_{t\ge 0}$ be any left translation invariant process on $\mathbb{G}$ with $Z(0)=0$. For any $x\in\mathbb{G}$ and $f\in C^{1,1}(\mathbb G)$,
 \begin{align*}
 & \left|\inf_{0\le s\le t}f(x\star Z(s))-f(x)-\inf_{0\le s\le t}\sum_{i=1}^m Z_i(s) X_i f(x)\right| \\
 &\le \sum_{i>m}\sup_{0\le s\le t}|Z_i(s)||X_i f(x)|+c\sum_{j=1}^{k-1}\sup_{0\le s\le t} d(Z(s),0)^{1+j} \\
 &\le c\sum_{j=1}^{k-1} \sup_{0\le s\le t}d(Z(s),0)^{1+j}\sum_{i>m} |X_i f(x)|.
 \end{align*}
 \end{lemma}

expanded_sketch:
Using a standard subordination argument for fractional powers of generators of Markov processes, the fractional heat content is represented probabilistically as
\[
Q^{(\alpha)}_\Omega(t)=\int_{\Omega}\mathbb P_x\big( B^\alpha(s)\in\Omega\ \text{for all }0\le s\le t\big)\,dx,
\]
where $B^\alpha$ is the subordinated horizontal Brownian motion on $\mathbb G$.

The method proceeds via a “functional version” of heat content: for any nonnegative measurable $f$,
\begin{align}\label{eq:Q_f}
 		Q^{(\alpha)}_f(t)=\int_{\mathbb G}\E_x\left[\inf_{0\le s\le t} f(B^\alpha(s))\right]dx.
 	\end{align}
noting that when $f=\mathbbm 1_\Omega$, this equals $Q^{(\alpha)}_\Omega(t)$. Then, “using the Taylor formula on Carnot groups,” the authors “prove the asymptotics of the displayed identity \eqref{eq:Q_f} for compactly supported smooth functions $f$,” and obtain the desired lower bound for the heat content “by an approximation argument.” They further state that the lower bound holds “for any bounded open set with finite horizontal perimeter.”

For the matching upper bound (and hence the full limit in establishing the main theorem), “the regularity conditions on the boundary are needed,” and the approach “mainly requires some estimates of the probabilities of small exit times.” We first recall the following theorem.
\begin{theorem}\label{lem:estimate1}
 	There exist constants $c,\beta>0$ such that for all $R>0$,
 	\begin{equation}\label{eq:exit_probability}
 		\begin{aligned}
 			\P_0\left(\sup_{0\le s\le t}d(B(s),0)> R\right)&\le e^{-\frac{R^2}{ct}}+\sum_{p=1}^k\mathcal{G}_p(R,t)+\sum_{p=1}^k\widetilde{\mathcal{G}}_p\left(R,t\right),
 		\end{aligned}
 	\end{equation}
 		where 
 		\begin{equation}\label{eq:G_g}
 			\begin{aligned}
 				\mathcal{G}_p(R,t)&=\exp\left(-\frac{R^{p\beta}}{ct^{\frac{\beta(p+1)}{2}+1}}\right)+\exp\left(-\frac{R^{p\beta}}{ct^{\frac{p\beta}{2}+1}}\right), \\
 				\widetilde{\mathcal{G}}_p(R,t)&=\exp\left(-\frac{R^{\beta(p+1)+2}}{ct^{\frac{\beta p}{2}+\beta+2}}\right)+\exp\left(-\frac{R^{\beta p+2}}{ct^{\frac{\beta p}{2}+2}}\right) \\
 				&+\exp\left(-\frac{R^{\beta(p+1)+2}}{ct^{\frac{\beta(p+1)^2+4p+2}{2p}}}\right)+\exp\left(-\frac{R^{p\beta+2}}{ct^{\frac{p\beta}{2}+2+\frac{1}{p}}}\right).
 			\end{aligned}
 		\end{equation}
 	\end{theorem}
Together with a Taylor type expansion of smooth functions on Carnot groups, this yields the required upper bound. The “assumption of non-characteristic boundary is very crucial,” since they “require $C^2$ regularity of the signed distance function from the boundary of the domain.”

expanded_theorem:
\label{thm:main}
		Let $\Omega$ be a bounded, open subset of $\mathbb{G}$ with $C^{2}$ boundary having no characteristic points. Then for all $1\leqslant \alpha\leqslant 2$,
		\begin{align*}
			\lim_{t\to 0}\frac{|\Omega|-Q^{(\alpha)}_\Omega(t)}{\mu_\alpha(t)}=|\partial \Omega|_{H},
		\end{align*}
		where $\mu_\alpha(t)$ is defined by
		\begin{align}\label{eq:mu_alpha}
		\mu_\alpha(t)=\begin{cases}
			t^{1/\alpha}\E[\overline{Y}^{\alpha}(1)] & \mbox{if $1<\alpha\le 2$} \\
			\frac{1}{\pi}t\log(1/t) & \mbox{if $\alpha=1$} \\
			t & \mbox{if $0<\alpha<1$},
		\end{cases}
	\end{align}.

