theorem.content:
\label{main:thm}
    Fix a sign choice $\pm$, $\varepsilon>0$, and positive integers $k, H$. There exists a positive constant $c$ (depending on $\pm, \varepsilon, k, H$) such that for all sufficiently large $X$, there are at least $cX^{1-\kappa-\varepsilon}$ positive integers $d\leq X$ such that the following hold:
    \begin{enumerate}
        \item For each $1\leq i\leq k$, if there exists a cubic field $K$ with $\pm\Delta_K=d+i$, then $h(K)>H$.

        \item We have 
        \[
        \#\{K \text{ cubic field }\mid \pm \Delta_K\in\{d+1,d+2,\dots,d+k\}\}\geq \frac{k}{2}.
         \]

    \end{enumerate}

ref_dict.main:thm:
\begin{theorem}\label{main:thm}
    Fix a sign choice $\pm$, $\varepsilon>0$, and positive integers $k, H$. There exists a positive constant $c$ (depending on $\pm, \varepsilon, k, H$) such that for all sufficiently large $X$, there are at least $cX^{1-\kappa-\varepsilon}$ positive integers $d\leq X$ such that the following hold:
    \begin{enumerate}
        \item For each $1\leq i\leq k$, if there exists a cubic field $K$ with $\pm\Delta_K=d+i$, then $h(K)>H$.

        \item We have 
        \[
        \#\{K \text{ cubic field }\mid \pm \Delta_K\in\{d+1,d+2,\dots,d+k\}\}\geq \frac{k}{2}.
         \]

    \end{enumerate}
\end{theorem}

