\subsection{What is done}
\label{sec:intro_what_is_done}

The main result of this paper is the following.

\begin{corollary}
    \label{cor:approx_by_compacts_implies_1_thomason}
    Let $\mathcal{X}$ be a concentrated regular algebraic stack with quasi-finite and locally separated diagonal. Then $\mathcal{X}$ satisfies the $1$-Thomason condition. Moreover, if $\mathcal{S}\to \mathcal{X}$ is an immersion, then $\mathcal{S}$ satisfies the $1$-Thomason condition. 
\end{corollary}

\begin{abstract}
 We show that the Thomason condition holds for any concentrated regular Noetherian algebraic stack with quasi-finite and locally separated diagonal. As a consequence, the derived category of quasi-coherent sheaves on such an algebraic stack is singly compactly generated. This extends results of Hall--Rydh from separated to locally separated diagonal, under additional regularity hypotheses.
\end{abstract}

The main result of this paper is the following.

Particularly, \Cref{introthm:thomason} asserts that $D_{\operatorname{qc}}(\mathcal{X})$ is singly compactly generated, and every closed subset of $|\mathcal{X}|$ arises as the support of a perfect complex. Moreover, \Cref{introthm:thomason} improves \cite[Theorem 2.1]{Hall:2022} to single compact generation in the special case of quasi-finite and locally separated diagonal. Furthermore, we prove a more general statement where $\mathcal{X}$ does not need to be concentrated; see \Cref{thm:generate}. Here, `concentrated' is a mild condition ensuring that compact objects coincide with perfect complexes. In our context, concentratedness coincides with being `tame' in the sense of \cite{Hall:2016}; see e.g.\ \cite[Proposition A.1]{DeDeyn/Lank/ManaliRahul:2025}.

Hall and Rydh introduced the notion of $\beta$-crispness in \cite{Hall/Rydh:2017a}. This notion requires that the Thomason $\beta$-Thomason condition be stable ascending under \'{e}tale, separated, quasi-compact morphisms representable by algebraic spaces. It is not clear whether $\mathcal{S}$ in \Cref{introthm:thomason} is $1$-crisp. In particular, the inductive argument used in the proof of \Cref{introthm:thomason} does not appear to interact well with immersions in the sense required for $\beta$-crispness. To be precise, any \'{e}tale cover of $\mathcal{S}$ need not arise as an \'{e}tale cover of $\mathcal{X}$.

\begin{lemma}
 \label{lem:immersion_is_Thomason}
 Let $t\colon \mathcal{Y}\to \mathcal{X}$ be an immersion of quasi-compact quasi-separated algebraic stacks. If $\mathcal{X}$ satisfies the $\beta$-Thomason condition, then so does $\mathcal{Y}$. 
\end{lemma}

\begin{theorem}
 \label{thm:generate}
 Let $\mathcal{X}$ be a quasi-compact quasi-separated regular algebraic stack with quasi-finite and locally separated diagonal. Then there is an object of $\operatorname{Perf}(\mathcal{X})$ which generates $D_{\operatorname{qc}}(\mathcal{X})$.
\end{theorem}

\begin{corollary}
 \label{cor:approx_by_compacts_implies_1_thomason}
 Let $\mathcal{X}$ be a concentrated regular algebraic stack with quasi-finite and locally separated diagonal. Then $\mathcal{X}$ satisfies the $1$-Thomason condition. Moreover, if $\mathcal{S}\to \mathcal{X}$ is an immersion, then $\mathcal{S}$ satisfies the $1$-Thomason condition. 
\end{corollary}

\begin{proposition}
 \label{prop:finite_faithfully_flat_affine_cover}
 Let $f\colon \mathcal{Y} \to \mathcal{X}$ be a finite, flat, surjective, morphism between Noetherian algebraic stacks. If $\mathcal{Y}$ satisfies the $\beta$-Thomason condition, then so does $\mathcal{X}$. 
\end{proposition}

